INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用了一年时间，终于弥补着当年的过失。", "corrected_sentence": "他用了一年时间，终于弥补了当年的过失。", "error_description": "体标误用：“终于”表示事情已经完成，要用“了”，不能用表示持续的“着”。正确：终于弥补了当年的过失。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
