INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把缺少的部分补足。", "primary_collocate": null, "pronunciation": "mí bǔ", "ipa": "mi˧˥ pu˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想靠兼职弥补每月收入的不足。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想办法弥补这次的损失。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃蔬菜可以弥补身体缺少的维生素。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱可以弥补学校的资金缺口。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天多练两小时，想弥补和别人的差距。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本新书弥补了这方面研究的不足。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子不高，就靠速度弥补身高的劣势。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期睡眠不足，周末睡再多，也很难弥补平时的睡眠缺口。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家发了补贴，弥补农民减少的收入。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店靠夜里的生意弥补白天的亏损。", "target_word": "弥补", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弥补了", "label": "体标"}, {"form": "弥补过", "label": "体标"}, {"form": "弥补不了", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "把不足、缺口、损失、差距等缺少的部分补足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf351384-2d63-4008-9220-bc6d4f59f608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弥补", "is_correct": true, "explanation": "弥补：靠兼职补上收入的缺口，与“不足”搭配。"}, {"text": "赚取", "is_correct": false, "explanation": "搭配：“赚取”的对象是钱、利润，不能说赚取“不足”。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：“挥霍”是浪费钱财，与“想靠兼职补足收入”的意思相反。"}, {"text": "扣除", "is_correct": false, "explanation": "搭配：“扣除”是从总数中去掉一部分，“不足”不能被扣除。"}], "explanations": {"弥补": "弥补：靠兼职补上收入的缺口，与“不足”搭配。", "赚取": "搭配：“赚取”的对象是钱、利润，不能说赚取“不足”。", "挥霍": "语义：“挥霍”是浪费钱财，与“想靠兼职补足收入”的意思相反。", "扣除": "搭配：“扣除”是从总数中去掉一部分，“不足”不能被扣除。"}, "sentence_index": 0, "correct_answer": "弥补"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月公司弥补了三名新员工。", "explanation": "这里应该用〈增加〉。弥补的对象是缺口或不足，员工人数变多要用增加。"}, {"text": "他在比赛中弥补了一项新纪录。", "explanation": "这里应该用〈创造〉。弥补是补上缺少的部分，做出新纪录要用创造。"}, {"text": "他把这碗饭弥补完了。", "explanation": "这里应该用〈吃〉。弥补的对象是缺口或不足，把饭吃完要用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弥补", "is_correct": true, "explanation": "弥补：用速度补上身高方面的不利，与“劣势”搭配。"}, {"text": "炫耀", "is_correct": false, "explanation": "语义：“炫耀”是夸耀优点，“劣势”不能拿来炫耀。"}, {"text": "增强", "is_correct": false, "explanation": "搭配：“增强”用于优势、能力，不说增强“劣势”。"}, {"text": "分享", "is_correct": false, "explanation": "搭配：“分享”的对象是快乐、经验，不能说分享“劣势”。"}], "explanations": {"弥补": "弥补：用速度补上身高方面的不利，与“劣势”搭配。", "炫耀": "语义：“炫耀”是夸耀优点，“劣势”不能拿来炫耀。", "增强": "搭配：“增强”用于优势、能力，不说增强“劣势”。", "分享": "搭配：“分享”的对象是快乐、经验，不能说分享“劣势”。"}, "sentence_index": 6, "correct_answer": "弥补"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "烟雾弥补了整个房间。", "explanation": "这里应该用〈弥漫〉。弥补是补足缺口，烟雾充满空间要用弥漫。"}, {"text": "作家弥补了一杯咖啡。", "explanation": "这里应该用〈喝〉。弥补的对象是缺口或不足，喝咖啡要用“喝”。"}, {"text": "这个城市的人口一年弥补了十万。", "explanation": "这里应该用〈增长〉。弥补是补上缺口，人口数量上升要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔捐款能把社区的资金缺口弥补下。", "corrected_sentence": "这笔捐款能把社区的资金缺口弥补上。", "error_description": "补语错误：补足缺口应说“弥补上”，“弥补下”不成立。正确：弥补上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天多练习，终于把落下的进度弥补了上。", "corrected_sentence": "他每天多练习，终于把落下的进度弥补上了。", "error_description": "“了”位置错误：完成标记“了”应放在补语“上”之后，说“弥补上了”，不说“弥补了上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f556ee77-2326-4a33-b7dc-cb1e36e3dda4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
