INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96189, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "后生是年轻的男子。", "primary_collocate": null, "pronunciation": "hòu shēng", "ipa": "xoʊ˥˩ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "一个后生走进了小店。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看着那个后生笑了。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这后生很有礼貌。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口站着一个高高的后生。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个勤快的后生，大家都喜欢他。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个后生在河边打鱼。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那后生把箱子搬上了车。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队里有不少后生。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位后生想跟你学做菜。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上住着一个后生，他每天砍柴。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後生", "label": "繁体"}], "register": "口语", "sense_fingerprint": "年轻的男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96189, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后生", "is_correct": true, "explanation": "正确答案：后生（hòu shēng），指年轻的男子。"}, {"text": "喉声", "is_correct": false, "explanation": "hóu（第二声）与 hòu（第四声）声调不同，意思是喉咙发出的声音。"}, {"text": "吼声", "is_correct": false, "explanation": "hǒu（第三声）与 hòu（第四声）声调不同，意思是吼叫的声音。"}, {"text": "后身", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（-n 与 -ng），意思是后部的身体。"}], "explanations": {"后生": "正确答案：后生（hòu shēng），指年轻的男子。", "喉声": "hóu（第二声）与 hòu（第四声）声调不同，意思是喉咙发出的声音。", "吼声": "hǒu（第三声）与 hòu（第四声）声调不同，意思是吼叫的声音。", "后身": "shēn 与 shēng 韵尾不同（-n 与 -ng），意思是后部的身体。"}, "sentence_index": null, "correct_answer": "后生"}, "level_3": {"options": [{"text": "后生", "is_correct": true, "explanation": "正确：“一个后生走进了小店”，人可以走进小店，符合语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能自己走进小店。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会自己走进小店。"}, {"text": "木箱", "is_correct": false, "explanation": "语义：木箱不会自己走进小店。"}], "explanations": {"后生": "正确：“一个后生走进了小店”，人可以走进小店，符合语境。", "婴儿": "语义：婴儿不能自己走进小店。", "石头": "语义：石头不会自己走进小店。", "木箱": "语义：木箱不会自己走进小店。"}, "sentence_index": 0, "correct_answer": "后生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口站着一棵高高的后生。", "explanation": "这里应该用〈个〉。“棵”用于树木，指人应使用“个”。"}, {"text": "村口站着一个高高的后生，他已经八十岁了。", "explanation": "这里应该用〈老人〉。“后生”指年轻男子，不能用来形容八十岁的老人。"}, {"text": "村口站着一个高高的后生，她扎着两条长辫子。", "explanation": "这里应该用〈姑娘〉。“后生”专指年轻男子，“她”指女子时不能用“后生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后生", "is_correct": true, "explanation": "正确：“那后生把箱子搬上了车”，年轻男子能搬箱子，符合语境。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“搬”的施事必须是能动的人或动物，桌子不能搬箱子。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不能把箱子搬上车，句意不通。"}, {"text": "小鸡", "is_correct": false, "explanation": "语义：小鸡搬不动箱子，与句中的力气活动不符。"}], "explanations": {"后生": "正确：“那后生把箱子搬上了车”，年轻男子能搬箱子，符合语境。", "桌子": "配价：“搬”的施事必须是能动的人或动物，桌子不能搬箱子。", "狗": "语义：狗不能把箱子搬上车，句意不通。", "小鸡": "语义：小鸡搬不动箱子，与句中的力气活动不符。"}, "sentence_index": 6, "correct_answer": "后生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山上住着一条后生，他每天砍柴。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，指人应使用“个”。"}, {"text": "山上住着一个后生，他才三岁，还在学走路。", "explanation": "这里应该用〈娃娃〉。后生指年轻男子，不指三岁的幼童。"}, {"text": "山上住着一个后生，他是我的爷爷。", "explanation": "这里应该用〈老人〉。后生指年轻男子，不用于称呼年长的亲属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看着那只后生挑着担子走远了。", "corrected_sentence": "我看着那个后生挑着担子走远了。", "error_description": "量词错误：“后生”指人，应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那头后生力气很大，一个人扛着米袋。", "corrected_sentence": "那个后生力气很大，一个人扛着米袋。", "error_description": "量词错误：“后生”指人，应用“个”；“头”只用于牲畜，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
