INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "年轻人，多指青年男子。", "primary_collocate": null, "pronunciation": "hòu shēng", "ipa": "xoʊ˥˩ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "村里的后生都去城里工作了。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个后生每天帮老人提水。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王大爷常说，现在的后生真有力气。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个后生长得高，人也很热情。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅教了后生很多本事。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还是个后生，要多学习。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有个后生来问路，我给他指了方向。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里来了几个后生，想租我家的房子。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位后生跑得很快。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，后生应该多帮助别人。", "target_word": "后生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後生", "label": "繁体"}], "register": "口语", "sense_fingerprint": "年轻人、多指青年男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后生", "is_correct": true, "explanation": "正确答案：后生（hòu shēng），指年轻人，多指青年男子。"}, {"text": "吼声", "is_correct": false, "explanation": "hǒu（第三声）与 hòu（第四声）声调不同，意思是吼叫的声音。"}, {"text": "后身", "is_correct": false, "explanation": "shēn 与 shēng 韵尾不同（-n 与 -ng），意思是后部、后身。"}, {"text": "喉声", "is_correct": false, "explanation": "hóu（第二声）与 hòu（第四声）声调不同，意思是喉咙发出的声音。"}], "explanations": {"后生": "正确答案：后生（hòu shēng），指年轻人，多指青年男子。", "吼声": "hǒu（第三声）与 hòu（第四声）声调不同，意思是吼叫的声音。", "后身": "shēn 与 shēng 韵尾不同（-n 与 -ng），意思是后部、后身。", "喉声": "hóu（第二声）与 hòu（第四声）声调不同，意思是喉咙发出的声音。"}, "sentence_index": null, "correct_answer": "后生"}, "level_3": {"options": [{"text": "后生", "is_correct": true, "explanation": "正确：“后生”指年轻人，“村里的后生去城里工作”符合语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿还不会工作，不能去城里工作。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能去城里工作。"}, {"text": "老太太", "is_correct": false, "explanation": "语义：“老太太”指年老的女性，与“去城里工作”的年轻劳动力不符。"}], "explanations": {"后生": "正确：“后生”指年轻人，“村里的后生去城里工作”符合语境。", "婴儿": "语义：婴儿还不会工作，不能去城里工作。", "小猫": "语义：小猫是动物，不能去城里工作。", "老太太": "语义：“老太太”指年老的女性，与“去城里工作”的年轻劳动力不符。"}, "sentence_index": 0, "correct_answer": "后生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口站着一头高高的后生，人也很热情。", "explanation": "这里应该用〈个〉。“头”是牲畜的量词，指人应使用“个”，不能说“一头后生”。"}, {"text": "她是个后生，从小就跟着爸爸下地干活。", "explanation": "这里应该用〈姑娘〉。“后生”专指年轻男子，指年轻女子应用“姑娘”。"}, {"text": "这个后生今年刚满三岁，还不会走路。", "explanation": "后生指年轻人，此处所说的是幼儿，应该用〈孩子〉或〈娃娃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后生", "is_correct": true, "explanation": "正确：“有个后生来问路”，年轻男子问路，符合后面“给他指了方向”的语境。"}, {"text": "姑娘", "is_correct": false, "explanation": "语义：后面的“他”指男性，与“姑娘”的女性身份不符。"}, {"text": "婴儿", "is_correct": false, "explanation": "搭配：“问路”要求能说话、能提问的人，婴儿不能问路。"}, {"text": "大婶", "is_correct": false, "explanation": "语义：“大婶”指中年女性，与后面的“他”所指的性别矛盾。"}], "explanations": {"后生": "正确：“有个后生来问路”，年轻男子问路，符合后面“给他指了方向”的语境。", "姑娘": "语义：后面的“他”指男性，与“姑娘”的女性身份不符。", "婴儿": "搭配：“问路”要求能说话、能提问的人，婴儿不能问路。", "大婶": "语义：“大婶”指中年女性，与后面的“他”所指的性别矛盾。"}, "sentence_index": 6, "correct_answer": "后生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一条后生，正在晒太阳。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，指人应使用“个”。"}, {"text": "这位后生已经九十岁了，走路要拄拐杖。", "explanation": "这里应该用〈老人〉。“后生”指年轻人，不能指九十岁的老人。"}, {"text": "草地上有后生在吃草。", "explanation": "这里应该用〈牛〉或〈羊〉。后生指年轻人，不能用来指吃草的动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只后生身材结实，干活很利索。", "corrected_sentence": "那个后生身材结实，干活很利索。", "error_description": "量词错误：“后生”指人，应用量词“个”，不能用“只”（“只”多用于动物或小件物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村口来了一条后生，背着一个大包袱。", "corrected_sentence": "村口来了一个后生，背着一个大包袱。", "error_description": "量词错误：“后生”指人，应用“个”；“条”用于细长的东西，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
