INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96191, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "征收是国家向人收钱或收东西。", "primary_collocate": null, "pronunciation": "zhēng shōu", "ipa": "ʈʂəŋ˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "国家向商店征收一笔特别费用。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定向进城车辆征收一笔拥堵费。", "target_word": "征收", "complexity_tier": "T3", "furigana": "zhèng fǔ jué dìng xiàng jìn chéng chē liàng zhēng shōu yì bǐ yōng dǔ fèi", "sentence_source": "generated"}, {"text": "战争时，国家向农民征收粮食。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府决定向大型超市征收一笔环保费。", "target_word": "征收", "complexity_tier": "T3", "furigana": "shì zhèng fǔ jué dìng xiàng dà xíng chāo shì zhēng shōu yì bǐ huán bǎo fèi", "sentence_source": "generated"}, {"text": "国家对烟酒征收很高的费用。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府向农民征收了两百元的水利费。", "target_word": "征收", "complexity_tier": "T3", "furigana": "zhèng fǔ xiàng nóng mín zhēng shōu le liǎng bǎi yuán de shuǐ lì fèi", "sentence_source": "generated"}, {"text": "他们向进口车征收一笔额外的钱。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家为什么要征收这些东西？", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，国王常向百姓征收粮食和布。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要向村里每户人家征收一笔修路费。", "target_word": "征收", "complexity_tier": "T3", "furigana": "zhèng fǔ yào xiàng cūn lǐ měi hù rén jiā zhēng shōu yì bǐ xiū lù fèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "征收了", "label": "体标"}, {"form": "征收过", "label": "体标"}, {"form": "徵收", "label": "繁体"}], "register": "书面", "sense_fingerprint": "征收|动词|国家向人收取钱、粮食或土地等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缴纳", "is_correct": false, "explanation": "语义：“缴纳”是交钱的一方，应是商店缴纳给国家，与“国家向商店”的方向相反，句意不通。"}, {"text": "征收", "is_correct": true, "explanation": "征收：国家依法向人收取钱款，与“国家”“商店”“特别费用”相合，符合句意。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、方案，不能直接带“一笔特别费用”。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：“挖掘”指把埋藏的东西挖出来，不能用来指向商店收费用，句意不通。"}], "explanations": {"缴纳": "语义：“缴纳”是交钱的一方，应是商店缴纳给国家，与“国家向商店”的方向相反，句意不通。", "征收": "征收：国家依法向人收取钱款，与“国家”“商店”“特别费用”相合，符合句意。", "讨论": "搭配：“讨论”的对象是问题、方案，不能直接带“一笔特别费用”。", "挖掘": "语义：“挖掘”指把埋藏的东西挖出来，不能用来指向商店收费用，句意不通。"}, "sentence_index": 0, "correct_answer": "征收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生每学期向学校征收一百元的学费。", "explanation": "这里应该用〈缴纳〉。征收的主体是国家或政府，学生向学校交学费要用缴纳，不能用征收。"}, {"text": "会议开始前，主任向全体员工征收了意见。", "explanation": "这里应该用〈征求〉。征收针对税款、粮食等财物，征求大家的意见要用征求。"}, {"text": "杂志社向读者征收了很多优秀的稿件。", "explanation": "这里应该用〈征集〉。征收的对象是税费和财物，向读者征集稿件要用征集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "借给", "is_correct": false, "explanation": "配价：“借给”要求接受借出物的人作宾语，“进口车”不能接受借款，句子结构不成立。"}, {"text": "征收", "is_correct": true, "explanation": "征收：国家依法向人收取钱款，与“他们”“进口车”“额外的钱”相合，符合句意。"}, {"text": "支付", "is_correct": false, "explanation": "语义：“支付”是付钱给对方，进口车不能收钱，句中“他们向进口车支付”句意不通。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”指给予嘉奖，不是收取钱款，“奖励一笔额外的钱”与句意不符。"}], "explanations": {"借给": "配价：“借给”要求接受借出物的人作宾语，“进口车”不能接受借款，句子结构不成立。", "征收": "征收：国家依法向人收取钱款，与“他们”“进口车”“额外的钱”相合，符合句意。", "支付": "语义：“支付”是付钱给对方，进口车不能收钱，句中“他们向进口车支付”句意不通。", "奖励": "语义：“奖励”指给予嘉奖，不是收取钱款，“奖励一笔额外的钱”与句意不符。"}, "sentence_index": 6, "correct_answer": "征收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市民每年向政府征收一笔税款。", "explanation": "这里应该用〈缴纳〉。征收的主体是国家或政府，市民向政府交税要用缴纳，不能用征收。"}, {"text": "商人向果农征收了一批苹果。", "explanation": "这里应该用〈收购〉。征收是国家依法收取钱物，商人从果农手里买苹果要用收购。"}, {"text": "他们征收了一个孤儿，把他带回了家。", "explanation": "这里应该用〈收养〉。征收的对象是钱款和财物，不能用于人；领养孩子要用收养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府村民征收了五十元的管理费。", "corrected_sentence": "政府向村民征收了五十元的管理费。", "error_description": "错误：“政府村民征收了五十元的管理费”，正确：“政府向村民征收了五十元的管理费”。缺少介词“向”，“村民”是征收的对象，需要“向”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家给进口酒征收了高额的关税。", "corrected_sentence": "国家对进口酒征收了高额的关税。", "error_description": "错误：“给进口酒征收”，正确：“对进口酒征收”。“征收”的对象要用介词“对”引出，“给”表示给予，与“征收”的意思相反，句意不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
