INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "政府依法向人民收取税款等。", "primary_collocate": null, "pronunciation": "zhēng shōu", "ipa": "ʈʂəŋ˥ ʂoʊ˥", "syllable_count": 2, "sentences": [{"text": "政府依法征收个人所得税。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家从今年起征收环境税。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税务局每月向公司征收税款。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府对高档汽车征收消费税。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市不征收房产税。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人认为，政府应该多征收富人的税。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按法律征收了一千万元税款。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法律规定，政府可以征收网店的税款。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年向市民征收垃圾处理费。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府征收的税款用来修路和建学校。", "target_word": "征收", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征收了", "label": "体标"}, {"form": "征收过", "label": "体标"}, {"form": "徵收", "label": "繁体"}], "register": "书面", "sense_fingerprint": "征收|动词|政府依法收取税款或费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指觉得美好而赞赏，不能用来指政府征税，句意不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求、要求，不能直接带“个人所得税”。"}, {"text": "征收", "is_correct": true, "explanation": "征收：政府依法向人收取税款，与“政府依法”“个人所得税”相合，符合句意。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是对喜事表示庆贺，与税款无关，句意不通。"}], "explanations": {"欣赏": "语义：“欣赏”指觉得美好而赞赏，不能用来指政府征税，句意不通。", "拒绝": "搭配：“拒绝”的对象是请求、要求，不能直接带“个人所得税”。", "征收": "征收：政府依法向人收取税款，与“政府依法”“个人所得税”相合，符合句意。", "祝贺": "语义：“祝贺”是对喜事表示庆贺，与税款无关，句意不通。"}, "sentence_index": 0, "correct_answer": "征收"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房东每月向租客征收房租。", "explanation": "这里应该用〈收取〉。征收只用于国家或政府依法收税，房东收房租要用收取。"}, {"text": "政府向市民征收了修路的意见。", "explanation": "这里应该用〈征求〉。征收针对税费和财物，征求市民对修路的意见要用征求。"}, {"text": "政府向社会征收设计方案。", "explanation": "这里应该用〈征集〉。征收的对象是税费和财物，征集设计方案要用征集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投资", "is_correct": false, "explanation": "语义：“投资”是把资金投入以求获利，税款不能用来投资，句意不通。"}, {"text": "赞助", "is_correct": false, "explanation": "语义：“赞助”是自愿出资支持，与“按法律”所指的依法强制收取相反，句意不通。"}, {"text": "征收", "is_correct": true, "explanation": "征收：他们依照法律向人收取税款，与“按法律”“一千万元税款”相合，符合句意。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：“吸收”指接收、收纳，不能用来指向人收税，句意不通。"}], "explanations": {"投资": "语义：“投资”是把资金投入以求获利，税款不能用来投资，句意不通。", "赞助": "语义：“赞助”是自愿出资支持，与“按法律”所指的依法强制收取相反，句意不通。", "征收": "征收：他们依照法律向人收取税款，与“按法律”“一千万元税款”相合，符合句意。", "吸收": "语义：“吸收”指接收、收纳，不能用来指向人收税，句意不通。"}, "sentence_index": 6, "correct_answer": "征收"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "居民每年向国家征收个人所得税。", "explanation": "这里应该用〈缴纳〉。征收的主体是国家或政府，居民向国家交税要用缴纳，不能说征收。"}, {"text": "工厂向农户征收了一批棉花。", "explanation": "这里应该用〈收购〉。征收是国家依法收取钱物，工厂向农户买棉花要用收购。"}, {"text": "银行向借款人征收了一笔贷款。", "explanation": "这里应该用〈收回〉。银行收回借出去的贷款，征收只用于国家依法收取税费，不能用于贷款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府依法给企业征收了车船税。", "corrected_sentence": "政府依法向企业征收了车船税。", "error_description": "错误：“给”表示给予，与“征收”（向人收取）意思相反，不能用来引出纳税人。正确：应用“向”引出纳税人，即“政府依法向企业征收了车船税”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府对香烟的征收了较重的消费税。", "corrected_sentence": "政府对香烟征收了较重的消费税。", "error_description": "错误：“对香烟的征收”把“征收”变成了名词，其后不能再接“了”作谓语，多出的“的”是错误所在。正确：“政府对香烟征收了较重的消费税”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
