INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96193, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "情侣是互相喜欢、在一起的一对男女。", "primary_collocate": null, "pronunciation": "qíng lǚ", "ipa": "tɕʰiŋ˧˥ ly˨˩˦", "syllable_count": 2, "sentences": [{"text": "公园里有很多情侣。", "target_word": "情侣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那对情侣在河边走路。", "target_word": "情侣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭馆常常有情侣来吃饭。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情侣们周末喜欢一起看电影。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是一对很幸福的情侣。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这对情侣今天穿着一样的衣服。", "target_word": "情侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一对情侣在门口拍照。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情人节那天，到处都是情侣。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们当了三年情侣，下个月要结婚。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家咖啡店的小桌子是给情侣坐的。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对情侣", "label": "量词"}, {"form": "小情侣", "label": "复合"}, {"form": "情侣装", "label": "复合"}, {"form": "情侶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "互相喜欢、在一起的一对男女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火车", "is_correct": false, "explanation": "语义：公园里一般不会有成群的火车，「公园里有很多火车」与场景不符。"}, {"text": "情侣", "is_correct": true, "explanation": "正确：「情侣」指相恋的一对男女，公园里有很多情侣很自然。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是放在家里的电器，「公园里有很多冰箱」与场景不符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的任务，不会满公园都是，「公园里有很多作业」不通。"}], "explanations": {"火车": "语义：公园里一般不会有成群的火车，「公园里有很多火车」与场景不符。", "情侣": "正确：「情侣」指相恋的一对男女，公园里有很多情侣很自然。", "冰箱": "语义：冰箱是放在家里的电器，「公园里有很多冰箱」与场景不符。", "作业": "语义：作业是学生的任务，不会满公园都是，「公园里有很多作业」不通。"}, "sentence_index": 0, "correct_answer": "情侣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和爷爷是情侣，每天一起下棋。", "explanation": "这里应该用〈爷孙〉。情侣指互相喜欢的一对男女，爷爷与我是亲属关系，不能说情侣。"}, {"text": "教室门口坐着一只情侣。", "explanation": "这里应该用〈对〉。情侣指成对的人，量词要用〈一对〉，「一只」用于单个动物或物品，不能指成对的人。"}, {"text": "这次登山，我找到了很可靠的情侣。", "explanation": "这里应该用〈同伴〉。情侣指相恋的一对，登山时结伴同行的人只是同伴，不能称情侣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋糕", "is_correct": false, "explanation": "搭配：「对」用于成双的东西，「蛋糕」一般用「块」，不说「一对蛋糕」。"}, {"text": "耳环", "is_correct": false, "explanation": "语义：耳环是饰品，不能在门口拍照，句子不通。"}, {"text": "情侣", "is_correct": true, "explanation": "正确：「情侣」是成对的一男一女，可以说「一对」，也能在门口拍照。"}, {"text": "筷子", "is_correct": false, "explanation": "配价：「拍照」的主语必须是人，筷子不能做主语。"}], "explanations": {"蛋糕": "搭配：「对」用于成双的东西，「蛋糕」一般用「块」，不说「一对蛋糕」。", "耳环": "语义：耳环是饰品，不能在门口拍照，句子不通。", "情侣": "正确：「情侣」是成对的一男一女，可以说「一对」，也能在门口拍照。", "筷子": "配价：「拍照」的主语必须是人，筷子不能做主语。"}, "sentence_index": 6, "correct_answer": "情侣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他现在是单身，还没有情侣。", "explanation": "这里应该用〈对象〉。情侣指已经相恋的一对，还没有恋爱的人要说有没有对象。"}, {"text": "这场比赛里，他是我最强的情侣。", "explanation": "这里应该用〈对手〉。情侣指相恋的人，比赛中的竞争者应说对手。"}, {"text": "我在路上看见一个情侣。", "explanation": "这里应该用〈对〉。情侣指成对的人，量词要用〈一对〉，「一个」只用于单个的人，不能指一对情侣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个情侣在河边慢慢走。", "corrected_sentence": "一对情侣在河边慢慢走。", "error_description": "量词错误：情侣是成对的人，数量要用量词「对」，应说「一对情侣」，不能用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多情侣们在海边散步。", "corrected_sentence": "很多情侣在海边散步。", "error_description": "「很多」已经表示数量多，后面不能再加「们」，应说「很多情侣」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
