INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "相恋的一对男女。", "primary_collocate": null, "pronunciation": "qíng lǚ", "ipa": "tɕʰiŋ˧˥ ly˨˩˦", "syllable_count": 2, "sentences": [{"text": "那两个人是情侣，不是朋友。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影院里坐着很多情侣。", "target_word": "情侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对情侣吵架了，现在不说话。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，他们是学校里有名的情侣。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情侣之间要多说话。", "target_word": "情侣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们看起来像一对快乐的情侣。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店卖情侣用的杯子。", "target_word": "情侣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多情侣在海边看日出。", "target_word": "情侣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她和男朋友大学时就成了情侣。", "target_word": "情侣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对情侣把手机放在桌子上，一直聊天。", "target_word": "情侣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对情侣", "label": "量词"}, {"form": "小情侣", "label": "复合"}, {"form": "情侣装", "label": "复合"}, {"form": "情侶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "相恋的一对男女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "朋友", "is_correct": false, "explanation": "语义：后半句已经说「不是朋友」，前面再说「是朋友」就自相矛盾。"}, {"text": "情侣", "is_correct": true, "explanation": "正确：「情侣」指相恋的一对，与「不是朋友」形成自然的对比。"}, {"text": "猫", "is_correct": false, "explanation": "语义：「那两个人」是人，不能说是猫，句子荒谬。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：「是」后面接「房子」来指人不通，名词搭配不当。"}], "explanations": {"朋友": "语义：后半句已经说「不是朋友」，前面再说「是朋友」就自相矛盾。", "情侣": "正确：「情侣」指相恋的一对，与「不是朋友」形成自然的对比。", "猫": "语义：「那两个人」是人，不能说是猫，句子荒谬。", "房子": "搭配：「是」后面接「房子」来指人不通，名词搭配不当。"}, "sentence_index": 0, "correct_answer": "情侣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和表哥是情侣，常常一起踢球。", "explanation": "这里应该用〈亲戚〉。情侣指相恋的一对男女，表哥与我是亲戚关系，不能说情侣。"}, {"text": "我在超市门口碰见一只情侣。", "explanation": "这里应该用〈对〉。情侣指成对的人，量词要用〈一对〉，不能用〈一只〉。"}, {"text": "她刚失恋，现在还没有情侣。", "explanation": "这里应该用〈对象〉。情侣指已经相恋的一对，刚失恋的人说没有恋爱对象要用对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "语义：老虎不用杯子，「卖老虎用的杯子」不合常理。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：「鞋子」不能用杯子，「卖鞋子用的杯子」不合常理。"}, {"text": "情侣", "is_correct": true, "explanation": "正确：商店卖的是情侣用的杯子，「情侣」与「用的杯子」搭配自然。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子不会用杯子，句子荒谬。"}], "explanations": {"老虎": "语义：老虎不用杯子，「卖老虎用的杯子」不合常理。", "鞋子": "语义：「鞋子」不能用杯子，「卖鞋子用的杯子」不合常理。", "情侣": "正确：商店卖的是情侣用的杯子，「情侣」与「用的杯子」搭配自然。", "蚊子": "语义：蚊子不会用杯子，句子荒谬。"}, "sentence_index": 6, "correct_answer": "情侣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两支球队在决赛中是强大的情侣。", "explanation": "这里应该用〈对手〉。情侣指相恋的人，决赛中相争的两支队伍是对手。"}, {"text": "我和弟弟是情侣，常常一起玩。", "explanation": "这里应该用〈兄弟〉。情侣指相恋的一对，弟弟与我是亲属关系，要说兄弟。"}, {"text": "我和妈妈是情侣，每天一起去公园散步。", "explanation": "这里应该用〈母子〉或〈母女〉。情侣指相恋的人，母亲与子女是亲子关系，不能说情侣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩是一对情侣们。", "corrected_sentence": "我们俩是一对情侣。", "error_description": "「一对」已经表示两个人，「情侣」后面不能再加「们」，应去掉「们」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们是一个快乐的情侣。", "corrected_sentence": "他们是一对快乐的情侣。", "error_description": "情侣指成对的人，量词要用「对」，不能用「个」，应说「一对快乐的情侣」，不能说「一个快乐的情侣」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
