INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "爱好是你特别喜欢做的事。", "primary_collocate": null, "pronunciation": "ài hào", "ipa": "ai˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我的爱好是跑步和看电影。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么爱好？", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的爱好是在周末钓鱼。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱好很特别，喜欢收集旧钟。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画是她最大的爱好。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人的爱好不一样。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：“你们有什么爱好？”", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把爱好变成了工作。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王爱好多，会唱歌也会下棋。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个有相同爱好的朋友。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "爱好|名词|自己特别喜欢做的事，如跑步、画画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的价钱，跑步和看电影不是价格，句意不通。"}, {"text": "爱好", "is_correct": true, "explanation": "爱好：自己特别喜欢做的事，与“跑步和看电影”相合，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是身体的重量数值，不能和“跑步和看电影”这类活动搭配。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的品质特点，跑步和看电影不是性格，句意不通。"}], "explanations": {"价格": "语义：“价格”指商品的价钱，跑步和看电影不是价格，句意不通。", "爱好": "爱好：自己特别喜欢做的事，与“跑步和看电影”相合，符合句意。", "体重": "搭配：“体重”是身体的重量数值，不能和“跑步和看电影”这类活动搭配。", "性格": "语义：“性格”指人的品质特点，跑步和看电影不是性格，句意不通。"}, "sentence_index": 0, "correct_answer": "爱好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爱好是老师，这是我一辈子的事业。", "explanation": "这里应该用〈职业〉。“爱好”指业余时间特别喜欢做的事，不是工作身份，不能说“是老师”。"}, {"text": "他的爱好很开朗，大家都喜欢和他交往。", "explanation": "这里应该用〈性格〉。“开朗”形容性格，“爱好”指特别喜欢做的事，不能说“爱好很开朗”。"}, {"text": "他的爱好很高，有一米八。", "explanation": "这里应该用〈身高〉。“一米八”说的是身体的高度，“爱好”指特别喜欢做的事，不能说“爱好很高，有一米八”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不能用来问别人有什么，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是身体的数值，“有什么身高”的问法不符合提问的搭配习惯。"}, {"text": "爱好", "is_correct": true, "explanation": "爱好：自己特别喜欢做的事，与“老师问我们”的提问相合，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的价钱，不是人的特点，句意不通。"}], "explanations": {"颜色": "语义：“颜色”指事物的色彩，不能用来问别人有什么，句意不通。", "身高": "搭配：“身高”是身体的数值，“有什么身高”的问法不符合提问的搭配习惯。", "爱好": "爱好：自己特别喜欢做的事，与“老师问我们”的提问相合，符合句意。", "价格": "语义：“价格”指商品的价钱，不是人的特点，句意不通。"}, "sentence_index": 6, "correct_answer": "爱好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中充分发挥了自己的爱好。", "explanation": "这里应该用〈特长〉。“发挥”搭配特长、作用，“爱好”指兴趣，不能说“发挥爱好”。"}, {"text": "他的爱好是成为一名宇航员，为此努力了很多年。", "explanation": "这里应该用〈理想〉。“理想”指人生的目标，“爱好”指特别喜欢做的事，不能说成人生目标。"}, {"text": "他的爱好一直很好，每次考试都是第一名。", "explanation": "这里应该用〈成绩〉。“好”搭配成绩，“爱好”指特别喜欢做的事，考试名次属于学习成绩，不能说“爱好很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一只很特别的爱好。", "corrected_sentence": "我有一个很特别的爱好。", "error_description": "错误：“一只”。“爱好”的量词应用“个”，“只”一般用于动物，不能修饰“爱好”。正确：“我有一个很特别的爱好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些爱好们让他的生活变得很精彩。", "corrected_sentence": "这些爱好让他的生活变得很精彩。", "error_description": "错误：“爱好们”。“们”只加在指人的名词后面，“爱好”是事物，不能加“们”。正确：“这些爱好让他的生活变得很精彩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
