INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对某种事物特别喜爱的兴趣。", "primary_collocate": null, "pronunciation": "ài hào", "ipa": "ai˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他对音乐的爱好从小就很明显。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对绘画的爱好要靠老师多引导。", "target_word": "爱好", "complexity_tier": "T3", "furigana": "hái zi duì huì huà de ài hào yào kào lǎo shī duō yǐn dǎo", "sentence_source": "generated"}, {"text": "她对花草的爱好影响了全家人。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对茶的爱好已经几十年了。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书的爱好让他的生活很丰富。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对足球的爱好比谁都深。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对古典音乐的爱好持续了很多年。", "target_word": "爱好", "complexity_tier": "T3", "furigana": "tā duì gǔ diǎn yīn yuè de ài hào chí xù le hěn duō nián", "sentence_source": "generated"}, {"text": "对京剧的爱好使他们成了朋友。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不隐藏自己对游戏的爱好。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对历史的爱好是从爷爷那里来的。", "target_word": "爱好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "爱好|名词|对某种事物特别喜爱的兴趣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb6f1cf-d962-499b-9300-bdfe2bb87906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，音乐没有外形，句意不通。"}, {"text": "爱好", "is_correct": true, "explanation": "爱好：对某种事物特别喜爱的兴趣，与“他对音乐的”相合，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用来指对音乐的喜爱，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用于商品，不能和“音乐”搭配。"}], "explanations": {"形状": "语义：“形状”指物体的外形，音乐没有外形，句意不通。", "爱好": "爱好：对某种事物特别喜爱的兴趣，与“他对音乐的”相合，符合句意。", "颜色": "语义：“颜色”指色彩，不能用来指对音乐的喜爱，句意不通。", "价格": "搭配：“价格”用于商品，不能和“音乐”搭配。"}, "sentence_index": 0, "correct_answer": "爱好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在舞台上充分发挥了自己的爱好。", "explanation": "这里应该用〈特长〉。“发挥”搭配特长、作用，表示展示才能，“爱好”指兴趣，不能说“发挥爱好”。"}, {"text": "她的爱好很开朗，大家都喜欢和她交往。", "explanation": "这里应该用〈性格〉。“开朗”形容性格，“爱好”指对某种事物的兴趣，不能说“爱好很开朗”。"}, {"text": "他最近的爱好变重了，有七十公斤。", "explanation": "这里应该用〈体重〉。“七十公斤”说的是身体的重量，“爱好”指对某种事物的兴趣，不能说“爱好有七十公斤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寿命", "is_correct": false, "explanation": "语义：“寿命”指生存的年限，与对音乐的喜爱无关，句意不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是劳动报酬，不能和“对古典音乐的”搭配。"}, {"text": "爱好", "is_correct": true, "explanation": "爱好：对某种事物特别喜爱的兴趣，与“她对古典音乐的”相合，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高度，不能用于对音乐的态度，句意不通。"}], "explanations": {"寿命": "语义：“寿命”指生存的年限，与对音乐的喜爱无关，句意不通。", "工资": "搭配：“工资”是劳动报酬，不能和“对古典音乐的”搭配。", "爱好": "爱好：对某种事物特别喜爱的兴趣，与“她对古典音乐的”相合，符合句意。", "身高": "语义：“身高”指身体的高度，不能用于对音乐的态度，句意不通。"}, "sentence_index": 6, "correct_answer": "爱好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作让他积累了很多宝贵的爱好。", "explanation": "这里应该用〈经验〉。“积累”后接经验、知识，“爱好”是喜欢的兴趣，不能被积累。"}, {"text": "每天刷牙是一个好爱好。", "explanation": "这里应该用〈习惯〉。“刷牙”是日常习惯，不是特别喜爱的兴趣，不能用“爱好”指称它。"}, {"text": "她的爱好是当一名画家，为此努力了很多年。", "explanation": "这里应该用〈理想〉。“理想”指人生的目标，“爱好”指兴趣，不能说成要为之努力的人生目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对绘画的爱好们很深。", "corrected_sentence": "他对绘画的爱好很深。", "error_description": "错误：“爱好们”。“们”只加在指人的名词后面，“爱好”是事物，不能加“们”。正确：“他对绘画的爱好很深”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对古典音乐爱好从小就很深。", "corrected_sentence": "她对古典音乐的爱好从小就很深。", "error_description": "错误：漏掉了“的”。“对古典音乐”修饰“爱好”，中间要用“的”连接。正确：“她对古典音乐的爱好从小就很深”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd48c4e28-4da9-44e3-a132-78cc59d1e43f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
