INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "庆典是为了高兴的事，大家一起办的热闹活动。", "primary_collocate": null, "pronunciation": "qìng diǎn", "ipa": "tɕʰiŋ⁵¹ tjɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "全城的人都来参加国庆庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校明天有一场盛大的庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庆典上有音乐，也有舞蹈。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里为丰收办了一场庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在庆典上玩得很开心。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庆典结束后，大家一起吃饭。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的周年庆典热闹极了。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上很热闹，原来是在办庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们请了很多朋友来参加庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次庆典有很多好玩的活动。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慶典", "label": "繁体"}, {"form": "一场庆典", "label": "量词"}, {"form": "一次庆典", "label": "量词"}], "register": "中性", "sense_fingerprint": "为喜事大家一起办的热闹活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "庆典", "is_correct": true, "explanation": "庆典（qìng diǎn）：正确答案，指为喜事大家一起办的热闹活动。"}, {"text": "清点", "is_correct": false, "explanation": "清点（qīng diǎn）与庆典的第一个音节声调不同（第一声与第四声），意思是逐一数清。"}, {"text": "轻点", "is_correct": false, "explanation": "轻点（qīng diǎn）与庆典的第一个音节声调不同，意思是动作或力度轻一些。"}, {"text": "清单", "is_correct": false, "explanation": "清单（qīng dān）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是逐项列出的单子。"}, {"text": "清淡", "is_correct": false, "explanation": "清淡（qīng dàn）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是味道不浓。"}], "explanations": {"庆典": "庆典（qìng diǎn）：正确答案，指为喜事大家一起办的热闹活动。", "清点": "清点（qīng diǎn）与庆典的第一个音节声调不同（第一声与第四声），意思是逐一数清。", "轻点": "轻点（qīng diǎn）与庆典的第一个音节声调不同，意思是动作或力度轻一些。", "清单": "清单（qīng dān）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是逐项列出的单子。", "清淡": "清淡（qīng dàn）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是味道不浓。"}, "sentence_index": null, "correct_answer": "庆典"}, "level_3": {"options": [{"text": "庆典", "is_correct": true, "explanation": "庆典：为国庆举办的热闹活动，与“全城的人都来参加”相符。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是悼念死者的仪式，与“国庆”的喜庆气氛相反。"}, {"text": "考试", "is_correct": false, "explanation": "语义：国庆不是考试，“全城的人都来参加国庆考试”说不通。"}, {"text": "大楼", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动，不能是建筑物。"}], "explanations": {"庆典": "庆典：为国庆举办的热闹活动，与“全城的人都来参加”相符。", "葬礼": "语义：葬礼是悼念死者的仪式，与“国庆”的喜庆气氛相反。", "考试": "语义：国庆不是考试，“全城的人都来参加国庆考试”说不通。", "大楼": "配价：“参加”的宾语应是活动，不能是建筑物。"}, "sentence_index": 0, "correct_answer": "庆典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家为牺牲的烈士举行了庆典，大家都很悲痛。", "explanation": "这里应该用〈追悼会〉。庆典是为喜事办的热闹活动，悼念烈士要用追悼会，不能用庆典。"}, {"text": "工人们在广场上举行了庆典，要求提高工资。", "explanation": "这里应该用〈集会〉。庆典用于庆祝喜事，要求提高工资的场合应说集会，不能用庆典。"}, {"text": "老师们为期末考试的成绩举行了庆典，讨论怎样复习。", "explanation": "这里应该用〈座谈会〉。庆典是为喜事办的热闹活动，讨论成绩和复习方法要用座谈会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆典", "is_correct": true, "explanation": "庆典：为周年举办的喜庆活动，与“公司的周年”和“热闹极了”相符。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地是安葬死者的地方，与“热闹极了”的喜庆场面相反。"}, {"text": "账本", "is_correct": false, "explanation": "搭配：“热闹”形容场面或场所，不能用来形容账本。"}, {"text": "公章", "is_correct": false, "explanation": "语义：公章是盖在文件上的印章，不会热闹，“周年公章”也说不通。"}], "explanations": {"庆典": "庆典：为周年举办的喜庆活动，与“公司的周年”和“热闹极了”相符。", "墓地": "语义：墓地是安葬死者的地方，与“热闹极了”的喜庆场面相反。", "账本": "搭配：“热闹”形容场面或场所，不能用来形容账本。", "公章": "语义：公章是盖在文件上的印章，不会热闹，“周年公章”也说不通。"}, "sentence_index": 6, "correct_answer": "庆典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班主任举行了庆典，犯错的同学都很紧张。", "explanation": "这里应该用〈检讨会〉。庆典是为喜事办的热闹活动，让犯错的同学当众检讨要用检讨会。"}, {"text": "全校师生为牺牲的老师举行了庆典，大家默哀三分钟。", "explanation": "这里应该用〈追悼会〉。庆典用于喜庆场合，悼念牺牲的老师要用追悼会。"}, {"text": "两个班举行了庆典，争论谁的作业多。", "explanation": "这里应该用〈辩论会〉。庆典是喜庆的仪式，争论问题要用辩论会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天参加了一只庆典。", "corrected_sentence": "我们昨天参加了一场庆典。", "error_description": "量词用错。“庆典”应搭配“场”或“次”，“只”用于动物和成对的物件，不能用来数庆典。正确说法是“一场庆典”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校办了一棵庆典。", "corrected_sentence": "学校办了一场庆典。", "error_description": "量词用错。“棵”用于树木，不能用来数“庆典”这类活动，应说“一场庆典”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
