INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "庆祝的仪式。", "primary_collocate": null, "pronunciation": "qìng diǎn", "ipa": "tɕʰiŋ⁵¹ tjɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "庆典开始时，大家先唱国歌。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长在庆典上讲了话。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的百年庆典在礼堂举行。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庆典的第一项是升旗。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上正式的衣服参加庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庆典上，校长给学生发了奖。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥通车时举行了庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "庆典按时开始，现场很安静。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在庆典上代表大家发言。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家为英雄举办了隆重的庆典。", "target_word": "庆典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "慶典", "label": "繁体"}, {"form": "一场庆典", "label": "量词"}, {"form": "一次庆典", "label": "量词"}], "register": "中性", "sense_fingerprint": "庆祝时举行的正式仪式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "庆典", "is_correct": true, "explanation": "庆典（qìng diǎn）：正确答案，指庆祝时举行的正式仪式。"}, {"text": "清点", "is_correct": false, "explanation": "清点（qīng diǎn）与庆典的第一个音节声调不同（第一声与第四声），意思是逐一数清。"}, {"text": "轻点", "is_correct": false, "explanation": "轻点（qīng diǎn）与庆典的第一个音节声调不同，意思是动作或力度轻一些。"}, {"text": "清单", "is_correct": false, "explanation": "清单（qīng dān）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是逐项列出的单子。"}, {"text": "清淡", "is_correct": false, "explanation": "清淡（qīng dàn）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是味道不浓。"}], "explanations": {"庆典": "庆典（qìng diǎn）：正确答案，指庆祝时举行的正式仪式。", "清点": "清点（qīng diǎn）与庆典的第一个音节声调不同（第一声与第四声），意思是逐一数清。", "轻点": "轻点（qīng diǎn）与庆典的第一个音节声调不同，意思是动作或力度轻一些。", "清单": "清单（qīng dān）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是逐项列出的单子。", "清淡": "清淡（qīng dàn）与庆典（qìng diǎn）读音相近，但声调和第二个音节不同，意思是味道不浓。"}, "sentence_index": null, "correct_answer": "庆典"}, "level_3": {"options": [{"text": "庆典", "is_correct": true, "explanation": "庆典：庆祝时的正式仪式，“开始时大家先唱国歌”符合这种场合。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭不是仪式，没有先唱国歌的环节。"}, {"text": "体检", "is_correct": false, "explanation": "语义：体检是检查身体的活动，开始时不会先唱国歌。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：午睡是休息，开始时不会先唱国歌，与语境不符。"}], "explanations": {"庆典": "庆典：庆祝时的正式仪式，“开始时大家先唱国歌”符合这种场合。", "午饭": "语义：午饭不是仪式，没有先唱国歌的环节。", "体检": "语义：体检是检查身体的活动，开始时不会先唱国歌。", "午睡": "语义：午睡是休息，开始时不会先唱国歌，与语境不符。"}, "sentence_index": 0, "correct_answer": "庆典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市民在广场上为遇难者举行了庆典，大家都在哭。", "explanation": "这里应该用〈追悼会〉。庆典是为喜事举行的仪式，为遇难者哀悼不能用庆典。"}, {"text": "我们一家人在家里举行了庆典，随便吃了顿饭。", "explanation": "这里应该用〈聚餐〉。庆典指隆重的庆祝仪式，家人随便吃饭不能说庆典。"}, {"text": "同学们开了一个庆典，争论该怎么办。", "explanation": "这里应该用〈讨论会〉。庆典是喜庆的仪式，争论问题要用讨论会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "庆典", "is_correct": true, "explanation": "庆典：庆祝时举行的仪式，“这座桥通车时举行了”后接它最自然。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是悼念死者的仪式，与桥梁通车的喜庆场合不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：桥梁通车时不会举行考试，“举行了考试”与语境不符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“举行”一般搭配活动或仪式，不能搭配“作业”。"}], "explanations": {"庆典": "庆典：庆祝时举行的仪式，“这座桥通车时举行了”后接它最自然。", "葬礼": "语义：葬礼是悼念死者的仪式，与桥梁通车的喜庆场合不符。", "考试": "语义：桥梁通车时不会举行考试，“举行了考试”与语境不符。", "作业": "搭配：“举行”一般搭配活动或仪式，不能搭配“作业”。"}, "sentence_index": 6, "correct_answer": "庆典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学术会议上，教授举行了庆典，讲解研究成果。", "explanation": "这里应该用〈报告〉。庆典是隆重的庆祝仪式，讲解研究成果要用报告。"}, {"text": "两队举行了庆典，争夺冠军。", "explanation": "这里应该用〈比赛〉。争夺冠军要用比赛，庆典是喜庆的仪式。"}, {"text": "学生们在教室参加庆典，一个人做完了三张试卷。", "explanation": "这里应该用〈考试〉。做试卷是考试，庆典是为喜事举行的仪式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长庆典上讲了一段话。", "corrected_sentence": "校长在庆典上讲了一段话。", "error_description": "地点短语“庆典上”前漏了“在”。表示动作发生的地点要说“在庆典上”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府在广场上举行了一座庆典。", "corrected_sentence": "市政府在广场上举行了一场庆典。", "error_description": "量词用错。“庆典”应搭配“场”或“次”，“座”用于山、桥、房屋等大型固定的东西，不能用来数庆典。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
