INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96202, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "分内应当做的。", "primary_collocate": null, "pronunciation": "yīng fèn", "ipa": "iŋ˥ fən˥˩", "syllable_count": 2, "sentences": [{"text": "这是我应分的事，你别客气。", "target_word": "应分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照顾老人是子女应分的事。", "target_word": "应分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得这样做是应分的。", "target_word": "应分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批改作业是应分的事。", "target_word": "应分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "保护环境是每个人应分的责任。", "target_word": "应分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扫地是你应分的事，别再推了。", "target_word": "应分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他认为帮朋友搬家是应分的事。", "target_word": "应分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按时交作业是学生应分的事。", "target_word": "应分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为客人开门是服务员应分的工作。", "target_word": "应分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些活儿是学生应分的，不用老师做。", "target_word": "应分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "应分：形容词，属于分内、应当做的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应分", "is_correct": true, "explanation": "应分作形容词，表示分内应当做的，此处修饰“事”，正确。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”形容温度或态度，用来修饰“我的事”说不通。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说价格高，与“你别客气”的语境不合。"}, {"text": "遥远", "is_correct": false, "explanation": "搭配：“遥远”不能修饰与自己直接相关的“我的事”，搭配不通。"}], "explanations": {"应分": "应分作形容词，表示分内应当做的，此处修饰“事”，正确。", "冰冷": "语义：“冰冷”形容温度或态度，用来修饰“我的事”说不通。", "昂贵": "语义：“昂贵”说价格高，与“你别客气”的语境不合。", "遥远": "搭配：“遥远”不能修饰与自己直接相关的“我的事”，搭配不通。"}, "sentence_index": 0, "correct_answer": "应分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的应分有一米八。", "explanation": "这里应该用〈身高〉。应分说分内应当做的，不能用来说人的身高。"}, {"text": "这辆新车很应分。", "explanation": "这里应该用〈实用〉。应分说分内应做的事，不用来评价物品好不好用。"}, {"text": "这张床很应分，睡得特别香。", "explanation": "这里应该用〈舒服〉。应分表示分内应当，不用来形容床或身体的舒适程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应分", "is_correct": true, "explanation": "应分作形容词，表示分内应当做的，此处修饰“事”，正确。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容心情，帮朋友搬家这件事本身不能说寂寞，说不通。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体，不能修饰“帮朋友搬家”这种行为。"}, {"text": "漆黑", "is_correct": false, "explanation": "搭配：“漆黑”是颜色，不能修饰帮人搬家这类行为，搭配不通。"}], "explanations": {"应分": "应分作形容词，表示分内应当做的，此处修饰“事”，正确。", "寂寞": "语义：“寂寞”形容心情，帮朋友搬家这件事本身不能说寂寞，说不通。", "透明": "语义：“透明”形容物体，不能修饰“帮朋友搬家”这种行为。", "漆黑": "搭配：“漆黑”是颜色，不能修饰帮人搬家这类行为，搭配不通。"}, "sentence_index": 6, "correct_answer": "应分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的应分很重，有一百公斤。", "explanation": "这里应该用〈体重〉。应分说分内应当做的，不能用来说人的体重。"}, {"text": "多吃蔬菜，身体才会应分。", "explanation": "这里应该用〈健康〉。应分不用来形容身体状况。"}, {"text": "这个消息让我很应分。", "explanation": "这里应该用〈高兴〉。应分表示分内应做，不表示人的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "按时打扫卫生是我们应分地的事。", "corrected_sentence": "按时打扫卫生是我们应分的事。", "error_description": "“应分”作形容词修饰名词时应用“的”，不能用状语标记“地”。“应分地的事”把“的”和“地”混用，是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗碗是孩子应分得事。", "corrected_sentence": "洗碗是孩子应分的事。", "error_description": "形容词“应分”修饰名词时要用“的”，不能用“得”。“应分得事”是把“的”写成“得”的错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
