INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96203, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "才学是一个人的本领和学问。", "primary_collocate": null, "pronunciation": "cái xué", "ipa": "tsʰaɪ³⁵ ɕɥɛ³⁵", "syllable_count": 2, "sentences": [{"text": "爷爷一生都很重视才学。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很有才学，书也读得多。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人才学不浅。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都说他才学高。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的才学来自多年的努力。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠才学找到了好工作。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书生因才学受到官员的赏识。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有才学，就写不出这样的文章。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生的才学令人佩服。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但人好，而且才学好。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "才學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "一个人的本领和学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才学", "is_correct": true, "explanation": "才学：一个人的本领和学问，与“爷爷一生都很重视”相符。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是令人烦躁的声音，一生都很重视噪音说不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不是人会重视一生的事物，与语境不符。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“重视”一般搭配学问、健康等抽象事物，不说“重视灰尘”。"}], "explanations": {"才学": "才学：一个人的本领和学问，与“爷爷一生都很重视”相符。", "噪音": "语义：噪音是令人烦躁的声音，一生都很重视噪音说不通。", "汽油": "语义：汽油是燃料，不是人会重视一生的事物，与语境不符。", "灰尘": "搭配：“重视”一般搭配学问、健康等抽象事物，不说“重视灰尘”。"}, "sentence_index": 0, "correct_answer": "才学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的才学很便宜，我买了两件。", "explanation": "这里应该用〈价格〉。才学指本领和学问，说衣服的钱数要用价格，不能用才学。"}, {"text": "他的才学很好，一顿能吃三碗饭。", "explanation": "这里应该用〈胃口〉。才学指本领和学问，不能用来说食量。"}, {"text": "这辆车的才学很快，跑得很稳。", "explanation": "这里应该用〈速度〉。才学不能用来形容车的速度，说车快要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才学", "is_correct": true, "explanation": "才学：本领和学问，书生因此受到官员的赏识，语义完整。"}, {"text": "体力", "is_correct": false, "explanation": "语义：书生受赏识不会因为体力，体力与书生的身份不符。"}, {"text": "身高", "is_correct": false, "explanation": "配价：“赏识”的对象应是才能或品行，身高不能作为受赏识的原因。"}, {"text": "鞋码", "is_correct": false, "explanation": "语义：鞋码是鞋子的尺寸，不能成为受官员赏识的原因。"}], "explanations": {"才学": "才学：本领和学问，书生因此受到官员的赏识，语义完整。", "体力": "语义：书生受赏识不会因为体力，体力与书生的身份不符。", "身高": "配价：“赏识”的对象应是才能或品行，身高不能作为受赏识的原因。", "鞋码": "语义：鞋码是鞋子的尺寸，不能成为受官员赏识的原因。"}, "sentence_index": 6, "correct_answer": "才学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的才学很好，喝一斤也不醉。", "explanation": "这里应该用〈酒量〉。才学指学问和才能，不能用来说喝酒的本事。"}, {"text": "她的才学很好，能看清远处的字。", "explanation": "这里应该用〈视力〉。才学不能用来说眼睛看得清楚，要用视力。"}, {"text": "他的才学很灵，一下就闻出了酒味。", "explanation": "这里应该用〈嗅觉〉。才学指学问和才能，说鼻子灵敏要用嗅觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有很才学，常常帮助别人。", "corrected_sentence": "她很有才学，常常帮助别人。", "error_description": "“很”与“有”的位置错了。“有才学”前要说“很有才学”，“有很才学”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个有才学书生。", "corrected_sentence": "这是一个有才学的书生。", "error_description": "定语后漏了“的”。“有才学”修饰“书生”，要说“有才学的书生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
