INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "才能和学识。", "primary_collocate": null, "pronunciation": "cái xué", "ipa": "tsʰaɪ³⁵ ɕɥɛ³⁵", "syllable_count": 2, "sentences": [{"text": "大家都很佩服他的才学。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很有才学。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凭才学当上了校长。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年轻时就以才学出名。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王很欣赏这个年轻人的才学。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才学远远超过同学们。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家才学出众。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想找有才学的人来帮忙。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的才学让所有人吃惊。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用才学赢得了尊重。", "target_word": "才学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "才學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人的才能和学识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec25c727-e10a-44a8-a064-b66203ddd4c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才学", "is_correct": true, "explanation": "才学：人的才能和学识，与“佩服他的”相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是人可以让别人佩服的才能或学识。"}, {"text": "罪行", "is_correct": false, "explanation": "语义：罪行是犯罪的行为，不值得佩服。"}, {"text": "身高", "is_correct": false, "explanation": "配价：“佩服”的对象应是才能、品德等，身高不能作为佩服的对象。"}], "explanations": {"才学": "才学：人的才能和学识，与“佩服他的”相符。", "体重": "语义：体重是身体的重量，不是人可以让别人佩服的才能或学识。", "罪行": "语义：罪行是犯罪的行为，不值得佩服。", "身高": "配价：“佩服”的对象应是才能、品德等，身高不能作为佩服的对象。"}, "sentence_index": 0, "correct_answer": "才学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱苹果的才学很贵，我没买。", "explanation": "这里应该用〈价格〉。才学指才能和学识，说苹果的钱数要用价格，不能用才学。"}, {"text": "他很有才学，能跑完一场马拉松。", "explanation": "这里应该用〈体力〉。才学指学问和才能，说跑步的耐力要用体力。"}, {"text": "他的才学很好听，唱歌很动人。", "explanation": "这里应该用〈嗓音〉。才学不能形容声音，说歌声好听要用嗓音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才学", "is_correct": true, "explanation": "才学：才能和学识，与“这位作家”和“出众”相符。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命是生存的年限，“寿命出众”说不通，与作家的才能无关。"}, {"text": "价钱", "is_correct": false, "explanation": "搭配：“出众”形容才能、成绩或外貌，不说价钱出众。"}, {"text": "车速", "is_correct": false, "explanation": "语义：车速是车辆的行驶速度，与作家无关，“作家车速出众”说不通。"}], "explanations": {"才学": "才学：才能和学识，与“这位作家”和“出众”相符。", "寿命": "语义：寿命是生存的年限，“寿命出众”说不通，与作家的才能无关。", "价钱": "搭配：“出众”形容才能、成绩或外貌，不说价钱出众。", "车速": "语义：车速是车辆的行驶速度，与作家无关，“作家车速出众”说不通。"}, "sentence_index": 6, "correct_answer": "才学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的才学很美，人人都夸。", "explanation": "这里应该用〈容貌〉。才学指学识和才能，形容长相要用容貌。"}, {"text": "他的才学高大，很结实。", "explanation": "这里应该用〈身材〉。才学不能形容人的体格，高大结实要用身材。"}, {"text": "这幅画的才学很鲜艳。", "explanation": "这里应该用〈颜色〉。才学不能形容颜色，说画面鲜艳要用颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个有才学人。", "corrected_sentence": "他是一个有才学的人。", "error_description": "定语后漏了“的”。“有才学”修饰“人”，要说“有才学的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一位很有才学老师。", "corrected_sentence": "她是一位很有才学的老师。", "error_description": "定语后漏了“的”。“很有才学”修饰“老师”，要说“很有才学的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7686a2eb-8c5a-439d-bd97-8705a94edbe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
