INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "排队是一个接着一个站成一排。", "primary_collocate": null, "pronunciation": "pái duì", "ipa": "pʰaɪ˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "学生们在门口排队。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家排队上车。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们排队走进教室。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在车站排队等车。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让小朋友排队洗手。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市门口排队的人很多。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在门口排队。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在路边排队等车。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天公园门口有人排队。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你们不要乱，要排队。", "target_word": "排队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排过队", "label": "体标"}, {"form": "排了队", "label": "体标"}], "register": "中性", "sense_fingerprint": "人一个接一个站成一排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd92a59cf-6673-4b7a-9df1-a19597e37236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排队", "is_correct": true, "explanation": "正确：排队指人一个接一个站成一排，符合学生在门口等候的语境。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：门口没有水，学生们在门口不能游泳。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：门口是公共通道，不是洗澡的地方，句子不通。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：学生在门口午睡不合常理，句子意思不通。"}], "explanations": {"排队": "正确：排队指人一个接一个站成一排，符合学生在门口等候的语境。", "游泳": "语义：门口没有水，学生们在门口不能游泳。", "洗澡": "语义：门口是公共通道，不是洗澡的地方，句子不通。", "午睡": "语义：学生在门口午睡不合常理，句子意思不通。"}, "sentence_index": 0, "correct_answer": "排队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些积木按颜色排队摆好。", "explanation": "这里应该用〈排列〉。排队的主语指人，表示人按次序站成行；按颜色摆放物品要说排列。"}, {"text": "他这次考试排队第三。", "explanation": "这里应该用〈排名〉。排队指人站成行等候，表示名次要说排名。"}, {"text": "他在争论中排队。", "explanation": "这里应该用〈站队〉。站队指在争论中表明立场，排队只表示站成行列，不表示选边。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排队", "is_correct": true, "explanation": "正确：排队指人站成一排等候，老师让学生在门口这样做，语义通顺。"}, {"text": "蹦极", "is_correct": false, "explanation": "语义：门口没有蹦极设施，学校里不会让学生在门口蹦极。"}, {"text": "跳水", "is_correct": false, "explanation": "语义：门口没有水池，老师不会让学生在门口跳水。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：老师让学生在门口午睡不合常理，句子意思不通。"}], "explanations": {"排队": "正确：排队指人站成一排等候，老师让学生在门口这样做，语义通顺。", "蹦极": "语义：门口没有蹦极设施，学校里不会让学生在门口蹦极。", "跳水": "语义：门口没有水池，老师不会让学生在门口跳水。", "午睡": "语义：老师让学生在门口午睡不合常理，句子意思不通。"}, "sentence_index": 6, "correct_answer": "排队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天演出，我们今天要排队这个舞蹈。", "explanation": "这里应该用〈排练〉。排队指人站成行列，不能带“舞蹈”作宾语；反复练习节目要说排练。"}, {"text": "工人们正在排队路上的障碍。", "explanation": "这里应该用〈排除〉。排队指人站成行列，不能带宾语；去除障碍要说排除。"}, {"text": "这篇文章需要排队。", "explanation": "这里应该用〈排版〉。排队指人站成行，排版才是安排印刷版面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们在食堂门口被排队买饭。", "corrected_sentence": "学生们在食堂门口排队买饭。", "error_description": "“被排队”是被动误用，正确形式为“排队”。排队是不及物动词，不能加“被”带出被动句，“被”要去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学后我们在校门口被排队回家。", "corrected_sentence": "放学后我们在校门口排队回家。", "error_description": "“被排队”是被动误用，正确形式为“排队”。排队是不及物动词，不能加“被”带出被动句，“被”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
