INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "方言是一个地方的人说的话，和别的地方有点不一样。", "primary_collocate": null, "pronunciation": "fāng yán", "ipa": "faŋ˥˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我奶奶说的是方言。", "target_word": "方言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地方的方言很好听。", "target_word": "方言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一回家就说方言。", "target_word": "方言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我听不懂四川的方言。", "target_word": "方言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京和上海的方言不一样。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷教我说了几句方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们用方言唱了一首歌。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在小城里，老人们都说着方言。", "target_word": "方言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她来北京以后，很少说方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学几句广东的方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种方言", "label": "量词"}, {"form": "方言区", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方的人说的、和别处不同的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96207, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。fāng yán 指一个地方的人说的、和别处不同的话。"}, {"text": "放言", "is_correct": false, "explanation": "放言（fàng yán）第一音节声调与 fāng 不同，意思是毫无顾忌地发表言论。"}, {"text": "房檐", "is_correct": false, "explanation": "房檐（fáng yán）第一音节声调与 fāng 不同，意思是屋顶向外伸出的部分。"}, {"text": "方眼", "is_correct": false, "explanation": "方眼（fāng yǎn）第二音节声调与 yán 不同，意思是方形的小孔。"}], "explanations": {"方言": "正确。fāng yán 指一个地方的人说的、和别处不同的话。", "放言": "放言（fàng yán）第一音节声调与 fāng 不同，意思是毫无顾忌地发表言论。", "房檐": "房檐（fáng yán）第一音节声调与 fāng 不同，意思是屋顶向外伸出的部分。", "方眼": "方眼（fāng yǎn）第二音节声调与 yán 不同，意思是方形的小孔。"}, "sentence_index": null, "correct_answer": "方言"}, "level_3": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。“我奶奶说的是”后面接的是她说的话，方言符合这个语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以说的话题，“我奶奶说的是冰箱”讲不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“说”不接乐器作说的内容，说话的对象应是语言或话题。"}, {"text": "三明治", "is_correct": false, "explanation": "语义：三明治是食物，不能作为“说的是”的内容。"}], "explanations": {"方言": "正确。“我奶奶说的是”后面接的是她说的话，方言符合这个语境。", "冰箱": "语义：冰箱不是可以说的话题，“我奶奶说的是冰箱”讲不通。", "钢琴": "搭配：“说”不接乐器作说的内容，说话的对象应是语言或话题。", "三明治": "语义：三明治是食物，不能作为“说的是”的内容。"}, "sentence_index": 0, "correct_answer": "方言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我会说一只方言。", "explanation": "这里应该用〈种〉。〈只〉用于动物或成对的东西，方言要用“一种方言”。"}, {"text": "我会说一把方言。", "explanation": "这里应该用〈种〉。〈把〉用于有柄或能握住的东西，不能用来数方言。"}, {"text": "我会说一条方言。", "explanation": "这里应该用〈种〉。〈条〉多用于河流、蛇等细长的东西，方言要用“一种方言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。“用方言唱歌”指用某地的话来唱，符合这个语境。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是写字用的工具，不能用来唱歌。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“唱”的凭借应是语言或声音，钢笔这类书写工具不能用在这里。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是唱歌的媒介，“用汽车唱歌”讲不通。"}], "explanations": {"方言": "正确。“用方言唱歌”指用某地的话来唱，符合这个语境。", "粉笔": "语义：粉笔是写字用的工具，不能用来唱歌。", "钢笔": "搭配：“唱”的凭借应是语言或声音，钢笔这类书写工具不能用在这里。", "汽车": "语义：汽车不是唱歌的媒介，“用汽车唱歌”讲不通。"}, "sentence_index": 6, "correct_answer": "方言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "联合国规定了六种官方方言。", "explanation": "这里应该用〈语言〉。方言只在某一地区使用，不能作为国际组织的官方用语。"}, {"text": "普通话是全国通用的方言。", "explanation": "这里应该用〈语言〉。方言指某一地区使用、有别于通用语的地方话，不能说“全国通用的方言”。"}, {"text": "他在会上做了一个方言。", "explanation": "这里应该用〈发言〉。方言指某一地区使用的地方话，不能指在会上讲的话；会上讲话要用“发言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我奶奶说的是一只方言。", "corrected_sentence": "我奶奶说的是一种方言。", "error_description": "量词错误：“方言”应该用量词“种”，“只”用于动物或成对的东西，不能用来数方言。正确说法是“一种方言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想跟奶奶学几句的方言。", "corrected_sentence": "我想跟奶奶学几句方言。", "error_description": "结构助词错误：数量短语“几句”直接修饰名词时中间不加“的”，应说“学几句方言”，多出的“的”使短语不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
