INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一地区使用的、有别于通用语的地方话。", "primary_collocate": null, "pronunciation": "fāng yán", "ipa": "faŋ˥˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个地区有自己的方言。", "target_word": "方言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "方言和普通话有很多不同。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多孩子只会说普通话，不会说方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请我们用方言说一个故事。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个地方的方言都有自己的特点。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家喜欢在书里写方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方的方言比北方的复杂。", "target_word": "方言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里要说普通话，回家可以说方言。", "target_word": "方言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把家乡的方言教给了女儿。", "target_word": "方言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去过的小城里，人们都说方言。", "target_word": "方言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种方言", "label": "量词"}, {"form": "方言区", "label": "复合"}], "register": "中性", "sense_fingerprint": "某地区使用、有别于通用语的地方话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。fāng yán 指某地区使用、有别于通用语的地方话。"}, {"text": "放言", "is_correct": false, "explanation": "放言（fàng yán）第一音节声调与 fāng 不同，意思是毫无顾忌地发表言论。"}, {"text": "房檐", "is_correct": false, "explanation": "房檐（fáng yán）第一音节声调与 fāng 不同，意思是屋顶向外伸出的部分。"}, {"text": "方眼", "is_correct": false, "explanation": "方眼（fāng yǎn）第二音节声调与 yán 不同，意思是方形的小孔。"}], "explanations": {"方言": "正确。fāng yán 指某地区使用、有别于通用语的地方话。", "放言": "放言（fàng yán）第一音节声调与 fāng 不同，意思是毫无顾忌地发表言论。", "房檐": "房檐（fáng yán）第一音节声调与 fāng 不同，意思是屋顶向外伸出的部分。", "方眼": "方眼（fāng yǎn）第二音节声调与 yán 不同，意思是方形的小孔。"}, "sentence_index": null, "correct_answer": "方言"}, "level_3": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。“这个地区有自己的”后面接的是地区的语言特点，方言符合这个语境。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“有自己的”不接身体部位来指地区的特点。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：地区没有“自己的冰箱”这种说法，讲不通。"}, {"text": "三角形", "is_correct": false, "explanation": "语义：三角形是几何图形，不属于一个地区的特点。"}], "explanations": {"方言": "正确。“这个地区有自己的”后面接的是地区的语言特点，方言符合这个语境。", "手指": "搭配：“有自己的”不接身体部位来指地区的特点。", "冰箱": "语义：地区没有“自己的冰箱”这种说法，讲不通。", "三角形": "语义：三角形是几何图形，不属于一个地区的特点。"}, "sentence_index": 0, "correct_answer": "方言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份国际条约用的是一种方言。", "explanation": "这里应该用〈语言〉。国际条约需要通行的语言，方言只在某一地区通行。"}, {"text": "这门全国通用的方言，各地的人都能听懂。", "explanation": "这里应该用〈普通话〉。方言只在某一地区通行，不能说“全国通用”。"}, {"text": "他想出了一个好方言，很快解决了问题。", "explanation": "这里应该用〈方法〉。方言指地方话，不能指解决问题的办法；办法要用“方法”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方言", "is_correct": true, "explanation": "正确。“南方的方言比北方的复杂”指两地方言的差异，符合这个语境。"}, {"text": "小鸡", "is_correct": false, "explanation": "语义：小鸡不是可以比较“复杂”程度的事物，“南方的小鸡比北方的复杂”讲不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“南方的月亮比北方的复杂”讲不通，月亮不是可比较复杂程度的事物。"}, {"text": "星期一", "is_correct": false, "explanation": "语义：星期一是日期，不是可以比较“复杂”程度的事物，讲不通。"}], "explanations": {"方言": "正确。“南方的方言比北方的复杂”指两地方言的差异，符合这个语境。", "小鸡": "语义：小鸡不是可以比较“复杂”程度的事物，“南方的小鸡比北方的复杂”讲不通。", "月亮": "语义：“南方的月亮比北方的复杂”讲不通，月亮不是可比较复杂程度的事物。", "星期一": "语义：星期一是日期，不是可以比较“复杂”程度的事物，讲不通。"}, "sentence_index": 6, "correct_answer": "方言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去过的小城里，人们都说一架方言。", "explanation": "这里应该用〈种〉。〈架〉用于飞机、机器等有架子的东西，方言要用“一种方言”。"}, {"text": "我们去过的小城里，人们都说一张方言。", "explanation": "这里应该用〈种〉。〈张〉用于纸、桌子等平面的东西，不能用来数方言。"}, {"text": "我们去过的小城里，人们都说一本方言。", "explanation": "这里应该用〈种〉。〈本〉用于书籍、本子，方言要用“一种方言”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶总是说的方言。", "corrected_sentence": "奶奶总是说方言。", "error_description": "结构助词错误：“说方言”是动宾结构作谓语，中间不能插入“的”；“说的方言”是定语结构，不能单独作谓语。正确说法是“奶奶总是说方言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会说一条方言，很难懂。", "corrected_sentence": "他会说一种方言，很难懂。", "error_description": "量词错误：“方言”应该用量词“种”，不能用“条”。正确说法是“一种方言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明日", "is_correct": true, "explanation": "“明日”指今天之后的一天，与“昨日”互为反义。"}, {"text": "下午", "is_correct": false, "explanation": "“下午”指中午到晚上之前的时段，与“昨日”没有反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周末尾的休息日，与“昨日”没有反义关系。"}, {"text": "节日", "is_correct": false, "explanation": "“节日”指特定的庆祝日子，与“昨日”没有反义关系。"}], "correct_answer": "明日", "explanations": {"明日": "“明日”指今天之后的一天，与“昨日”互为反义。", "下午": "“下午”指中午到晚上之前的时段，与“昨日”没有反义关系。", "周末": "“周末”指一周末尾的休息日，与“昨日”没有反义关系。", "节日": "“节日”指特定的庆祝日子，与“昨日”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明日", "is_correct": true, "explanation": "“明日”指今天之后的一天，与“昨日”互为反义。"}, {"text": "傍晚", "is_correct": false, "explanation": "“傍晚”指天快黑的时候，与“昨日”没有反义关系。"}, {"text": "早晨", "is_correct": false, "explanation": "“早晨”指天刚亮的时段，与“昨日”没有反义关系。"}, {"text": "时候", "is_correct": false, "explanation": "“时候”泛指一段时间，与“昨日”没有反义关系。"}], "correct_answer": "明日", "explanations": {"明日": "“明日”指今天之后的一天，与“昨日”互为反义。", "傍晚": "“傍晚”指天快黑的时候，与“昨日”没有反义关系。", "早晨": "“早晨”指天刚亮的时段，与“昨日”没有反义关系。", "时候": "“时候”泛指一段时间，与“昨日”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "昨日是今天的前一天。", "primary_collocate": null, "pronunciation": "zuó rì", "ipa": "tswo³⁵ ʐɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "昨日是星期五，今天是星期六。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是十号，昨日是九号。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日下了一场大雨。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日晚上，我们一起吃了饭。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨日去了图书馆，今天在家。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日天气很冷，今天暖和多了。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日的作业，今天老师已经看完了。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨日没来上课，今天来了。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日我还在北京，今天就到上海了。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说昨日是她的生日。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "今天的前一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨日", "is_correct": true, "explanation": "“昨日”指今天的前一天，与“是星期五，今天是星期六”的语境相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”在今天之后，“明天是星期五”与“今天是星期六”矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：“去年”不能与具体的星期几搭配。"}, {"text": "今天", "is_correct": false, "explanation": "语义：同一个“今天”不能同时是星期五和星期六。"}], "explanations": {"昨日": "“昨日”指今天的前一天，与“是星期五，今天是星期六”的语境相符。", "明天": "语义：“明天”在今天之后，“明天是星期五”与“今天是星期六”矛盾。", "去年": "搭配：“去年”不能与具体的星期几搭配。", "今天": "语义：同一个“今天”不能同时是星期五和星期六。"}, "sentence_index": 0, "correct_answer": "昨日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛昨日会开始，大家都很期待。", "explanation": "这里应该用〈明天〉。昨日指已经过去的一天，不能和表示将来的“会”一起用。"}, {"text": "我们昨日一共旅行了五天。", "explanation": "这里应该用〈上个月〉。昨日只指今天的前一天，一天之内不可能旅行五天。"}, {"text": "昨日夏天，我们一起去了海边。", "explanation": "这里应该用〈去年〉。昨日只指今天的前一天，不能用来指一个季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨日", "is_correct": true, "explanation": "“昨日”指今天的前一天，与“今天老师已经看完了”的时间安排相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指今天之后的一天，今天不可能已经看完明天的作业。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指尚未到来的时间，今天不可能已经看完将来的作业。"}, {"text": "后天", "is_correct": false, "explanation": "语义：“后天”指两天之后，与“今天老师已经看完了”矛盾。"}], "explanations": {"昨日": "“昨日”指今天的前一天，与“今天老师已经看完了”的时间安排相符。", "明天": "语义：“明天”指今天之后的一天，今天不可能已经看完明天的作业。", "将来": "语义：“将来”指尚未到来的时间，今天不可能已经看完将来的作业。", "后天": "语义：“后天”指两天之后，与“今天老师已经看完了”矛盾。"}, "sentence_index": 6, "correct_answer": "昨日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨日经常跑步，身体很好。", "explanation": "这里应该用〈平时〉。昨日指今天的前一天这一具体的一天，不能用来表示经常、反复做的事。"}, {"text": "我昨日每天都给妈妈打电话。", "explanation": "这里应该用〈以前〉。昨日只指一天，不能表示每天重复的动作。"}, {"text": "我昨日永远记得你，这是真的。", "explanation": "这里应该用〈一直〉。昨日指一个具体的日子，不能表示长久持续的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨日的去超市买了一些水果。", "corrected_sentence": "我昨日去超市买了一些水果。", "error_description": "“昨日”修饰动词时不能加“的”。错误：“昨日的去超市”；正确：“昨日去超市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨日的去书店买了一本词典。", "corrected_sentence": "我昨日去书店买了一本词典。", "error_description": "“昨日”修饰动词时不加“的”（“昨日的作业”中的“的”只用于修饰名词）。错误：“昨日的去书店”；正确：“昨日去书店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明日", "is_correct": true, "explanation": "“明日”指今天之后的一天，与“昨日”互为反义。"}, {"text": "周末", "is_correct": false, "explanation": "“周末”指一周末尾的休息日，与“昨日”没有反义关系。"}, {"text": "节日", "is_correct": false, "explanation": "“节日”指特定的庆祝日子，与“昨日”没有反义关系。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”泛指时间本身，与“昨日”没有反义关系。"}], "correct_answer": "明日", "explanations": {"明日": "“明日”指今天之后的一天，与“昨日”互为反义。", "周末": "“周末”指一周末尾的休息日，与“昨日”没有反义关系。", "节日": "“节日”指特定的庆祝日子，与“昨日”没有反义关系。", "时间": "“时间”泛指时间本身，与“昨日”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明日", "is_correct": true, "explanation": "“明日”指今天之后的一天，与“昨日”互为反义。"}, {"text": "傍晚", "is_correct": false, "explanation": "“傍晚”指天快黑的时候，与“昨日”没有反义关系。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜深的时候，与“昨日”没有反义关系。"}, {"text": "午后", "is_correct": false, "explanation": "“午后”指中午以后的时段，与“昨日”没有反义关系。"}], "correct_answer": "明日", "explanations": {"明日": "“明日”指今天之后的一天，与“昨日”互为反义。", "傍晚": "“傍晚”指天快黑的时候，与“昨日”没有反义关系。", "深夜": "“深夜”指夜深的时候，与“昨日”没有反义关系。", "午后": "“午后”指中午以后的时段，与“昨日”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "昨天。", "primary_collocate": null, "pronunciation": "zuó rì", "ipa": "tswo³⁵ ʐɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "昨日的会议开得很长。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨日买了一本新书。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师昨日在课上讲过这个字。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日下午，妹妹给我打了电话。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨日刚从北京回来。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日我们看了一场电影。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日天黑以后，他才回家。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨日一整天都在家里休息。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨日刚下过雨，路上还是湿的。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨日没带手机，所以没接到电话。", "target_word": "昨日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "昨天（书面说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ae03713-7b77-404a-928c-a57fedb969c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨日", "is_correct": true, "explanation": "“昨日”指今天的前一天，与“开得很长”所说的已经开过的会议相符。"}, {"text": "后天", "is_correct": false, "explanation": "语义：“后天”指两天之后，还没有发生，不能说已经开完的会议开得很长。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不是时间，不能修饰“会议”作时间定语。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“开得很长”所说的已经发生的会议矛盾。"}], "explanations": {"昨日": "“昨日”指今天的前一天，与“开得很长”所说的已经开过的会议相符。", "后天": "语义：“后天”指两天之后，还没有发生，不能说已经开完的会议开得很长。", "天气": "搭配：“天气”不是时间，不能修饰“会议”作时间定语。", "明天": "语义：“明天”指将来，与“开得很长”所说的已经发生的会议矛盾。"}, "sentence_index": 0, "correct_answer": "昨日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日的会议将在下午举行。", "explanation": "这里应该用〈明天〉。昨日指已经过去的一天，不能和表示将来的“将在”连用。"}, {"text": "这个问题我昨日已经研究了三年。", "explanation": "这里应该用〈以前〉。昨日指今天的前一天，不能表示三年这样的长时段。"}, {"text": "昨日冬天，我们在北方过年。", "explanation": "这里应该用〈去年〉。昨日只指今天的前一天，不能用来指一个季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨日", "is_correct": true, "explanation": "“昨日”指今天的前一天，与“天黑以后，他才回家”的情境相符。"}, {"text": "早上", "is_correct": false, "explanation": "语义：早上天还亮着，不会天黑，与“天黑以后”矛盾。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”需带具体的星期几，不能作时间状语。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨是天刚亮的时候，与“天黑”矛盾。"}], "explanations": {"昨日": "“昨日”指今天的前一天，与“天黑以后，他才回家”的情境相符。", "早上": "语义：早上天还亮着，不会天黑，与“天黑以后”矛盾。", "星期": "搭配：“星期”需带具体的星期几，不能作时间状语。", "清晨": "语义：清晨是天刚亮的时候，与“天黑”矛盾。"}, "sentence_index": 6, "correct_answer": "昨日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "等昨日我再去找你吧。", "explanation": "这里应该用〈下周〉。“等……再……”后面接的是将来的时间，昨日已经过去，不能用在这里。"}, {"text": "你放心，昨日一定会来参加比赛。", "explanation": "这里应该用〈后天〉。“一定会”表示将来，昨日指已经过去的一天，两者不能连用。"}, {"text": "昨日夏天，我们都会去海边。", "explanation": "这里应该用〈每年〉。昨日只指今天的前一天，不能表示每年重复发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨日的和朋友去逛了街。", "corrected_sentence": "我昨日和朋友去逛了街。", "error_description": "“昨日”作时间状语后不能加“的”。错误：“昨日的和朋友”；正确：“昨日和朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨日的在超市遇见了老同学。", "corrected_sentence": "我昨日在超市遇见了老同学。", "error_description": "“昨日”作时间状语，后面不加“的”。错误：“昨日的在超市”；正确：“昨日在超市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f12b650e-9f76-45c1-a843-af06fa3a9838') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
