INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96211, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "暗杀是偷偷地把人杀死。", "primary_collocate": null, "pronunciation": "àn shā", "ipa": "an˥˩ ʂa˥", "syllable_count": 2, "sentences": [{"text": "有人想暗杀这位市长。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人晚上跟着他，想暗杀他。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现有人要暗杀总统。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里，坏人想暗杀国王。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们计划了很久，要暗杀那个老板。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的杀手在车里暗杀了他。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕有人暗杀他，所以不敢出门。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上有很多人想暗杀皇帝。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了想暗杀他的人。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有公开动手，而是想暗杀对方。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗杀了", "label": "体标"}, {"form": "暗杀过", "label": "体标"}, {"form": "暗杀者", "label": "复合"}], "register": "书面语", "sense_fingerprint": "偷偷地把人杀死（行为方式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的常见意思是进食，“想吃这位市长”读来荒谬，与“有人想……”的语境不合。"}, {"text": "暗杀", "is_correct": true, "explanation": "正确。暗杀是偷偷杀人，符合“有人想……这位市长”的语境。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”多用于动物、婴儿或病人，不说“喂这位市长”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是物品或身体，“想洗这位市长”读来荒谬。"}], "explanations": {"吃": "语义：“吃”的常见意思是进食，“想吃这位市长”读来荒谬，与“有人想……”的语境不合。", "暗杀": "正确。暗杀是偷偷杀人，符合“有人想……这位市长”的语境。", "喂": "搭配：“喂”多用于动物、婴儿或病人，不说“喂这位市长”。", "洗": "语义：“洗”的对象是物品或身体，“想洗这位市长”读来荒谬。"}, "sentence_index": 0, "correct_answer": "暗杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大庭广众之下暗杀了对方。", "explanation": "这里应该用〈刺杀〉。暗杀强调秘密地杀人，与“大庭广众之下”相矛盾；公开行凶要用刺杀。"}, {"text": "他因为暗杀罪被判了十年。", "explanation": "这里应该用〈谋杀〉。谋杀是法律上的罪名，“暗杀”描述的是一种行为方式，不是罪名。"}, {"text": "敌人一连暗杀了他三天三夜，他才逃出了城。", "explanation": "这里应该用〈追杀〉。暗杀是一次秘密的杀人行动，不能持续数日；一路追赶、反复加害要说“追杀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吻", "is_correct": false, "explanation": "语义：“吻”不会让人怕到不敢出门，与“怕”的理由不合。"}, {"text": "暗杀", "is_correct": true, "explanation": "正确。暗杀是秘密杀人，正好解释“他怕有人……所以不敢出门”。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：怕被祝福并不会让人不敢出门，句子读来不合常理。"}, {"text": "拜", "is_correct": false, "explanation": "搭配：“拜”多接“师”“访”等，“拜他”不是常用搭配，也不表示威胁。"}], "explanations": {"吻": "语义：“吻”不会让人怕到不敢出门，与“怕”的理由不合。", "暗杀": "正确。暗杀是秘密杀人，正好解释“他怕有人……所以不敢出门”。", "祝福": "语义：怕被祝福并不会让人不敢出门，句子读来不合常理。", "拜": "搭配：“拜”多接“师”“访”等，“拜他”不是常用搭配，也不表示威胁。"}, "sentence_index": 6, "correct_answer": "暗杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在背后暗杀了我，结果我只是丢了工作。", "explanation": "这里应该用〈暗算〉。暗杀是杀死人，而这里对方只让我丢了工作，应说“暗算”（暗中算计陷害）。"}, {"text": "他一直想暗杀那道数学题。", "explanation": "这里应该用〈攻克〉。暗杀的对象是人，攻克难题要说“攻克”。"}, {"text": "敌军在城里暗杀了全部老百姓。", "explanation": "这里应该用〈屠杀〉。暗杀针对特定的人，大批平民遇害要说“屠杀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个杀手没有暗杀了那位总统。", "corrected_sentence": "那个杀手没有暗杀那位总统。", "error_description": "用“没有”否定动作时，动词后不能再加“了”；应说“没有暗杀那位总统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这辈子从来没暗杀谁过。", "corrected_sentence": "他这辈子从来没暗杀过谁。", "error_description": "“过”要紧跟动词，应说“暗杀过谁”，不能放在宾语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96212, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
