INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96212, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "秘密地杀害某人。", "primary_collocate": null, "pronunciation": "àn shā", "ipa": "an˥˩ ʂa˥", "syllable_count": 2, "sentences": [{"text": "杀手秘密接近他，准备暗杀他。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人暗杀过这位将军，但没有成功。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人派人去暗杀那位将军。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在夜里暗杀了一个官员。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一个想暗杀国王的人。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想伤害别人，更不会暗杀谁。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，有人想暗杀这位记者。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个杀手专门替人暗杀仇家。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王怕有人暗杀他，身边总有很多人。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了钱，答应去暗杀那个商人。", "target_word": "暗杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗杀了", "label": "体标"}, {"form": "暗杀过", "label": "体标"}, {"form": "暗杀者", "label": "复合"}], "register": "书面语", "sense_fingerprint": "秘密地杀害特定的人（针对某个对象）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是公开表示好意，与“秘密接近”的意图矛盾。"}, {"text": "暗杀", "is_correct": true, "explanation": "正确。暗杀与“秘密接近”的意图一致。"}, {"text": "救助", "is_correct": false, "explanation": "语义：“救助”是帮人脱离危险，与杀手的意图完全相反。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：杀手秘密接近目标是为了下手，不是为了“表扬”他。"}], "explanations": {"欢迎": "语义：“欢迎”是公开表示好意，与“秘密接近”的意图矛盾。", "暗杀": "正确。暗杀与“秘密接近”的意图一致。", "救助": "语义：“救助”是帮人脱离危险，与杀手的意图完全相反。", "表扬": "语义：杀手秘密接近目标是为了下手，不是为了“表扬”他。"}, "sentence_index": 0, "correct_answer": "暗杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "歹徒在夜里暗杀了一个官员，还要求赎金。", "explanation": "这里应该用〈绑架〉。暗杀会让对方死亡，就无法再要求赎金；要赎金说明人质还活着，应说“绑架”。"}, {"text": "比赛中他故意暗杀对手的膝盖。", "explanation": "这里应该用〈伤害〉。暗杀是杀死人，不能说“暗杀膝盖”；伤到身体部位要说“伤害”。"}, {"text": "猎人在夜里暗杀了一只狼。", "explanation": "这里应该用〈猎杀〉。暗杀的对象是人，捕杀野生动物要说“猎杀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“想吃这位记者”不合常理。"}, {"text": "暗杀", "is_correct": true, "explanation": "正确。暗杀是秘密杀人，符合“警察说有人想……”的威胁语境。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”多用于动物、婴儿或病人，不说“喂这位记者”。"}, {"text": "拜", "is_correct": false, "explanation": "搭配：“拜”多接“师”“访”等，“拜这位记者”不是常用搭配。"}], "explanations": {"吃": "语义：“吃”的对象是食物，“想吃这位记者”不合常理。", "暗杀": "正确。暗杀是秘密杀人，符合“警察说有人想……”的威胁语境。", "喂": "搭配：“喂”多用于动物、婴儿或病人，不说“喂这位记者”。", "拜": "搭配：“拜”多接“师”“访”等，“拜这位记者”不是常用搭配。"}, "sentence_index": 6, "correct_answer": "暗杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在背后暗杀了我的同事，让他丢了工作。", "explanation": "这里应该用〈暗算〉。暗杀是杀死人，而这里只是让同事丢了工作，应说“暗算”（暗中算计陷害）。"}, {"text": "他因为暗杀罪被关了十年。", "explanation": "这里应该用〈谋杀〉。谋杀是法律上的罪名，“暗杀”描述的是行为方式，不是罪名。"}, {"text": "他当着众人的面暗杀了那个陌生人，连一句话都没说。", "explanation": "这里应该用〈刺杀〉。暗杀强调秘密下手，当着众人动手要说“刺杀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们没有暗杀了那个邻居。", "corrected_sentence": "他们没有暗杀那个邻居。", "error_description": "用“没有”否定动作时，动词后不能再加“了”；应说“没有暗杀那个邻居”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个杀手从来没暗杀着政客。", "corrected_sentence": "那个杀手从来没暗杀过政客。", "error_description": "体标错误：表示从未有过的经历要用“过”，“着”表示动作持续，与“从来没”不搭配。正确形式是“暗杀过政客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
