INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "最高等是排在最上面的一等。", "primary_collocate": null, "pronunciation": "zuì gāo děng", "ipa": "tsuei˥˩ kau˥ təŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家饭店的服务是最高等的。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的毕业论文拿到了最高等。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶叶是最高等的，价钱也很贵。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛分成三等，他拿到了最高等。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果都是最高等的，请放心吃。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这篇作文评为最高等。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过鉴定，这块玉列为最高等。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的服务分三等，我们选了最高等。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种钢材按质量分三等，其中最高等的很少。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把他的画评为最高等，还给了他一个大奖。", "target_word": "最高等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "排在最上面的一等，指分等时位置最靠上的那一档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0aec723e-4c3d-4b32-a6e4-74bef640e8d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最高等", "is_correct": true, "explanation": "正确。最高等指分等评定中最上面的一档，与“服务”的评价语境相符。"}, {"text": "最胖", "is_correct": false, "explanation": "体貌：“胖”只用于人或动物的体形，不能用来评价饭店的服务。"}, {"text": "最大", "is_correct": false, "explanation": "搭配：“服务”说质量和水平，不说“最大”，“大”指体积或规模。"}, {"text": "最古老", "is_correct": false, "explanation": "语义：服务没有年代久远的问题，“古老”指历史悠久的事物，与句意不符。"}], "explanations": {"最高等": "正确。最高等指分等评定中最上面的一档，与“服务”的评价语境相符。", "最胖": "体貌：“胖”只用于人或动物的体形，不能用来评价饭店的服务。", "最大": "搭配：“服务”说质量和水平，不说“最大”，“大”指体积或规模。", "最古老": "语义：服务没有年代久远的问题，“古老”指历史悠久的事物，与句意不符。"}, "sentence_index": 0, "correct_answer": "最高等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的音量最高等。", "explanation": "这里应该用〈最大〉。音量指声音的强弱，比较多少用最大；〈最高等〉只用于分等级的事物。"}, {"text": "今天的天气是最高等的。", "explanation": "这里应该用〈最好〉。天气的好坏用“最好”描述，〈最高等〉说的是等级，不用于天气。"}, {"text": "这条河的长度最高等。", "explanation": "这里应该用〈最长〉。长度比较长短用最长，〈最高等〉说的是等级，不用于长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最高等", "is_correct": true, "explanation": "正确。鉴定后按等级归类，“列为最高等”指被定为最上一档。"}, {"text": "最漂亮", "is_correct": false, "explanation": "语义：鉴定列等的依据是质量等级，“漂亮”只描述外观，不能用来归等。"}, {"text": "最长", "is_correct": false, "explanation": "搭配：“列为”后接等级或类别，不接“最长”，“长”说的是长度。"}, {"text": "最年轻", "is_correct": false, "explanation": "语义：玉没有年龄，“年轻”不能用来形容鉴定的结果。"}], "explanations": {"最高等": "正确。鉴定后按等级归类，“列为最高等”指被定为最上一档。", "最漂亮": "语义：鉴定列等的依据是质量等级，“漂亮”只描述外观，不能用来归等。", "最长": "搭配：“列为”后接等级或类别，不接“最长”，“长”说的是长度。", "最年轻": "语义：玉没有年龄，“年轻”不能用来形容鉴定的结果。"}, "sentence_index": 6, "correct_answer": "最高等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的重量最高等。", "explanation": "这里应该用〈最重〉。重量比多少用最重，〈最高等〉用于等级评定，不用于重量。"}, {"text": "这次活动的人数最高等。", "explanation": "这里应该用〈最多〉。人数比多少用最多，〈最高等〉说的是等级。"}, {"text": "这个房间的温度最高等。", "explanation": "这里应该用〈最热〉。温度的高低用最热来描述，〈最高等〉不能用于温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台冰箱的质量是很最高等的。", "corrected_sentence": "这台冰箱的质量是最高等的。", "error_description": "错误：在〈最高等〉前加了〈很〉。最高等本身已表示最高，不能再与〈很〉连用，应去掉〈很〉，改为“是最高等的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批茶叶经过检验，评为最最高等。", "corrected_sentence": "这批茶叶经过检验，评为最高等。", "error_description": "错误：〈最高等〉前多了一个“最”。最高等本身已含“最”，不能再重复，应改为“评为最高等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
