INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96215, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96215, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "月亮是晚上挂在天上的亮亮的圆东西。", "primary_collocate": null, "pronunciation": "yuè liang", "ipa": "ɥɛ˥˩ ljɑŋ", "syllable_count": 2, "sentences": [{"text": "晚上，月亮挂在天上，又圆又亮。", "target_word": "月亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的月亮真圆啊！", "target_word": "月亮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和奶奶坐在院子里看月亮。", "target_word": "月亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "月亮出来了，天上有很多星星。", "target_word": "月亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友指着月亮说：“它像一个大盘子。”", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮今天晚上很亮，路上不黑。", "target_word": "月亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云把月亮挡住了，什么也看不见。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮从云后面慢慢露出来了。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天看见了一个很大的月亮。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的月亮像一个白白的大饼。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "轮", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "月亮：夜晚天上看得见的又圆又亮的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月亮", "is_correct": true, "explanation": "正确：晚上挂在天上、又圆又亮的是月亮。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是白天出现的，与句中的“晚上”冲突。"}, {"text": "云", "is_correct": false, "explanation": "搭配：云不能用“又圆又亮”来形容，句子说不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹出现在雨后的天空，不会在晚上挂着又圆又亮的一个东西。"}], "explanations": {"月亮": "正确：晚上挂在天上、又圆又亮的是月亮。", "太阳": "语义：太阳是白天出现的，与句中的“晚上”冲突。", "云": "搭配：云不能用“又圆又亮”来形容，句子说不通。", "彩虹": "语义：彩虹出现在雨后的天空，不会在晚上挂着又圆又亮的一个东西。"}, "sentence_index": 0, "correct_answer": "月亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天上挂着一本月亮。", "explanation": "这里不能用“本”（书籍的量词）。月亮应用“轮”或“个”，不用“本”。"}, {"text": "夜里，天上突然下起了月亮，院子里都湿了。", "explanation": "这里应该用〈雨〉。下的是雨或雪，月亮是天体，不能说“下”。"}, {"text": "中午的月亮很热，晒得我们满头大汗。", "explanation": "这里应该用〈太阳〉。白天晒人、发热的是太阳；月亮在夜里出现，不会在中午发热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": true, "explanation": "正确：云遮住的是挂在天上的月亮，“什么也看不见”合理。"}, {"text": "墙", "is_correct": false, "explanation": "语义：云在天上，挡不住地上的墙，句子不合逻辑。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是写在纸上的字，云不能把它挡住，句子说不通。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字写在纸上或牌子上，天上的云挡不住它，句子说不通。"}], "explanations": {"月亮": "正确：云遮住的是挂在天上的月亮，“什么也看不见”合理。", "墙": "语义：云在天上，挡不住地上的墙，句子不合逻辑。", "作业": "语义：作业是写在纸上的字，云不能把它挡住，句子说不通。", "名字": "语义：名字写在纸上或牌子上，天上的云挡不住它，句子说不通。"}, "sentence_index": 6, "correct_answer": "月亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上的月亮特别多，一闪一闪的。", "explanation": "这里应该用〈星星〉。星星有很多颗、会一闪一闪；月亮只有一个，不能说“特别多”。"}, {"text": "窗前飘着一盏白白的月亮。", "explanation": "这里不能用“盏”（灯的量词）。月亮应用“轮”或“个”。"}, {"text": "院子里挂着一排亮亮的月亮。", "explanation": "这里应该用〈灯笼〉。灯笼可以成排挂着；月亮只有一个，不能说“一排”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我抬头看见一只明亮的月亮。", "corrected_sentence": "我抬头看见一轮明亮的月亮。", "error_description": "错误在量词“只”。“只”用于动物等，不能用于月亮。月亮应说“一轮”，正确的是“一轮明亮的月亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月亮从东边的山后慢慢升起去了。", "corrected_sentence": "月亮从东边的山后慢慢升起来了。", "error_description": "错误在趋向补语“去”。“去”表示远离说话人，月亮从山后升起是朝向说话人的方向，应说“升起来”，即“升起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
