INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96216, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球的卫星，夜晚在天空中可见。", "primary_collocate": null, "pronunciation": "yuè liang", "ipa": "ɥɛ˥˩ ljɑŋ", "syllable_count": 2, "sentences": [{"text": "月亮是地球的卫星，绕着地球转。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮自己不发光，它反射太阳的光。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想去月亮上做研究。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮绕地球一圈大约要二十七天。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮的引力会让海水涨潮和退潮。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮比地球小很多。", "target_word": "月亮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "宇航员第一次登上了月亮。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮离地球比太阳近得多。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮上没有空气，也没有水。", "target_word": "月亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮的表面有很多小坑。", "target_word": "月亮", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "轮", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "月亮：绕地球运行的天体，即地球的卫星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b21d38-673e-4382-b312-55fb37567b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月亮", "is_correct": true, "explanation": "正确：月亮是地球的天然卫星，绕着地球转。"}, {"text": "行星", "is_correct": false, "explanation": "语义：行星是绕太阳转的天体，不是地球的卫星。"}, {"text": "火星", "is_correct": false, "explanation": "语义：火星是行星，并不绕地球转，不是地球的卫星。"}, {"text": "恒星", "is_correct": false, "explanation": "搭配：“……的卫星”指绕行星运转的天体，恒星不能这样搭配。"}], "explanations": {"月亮": "正确：月亮是地球的天然卫星，绕着地球转。", "行星": "语义：行星是绕太阳转的天体，不是地球的卫星。", "火星": "语义：火星是行星，并不绕地球转，不是地球的卫星。", "恒星": "搭配：“……的卫星”指绕行星运转的天体，恒星不能这样搭配。"}, "sentence_index": 0, "correct_answer": "月亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家发现了一条月亮，它绕着地球转。", "explanation": "这里不能用“条”（长条形东西的量词）。月亮应用“轮”或“个”。"}, {"text": "月亮是人类发射到太空的。", "explanation": "这里应该用〈人造卫星〉。人造卫星是人类发射到太空的；月亮是天然卫星，不是人发射的。"}, {"text": "月亮是太阳的光反射过来的。", "explanation": "这里应该用〈月光〉。月亮是天体，不是光线；被太阳光照亮后反射过来的是“月光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": true, "explanation": "正确：宇航员登上的是月球，即这里的月亮。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳炽热，人无法登上去。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“登上”一般接山、楼梯等，不能说“登上大海”。"}, {"text": "云", "is_correct": false, "explanation": "语义：云由水汽组成，人无法登上去。"}], "explanations": {"月亮": "正确：宇航员登上的是月球，即这里的月亮。", "太阳": "语义：太阳炽热，人无法登上去。", "大海": "搭配：“登上”一般接山、楼梯等，不能说“登上大海”。", "云": "语义：云由水汽组成，人无法登上去。"}, "sentence_index": 6, "correct_answer": "月亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮很亮，它会自己发光。", "explanation": "这里应该用〈太阳〉。太阳自己发光；月亮自己不发光，只是反射太阳的光。"}, {"text": "月亮绕着地球转，地球也绕着月亮转。", "explanation": "这里应该用〈太阳〉。地球绕着太阳转，不绕着月亮转；月亮是绕地球转的卫星。"}, {"text": "月亮是我们居住的星球。", "explanation": "这里应该用〈地球〉。我们居住的是地球这样的星球；月亮是地球的卫星，人并不住在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "用望远镜能看见一只月亮。", "corrected_sentence": "用望远镜能看见一轮月亮。", "error_description": "错误在量词“只”。“只”用于动物等，不能用于月亮。月亮应说“一轮”，正确的是“能看见一轮月亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜空里只挂着一座月亮。", "corrected_sentence": "夜空里只挂着一轮月亮。", "error_description": "错误在量词“座”。“座”用于山、楼房等大型固定的东西，不能用于月亮。这里应说“一轮月亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f477ad3f-6d70-46a1-ad0e-65fc804cf633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
