INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "期限是做一件事要在什么时候以前做完。", "primary_collocate": null, "pronunciation": "qī xiàn", "ipa": "tɕʰi˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "交作业的期限是明天。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们的期限只有三天。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名的期限已经到了。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在期限以前交了报告。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个任务的期限太短了。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求我们按期限完成工作。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能把期限再推迟几天？", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交申请表的期限是下周五。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我超过了期限，所以老师不高兴。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离最后期限只剩两天了。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "最后期限", "label": "复合"}], "register": "中性", "sense_fingerprint": "完成某事的最后时间点，即截止的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期限", "is_correct": true, "explanation": "正确答案。“交作业的期限”指完成作业的截止时间，与“是明天”相符。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“交作业”不说交“教室”，“教室是明天”也不通。"}, {"text": "分数", "is_correct": false, "explanation": "语义：“分数”是成绩，不是截止时间，“交作业的分数是明天”不通。"}, {"text": "费用", "is_correct": false, "explanation": "语义：“费用”是钱款，不能是某个时间点。"}], "explanations": {"期限": "正确答案。“交作业的期限”指完成作业的截止时间，与“是明天”相符。", "教室": "搭配：“交作业”不说交“教室”，“教室是明天”也不通。", "分数": "语义：“分数”是成绩，不是截止时间，“交作业的分数是明天”不通。", "费用": "语义：“费用”是钱款，不能是某个时间点。"}, "sentence_index": 0, "correct_answer": "期限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的期限是两千元。", "explanation": "这里应该用〈费用〉。“期限”指做事的截止时间，不用来说旅行的花费。"}, {"text": "我爷爷的期限已经八十岁了。", "explanation": "这里应该用〈年龄〉。“期限”指做事的截止时间，不能用来说人的岁数。"}, {"text": "他的期限已经有一米八了。", "explanation": "这里应该用〈身高〉。“期限”指做事的截止时间，不能用来说人的身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期限", "is_correct": true, "explanation": "正确答案。“推迟期限”指把截止时间往后延，与句意相符。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是物品，不能被“推迟”，“把行李再推迟几天”不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”是位置，不是时间，不能被推迟几天。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“推迟”不与“价格”搭配，说“推迟价格”不通。"}], "explanations": {"期限": "正确答案。“推迟期限”指把截止时间往后延，与句意相符。", "行李": "语义：“行李”是物品，不能被“推迟”，“把行李再推迟几天”不通。", "座位": "语义：“座位”是位置，不是时间，不能被推迟几天。", "价格": "搭配：“推迟”不与“价格”搭配，说“推迟价格”不通。"}, "sentence_index": 6, "correct_answer": "期限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店离我家的期限很近。", "explanation": "这里应该用〈距离〉。“期限”指做事的截止时间，不能用来说两地之间的远近。"}, {"text": "这段录音的期限是三分钟。", "explanation": "这里应该用〈时长〉。录音的长短用“时长”，“期限”指做事的截止时间，不说录音的期限。"}, {"text": "这双鞋的期限是三百元。", "explanation": "这里应该用〈价格〉。“期限”指做事的截止时间，不用来说东西的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把期限太短了，我们来不及。", "corrected_sentence": "这个期限太短了，我们来不及。", "error_description": "错误：“期限”的量词用错。“期限”应与“个”搭配，说“这个期限”；“把”用于有柄的器具，不能用来数“期限”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把交作业地期限定在明天。", "corrected_sentence": "老师把交作业的期限定在明天。", "error_description": "错误：定语标记用错。“交作业”修饰“期限”，应用“的”，不能用“地”（“地”用于状语）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
