INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96218, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "限定的时间。", "primary_collocate": null, "pronunciation": "qī xiàn", "ipa": "tɕʰi˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这本书的借阅期限是三十天。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张优惠券的使用期限到月底。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同的期限一共是两年。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的签证有效期限快到了。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贷款的期限越长，每月还得越少。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工作的期限写在合同上了。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的退货期限是七天。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房的期限已经过了，我要搬家。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔借款的期限只有半年。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件的保存期限是五年。", "target_word": "期限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "最后期限", "label": "复合"}], "register": "中性", "sense_fingerprint": "事物所限定的一段时间长度，如借阅期限、有效期限", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期限", "is_correct": true, "explanation": "正确答案。“借阅期限”指借书可以持续的时长，与“三十天”相符。"}, {"text": "日期", "is_correct": false, "explanation": "语义：“日期”指某一天，不是一段时长，“借阅日期是三十天”不通。"}, {"text": "押金", "is_correct": false, "explanation": "语义：“押金”是钱款，不是时间，不能说“是三十天”。"}, {"text": "封面", "is_correct": false, "explanation": "搭配：“借阅”不与“封面”搭配，“封面是三十天”也不成立。"}], "explanations": {"期限": "正确答案。“借阅期限”指借书可以持续的时长，与“三十天”相符。", "日期": "语义：“日期”指某一天，不是一段时长，“借阅日期是三十天”不通。", "押金": "语义：“押金”是钱款，不是时间，不能说“是三十天”。", "封面": "搭配：“借阅”不与“封面”搭配，“封面是三十天”也不成立。"}, "sentence_index": 0, "correct_answer": "期限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个城市的期限是五百公里。", "explanation": "这里应该用〈距离〉。“期限”指限定的时间，不用来说两地的距离。"}, {"text": "这个箱子的期限是二十公斤。", "explanation": "这里应该用〈重量〉。“期限”指限定的时间，不用来说东西有多重。"}, {"text": "这部电影的期限是两个小时。", "explanation": "这里应该用〈时长〉。电影有时长，“期限”指规定的截止或有效时段，不说电影的期限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期限", "is_correct": true, "explanation": "正确答案。“退货期限”指可以退货的时间段，与“七天”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是钱数，不是时间，“退货价格是七天”不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”是地点，不能用“是七天”来说明。"}, {"text": "商品", "is_correct": false, "explanation": "搭配：“是七天”需要时间类的主语，“退货商品”不搭配。"}], "explanations": {"期限": "正确答案。“退货期限”指可以退货的时间段，与“七天”相符。", "价格": "语义：“价格”是钱数，不是时间，“退货价格是七天”不通。", "地址": "语义：“地址”是地点，不能用“是七天”来说明。", "商品": "搭配：“是七天”需要时间类的主语，“退货商品”不搭配。"}, "sentence_index": 6, "correct_answer": "期限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段期限经济很困难。", "explanation": "这里应该用〈时期〉。“时期”指一段时间里的状况，可以说“这段时期”；“期限”指规定的截止或有效时段，不这样描述状况。"}, {"text": "他的期限已经三十岁了。", "explanation": "这里应该用〈年龄〉。“年龄”指人活过的年数，“期限”不能用来说人的岁数。"}, {"text": "这件衣服的期限是两百元。", "explanation": "这里应该用〈价格〉。“期限”指限定的时间，不用来说衣服的价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张会员卡地有效期限是一年。", "corrected_sentence": "这张会员卡的有效期限是一年。", "error_description": "错误：定语标记用错。“这张会员卡”修饰“有效期限”，应用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把会员地期限延长了一年。", "corrected_sentence": "我们把会员期限延长了一年。", "error_description": "错误：多余的“地”。名词修饰名词直接连用，应说“会员期限”，不加“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
