INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "标准时是大家一起用的同一个时间。", "primary_collocate": null, "pronunciation": "biāo zhǔn shí", "ipa": "piɑʊ̯˥ ʈʂuən˨˩˦ ʂʐ̩˧˥", "syllable_count": 3, "sentences": [{"text": "为了开会方便，大家都用标准时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国科学家用标准时记录数据。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了和大家一样，我把手表调成了标准时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会通知上的时间是标准时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，标准时是大家共同用的时间。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直播写的是标准时，你要换成当地时间。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了标准时，不同国家的人就能约好时间。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动通知上写的是标准时，不是本地时间。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家约好按标准时上网开会，就不会弄错时间。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船上的人用标准时，所以不会弄错时间。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "标准时间", "label": "复合"}, {"form": "世界标准时", "label": "复合"}], "register": "中性", "sense_fingerprint": "标准时：大家共同使用的同一个时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准时", "is_correct": true, "explanation": "正确。“为了开会方便，大家都用”后面接的是大家共用的时间，标准时符合这个语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：开会时大家不会“用天气”，天气不能作为开会的使用对象。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：大家不会“用海洋”来开会，这个说法讲不通。"}, {"text": "草莓", "is_correct": false, "explanation": "搭配：“用草莓”不能表示开会时的使用方式，草莓与开会无关。"}], "explanations": {"标准时": "正确。“为了开会方便，大家都用”后面接的是大家共用的时间，标准时符合这个语境。", "天气": "语义：开会时大家不会“用天气”，天气不能作为开会的使用对象。", "海洋": "语义：大家不会“用海洋”来开会，这个说法讲不通。", "草莓": "搭配：“用草莓”不能表示开会时的使用方式，草莓与开会无关。"}, "sentence_index": 0, "correct_answer": "标准时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "美国和北京的标准时是十三个小时。", "explanation": "这里应该用〈时差〉。标准时指大家共用的同一个时间，不表示两地相差的时间长度；两地相差多少要用“时差”。"}, {"text": "这个标准时每天快三分钟，大家都要重新调一下。", "explanation": "这里应该用〈时钟〉。标准时是大家共用的同一个时间，不会快慢；说“每天快三分钟”要用“时钟”。"}, {"text": "这个工作的标准时是八个小时。", "explanation": "这里应该用〈标准工时〉。标准时是大家共用的同一个时间，不表示工作的时长；工作时长要用“标准工时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准时", "is_correct": true, "explanation": "正确。“有了标准时，不同国家的人就能约好时间”说的是共同的时间标准，符合这个语境。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照不能帮助不同国家的人约定时间，讲不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与约定时间没有关系，句子的因果关系不成立。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“有了雨伞”不能作为约定时间的依据，搭配不当。"}], "explanations": {"标准时": "正确。“有了标准时，不同国家的人就能约好时间”说的是共同的时间标准，符合这个语境。", "护照": "语义：护照不能帮助不同国家的人约定时间，讲不通。", "钢琴": "语义：钢琴与约定时间没有关系，句子的因果关系不成立。", "雨伞": "搭配：“有了雨伞”不能作为约定时间的依据，搭配不当。"}, "sentence_index": 6, "correct_answer": "标准时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他抓住了合适的标准时，很快完成了任务。", "explanation": "这里应该用〈时机〉。标准时指大家共用的计时时刻，不能指做事的合适时候；合适的时候要用“时机”。"}, {"text": "童年的标准时过得很快。", "explanation": "这里应该用〈时光〉。标准时指大家共用的时间点，不指一段岁月；说童年过得很快要用“时光”。"}, {"text": "他的标准时是三十岁。", "explanation": "这里应该用〈年龄〉。标准时是大家共用的同一个时间，不能用来说人的岁数；岁数要用“年龄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "为了开会方便，大家都用一只标准时。", "corrected_sentence": "为了开会方便，大家都用一个标准时。", "error_description": "量词错误：“标准时”这里应该用量词“个”，不能用“只”。正确说法是“一个标准时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校明年开始用了标准时。", "corrected_sentence": "我们学校明年开始用标准时。", "error_description": "时态错误：“明年”指将来，不能与表示完成的“了”搭配，这里应说“明年开始用标准时”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
