INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个地区统一使用的标准计时制度。", "primary_collocate": null, "pronunciation": "biāo zhǔn shí", "ipa": "piɑʊ̯˥ ʈʂuən˨˩˦ ʂʐ̩˧˥", "syllable_count": 3, "sentences": [{"text": "中国虽然很大，但全国只用一个标准时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天过后，这里又改回标准时了。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国东部的标准时比北京晚十三个小时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美国很大，国内分成好几个标准时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天用标准时，夏天用夏令时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的标准时是东八区时间。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律规定，全国都要用同一种标准时。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本和韩国的标准时一样，都比北京快一小时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去英国时，手机会自动改成那里的标准时。", "target_word": "标准时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家改了标准时，所有的钟都要重新调。", "target_word": "标准时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "标准时间", "label": "复合"}], "register": "中性", "sense_fingerprint": "标准时：某个地区统一规定使用的计时制度，与夏令时相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "标准时", "is_correct": true, "explanation": "正确。“全国只用一个”后面接的是全国统一使用的计时制度，标准时符合这个语境。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯不是计时制度，全国不能“只用一个地毯”来计时。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：晚饭不是计时制度，全国不会“只用一个晚饭”来计时，讲不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“只用一个”的对象应是计时制度，冰箱与计时无关。"}], "explanations": {"标准时": "正确。“全国只用一个”后面接的是全国统一使用的计时制度，标准时符合这个语境。", "地毯": "语义：地毯不是计时制度，全国不能“只用一个地毯”来计时。", "晚饭": "语义：晚饭不是计时制度，全国不会“只用一个晚饭”来计时，讲不通。", "冰箱": "搭配：“只用一个”的对象应是计时制度，冰箱与计时无关。"}, "sentence_index": 0, "correct_answer": "标准时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天过后，这里又改回一只标准时了。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对的东西，标准时要用“一个标准时”。"}, {"text": "法律规定，全国都要用同一把标准时。", "explanation": "这里应该用〈种〉。〈把〉用于有柄或能握住的东西，“同一种标准时”才对。"}, {"text": "美国东部的一张标准时比北京晚十三个小时。", "explanation": "这里应该用〈个〉。〈张〉用于纸、桌子等平面的东西，标准时不能用这个量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准时", "is_correct": true, "explanation": "正确。“法律规定，全国都要用同一种”后面接的是统一规定的计时制度，标准时符合这个语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以由法律统一规定使用的东西。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：草莓不能被法律规定为全国统一使用的对象。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是计时制度，不能由法律规定全国统一“用”。"}], "explanations": {"标准时": "正确。“法律规定，全国都要用同一种”后面接的是统一规定的计时制度，标准时符合这个语境。", "天气": "语义：天气不是可以由法律统一规定使用的东西。", "草莓": "语义：草莓不能被法律规定为全国统一使用的对象。", "海洋": "语义：海洋不是计时制度，不能由法律规定全国统一“用”。"}, "sentence_index": 6, "correct_answer": "标准时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美国和中国之间的标准时是十三个小时。", "explanation": "这里应该用〈时差〉。时差是两地之间的时间差距，标准时是一套计时制度，不表示时间的长短。"}, {"text": "墙上的标准时慢了五分钟。", "explanation": "这里应该用〈时钟〉。标准时是计时制度，不能说“标准时慢了”，说钟慢要用时钟。"}, {"text": "他的标准时很高，大家都很佩服。", "explanation": "这里应该用〈水准〉。标准时指地区的计时制度，不能用来说人的能力高；能力高低要用“水准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全国只用一把标准时。", "corrected_sentence": "全国只用一种标准时。", "error_description": "量词错误：“标准时”这里应该用量词“种”，不能用“把”。正确说法是“一种标准时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全国明年开始采用了标准时。", "corrected_sentence": "全国明年开始采用标准时。", "error_description": "时态错误：“明年”指将来，不能与表示完成的“了”搭配，这里应说“明年开始采用标准时”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有经验", "is_correct": true, "explanation": "反义：“没经验”指以前没做过，“有经验”指做过、会做，二者互为反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "不构成反义：“勇敢”说不怕困难，与“没经验”无相对关系。"}, {"text": "清楚", "is_correct": false, "explanation": "不构成反义：“清楚”说明白、分明，与“没经验”无相对关系。"}, {"text": "大方", "is_correct": false, "explanation": "不构成反义：“大方”说举止不拘谨，与“没经验”无相对关系。"}], "correct_answer": "有经验", "explanations": {"有经验": "反义：“没经验”指以前没做过，“有经验”指做过、会做，二者互为反义。", "勇敢": "不构成反义：“勇敢”说不怕困难，与“没经验”无相对关系。", "清楚": "不构成反义：“清楚”说明白、分明，与“没经验”无相对关系。", "大方": "不构成反义：“大方”说举止不拘谨，与“没经验”无相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有经验", "is_correct": true, "explanation": "反义：“没经验”指以前没做过，“有经验”指做过、会做，二者互为反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "不构成反义：“勇敢”说不怕困难，与“没经验”无相对关系。"}, {"text": "安静", "is_correct": false, "explanation": "不构成反义：“安静”说声音小、不吵闹，与“没经验”无相对关系。"}, {"text": "聪明", "is_correct": false, "explanation": "不构成反义：“聪明”说头脑灵活，与“没经验”不构成相对关系。"}], "correct_answer": "有经验", "explanations": {"有经验": "反义：“没经验”指以前没做过，“有经验”指做过、会做，二者互为反义。", "勇敢": "不构成反义：“勇敢”说不怕困难，与“没经验”无相对关系。", "安静": "不构成反义：“安静”说声音小、不吵闹，与“没经验”无相对关系。", "聪明": "不构成反义：“聪明”说头脑灵活，与“没经验”不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没经验是以前没做过，还不太会。", "primary_collocate": null, "pronunciation": "méi jīng yàn", "ipa": "mei˧˥ tɕiŋ˥˥ jɛn˥˩", "syllable_count": 3, "sentences": [{"text": "我第一次开车，没经验。", "target_word": "没经验", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他刚工作，没经验，需要学习。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没经验，请你多教教我。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做饭没经验，菜总是太咸。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带孩子没经验，常常很着急。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都没经验，慢慢来吧。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一次租房，我没经验，多花了钱。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说自己没经验，不敢做这个工作。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我第一次做饺子，没经验。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的老师没经验，上课有点紧张。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "以前没做过某件事，所以还不太会做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没经验", "is_correct": true, "explanation": "正确：“没经验”说明以前没开过车，与“第一次”相呼应。"}, {"text": "很熟练", "is_correct": false, "explanation": "语义：第一次开车谈不上“熟练”，与“第一次”矛盾。"}, {"text": "很娴熟", "is_correct": false, "explanation": "语义：第一次开车谈不上“娴熟”，与“第一次”矛盾。"}, {"text": "很有经验", "is_correct": false, "explanation": "语义：“有经验”与“第一次”矛盾，第一次开车不会有经验。"}], "explanations": {"没经验": "正确：“没经验”说明以前没开过车，与“第一次”相呼应。", "很熟练": "语义：第一次开车谈不上“熟练”，与“第一次”矛盾。", "很娴熟": "语义：第一次开车谈不上“娴熟”，与“第一次”矛盾。", "很有经验": "语义：“有经验”与“第一次”矛盾，第一次开车不会有经验。"}, "sentence_index": 0, "correct_answer": "没经验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天没经验，一直打哈欠。", "explanation": "这里应该用〈没精神〉。没经验只说缺少做事的经历和技能，不能用来形容人的精神状态。"}, {"text": "她最近没经验，只喝了一点粥。", "explanation": "这里应该用〈没胃口〉。没经验指缺少实际经历，不能用来说食欲不好。"}, {"text": "他跑了一天，已经没经验了。", "explanation": "这里应该用〈没力气〉。没经验指缺少做过某事的经历，不能用来形容体力耗尽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没经验", "is_correct": true, "explanation": "正确：“没经验”说明缺少经历，与“第一次租房”“多花了钱”相符。"}, {"text": "很精明", "is_correct": false, "explanation": "语义：“精明”的人不会多花钱，与后半句“多花了钱”矛盾。"}, {"text": "很干练", "is_correct": false, "explanation": "语义：“很干练”说办事利落、有能力，与“多花了钱”的结果矛盾。"}, {"text": "很内行", "is_correct": false, "explanation": "语义：“很内行”说明懂行，与“第一次租房”及“多花了钱”矛盾。"}], "explanations": {"没经验": "正确：“没经验”说明缺少经历，与“第一次租房”“多花了钱”相符。", "很精明": "语义：“精明”的人不会多花钱，与后半句“多花了钱”矛盾。", "很干练": "语义：“很干练”说办事利落、有能力，与“多花了钱”的结果矛盾。", "很内行": "语义：“很内行”说明懂行，与“第一次租房”及“多花了钱”矛盾。"}, "sentence_index": 6, "correct_answer": "没经验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天没经验，不想出门。", "explanation": "这里应该用〈没心情〉。没经验指缺少实际经历，不能用来形容情绪。"}, {"text": "他从来没经验，对谁都很好。", "explanation": "这里应该用〈没脾气〉。没经验只说缺少阅历和技能，不能用来形容性情温和。"}, {"text": "他脸色没经验，看起来很憔悴。", "explanation": "这里应该用〈没气色〉。没经验指缺少实际经历，不能用来形容脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不没经验，请大家多帮帮他。", "corrected_sentence": "他没经验，请大家多帮帮他。", "error_description": "错误形式：“不没经验”，多加了否定词“不”。正确形式：“没经验”。“没经验”本身已是否定，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他第一次进厨房，很没经验过。", "corrected_sentence": "他第一次进厨房，很没经验。", "error_description": "错误形式：“很没经验过”，在形容词“没经验”后加了表示经历的“过”。正确形式：“很没经验”。“没经验”是形容词，表示状态，不能加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
