INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96224, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "缺少实际经历和体验。", "primary_collocate": null, "pronunciation": "méi jīng yàn", "ipa": "mei˧˥ tɕiŋ˥˥ jɛn˥˩", "syllable_count": 3, "sentences": [{"text": "他年纪小，没经验，不懂社会。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她没经验，不知道生活有多难。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人没经验，容易相信别人。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从没出过国，对外面的世界没经验。", "target_word": "没经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这种生活没经验，不知道怎么办。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚毕业，没经验，对社会还不了解。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她没经验，所以不知道这样做有危险。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子没经验，不知道火会烫手。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对爱情没经验，不知道怎么和女朋友相处。", "target_word": "没经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没经验，不知道坏人会骗人。", "target_word": "没经验", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "缺少实际的生活经历和体验，对人和事了解不深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55aaaa31-ecfe-4c48-a2a5-b97093244256') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96224, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没经验", "is_correct": true, "explanation": "正确：“没经验”指缺少实际的生活经历，与“年纪小”“不懂社会”相符。"}, {"text": "老练", "is_correct": false, "explanation": "语义：“老练”指阅历深、处事稳重，与“年纪小”“不懂社会”矛盾。"}, {"text": "练达", "is_correct": false, "explanation": "语域：“练达”偏书面，口语里很少这样形容年轻人；且意思是阅历丰富，与“不懂社会”矛盾。"}, {"text": "成熟", "is_correct": false, "explanation": "语义：“成熟”指心智和处事成熟，与“不懂社会”矛盾。"}], "explanations": {"没经验": "正确：“没经验”指缺少实际的生活经历，与“年纪小”“不懂社会”相符。", "老练": "语义：“老练”指阅历深、处事稳重，与“年纪小”“不懂社会”矛盾。", "练达": "语域：“练达”偏书面，口语里很少这样形容年轻人；且意思是阅历丰富，与“不懂社会”矛盾。", "成熟": "语义：“成熟”指心智和处事成熟，与“不懂社会”矛盾。"}, "sentence_index": 0, "correct_answer": "没经验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下雨了，大家都没经验出去玩。", "explanation": "这里应该用〈没心情〉。没经验指缺少实际经历，不能用来形容想不想做某事的情绪。"}, {"text": "这次考试，我心里没经验。", "explanation": "这里应该用〈没底〉。没经验指缺少实际经历，不能用来形容心里有没有把握。"}, {"text": "他昨晚没睡好，今天没经验。", "explanation": "这里应该用〈没精神〉。没经验指缺少实际经历，不能用来形容精神状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96224, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没经验", "is_correct": true, "explanation": "正确：“没经验”指缺少阅历，与“不知道这样做有危险”相符。"}, {"text": "机灵", "is_correct": false, "explanation": "语义：“机灵”的人通常能察觉危险，与“所以不知道危险”矛盾。"}, {"text": "谨慎", "is_correct": false, "explanation": "语义：“谨慎”的人会先想到危险，与后半句“不知道有危险”矛盾。"}, {"text": "见多识广", "is_correct": false, "explanation": "语域：“见多识广”是书面色彩较重的成语，与口语句子的语气不合；且与“不知道危险”矛盾。"}], "explanations": {"没经验": "正确：“没经验”指缺少阅历，与“不知道这样做有危险”相符。", "机灵": "语义：“机灵”的人通常能察觉危险，与“所以不知道危险”矛盾。", "谨慎": "语义：“谨慎”的人会先想到危险，与后半句“不知道有危险”矛盾。", "见多识广": "语域：“见多识广”是书面色彩较重的成语，与口语句子的语气不合；且与“不知道危险”矛盾。"}, "sentence_index": 6, "correct_answer": "没经验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这几天没经验，不爱说话。", "explanation": "这里应该用〈没心情〉。没经验指缺少实际经历，不能用来形容情绪。"}, {"text": "他这人从来没经验，从不跟人争。", "explanation": "这里应该用〈没脾气〉。没经验只说缺少阅历和技能，不能用来形容性情温和。"}, {"text": "孩子哭了一下午，已经哭得没经验了。", "explanation": "这里应该用〈没力气〉。没经验指缺少做过某事的经历，不能用来形容体力耗尽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她年纪轻轻，不没经验，又太相信别人。", "corrected_sentence": "她年纪轻轻，没经验，又太相信别人。", "error_description": "错误形式：“不没经验”，多加了否定词“不”。正确形式：“没经验”。“没经验”本身已是否定，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45638abb-bbf4-4701-9245-b00271ad78d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
