INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋中划定的、归某国或某用途管理的一定范围。", "primary_collocate": null, "pronunciation": "hǎi yù", "ipa": "xaɪ̯˨˩˦ y˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家管理的海域比陆地还大。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海域夏天不能打鱼。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上画出了这两国的海域。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海警负责保护我国的海域。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外国船进入我国海域，需要先申请。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个国家的海域连在一起。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图标出了不同国家的海域。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海域归两个国家一起管理。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海域的范围要由法律来决定。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔船不能越过线，进入别国的海域。", "target_word": "海域", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "海域：海洋中划定的、归某国或某用途管理的一定范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffd1fe1-bbcd-4c9d-bb4e-b4a9057a0a52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96226, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：划定归某国管理的海里范围。"}, {"text": "海鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是海里的鱼。"}, {"text": "海雾", "is_correct": false, "explanation": "wù 与 yù 韵母不同（u 与 ü），意思是海上的雾。"}, {"text": "海雨", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是海上的雨。"}], "explanations": {"海域": "海域：划定归某国管理的海里范围。", "海鱼": "yú（第二声）与 yù（第四声）声调不同，意思是海里的鱼。", "海雾": "wù 与 yù 韵母不同（u 与 ü），意思是海上的雾。", "海雨": "yǔ（第三声）与 yù（第四声）声调不同，意思是海上的雨。"}, "sentence_index": null, "correct_answer": "海域"}, "level_3": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：划定归某国管理的海里范围，与“比陆地还大”相符。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市建在陆地上，不可能比陆地还大。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是陆地的一部分，不可能比陆地还大。"}, {"text": "海岸", "is_correct": false, "explanation": "语义：海岸是狭长的岸线，面积远小于陆地，不可能比陆地还大。"}], "explanations": {"海域": "海域：划定归某国管理的海里范围，与“比陆地还大”相符。", "城市": "语义：城市建在陆地上，不可能比陆地还大。", "花园": "语义：花园是陆地的一部分，不可能比陆地还大。", "海岸": "语义：海岸是狭长的岸线，面积远小于陆地，不可能比陆地还大。"}, "sentence_index": 0, "correct_answer": "海域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国的海域是一条分界线。", "explanation": "这里应该用〈边界〉。海域指海洋中划定的一定范围，不是一条线，表示两国的分界要用「边界」。"}, {"text": "这片海域上长满了庄稼。", "explanation": "这里应该用〈陆地〉。海域指海洋中的一定范围，不是陆地，庄稼要种在「陆地」上。"}, {"text": "这片海域管理着三个城市。", "explanation": "这里应该用〈行政区〉。海域指海洋中划定的一定范围，不是行政机构，管理城市要用「行政区」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96226, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：划定归某国管理的海里范围。"}, {"text": "海运", "is_correct": false, "explanation": "yùn 与 yù 只差一个韵尾 n，意思是用船在海上运东西。"}, {"text": "海员", "is_correct": false, "explanation": "yuán（第二声）与 yù（第四声）韵母、声调都不同，意思是在船上工作的人。"}, {"text": "海陆", "is_correct": false, "explanation": "lù 与 yù 声调相同、声母不同，意思是海洋和陆地。"}], "explanations": {"海域": "海域：划定归某国管理的海里范围。", "海运": "yùn 与 yù 只差一个韵尾 n，意思是用船在海上运东西。", "海员": "yuán（第二声）与 yù（第四声）韵母、声调都不同，意思是在船上工作的人。", "海陆": "lù 与 yù 声调相同、声母不同，意思是海洋和陆地。"}, "sentence_index": null, "correct_answer": "海域"}, "level_3": {"options": [{"text": "海域", "is_correct": true, "explanation": "海域：划定归某国管理的海里范围，与“标出了不同国家的”相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：地图上不会标出歌曲，这句话不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“标出”用于可以标示的位置或范围，不能用于“心情”。"}, {"text": "味道", "is_correct": false, "explanation": "语义：地图不能标出味道，这句话说不通。"}], "explanations": {"海域": "海域：划定归某国管理的海里范围，与“标出了不同国家的”相符。", "歌曲": "语义：地图上不会标出歌曲，这句话不通。", "心情": "搭配：“标出”用于可以标示的位置或范围，不能用于“心情”。", "味道": "语义：地图不能标出味道，这句话说不通。"}, "sentence_index": 6, "correct_answer": "海域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海域的面积占了地球表面的七成。", "explanation": "这里应该用〈海洋〉。海域指海洋中划定的一定范围，不是整个海洋，说占地球表面七成要用「海洋」。"}, {"text": "海域从山上流下来，注入大海。", "explanation": "这里应该用〈河流〉。海域是海洋中的一定范围，不会流动，水从山上流下要用「河流」。"}, {"text": "这片海域里长满了大树。", "explanation": "这里应该用〈森林〉。海域是海洋中的范围，不会长树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国之间有一座有争议的海域。", "corrected_sentence": "两国之间有一片有争议的海域。", "error_description": "量词错误：“海域”是一大片，量词要用“片”，“座”用于山、楼等体积大而固定的东西，不用于海域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国都想管理这条有争议的海域。", "corrected_sentence": "两国都想管理这片有争议的海域。", "error_description": "量词错误：“海域”是一大片，量词要用“片”，“条”用于长条形事物，应说“这片有争议的海域”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
