INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "深夜是夜里很晚，大家都睡了的时候。", "primary_collocate": null, "pronunciation": "shēn yè", "ipa": "ʂən˥˥ je˥˩", "syllable_count": 2, "sentences": [{"text": "深夜了，孩子早就睡着了。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深夜的路上很少有车。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在深夜醒了过来。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他深夜还在练习写汉字。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深夜，月亮挂在天上。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在深夜打电话给朋友。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深夜的医院里只有几个人。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到深夜，楼上就很安静。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸深夜才下班回家。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在深夜听音乐。", "target_word": "深夜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "深夜：大家都睡了的夜里很晚的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0aec723e-4c3d-4b32-a6e4-74bef640e8d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深夜", "is_correct": true, "explanation": "正确答案。深夜指大家都睡了的夜里很晚的时候。"}, {"text": "深意", "is_correct": false, "explanation": "shēn yì 与 shēn yè 第二音节韵母不同（i 与 e），意思是深刻的含义。"}, {"text": "新叶", "is_correct": false, "explanation": "xīn yè 与 shēn yè 第一音节不同（xīn 与 shēn），意思是新长出的叶子。"}, {"text": "针叶", "is_correct": false, "explanation": "zhēn yè 与 shēn yè 第一音节声母不同（zh 与 sh），意思是针形的叶子。"}], "explanations": {"深夜": "正确答案。深夜指大家都睡了的夜里很晚的时候。", "深意": "shēn yì 与 shēn yè 第二音节韵母不同（i 与 e），意思是深刻的含义。", "新叶": "xīn yè 与 shēn yè 第一音节不同（xīn 与 shēn），意思是新长出的叶子。", "针叶": "zhēn yè 与 shēn yè 第一音节声母不同（zh 与 sh），意思是针形的叶子。"}, "sentence_index": null, "correct_answer": "深夜"}, "level_3": {"options": [{"text": "深夜", "is_correct": true, "explanation": "正确。“深夜了”表示夜里很晚、大家都睡了，与“孩子早就睡着了”相合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是时间，“书包了”无法表示夜里的时刻。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是家具，不能表示时间，与“孩子早就睡着了”也不相容。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能与“了”构成表示时间的短语，与“孩子早就睡着了”也不相容。"}], "explanations": {"深夜": "正确。“深夜了”表示夜里很晚、大家都睡了，与“孩子早就睡着了”相合。", "书包": "语义：书包不是时间，“书包了”无法表示夜里的时刻。", "饭桌": "语义：饭桌是家具，不能表示时间，与“孩子早就睡着了”也不相容。", "冰箱": "搭配：“冰箱”不能与“了”构成表示时间的短语，与“孩子早就睡着了”也不相容。"}, "sentence_index": 0, "correct_answer": "深夜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天深夜六点起床。", "explanation": "这里应该用〈清晨〉。深夜指大家都睡了的时候，不能用来说六点起床。"}, {"text": "这件衣服的深夜很漂亮。", "explanation": "“深夜”只指时间，不能指衣服的样子，这里是误用，没有替代词。"}, {"text": "他写了一条深夜。", "explanation": "这里不宜用“条”计量。“深夜”是时间，不能用“条”计数，这里是量词误用，没有替代词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深夜", "is_correct": true, "explanation": "正确。深夜的医院指夜里很晚时的医院，与“只有几个人”相合。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房不是医院，“书房的医院”语义矛盾。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁不是医院，“地铁的医院”语义矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园”与“医院”不构成可以修饰的关系，“花园的医院”搭配不当。"}], "explanations": {"深夜": "正确。深夜的医院指夜里很晚时的医院，与“只有几个人”相合。", "书房": "语义：书房不是医院，“书房的医院”语义矛盾。", "地铁": "语义：地铁不是医院，“地铁的医院”语义矛盾。", "花园": "搭配：“花园”与“医院”不构成可以修饰的关系，“花园的医院”搭配不当。"}, "sentence_index": 6, "correct_answer": "深夜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我深夜八点去上学。", "explanation": "这里应该用〈早上〉。深夜指大家都睡了的很晚时候，不能用来说早上八点去上学。"}, {"text": "这本书的深夜很厚。", "explanation": "“深夜”只指时间，不能指书的样子，这里是误用，没有替代词。"}, {"text": "我们在深夜的午饭时间见了面。", "explanation": "“深夜”与“午饭时间”矛盾，深夜指大家都睡了的时候，不能修饰午饭时间，这里是误用，没有替代词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在在深夜还没睡。", "corrected_sentence": "妈妈在深夜还没睡。", "error_description": "错误：“在在深夜还没睡”；正确：“在深夜还没睡”。介词“在”重复，多余的一个要删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很少在深夜的出门。", "corrected_sentence": "我很少在深夜出门。", "error_description": "错误：“在深夜的出门”；正确：“在深夜出门”。“的”不能插在时间状语和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
