INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外的路灯已经了灭。", "corrected_sentence": "窗外的路灯已经灭了。", "error_description": "“了”的位置错误：“了”应放在“灭”之后，应说“已经灭了”，不能说“已经了灭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一阵风过去，油灯灭就了。", "corrected_sentence": "一阵风过去，油灯就灭了。", "error_description": "语序错误：副词“就”应放在动词“灭”前，应说“就灭了”，不能说“灭就了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e020f34-d842-4565-99ef-6122acbe7304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
