INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96231, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演唱是在大家面前唱歌。", "primary_collocate": null, "pronunciation": "yǎn chàng", "ipa": "jɛn˨˩˦ ʈʂʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她在晚会上演唱了一首歌。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手今晚要在体育馆演唱。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演唱得非常好听。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在台上演唱中文歌。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你给大家演唱一首吧。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她演唱时一点也不紧张。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们站在前面演唱。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们演唱过这首老歌。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位年轻人在街头演唱。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次在大家面前演唱，很紧张。", "target_word": "演唱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演唱了", "label": "体标"}, {"form": "演唱过", "label": "体标"}, {"form": "演唱着", "label": "体标"}], "register": "中性", "sense_fingerprint": "演唱：在大家面前唱歌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0aec723e-4c3d-4b32-a6e4-74bef640e8d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96231, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演唱", "is_correct": true, "explanation": "演唱（yǎn chàng）是正确答案，指在大家面前唱歌。"}, {"text": "延长", "is_correct": false, "explanation": "yán cháng（延长）与 yǎn chàng 两个音节的声调都不同，意思是延长。"}, {"text": "盐场", "is_correct": false, "explanation": "yán chǎng（盐场）与 yǎn chàng 两个音节的声调都不同，意思是盐场。"}, {"text": "烟厂", "is_correct": false, "explanation": "yān chǎng（烟厂）与 yǎn chàng 两个音节的声调都不同，意思是烟厂。"}], "explanations": {"演唱": "演唱（yǎn chàng）是正确答案，指在大家面前唱歌。", "延长": "yán cháng（延长）与 yǎn chàng 两个音节的声调都不同，意思是延长。", "盐场": "yán chǎng（盐场）与 yǎn chàng 两个音节的声调都不同，意思是盐场。", "烟厂": "yān chǎng（烟厂）与 yǎn chàng 两个音节的声调都不同，意思是烟厂。"}, "sentence_index": null, "correct_answer": "演唱"}, "level_3": {"options": [{"text": "演唱", "is_correct": true, "explanation": "演唱：在大家面前唱歌。“她在晚会上演唱了一首歌”搭配正确。"}, {"text": "吃", "is_correct": false, "explanation": "语义：歌曲不能被吃，“吃了一首歌”说不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“一首歌”作宾语。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等场所，不接歌曲。"}], "explanations": {"演唱": "演唱：在大家面前唱歌。“她在晚会上演唱了一首歌”搭配正确。", "吃": "语义：歌曲不能被吃，“吃了一首歌”说不通。", "睡": "配价：“睡”是不及物动词，不能带“一首歌”作宾语。", "打扫": "搭配：“打扫”的对象是房间、地面等场所，不接歌曲。"}, "sentence_index": 0, "correct_answer": "演唱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在教室里演唱生字。", "explanation": "这里应该用〈读〉。演唱只用于歌曲，读生字要用〈读〉。"}, {"text": "孩子们在台上演唱舞蹈。", "explanation": "这里应该用〈表演〉。演唱只指唱歌，跳舞要用〈表演〉。"}, {"text": "孩子们在台上演唱课文。", "explanation": "这里应该用〈朗读〉。演唱只用于歌曲，念课文要用〈朗读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演唱", "is_correct": true, "explanation": "演唱：在大家面前唱歌。“老师让我们站在前面演唱”语义通顺。"}, {"text": "哭", "is_correct": false, "explanation": "语义：站在前面哭与“老师让我们”的语境不符，句意说不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”是及物动词，句中缺少宾语，不能单独作谓语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：站在前面洗不成立，“洗”与此处的场景不符。"}], "explanations": {"演唱": "演唱：在大家面前唱歌。“老师让我们站在前面演唱”语义通顺。", "哭": "语义：站在前面哭与“老师让我们”的语境不符，句意说不通。", "送": "配价：“送”是及物动词，句中缺少宾语，不能单独作谓语。", "洗": "语义：站在前面洗不成立，“洗”与此处的场景不符。"}, "sentence_index": 6, "correct_answer": "演唱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视机在大家面前演唱歌曲。", "explanation": "这里应该用〈播放〉。演唱要由人来唱，电视机只能播放歌曲。"}, {"text": "演员在剧场演唱笑话。", "explanation": "这里应该用〈讲〉。演唱只用于歌曲，讲笑话要用〈讲〉。"}, {"text": "这位律师在法庭上演唱证词。", "explanation": "这里应该用〈宣读〉。演唱只用于歌曲，宣读证词要用〈宣读〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在台上演唱了着一首新歌。", "corrected_sentence": "她在台上演唱着一首新歌。", "error_description": "错误：“演唱了着”；正确：“演唱着”。“了”与“着”不能同时标记同一动作的状态，多余的“了”要删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹把演唱了一首童谣。", "corrected_sentence": "妹妹演唱了一首童谣。", "error_description": "错误：“把”后直接接动词“演唱了”，缺少被处置的宾语，“把”字句不成立；应删去“把”，写作“妹妹演唱了一首童谣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
