INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96235, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爹是对爸爸的叫法。", "primary_collocate": null, "pronunciation": "diē", "ipa": "tje˥˥", "syllable_count": 1, "sentences": [{"text": "爹，您吃饭了吗？", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爹在农村种地。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就喊：“爹，我回来了！”", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爹今年六十岁了。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爹给我买了一件新衣服。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我最怕我爹。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她叫爹去吃饭。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爹和娘都在老家。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爹每天早上都去河边走路。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爹，这件事请您别告诉妈。", "target_word": "爹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爹爹", "label": "重叠"}], "register": "口语", "sense_fingerprint": "爹：口语里对爸爸的叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0aec723e-4c3d-4b32-a6e4-74bef640e8d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96235, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爹", "is_correct": true, "explanation": "爹（diē）是正确答案，指对爸爸的叫法。"}, {"text": "贴", "is_correct": false, "explanation": "tiē（贴）与 diē 声母不同（t 与 d），意思是贴。"}, {"text": "捏", "is_correct": false, "explanation": "niē（捏）与 diē 声母不同（n 与 d），意思是用手指夹住。"}, {"text": "碟", "is_correct": false, "explanation": "dié（碟）与 diē 声调不同（第二声与第一声），意思是碟子。"}, {"text": "些", "is_correct": false, "explanation": "xiē（些）与 diē 声母不同（x 与 d），意思是一些。"}], "explanations": {"爹": "爹（diē）是正确答案，指对爸爸的叫法。", "贴": "tiē（贴）与 diē 声母不同（t 与 d），意思是贴。", "捏": "niē（捏）与 diē 声母不同（n 与 d），意思是用手指夹住。", "碟": "dié（碟）与 diē 声调不同（第二声与第一声），意思是碟子。", "些": "xiē（些）与 diē 声母不同（x 与 d），意思是一些。"}, "sentence_index": null, "correct_answer": "爹"}, "level_3": {"options": [{"text": "爹", "is_correct": true, "explanation": "爹：对爸爸的叫法。“爹，您吃饭了吗？”称呼正确。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被直接称呼，句中是对人的称呼。"}, {"text": "令尊", "is_correct": false, "explanation": "语域：“令尊”是敬称别人父亲的书面语，不能用于直接称呼自己的父亲。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被称呼，与“您吃饭了吗”的对话语境不符。"}], "explanations": {"爹": "爹：对爸爸的叫法。“爹，您吃饭了吗？”称呼正确。", "桌子": "语义：桌子不能被直接称呼，句中是对人的称呼。", "令尊": "语域：“令尊”是敬称别人父亲的书面语，不能用于直接称呼自己的父亲。", "石头": "语义：石头不能被称呼，与“您吃饭了吗”的对话语境不符。"}, "sentence_index": 0, "correct_answer": "爹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在正式的登记表上，爹的姓名要填在这一栏。", "explanation": "这里应该用〈父亲〉。爹是口语，正式的登记表要用〈父亲〉。"}, {"text": "请问，爹，火车站怎么走？", "explanation": "这里应该用〈叔叔〉。爹只称自己的父亲，向陌生的老人问路要用〈叔叔〉。"}, {"text": "他对医生说：“爹，我的腿疼。”", "explanation": "这里应该用〈大夫〉。爹只指父亲，对看病的人不能称“爹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96235, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爹", "is_correct": true, "explanation": "爹（diē）是正确答案，指对爸爸的叫法。"}, {"text": "蝶", "is_correct": false, "explanation": "dié（蝶）与 diē 声调不同，意思是蝴蝶。"}, {"text": "叠", "is_correct": false, "explanation": "dié（叠）与 diē 声调不同，意思是重叠、折叠。"}, {"text": "咧", "is_correct": false, "explanation": "liē（咧）与 diē 声母不同（l 与 d），意思是嘴向两边张开（咧嘴）。"}, {"text": "丢", "is_correct": false, "explanation": "diū（丢）与 diē 韵母不同（-ū 与 -ē），意思是失去。"}], "explanations": {"爹": "爹（diē）是正确答案，指对爸爸的叫法。", "蝶": "dié（蝶）与 diē 声调不同，意思是蝴蝶。", "叠": "dié（叠）与 diē 声调不同，意思是重叠、折叠。", "咧": "liē（咧）与 diē 声母不同（l 与 d），意思是嘴向两边张开（咧嘴）。", "丢": "diū（丢）与 diē 韵母不同（-ū 与 -ē），意思是失去。"}, "sentence_index": null, "correct_answer": "爹"}, "level_3": {"options": [{"text": "爹", "is_correct": true, "explanation": "爹：对爸爸的叫法。“她叫爹去吃饭”中指她的父亲，搭配正确。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能被叫去吃饭，句意说不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是物体，不能被叫去吃饭。"}, {"text": "家父", "is_correct": false, "explanation": "语域：“家父”是谦称自己的父亲，不能用来指“她”的父亲。"}], "explanations": {"爹": "爹：对爸爸的叫法。“她叫爹去吃饭”中指她的父亲，搭配正确。", "窗户": "语义：窗户不能被叫去吃饭，句意说不通。", "玻璃": "语义：玻璃是物体，不能被叫去吃饭。", "家父": "语域：“家父”是谦称自己的父亲，不能用来指“她”的父亲。"}, "sentence_index": 6, "correct_answer": "爹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对妈妈说：“爹，您先吃吧。”", "explanation": "“爹”只指父亲，这里对的是母亲，不能称“爹”。"}, {"text": "我对姑姑说：“爹，您的包忘在车上了。”", "explanation": "“爹”只指父亲，这里对的是父亲的姐妹，不能称“爹”。"}, {"text": "我对哥哥说：“爹，你先去洗澡吧。”", "explanation": "“爹”只指父亲，这里对的是同辈的男性，不能称“爹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这辈子只有一只爹。", "corrected_sentence": "我这辈子只有一个爹。", "error_description": "“爹”的量词应用“个”，“只”用于动物等，不能修饰人。正确形式是“一个爹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爹的很会做饭。", "corrected_sentence": "我爹很会做饭。", "error_description": "错误：“我爹的很会做饭”中多了“的”。“我爹”直接作主语，“的”应删去，写作“我爹很会做饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
