INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参与玩耍或游戏的人。", "primary_collocate": null, "pronunciation": "wán zhě", "ipa": "uan˧˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个游戏很好玩，每个玩者都笑了。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的几位玩者在沙子里玩得很开心。", "target_word": "玩者", "complexity_tier": "T3", "furigana": "wán zhě", "sentence_source": "generated"}, {"text": "这次活动一共有二十个玩者参加。", "target_word": "玩者", "complexity_tier": "T3", "furigana": "wán zhě", "sentence_source": "generated"}, {"text": "新玩者要先看一下游戏的规则。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩者必须遵守这个游戏的规则。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每位玩者发了一张卡片。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一个玩者赢了这次游戏。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很小，只能坐四个玩者。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的玩者不会因为输了就生气。", "target_word": "玩者", "complexity_tier": "T3", "furigana": "wán zhě", "sentence_source": "generated"}, {"text": "玩者们围着桌子，认真地玩牌。", "target_word": "玩者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "参与游戏或玩耍的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "玩者", "is_correct": true, "explanation": "正确答案：玩者，指参与玩耍或游戏的人。"}, {"text": "王者", "is_correct": false, "explanation": "wáng 与 wán 韵母不同（-ang 与 -an），声调相同，意思是君王，也指某方面的冠军。"}, {"text": "完整", "is_correct": false, "explanation": "zhěng 比 zhě 多一个韵尾 -ng，意思是完备、不缺少。"}, {"text": "闻者", "is_correct": false, "explanation": "wén 与 wán 韵母不同（-en 与 -an），声调相同，意思是听到的人（书面语）。"}], "explanations": {"玩者": "正确答案：玩者，指参与玩耍或游戏的人。", "王者": "wáng 与 wán 韵母不同（-ang 与 -an），声调相同，意思是君王，也指某方面的冠军。", "完整": "zhěng 比 zhě 多一个韵尾 -ng，意思是完备、不缺少。", "闻者": "wén 与 wán 韵母不同（-en 与 -an），声调相同，意思是听到的人（书面语）。"}, "sentence_index": null, "correct_answer": "玩者"}, "level_3": {"options": [{"text": "方案", "is_correct": false, "explanation": "配价：“笑”要求有生命的人作主语，“方案”不能笑。"}, {"text": "玩者", "is_correct": true, "explanation": "正确：玩者是参与游戏的人，游戏好玩时他们会笑。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不会笑，句中说的是“每个……都笑了”的人。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是没有生命的器具，不会笑。"}], "explanations": {"方案": "配价：“笑”要求有生命的人作主语，“方案”不能笑。", "玩者": "正确：玩者是参与游戏的人，游戏好玩时他们会笑。", "石头": "语义：石头不是人，不会笑，句中说的是“每个……都笑了”的人。", "灯": "语义：灯是没有生命的器具，不会笑。"}, "sentence_index": 0, "correct_answer": "玩者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "玩者坐在看台上为选手加油。", "explanation": "这里应该用〈观众〉。坐在看台上为选手加油的是观众，玩者是参与游戏的人。"}, {"text": "玩者负责判断比赛的输赢。", "explanation": "这里应该用〈裁判〉。判断输赢的是裁判，玩者是参与游戏的人。"}, {"text": "玩者每天指导队员训练。", "explanation": "这里应该用〈教练〉。指导队员训练的是教练。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能赢游戏，句中说的是参赛的人。"}, {"text": "玩者", "is_correct": true, "explanation": "正确：玩者是参赛的人，可以赢得这次游戏。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不会参赛，也不能赢得游戏。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不是参赛者，不能赢得游戏。"}], "explanations": {"桌子": "语义：桌子不能赢游戏，句中说的是参赛的人。", "玩者": "正确：玩者是参赛的人，可以赢得这次游戏。", "椅子": "语义：椅子是家具，不会参赛，也不能赢得游戏。", "镜子": "语义：镜子不是参赛者，不能赢得游戏。"}, "sentence_index": 6, "correct_answer": "玩者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玩者在厨房里炒了一盘好菜。", "explanation": "这里应该用〈厨师〉。在厨房里炒菜的是厨师，玩者指参与玩耍或游戏的人。"}, {"text": "玩者在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。在法庭上为被告辩护的是律师，玩者是参与游戏的人。"}, {"text": "玩者每天给病人量体温、换药。", "explanation": "这里应该用〈护士〉。给病人量体温、换药的是护士，玩者是参与游戏的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只新玩者很快就学会了规则。", "corrected_sentence": "一位新玩者很快就学会了规则。", "error_description": "量词错误：指人的“玩者”要用“位”，不能用“只”。应说“一位新玩者”，不说“一只新玩者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个很认真地玩者，从不迟到。", "corrected_sentence": "他是个很认真的玩者，从不迟到。", "error_description": "结构助词错误：修饰名词“玩者”要用“的”，写成“很认真的玩者”；“地”用于修饰动词，“很认真地玩者”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
