INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从事生产的组织或部门。", "primary_collocate": null, "pronunciation": "shēng chǎn dān wèi", "ipa": "ʂɤŋ˥ tʂʰan˨˩ tan˥ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "这个生产单位有三百名工人。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要求每个生产单位都注意安全。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有五个生产单位。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产单位的负责人明天开会。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位去年完成了任务。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的各个生产单位每月都要检查一次设备。", "target_word": "生产单位", "complexity_tier": "T3", "furigana": "gōng sī de gè gè shēng chǎn dān wèi měi yuè dōu yào jiǎn chá yí cì shè bèi", "sentence_source": "generated"}, {"text": "领导来生产单位了解工人的情况。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个生产单位当会计。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个生产单位都要写工作报告。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生产单位的管理很严格。", "target_word": "生产单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "从事生产的组织或部门，强调管理和任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产单位", "is_correct": true, "explanation": "正确：生产单位指从事生产的组织或部门，可以有三百名工人，符合句意。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：茶馆是供人饮茶的场所，不从事生产，一般不会有三百名工人。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园是教育机构，不从事生产劳动，与“工人”不合。"}, {"text": "小卖部", "is_correct": false, "explanation": "语义：小卖部是很小的商店，不从事生产，不会有三百名工人。"}], "explanations": {"生产单位": "正确：生产单位指从事生产的组织或部门，可以有三百名工人，符合句意。", "茶馆": "语义：茶馆是供人饮茶的场所，不从事生产，一般不会有三百名工人。", "幼儿园": "语义：幼儿园是教育机构，不从事生产劳动，与“工人”不合。", "小卖部": "语义：小卖部是很小的商店，不从事生产，不会有三百名工人。"}, "sentence_index": 0, "correct_answer": "生产单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司新开了一条生产单位。", "explanation": "这里应该用〈个〉。生产单位是组织或部门，量词用“个”；“条”用于线状事物，如生产线。"}, {"text": "这个生产单位每晚都演出，观众很多。", "explanation": "这里应该用〈剧院〉。生产单位是从事生产的组织或部门，不演出节目；演出要在剧院。"}, {"text": "他是我们公司最能干的生产单位。", "explanation": "这里应该用〈员工〉。生产单位指组织或部门，不指人，不能用来称呼某个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产单位", "is_correct": true, "explanation": "正确：这里指从事生产的组织，领导来此了解工人的情况，符合句意。"}, {"text": "茶馆", "is_correct": false, "explanation": "语义：茶馆是饮茶的场所，不从事生产，没有需要领导了解情况的工人。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店的人员是理发师，不称“工人”，与句中的“工人的情况”不合。"}, {"text": "诊所", "is_correct": false, "explanation": "搭配：诊所的工作人员是医护人员，不称“工人”，与“了解工人的情况”不搭。"}], "explanations": {"生产单位": "正确：这里指从事生产的组织，领导来此了解工人的情况，符合句意。", "茶馆": "语义：茶馆是饮茶的场所，不从事生产，没有需要领导了解情况的工人。", "理发店": "语义：理发店的人员是理发师，不称“工人”，与句中的“工人的情况”不合。", "诊所": "搭配：诊所的工作人员是医护人员，不称“工人”，与“了解工人的情况”不搭。"}, "sentence_index": 6, "correct_answer": "生产单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都去生产单位存钱。", "explanation": "这里应该用〈银行〉。生产单位是从事生产的组织，不办存款业务；存钱要去银行。"}, {"text": "这个生产单位有三百名学生，每天都上课。", "explanation": "这里应该用〈学校〉。生产单位是工厂或部门，没有“学生”，上课要去学校。"}, {"text": "我把这个生产单位放进了口袋。", "explanation": "这里应该用〈钥匙〉。生产单位指组织或部门，不是物品，不能放进口袋；能放进口袋的是钥匙这类小东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产单位下个月要搬到新地方。", "corrected_sentence": "这个生产单位下个月要搬到新地方。", "error_description": "量词错误：“生产单位”指组织或部门，量词应用“个”，不用“条”（“条”用于线状事物）。正确说法是“这个生产单位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个生产单位的很大，每天都有很多工人。", "corrected_sentence": "这个生产单位很大，每天都有很多工人。", "error_description": "多余的“的”：“生产单位”与“很大”之间不需要“的”。正确说法是“这个生产单位很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
