INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "登场是走到台上，开始表演。", "primary_collocate": null, "pronunciation": "dēng chǎng", "ipa": "tɤŋ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "演员们准备登场了。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯亮了，歌手慢慢登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩第一个登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很紧张地登场，唱了一首歌。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上，乐队正在登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请下一位同学登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着红衣服登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先登场的同学到后面等着。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众鼓掌欢迎，歌手登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "登场以前，她一直很紧张。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登过场", "label": "体标"}, {"form": "登了场", "label": "体标"}], "register": "中性", "sense_fingerprint": "走上舞台开始表演", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd92a59cf-6673-4b7a-9df1-a19597e37236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登场", "is_correct": true, "explanation": "正确：登场指走上舞台开始表演，演员准备登场，语义通顺。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是人的一次性出现于世，演员准备出生的说法不通。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：出版用于书籍、报刊等出版物，不能用来说演员。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，主语不能是演员，“演员们准备下雨了”不通。"}], "explanations": {"登场": "正确：登场指走上舞台开始表演，演员准备登场，语义通顺。", "出生": "语义：出生是人的一次性出现于世，演员准备出生的说法不通。", "出版": "搭配：出版用于书籍、报刊等出版物，不能用来说演员。", "下雨": "语义：下雨是天气现象，主语不能是演员，“演员们准备下雨了”不通。"}, "sentence_index": 0, "correct_answer": "登场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天早上七点登场去上学。", "explanation": "这里应该用〈出门〉。登场指走上台表演，早上去上学要说出门。"}, {"text": "他在火车站登场，买了一张票。", "explanation": "这里应该用〈进站〉。登场指走上舞台表演，在火车站进去要说进站。"}, {"text": "她很紧张地登场，爬上了山顶。", "explanation": "这里应该用〈登顶〉。登场指走上台表演，到达山顶要说登顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登场", "is_correct": true, "explanation": "正确：登场指走上舞台开始表演，他穿着红衣服走上舞台，语义通顺。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：印刷是把文字图像印在纸上，不指人走上舞台，句子意思不通。"}, {"text": "公布", "is_correct": false, "explanation": "配价：公布需要带宾语，如公布结果，单用在此处句子不完整。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：搬运需要带宾语，如搬运货物，单用在此处句子不完整。"}], "explanations": {"登场": "正确：登场指走上舞台开始表演，他穿着红衣服走上舞台，语义通顺。", "印刷": "语义：印刷是把文字图像印在纸上，不指人走上舞台，句子意思不通。", "公布": "配价：公布需要带宾语，如公布结果，单用在此处句子不完整。", "搬运": "配价：搬运需要带宾语，如搬运货物，单用在此处句子不完整。"}, "sentence_index": 6, "correct_answer": "登场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上七点登场去菜市场买菜。", "explanation": "这里应该用〈出门〉。登场指走上舞台表演，早上去买菜要说出门。"}, {"text": "他在医院登场看病。", "explanation": "这里应该用〈就诊〉。登场指走上舞台表演，去医院看病要说就诊。"}, {"text": "他在地铁站登场，刷了卡。", "explanation": "这里应该用〈进站〉。登场指走上舞台表演，刷卡进站要说进站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
