INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96244, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演员出场；人物出现。", "primary_collocate": null, "pronunciation": "dēng chǎng", "ipa": "tɤŋ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "电影的主角终于登场了。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新角色在第三集登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都等着他登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个角色一登场，观众就笑了。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的坏人很晚才登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后登场的是一位老人。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二个人物登场的时候，音乐变了。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的新人物登场了。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画里，新的反派一个个登场。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的登场让大家很高兴。", "target_word": "登场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登过场", "label": "体标"}, {"form": "登了场", "label": "体标"}], "register": "中性", "sense_fingerprint": "人物或角色出现、出场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd92a59cf-6673-4b7a-9df1-a19597e37236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登场", "is_correct": true, "explanation": "正确：登场指人物出现或演员出场，电影主角终于出现，语义通顺。"}, {"text": "煮饭", "is_correct": false, "explanation": "语义：煮饭是做饭的动作，与电影主角出现的意思不符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：出版用于书籍、报刊等出版物，不能用来说电影主角。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，主语不能是电影主角，句子不通。"}], "explanations": {"登场": "正确：登场指人物出现或演员出场，电影主角终于出现，语义通顺。", "煮饭": "语义：煮饭是做饭的动作，与电影主角出现的意思不符。", "出版": "搭配：出版用于书籍、报刊等出版物，不能用来说电影主角。", "下雨": "语义：下雨是天气现象，主语不能是电影主角，句子不通。"}, "sentence_index": 0, "correct_answer": "登场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车一登场，乘客就下车。", "explanation": "这里应该用〈到达〉。登场指人物或演员出场，不能用于车辆。"}, {"text": "他在飞机上登场了。", "explanation": "这里应该用〈登机〉。登场指演员或人物出场，上飞机要说登机。"}, {"text": "他终于在山顶登场了。", "explanation": "这里应该用〈登顶〉。登场指出场或人物出现，到达山顶要说登顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登场", "is_correct": true, "explanation": "正确：登场指人物出现，第二个人物出现时音乐变了，语义通顺。"}, {"text": "印刷", "is_correct": false, "explanation": "语义：印刷是把文字图像印在纸上，不指人物出现，句子意思不通。"}, {"text": "公布", "is_correct": false, "explanation": "配价：公布需要带宾语，如公布结果，单用在此处句子不完整。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：搬运需要带宾语，如搬运货物，单用在此处句子不完整。"}], "explanations": {"登场": "正确：登场指人物出现，第二个人物出现时音乐变了，语义通顺。", "印刷": "语义：印刷是把文字图像印在纸上，不指人物出现，句子意思不通。", "公布": "配价：公布需要带宾语，如公布结果，单用在此处句子不完整。", "搬运": "配价：搬运需要带宾语，如搬运货物，单用在此处句子不完整。"}, "sentence_index": 6, "correct_answer": "登场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里登场做饭了。", "explanation": "这里应该用〈下厨〉。登场指人物或演员出现，在厨房做饭要说下厨。"}, {"text": "他每天晚上登场吃饭。", "explanation": "这里应该用〈回家〉。登场指人物或演员出场，不能表示回家后吃饭。"}, {"text": "他今天去医院登场。", "explanation": "这里应该用〈挂号〉。登场指演员或人物出场，去医院看病要说挂号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "观众等了很久，主角终于被登场。", "corrected_sentence": "观众等了很久，主角终于登场。", "error_description": "“被登场”是被动误用，正确形式为“登场”。登场是不及物动词，不能加“被”带出被动句，“被”要去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "故事开始以后，第一个人物被登场了。", "corrected_sentence": "故事开始以后，第一个人物登场了。", "error_description": "“被登场”是被动误用，正确形式为“登场”。登场是不及物动词，不能加“被”带出被动句，“被”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
