INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96245, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96245, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "积分是游戏或比赛里一点一点攒起来的分数。", "primary_collocate": null, "pronunciation": "jī fēn", "ipa": "tɕi˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这场比赛后，我们队的积分最高。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他玩游戏很努力，积分很快就多了。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赢一场比赛，队伍的积分会多三分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班在游戏里的积分排第一。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的积分比我多十分，所以他赢了。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输了这场球，没有拿到积分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏做完任务就能加积分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束时，两个队的积分一样多。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，答对一个问题，积分就加一分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的积分太少，不能进下一关。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "積分", "label": "繁体"}, {"form": "积分榜", "label": "复合词"}, {"form": "积分赛", "label": "复合词"}], "register": "中性", "sense_fingerprint": "游戏或比赛中一点一点攒起来、决定排名的分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96245, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "积分", "is_correct": true, "explanation": "正确答案：积分（jī fēn），指游戏或比赛里攒起来的分数。"}, {"text": "七分", "is_correct": false, "explanation": "qī 与 jī 的声母不同（q 与 j），意思是七分、七成。"}, {"text": "计分", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是计算分数。"}, {"text": "几分", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是几成、一些。"}, {"text": "鸡粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是鸡味调味粉。"}], "explanations": {"积分": "正确答案：积分（jī fēn），指游戏或比赛里攒起来的分数。", "七分": "qī 与 jī 的声母不同（q 与 j），意思是七分、七成。", "计分": "jì（第四声）与 jī（第一声）声调不同，意思是计算分数。", "几分": "jǐ（第三声）与 jī（第一声）声调不同，意思是几成、一些。", "鸡粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是鸡味调味粉。"}, "sentence_index": null, "correct_answer": "积分"}, "level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资是按合同发放的报酬，与比赛结果无关，“这场比赛后”不能说它最高。"}, {"text": "积分", "is_correct": true, "explanation": "正确。“我们队的积分”最高，符合比赛语境。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费与比赛成绩无关，“学费最高”不合语境。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价是门票的定价，不是比赛的结果，“这场比赛后”不能说它最高。"}], "explanations": {"工资": "语义：工资是按合同发放的报酬，与比赛结果无关，“这场比赛后”不能说它最高。", "积分": "正确。“我们队的积分”最高，符合比赛语境。", "学费": "语义：学费与比赛成绩无关，“学费最高”不合语境。", "票价": "语义：票价是门票的定价，不是比赛的结果，“这场比赛后”不能说它最高。"}, "sentence_index": 0, "correct_answer": "积分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛结束时，两队的积分是三比一。", "explanation": "这里应该用〈比分〉。比赛结束时双方的得分比较用“比分”，“积分”是累计的分数，不用于单场比赛。"}, {"text": "我们队的积分被小偷偷走了。", "explanation": "积分是抽象的分数，不是实物，不能被“偷走”；只能被扣掉或减少。"}, {"text": "比赛还没开始，我们就积分了三分。", "explanation": "“积分”是名词，不能当动词带“了三分”；应说“得了三分”或“拿到三个积分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体温", "is_correct": false, "explanation": "语义：“体温”是人体的温度，游戏任务不会“加体温”。"}, {"text": "积分", "is_correct": true, "explanation": "正确。游戏做完任务后能“加积分”，符合语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：游戏奖励不会“加身高”，句子读来不合常理。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“加”后接的是可累积的数量或奖励，不说“加头发”。"}], "explanations": {"体温": "语义：“体温”是人体的温度，游戏任务不会“加体温”。", "积分": "正确。游戏做完任务后能“加积分”，符合语境。", "身高": "语义：游戏奖励不会“加身高”，句子读来不合常理。", "头发": "搭配：“加”后接的是可累积的数量或奖励，不说“加头发”。"}, "sentence_index": 6, "correct_answer": "积分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你的一张积分太少，不能进下一关。", "explanation": "这里的量词错了。积分是抽象的分数，不能用“张”（“张”用于纸、票等平面物），应说“你的积分太少”。"}, {"text": "这次投票你的积分最多，所以你当选了。", "explanation": "这里应该用〈票数〉。选举统计的是票数，不用“积分”。"}, {"text": "这次期末考试，他的积分是九十分。", "explanation": "这里应该用〈分数〉。考试成绩用“分数”，“积分”是游戏或比赛中累计的分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队的积分已经有五十分个了。", "corrected_sentence": "我们队的积分已经有五十分了。", "error_description": "“分”本身已是积分的计量单位，后面不能再加“个”，应说“五十分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队的积分比他们队很多。", "corrected_sentence": "我们队的积分比他们队多很多。", "error_description": "比字句中形容词前不能加“很”，程度要放在后面：“多很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
