INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "累计起来的分数。", "primary_collocate": null, "pronunciation": "jī fēn", "ipa": "tɕi˥ fən˥", "syllable_count": 2, "sentences": [{"text": "我的会员积分已经有一千分了。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的积分可以换小礼物。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西的时候，收银员给我加了积分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用信用卡的积分换了一张电影票。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的积分不够，还不能换这个杯子。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次坐飞机，航空公司都会给你积分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我的积分多了两百分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每年都用积分换一次免费的饭。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看一下你的账户里还有多少积分。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一年，这些积分就不能用了。", "target_word": "积分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "積分", "label": "繁体"}, {"form": "积分卡", "label": "复合词"}], "register": "中性", "sense_fingerprint": "购物、会员、信用卡等累计起来、可以兑换东西的分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96246, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "积分", "is_correct": true, "explanation": "正确答案：积分（jī fēn），指累计起来的分数。"}, {"text": "七分", "is_correct": false, "explanation": "qī 与 jī 的声母不同（q 与 j），意思是七分、七成。"}, {"text": "计分", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是计算分数。"}, {"text": "几分", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是几成、一些。"}, {"text": "鸡粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是鸡味调味粉。"}], "explanations": {"积分": "正确答案：积分（jī fēn），指累计起来的分数。", "七分": "qī 与 jī 的声母不同（q 与 j），意思是七分、七成。", "计分": "jì（第四声）与 jī（第一声）声调不同，意思是计算分数。", "几分": "jǐ（第三声）与 jī（第一声）声调不同，意思是几成、一些。", "鸡粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是鸡味调味粉。"}, "sentence_index": null, "correct_answer": "积分"}, "level_3": {"options": [{"text": "卡号", "is_correct": false, "explanation": "语义：卡号是编号，不能用“有一千分”来计量。"}, {"text": "积分", "is_correct": true, "explanation": "正确。“会员积分”与“已经有一千分”的说法一致。"}, {"text": "期限", "is_correct": false, "explanation": "语义：期限是时间，不用“分”来计算。"}, {"text": "等级", "is_correct": false, "explanation": "搭配：等级是层次，不说“等级已经有一千分”。"}], "explanations": {"卡号": "语义：卡号是编号，不能用“有一千分”来计量。", "积分": "正确。“会员积分”与“已经有一千分”的说法一致。", "期限": "语义：期限是时间，不用“分”来计算。", "等级": "搭配：等级是层次，不说“等级已经有一千分”。"}, "sentence_index": 0, "correct_answer": "积分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天积分很努力，所以很快就攒够了。", "explanation": "“积分”是名词，不能直接当动词用；应说“每天攒积分很努力”。"}, {"text": "我用信用卡换了一张积分。", "explanation": "积分是抽象的分数，不能用量词“张”；应说“用信用卡积分换了一张票”。"}, {"text": "我这次考试的积分很高。", "explanation": "这里应该用〈分数〉。考试成绩用“分数”，“积分”指购物或会员累计的分数，不用于考试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：年龄按岁计算，不能说“多了两百分”。"}, {"text": "积分", "is_correct": true, "explanation": "正确。“积分”可以“多了两百分”，符合语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重按公斤计算，不能说“多了两百分”。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：账单多指金额，“多了两百分”不是常用搭配。"}], "explanations": {"年龄": "语义：年龄按岁计算，不能说“多了两百分”。", "积分": "正确。“积分”可以“多了两百分”，符合语境。", "体重": "语义：体重按公斤计算，不能说“多了两百分”。", "账单": "搭配：账单多指金额，“多了两百分”不是常用搭配。"}, "sentence_index": 6, "correct_answer": "积分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "过了一年，这一只积分就不能用了。", "explanation": "这里的量词错了。“只”用于动物或成对的器物，不能修饰积分，应说“这些积分”。"}, {"text": "我把积分放进口袋里了。", "explanation": "积分是账户里的抽象分数，不是实物，不能放进口袋。"}, {"text": "这本书的积分很有意思。", "explanation": "这里应该用〈内容〉。积分是累计可兑换的分数，不能形容为“有意思”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的积分已经有五百份了。", "corrected_sentence": "她的积分已经有五百分了。", "error_description": "“积分”的计量单位是“分”，不能说“五百份”，应说“五百分”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我的积分比上个月很多。", "corrected_sentence": "这个月我的积分比上个月多很多。", "error_description": "比字句中形容词前不能加“很”，程度放在后面：“多很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
