INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "简历是写一个人学过什么、做过什么的小纸。", "primary_collocate": null, "pronunciation": "jiǎn lì", "ipa": "tɕjɛn˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "我把简历发给了那家公司。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的简历只写一页就够了。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在简历上写了自己的电话。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，请带一份简历来。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的简历上有两年工作经历。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看了你的简历，想见你一面。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份简历打印得很清楚。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在电脑上做新的简历。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请朋友帮我看看简历。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把你的简历放在桌子上吧。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "簡歷", "label": "繁体"}, {"form": "个人简历", "label": "复合词"}], "register": "中性", "sense_fingerprint": "求职时交给公司的、写着学习和工作情况的一份纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96247, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历（jiǎn lì）：求职时交给公司、写着个人学习和工作情况的材料。"}, {"text": "建立", "is_correct": false, "explanation": "jiàn 与 jiǎn 声调不同（第四声与第三声），lì 相同，意思是建立。"}, {"text": "奖励", "is_correct": false, "explanation": "jiǎng 与 jiǎn 只差韵尾（-ng 与 -n），lì 相同，意思是奖励。"}, {"text": "尖利", "is_correct": false, "explanation": "jiān 与 jiǎn 声调不同（第一声与第三声），lì 相同，意思是锋利。"}], "explanations": {"简历": "简历（jiǎn lì）：求职时交给公司、写着个人学习和工作情况的材料。", "建立": "jiàn 与 jiǎn 声调不同（第四声与第三声），lì 相同，意思是建立。", "奖励": "jiǎng 与 jiǎn 只差韵尾（-ng 与 -n），lì 相同，意思是奖励。", "尖利": "jiān 与 jiǎn 声调不同（第一声与第三声），lì 相同，意思是锋利。"}, "sentence_index": null, "correct_answer": "简历"}, "level_3": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历是求职材料，可以发给公司，符合「我把___发给了那家公司」的语境。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是公司发给员工的，方向相反，不能由「我」发给公司。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能发给公司。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：「发」的对象多是文件、消息，不能与心情搭配。"}], "explanations": {"简历": "简历是求职材料，可以发给公司，符合「我把___发给了那家公司」的语境。", "工资": "语义：工资是公司发给员工的，方向相反，不能由「我」发给公司。", "天气": "语义：天气是自然现象，不能发给公司。", "心情": "搭配：「发」的对象多是文件、消息，不能与心情搭配。"}, "sentence_index": 0, "correct_answer": "简历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的简历写在了网站上。", "explanation": "这里应该用〈简介〉。简历指个人的学习和工作经历，介绍公司要用简介。"}, {"text": "他昨天收到了一只简历。", "explanation": "这里应该用〈份〉。量词〈只〉用于动物或成对的物品，简历是纸质材料，要用〈份〉。"}, {"text": "她在办公室里打印了一台简历。", "explanation": "这里应该用〈份〉。量词〈台〉用于机器，简历不能用〈台〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96247, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历（jiǎn lì）：求职时交给公司、写着个人学习和工作情况的材料。"}, {"text": "脚力", "is_correct": false, "explanation": "jiǎo 与 jiǎn 只差韵尾（-ǎo 与 -ǎn），lì 相同，意思是走路的力气。"}, {"text": "检录", "is_correct": false, "explanation": "jiǎn 相同，lù 与 lì 韵母不同，意思是比赛前点名登记。"}, {"text": "监理", "is_correct": false, "explanation": "jiān lǐ 与 jiǎn lì 声母韵母相同，只是声调不同，意思是监督管理。"}], "explanations": {"简历": "简历（jiǎn lì）：求职时交给公司、写着个人学习和工作情况的材料。", "脚力": "jiǎo 与 jiǎn 只差韵尾（-ǎo 与 -ǎn），lì 相同，意思是走路的力气。", "检录": "jiǎn 相同，lù 与 lì 韵母不同，意思是比赛前点名登记。", "监理": "jiān lǐ 与 jiǎn lì 声母韵母相同，只是声调不同，意思是监督管理。"}, "sentence_index": null, "correct_answer": "简历"}, "level_3": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历是纸质材料，可以打印，符合「这份___打印得很清楚」的语境。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是实物，不能打印。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：「打印」的对象是文字材料，不能与早餐搭配。"}, {"text": "心意", "is_correct": false, "explanation": "语义：心意是抽象的情感，不能打印。"}], "explanations": {"简历": "简历是纸质材料，可以打印，符合「这份___打印得很清楚」的语境。", "礼物": "语义：礼物是实物，不能打印。", "早餐": "搭配：「打印」的对象是文字材料，不能与早餐搭配。", "心意": "语义：心意是抽象的情感，不能打印。"}, "sentence_index": 6, "correct_answer": "简历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从包里拿出一首简历。", "explanation": "这里应该用〈份〉。量词〈首〉用于诗词歌曲，简历不能用〈首〉计量。"}, {"text": "这次旅行是我最难忘的简历。", "explanation": "这里应该用〈经历〉。简历是求职用的个人材料，指旅行中难忘的经过要用经历。"}, {"text": "公司来了一位简历。", "explanation": "这里应该用〈份〉。量词〈位〉用于人，简历是材料，不是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一本简历交给了经理。", "corrected_sentence": "他把一份简历交给了经理。", "error_description": "量词错误：「简历」应用量词「份」，「本」用于书籍，应说「一份简历」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你准备一把简历。", "corrected_sentence": "请你准备一份简历。", "error_description": "量词错误：「简历」应用量词「份」，「把」用于有柄的物品，应说「一份简历」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
