INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对个人学习、工作经历的简要介绍。", "primary_collocate": null, "pronunciation": "jiǎn lì", "ipa": "tɕjɛn˨˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他的简历很简单，只有两个工作。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的简历里有很多国外学习的经历。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的个人简历写得很清楚。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的最后有作者的简历。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的简历很完整，学习和工作的经历都有。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从他的简历看，他在银行做过五年。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的简历上写着他在北京长大。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手的简历在网上能找到。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的简历很长，从小学一直写到现在。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了她的简历，我才知道她学过画画。", "target_word": "简历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "簡歷", "label": "繁体"}, {"form": "个人简历", "label": "复合词"}], "register": "中性", "sense_fingerprint": "对一个人学习和工作经历的简要介绍内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96248, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历（jiǎn lì）：对个人学习和工作经历的简要介绍。"}, {"text": "建立", "is_correct": false, "explanation": "jiàn 与 jiǎn 声调不同（第四声与第三声），lì 相同，意思是建立。"}, {"text": "奖励", "is_correct": false, "explanation": "jiǎng 与 jiǎn 只差韵尾（-ng 与 -n），lì 相同，意思是奖励。"}, {"text": "尖利", "is_correct": false, "explanation": "jiān 与 jiǎn 声调不同（第一声与第三声），lì 相同，意思是锋利。"}], "explanations": {"简历": "简历（jiǎn lì）：对个人学习和工作经历的简要介绍。", "建立": "jiàn 与 jiǎn 声调不同（第四声与第三声），lì 相同，意思是建立。", "奖励": "jiǎng 与 jiǎn 只差韵尾（-ng 与 -n），lì 相同，意思是奖励。", "尖利": "jiān 与 jiǎn 声调不同（第一声与第三声），lì 相同，意思是锋利。"}, "sentence_index": null, "correct_answer": "简历"}, "level_3": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历指个人的学习和工作经历，「他的___很简单，只有两个工作」指的正是这个。"}, {"text": "房子", "is_correct": false, "explanation": "语义：「只有两个工作」说的是人的工作经历，房子不能有工作。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有工作经历，与「只有两个工作」不搭。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：「只有两个工作」的主语应是人的经历，手机不搭配。"}], "explanations": {"简历": "简历指个人的学习和工作经历，「他的___很简单，只有两个工作」指的正是这个。", "房子": "语义：「只有两个工作」说的是人的工作经历，房子不能有工作。", "天气": "语义：天气没有工作经历，与「只有两个工作」不搭。", "手机": "搭配：「只有两个工作」的主语应是人的经历，手机不搭配。"}, "sentence_index": 0, "correct_answer": "简历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的简历写了三十年的历史。", "explanation": "这里应该用〈简介〉。简历只写个人的学习和工作经历，介绍公司的历史要用简介。"}, {"text": "他写了一只简历，讲了自己的童年。", "explanation": "这里应该用〈份〉。量词〈只〉用于动物或成对的物品，简历不能用〈只〉。"}, {"text": "他的留学简历让他变得更加成熟。", "explanation": "这里应该用〈经历〉。简历是对学习、工作经历的简要书面介绍，指人生中实际发生的过程要用经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96248, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历（jiǎn lì）：对个人学习和工作经历的简要介绍。"}, {"text": "脚力", "is_correct": false, "explanation": "jiǎo 与 jiǎn 只差韵尾（-ǎo 与 -ǎn），lì 相同，意思是走路的力气。"}, {"text": "检录", "is_correct": false, "explanation": "jiǎn 相同，lù 与 lì 韵母不同，意思是比赛前点名登记。"}, {"text": "监理", "is_correct": false, "explanation": "jiān lǐ 与 jiǎn lì 声母韵母相同，只是声调不同，意思是监督管理。"}], "explanations": {"简历": "简历（jiǎn lì）：对个人学习和工作经历的简要介绍。", "脚力": "jiǎo 与 jiǎn 只差韵尾（-ǎo 与 -ǎn），lì 相同，意思是走路的力气。", "检录": "jiǎn 相同，lù 与 lì 韵母不同，意思是比赛前点名登记。", "监理": "jiān lǐ 与 jiǎn lì 声母韵母相同，只是声调不同，意思是监督管理。"}, "sentence_index": null, "correct_answer": "简历"}, "level_3": {"options": [{"text": "简历", "is_correct": true, "explanation": "简历指个人的学习和工作经历，「校长的___上写着他在北京长大」指的正是这个。"}, {"text": "课表", "is_correct": false, "explanation": "语义：课表记录的是课程安排，不写人的出生地和成长经历。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：「写着」的载体是文字材料，照片上一般不写出生地和成长经历。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单记录的是菜品，与人的成长经历无关。"}], "explanations": {"简历": "简历指个人的学习和工作经历，「校长的___上写着他在北京长大」指的正是这个。", "课表": "语义：课表记录的是课程安排，不写人的出生地和成长经历。", "照片": "搭配：「写着」的载体是文字材料，照片上一般不写出生地和成长经历。", "菜单": "语义：菜单记录的是菜品，与人的成长经历无关。"}, "sentence_index": 6, "correct_answer": "简历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她写了一首简历。", "explanation": "这里应该用〈份〉。量词〈首〉用于诗歌，简历不能用〈首〉计量。"}, {"text": "这本小说讲了一个感人的简历。", "explanation": "这里应该用〈故事〉。简历是对个人学习和工作经历的简要介绍，讲述有情节的人物经历要用故事。"}, {"text": "那次爬山是一段很危险的简历。", "explanation": "这里应该用〈经历〉。简历是对学习、工作经历的简要介绍，亲身经过的事情要用经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_versio