INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的一把简历写得很认真。", "corrected_sentence": "她的一份简历写得很认真。", "error_description": "量词错误：「简历」应用量词「份」，「把」用于有柄的器具，应说「一份简历」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她递给我一台简历。", "corrected_sentence": "她递给我一份简历。", "error_description": "量词错误：「简历」应用量词「份」，「台」用于机器，应说「一份简历」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
