INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "要求集体成员遵守的行为规则。", "primary_collocate": null, "pronunciation": "jì lǜ", "ipa": "tɕi˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "上课时要遵守纪律。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队的纪律非常严格。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听老师的话，违反了纪律。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班的纪律很好，大家都很安静。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有一条纪律：上班不能迟到。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对考试纪律要求很高。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评了她，因为她违反了纪律。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员们都要遵守球队的纪律。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家要注意会场纪律。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有纪律的队伍，很难打赢比赛。", "target_word": "纪律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "紀律", "label": "繁体"}], "register": "中性", "sense_fingerprint": "集体对成员的行为所作的约束性规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0aec723e-4c3d-4b32-a6e4-74bef640e8d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纪律", "is_correct": true, "explanation": "正确。上课时要遵守的是课堂的纪律。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“遵守”的对象是规则，“天气”不能被遵守。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“遵守”的对象是规则，“颜色”不是规则，不能被遵守。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气不是规则，不能说“遵守空气”。"}], "explanations": {"纪律": "正确。上课时要遵守的是课堂的纪律。", "天气": "搭配：“遵守”的对象是规则，“天气”不能被遵守。", "颜色": "搭配：“遵守”的对象是规则，“颜色”不是规则，不能被遵守。", "空气": "搭配：空气不是规则，不能说“遵守空气”。"}, "sentence_index": 0, "correct_answer": "纪律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个菜的纪律很好，吃起来很香。", "explanation": "这里应该用〈味道〉。菜的好坏用“味道”来说，“纪律”指集体成员要遵守的行为规则，不能用来形容菜。"}, {"text": "这种花的开放纪律很明显。", "explanation": "这里应该用〈规律〉。事物发展、变化中的内在规则用“规律”，“纪律”指集体成员要遵守的行为规则，不能用于花的开放。"}, {"text": "这块布的纪律很好，颜色不掉。", "explanation": "这里应该用〈质量〉。布的好坏用“质量”来说，〈纪律〉指集体成员要遵守的行为规则，不能用来形容布料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纪律", "is_correct": true, "explanation": "正确。违反的是课堂或集体的规则，与“批评”相符。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“违反”的对象是规则，“时间”不能被违反。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”是心理情感，不能用“违反”来表示被批评的原因。"}, {"text": "空间", "is_correct": false, "explanation": "搭配：“空间”不是规则，不能说“违反空间”。"}], "explanations": {"纪律": "正确。违反的是课堂或集体的规则，与“批评”相符。", "时间": "搭配：“违反”的对象是规则，“时间”不能被违反。", "感情": "语义：“感情”是心理情感，不能用“违反”来表示被批评的原因。", "空间": "搭配：“空间”不是规则，不能说“违反空间”。"}, "sentence_index": 6, "correct_answer": "纪律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐的纪律很动听。", "explanation": "这里应该用〈旋律〉。音乐好不好听用“旋律”，“纪律”指集体成员要遵守的规则，不能用来形容音乐。"}, {"text": "这支队伍的纪律很快，三分钟就跑完了。", "explanation": "这里应该用〈速度〉。跑得快慢用“速度”，“纪律”指集体成员要遵守的行为规则，不能用来形容跑步。"}, {"text": "这篇文章的纪律很清楚。", "explanation": "这里应该用〈条理〉。文章的层次、逻辑用“条理”，“纪律”指集体成员要遵守的行为规则，不能用来形容文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学校有两个纪律。", "corrected_sentence": "这个学校有两条纪律。", "error_description": "错误：纪律的量词用了〈个〉。纪律是规则，应用量词〈条〉，应改为“两条纪律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支球队的纪律很高。", "corrected_sentence": "这支球队的纪律很严格。", "error_description": "错误：“纪律很高”；正确：“纪律很严格”。“纪律”常和“严格”“好”搭配，不说“纪律很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
