INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "组织学是研究身体里的细小部分的学问。", "primary_collocate": null, "pronunciation": "zǔ zhī xué", "ipa": "tsu˨˩ ʈʂɨ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "组织学是研究身体里细小部分的学问。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学医的学生都要上组织学课。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学里学组织学。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学老师让我们用显微镜看。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对组织学很有兴趣，常常看书。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学组织学要先学会用显微镜。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学的书里有很多图片。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门组织学很难，我考得不好。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生也需要懂一点组织学。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的组织学考试我没有考好。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "組織學", "label": "繁体"}, {"form": "组织学家", "label": "复合词"}], "register": "中性", "sense_fingerprint": "学医时要学的、用显微镜看身体细小部分的课程和学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组织学", "is_correct": true, "explanation": "组织学研究身体里细小部分的结构，「___是研究身体里细小部分的学问」指的正是这门学科。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，不研究身体里的细小部分。"}, {"text": "经济学", "is_correct": false, "explanation": "语义：经济学研究经济活动，与身体结构无关。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：「是……的学问」要用学科名称，体育是活动，不是学问。"}], "explanations": {"组织学": "组织学研究身体里细小部分的结构，「___是研究身体里细小部分的学问」指的正是这门学科。", "天文学": "语义：天文学研究天体，不研究身体里的细小部分。", "经济学": "语义：经济学研究经济活动，与身体结构无关。", "体育": "搭配：「是……的学问」要用学科名称，体育是活动，不是学问。"}, "sentence_index": 0, "correct_answer": "组织学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "组织学课上，同学们在做尸体解剖。", "explanation": "这里应该用〈解剖学〉。组织学用显微镜观察细胞和组织切片，尸体解剖属于解剖学。"}, {"text": "学校开设了一台组织学。", "explanation": "这里应该用〈门〉。量词〈台〉用于机器，学科和课程要用〈门〉。"}, {"text": "组织学研究血液怎样在全身流动。", "explanation": "这里应该用〈生理学〉。组织学研究组织的微细结构，血液怎样流动属于生理学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组织学", "is_correct": true, "explanation": "「组织学的书里有很多图片」中的主题是组织学，符合语境。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不能作为书的主题，「沙发的书」说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能作为书的主题，与「书里有很多图片」无关。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「……的书」要求有明确的主题，桌子作为主题不搭配。"}], "explanations": {"组织学": "「组织学的书里有很多图片」中的主题是组织学，符合语境。", "沙发": "语义：沙发不能作为书的主题，「沙发的书」说不通。", "冰箱": "语义：冰箱不能作为书的主题，与「书里有很多图片」无关。", "桌子": "搭配：「……的书」要求有明确的主题，桌子作为主题不搭配。"}, "sentence_index": 6, "correct_answer": "组织学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "组织学研究细菌如何感染人体。", "explanation": "这里应该用〈微生物学〉。组织学研究组织的微细结构，细菌感染人体属于微生物学。"}, {"text": "组织学研究基因如何代代相传。", "explanation": "这里应该用〈遗传学〉。组织学关注细胞和组织的结构，基因的遗传要用遗传学。"}, {"text": "这所大学开设了一座组织学。", "explanation": "这里应该用〈门〉。量词〈座〉用于建筑、山岭，学科要用〈门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他选了一只组织学。", "corrected_sentence": "他选了一门组织学。", "error_description": "量词错误：学科用「门」，「只」用于动物或成对的物品，应说「一门组织学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
