INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究生物体组织的微细结构的学科。", "primary_collocate": null, "pronunciation": "zǔ zhī xué", "ipa": "tsu˨˩ ʈʂɨ˥ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "组织学属于生物学和医学的一门学科。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学主要研究生物体组织的结构。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习组织学需要用显微镜观察切片。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学课上，老师讲了细胞的排列。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授一生都在研究组织学。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学和解剖学都是医学的基础课。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学的发展离不开显微镜的进步。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读研究生时选了组织学这个方向。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "组织学帮助医生了解身体各部分的结构。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本组织学教材介绍了很多生物组织。", "target_word": "组织学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "組織學", "label": "繁体"}, {"form": "组织学家", "label": "复合词"}], "register": "书面", "sense_fingerprint": "医学和生物学中研究生物体组织微细结构的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dfb1879-8c52-4cce-9e11-d9583ea4d71c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "组织学", "is_correct": true, "explanation": "组织学是生物学和医学的学科，「___属于生物学和医学的一门学科」指的正是它。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史属于人文学科，不属于生物学和医学。"}, {"text": "物理", "is_correct": false, "explanation": "语义：物理属于自然科学中的物理学科，不属于生物学和医学。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是艺术，不属于生物学和医学。"}], "explanations": {"组织学": "组织学是生物学和医学的学科，「___属于生物学和医学的一门学科」指的正是它。", "历史": "语义：历史属于人文学科，不属于生物学和医学。", "物理": "语义：物理属于自然科学中的物理学科，不属于生物学和医学。", "音乐": "语义：音乐是艺术，不属于生物学和医学。"}, "sentence_index": 0, "correct_answer": "组织学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "组织学研究性状如何代代相传。", "explanation": "这里应该用〈遗传学〉。组织学研究组织的微细结构，性状的遗传属于遗传学。"}, {"text": "他在大学里学了一把组织学。", "explanation": "这里应该用〈门〉。量词〈把〉用于有柄的器具，学科要用〈门〉。"}, {"text": "组织学研究激素如何调节身体。", "explanation": "这里应该用〈内分泌学〉。组织学研究组织的微细结构，激素对身体的调节属于内分泌学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "组织学", "is_correct": true, "explanation": "组织学的发展需要显微镜等工具的进步，「___的发展离不开显微镜的进步」指的正是它。"}, {"text": "芭蕾", "is_correct": false, "explanation": "语义：芭蕾是舞蹈艺术，与显微镜和微细结构无关。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是体育运动，其发展与显微镜的进步无关。"}, {"text": "相声", "is_correct": false, "explanation": "搭配：相声是曲艺表演，不能说「离不开显微镜的进步」。"}], "explanations": {"组织学": "组织学的发展需要显微镜等工具的进步，「___的发展离不开显微镜的进步」指的正是它。", "芭蕾": "语义：芭蕾是舞蹈艺术，与显微镜和微细结构无关。", "足球": "语义：足球是体育运动，其发展与显微镜的进步无关。", "相声": "搭配：相声是曲艺表演，不能说「离不开显微镜的进步」。"}, "sentence_index": 6, "correct_answer": "组织学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本组织学教材讲了古代战争的历史。", "explanation": "这里应该用〈历史学〉。组织学研究组织的微细结构，古代战争的历史属于历史学。"}, {"text": "他在大学里学了一条组织学。", "explanation": "这里应该用〈门〉。量词〈条〉用于长的东西，学科要用〈门〉。"}, {"text": "组织学研究生物与环境的关系。", "explanation": "这里应该用〈生态学〉。组织学研究组织的微细结构，生物与环境的关系属于生态学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbd9ff5-40fc-4795-93e0-b2101931d359') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
