INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "绝大多数是差不多全部，只有很少的例外。", "primary_collocate": null, "pronunciation": "jué dà duō shù", "ipa": "tɕyɛ˧˥ ta˥˩ tuo˥ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "这些菜绝大多数都卖完了。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书我绝大多数都看过。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的同学绝大多数都去过北京。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绝大多数时间他都在家。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的绝大多数人我都认识。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国绝大多数地方今天下雨了。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绝大多数问题我都能回答。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里绝大多数老师都参加了培训。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他绝大多数时候都很安静。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上绝大多数人都唱了歌。", "target_word": "绝大多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "差不多全部，只有极少例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd92a59cf-6673-4b7a-9df1-a19597e37236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝大多数", "is_correct": true, "explanation": "绝大多数表示差不多全部，填入后“这些菜绝大多数都卖完了”通顺。"}, {"text": "一点儿", "is_correct": false, "explanation": "搭配：“一点儿”后接“都”只用于否定句，“这些菜一点儿都卖完了”不通。"}, {"text": "一个人", "is_correct": false, "explanation": "搭配：“一个人”不能与“这些菜”搭配作主语，句子不通。"}, {"text": "一位同学", "is_correct": false, "explanation": "搭配：“一位同学”指人，不能与“这些菜”搭配，句子不通。"}], "explanations": {"绝大多数": "绝大多数表示差不多全部，填入后“这些菜绝大多数都卖完了”通顺。", "一点儿": "搭配：“一点儿”后接“都”只用于否定句，“这些菜一点儿都卖完了”不通。", "一个人": "搭配：“一个人”不能与“这些菜”搭配作主语，句子不通。", "一位同学": "搭配：“一位同学”指人，不能与“这些菜”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "绝大多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班绝大多数同学只有一个人及格了。", "explanation": "这里误把“绝大多数”当作“个别”来用。绝大多数指差不多全部，“只有一个人及格”说明极少，与之矛盾。"}, {"text": "我一个人的绝大多数都没去。", "explanation": "这里误把“绝大多数”当作“个体中的大部分”来用。绝大多数指由许多个体组成的群体中差不多全部，“我一个人”不构成群体。"}, {"text": "这壶茶绝大多数我都喝完了。", "explanation": "这里应该用〈差不多〉或〈几乎〉。绝大多数要求由许多个体组成的群体，“茶”是不可数的整体，应说“差不多都喝完了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝大多数", "is_correct": true, "explanation": "绝大多数表示差不多全部，填入后“绝大多数问题我都能回答”通顺。"}, {"text": "每个人", "is_correct": false, "explanation": "搭配：“每个人”指人，不能修饰“问题”，句子不通。"}, {"text": "一小撮", "is_correct": false, "explanation": "搭配：“一小撮”指很少的人或事，与“我都能回答”搭配不当。"}, {"text": "一位老师", "is_correct": false, "explanation": "搭配：“一位老师”指人，不能修饰“问题”，句子不通。"}], "explanations": {"绝大多数": "绝大多数表示差不多全部，填入后“绝大多数问题我都能回答”通顺。", "每个人": "搭配：“每个人”指人，不能修饰“问题”，句子不通。", "一小撮": "搭配：“一小撮”指很少的人或事，与“我都能回答”搭配不当。", "一位老师": "搭配：“一位老师”指人，不能修饰“问题”，句子不通。"}, "sentence_index": 6, "correct_answer": "绝大多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚会上绝大多数人只有一个人唱了歌。", "explanation": "这里误把“绝大多数”当作“个别”来用。绝大多数指差不多全部，“只有一个人唱了歌”说明极少，与之矛盾。"}, {"text": "晚会上绝大多数人唱了歌，但有一半的人没唱。", "explanation": "这里误把“绝大多数”当作“一半”来用。绝大多数指差不多全部，“一半的人没唱”与之矛盾，应说“大多数人唱了歌”。"}, {"text": "晚会上绝大多数人只有我一个人。", "explanation": "这里误把“绝大多数”当作“个体”来用。绝大多数指差不多全部，“只有我一个人”是单个个体，不能构成绝大多数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很绝大多数作业我都做完了。", "corrected_sentence": "绝大多数作业我都做完了。", "error_description": "“很”不能修饰“绝大多数”。“绝大多数”是数量表达，应直接放在名词前，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "绝大多数个朋友都很支持我。", "corrected_sentence": "绝大多数朋友都很支持我。", "error_description": "“个”是个体量词，不能插在“绝大多数”和名词之间。应直接说“绝大多数朋友”，去掉“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
