INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "创作剧本的人。", "primary_collocate": null, "pronunciation": "biān jù", "ipa": "pjɛn˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "编剧花了半年时间才写完这个剧本。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话剧的编剧是一位有名的老作家。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视剧还没拍完，编剧就要改剧本了。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他既是这部戏的导演，也是它的编剧。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编剧需要有丰富的想象力，还要懂得人物的心理。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员对剧本有意见时，会先去找编剧谈一谈。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编剧在剧本里为每个角色写了不同的台词。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位编剧的作品得过很多奖。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想成为编剧的人要多读书，多看戏。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了三位编剧一起写这部电视剧。", "target_word": "编剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "总编剧", "label": "复合"}, {"form": "編劇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "创作剧本的人，常与导演、演员并提", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96256, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "编剧", "is_correct": true, "explanation": "正确答案：编剧，指创作剧本的人。"}, {"text": "编组", "is_correct": false, "explanation": "zǔ 与 jù 声母不同（z 与 j），声调也不同，意思是按次序组成的队或编排车厢。"}, {"text": "编曲", "is_correct": false, "explanation": "qǔ 与 jù 声母不同（q 与 j），声调也不同（第三声与第四声），意思是为乐曲作曲或配器。"}, {"text": "边际", "is_correct": false, "explanation": "jì 与 jù 韵母不同（i 与 ü），声调相同，意思是边缘或界限。"}, {"text": "编辑", "is_correct": false, "explanation": "jí 与 jù 韵母不同（i 与 ü），声调也不同，意思是整理、修改书报或影视材料。"}], "explanations": {"编剧": "正确答案：编剧，指创作剧本的人。", "编组": "zǔ 与 jù 声母不同（z 与 j），声调也不同，意思是按次序组成的队或编排车厢。", "编曲": "qǔ 与 jù 声母不同（q 与 j），声调也不同（第三声与第四声），意思是为乐曲作曲或配器。", "边际": "jì 与 jù 韵母不同（i 与 ü），声调相同，意思是边缘或界限。", "编辑": "jí 与 jù 韵母不同（i 与 ü），声调也不同，意思是整理、修改书报或影视材料。"}, "sentence_index": null, "correct_answer": "编剧"}, "level_3": {"options": [{"text": "演员", "is_correct": false, "explanation": "语义：演员负责表演，不负责写剧本。"}, {"text": "编剧", "is_correct": true, "explanation": "正确：编剧是创作剧本的人，花时间写剧本的正是编剧。"}, {"text": "读者", "is_correct": false, "explanation": "语义：读者是看剧本的人，不会写完剧本。"}, {"text": "出版社", "is_correct": false, "explanation": "配价：“写完”要求能动笔的人作主语，出版社是机构，不能写剧本。"}], "explanations": {"演员": "语义：演员负责表演，不负责写剧本。", "编剧": "正确：编剧是创作剧本的人，花时间写剧本的正是编剧。", "读者": "语义：读者是看剧本的人，不会写完剧本。", "出版社": "配价：“写完”要求能动笔的人作主语，出版社是机构，不能写剧本。"}, "sentence_index": 0, "correct_answer": "编剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "编剧在片场调整灯光的亮度。", "explanation": "这里应该用〈灯光师〉。调整灯光的是灯光师，编剧只负责剧本。"}, {"text": "编剧在墙上画了一幅壁画。", "explanation": "这里应该用〈画家〉。画壁画的是画家，编剧不画画。"}, {"text": "编剧在片场扛着摄像机拍了一整天。", "explanation": "这里应该用〈摄影师〉。扛着摄像机拍摄的是摄影师，编剧不负责拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96256, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "编剧", "is_correct": true, "explanation": "正确答案：编剧，指创作剧本的人。"}, {"text": "分句", "is_correct": false, "explanation": "fēn 与 biān 声母（f 与 b）和韵母（en 与 ian）都不同，声调相同；jù 相同。意思是复句中的一个组成部分。"}, {"text": "单据", "is_correct": false, "explanation": "dān 与 biān 声母（d 与 b）和韵母（an 与 ian）都不同，声调相同；jù 相同。意思是记录经济往来的凭证。"}, {"text": "番剧", "is_correct": false, "explanation": "fān 与 biān 声母（f 与 b）和韵母（an 与 ian）都不同，声调相同；jù 相同。意思是分集播出的动画作品。"}, {"text": "变局", "is_correct": false, "explanation": "biàn 与 biān 声调不同，jú 与 jù 声调也不同，意思是局势的变化。"}], "explanations": {"编剧": "正确答案：编剧，指创作剧本的人。", "分句": "fēn 与 biān 声母（f 与 b）和韵母（en 与 ian）都不同，声调相同；jù 相同。意思是复句中的一个组成部分。", "单据": "dān 与 biān 声母（d 与 b）和韵母（an 与 ian）都不同，声调相同；jù 相同。意思是记录经济往来的凭证。", "番剧": "fān 与 biān 声母（f 与 b）和韵母（an 与 ian）都不同，声调相同；jù 相同。意思是分集播出的动画作品。", "变局": "biàn 与 biān 声调不同，jú 与 jù 声调也不同，意思是局势的变化。"}, "sentence_index": null, "correct_answer": "编剧"}, "level_3": {"options": [{"text": "运动员", "is_correct": false, "explanation": "语义：运动员参加比赛，不负责为角色写台词。"}, {"text": "花匠", "is_correct": false, "explanation": "语义：花匠照料花草，不写剧本里的台词。"}, {"text": "画家", "is_correct": false, "explanation": "搭配：“写”和“台词”搭配，画家画的是画，不说写台词。"}, {"text": "编剧", "is_correct": true, "explanation": "正确：编剧负责在剧本里为角色写台词。"}], "explanations": {"运动员": "语义：运动员参加比赛，不负责为角色写台词。", "花匠": "语义：花匠照料花草，不写剧本里的台词。", "画家": "搭配：“写”和“台词”搭配，画家画的是画，不说写台词。", "编剧": "正确：编剧负责在剧本里为角色写台词。"}, "sentence_index": 6, "correct_answer": "编剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "编剧在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。在法庭上为被告辩护的是律师，编剧写的是剧本，不做辩护工作。"}, {"text": "编剧每天给病人量体温、换药。", "explanation": "这里应该用〈护士〉。给病人量体温、换药的是护士，编剧不负责护理病人。"}, {"text": "编剧开着出租车送乘客去机场。", "explanation": "这里应该用〈司机〉。开出租车送乘客的是司机，编剧不做这种工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位年轻地编剧已经写完了三集剧本。", "corrected_sentence": "这位年轻的编剧已经写完了三集剧本。", "error_description": "结构助词错误：修饰名词“编剧”要用“的”，应写“年轻的编剧”；“地”用于修饰动词，“年轻地编剧”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司请了一本新编剧。", "corrected_sentence": "公司请了一位新编剧。", "error_description": "量词错误：“编剧”指人，应用“位”，不能用“本”（“本”用于书、剧本等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
