INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脖子是连着头和身体的那一小段。", "primary_collocate": null, "pronunciation": "bó zi", "ipa": "pwo˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "冬天我用围巾围住脖子。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脖子很长，像一只鹅。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡错了姿势，脖子很疼。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把围巾绕在脖子上。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长颈鹿的脖子特别长。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬了很久的头，脖子有点酸。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我慢慢转动脖子。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫趴在我的脖子上睡着了。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，他的脖子上都是汗。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脖子上戴着一条项链。", "target_word": "脖子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "脖子：日常说的连着头和身体的那一小段身体部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96257, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脖子", "is_correct": true, "explanation": "正确答案。脖子 bó zi，连着头和身体的部分。"}, {"text": "鼻子", "is_correct": false, "explanation": "韵母不同：bí（第二声）的韵母是 i，bó 的韵母是 o，bí 的意思是鼻子。"}, {"text": "婆子", "is_correct": false, "explanation": "声母不同：pó（第二声）的声母是 p，bó 的声母是 b，pó zi 的意思是老年妇女（口语）。"}, {"text": "钵子", "is_correct": false, "explanation": "声调不同：bō（第一声）与 bó（第二声）声调不同，bō zi 的意思是钵子（一种碗）。"}], "explanations": {"脖子": "正确答案。脖子 bó zi，连着头和身体的部分。", "鼻子": "韵母不同：bí（第二声）的韵母是 i，bó 的韵母是 o，bí 的意思是鼻子。", "婆子": "声母不同：pó（第二声）的声母是 p，bó 的声母是 b，pó zi 的意思是老年妇女（口语）。", "钵子": "声调不同：bō（第一声）与 bó（第二声）声调不同，bō zi 的意思是钵子（一种碗）。"}, "sentence_index": null, "correct_answer": "脖子"}, "level_3": {"options": [{"text": "脖子", "is_correct": true, "explanation": "正确答案。围巾可以围在颈部，“脖子”指连着头和身体的部位。"}, {"text": "时间", "is_correct": false, "explanation": "语义：围巾是实物，“时间”是抽象概念，不能被围住。"}, {"text": "理想", "is_correct": false, "explanation": "语义：“理想”是抽象的追求，不能被围巾围住，与“冬天”保暖的情境冲突。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“围住”后接的应是有形的身体部位或物件，不说围住“心情”。"}], "explanations": {"脖子": "正确答案。围巾可以围在颈部，“脖子”指连着头和身体的部位。", "时间": "语义：围巾是实物，“时间”是抽象概念，不能被围住。", "理想": "语义：“理想”是抽象的追求，不能被围巾围住，与“冬天”保暖的情境冲突。", "心情": "搭配：“围住”后接的应是有形的身体部位或物件，不说围住“心情”。"}, "sentence_index": 0, "correct_answer": "脖子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的脖子又大又亮。", "explanation": "这里应该用〈眼睛〉。“又大又亮”形容眼睛，不能用来形容脖子。"}, {"text": "他吃得太多，脖子很撑。", "explanation": "这里应该用〈肚子〉。“撑”说的是肚子装满，不说脖子撑。"}, {"text": "他皱着脖子，看起来很不高兴。", "explanation": "这里应该用〈眉毛〉。“皱”用于眉毛，不说皱脖子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脖子", "is_correct": true, "explanation": "正确答案。医生让人慢慢转动的是颈部，“脖子”指连着头和身体的部位。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不是可以转动的具体事物，与身体活动的语境冲突。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空无法被人慢慢转动，这里指身体的活动。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“转动”不与“故事”搭配，句中说的是身体的活动。"}], "explanations": {"脖子": "正确答案。医生让人慢慢转动的是颈部，“脖子”指连着头和身体的部位。", "数学": "语义：“数学”是学科，不是可以转动的具体事物，与身体活动的语境冲突。", "天空": "语义：天空无法被人慢慢转动，这里指身体的活动。", "故事": "搭配：“转动”不与“故事”搭配，句中说的是身体的活动。"}, "sentence_index": 6, "correct_answer": "脖子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站到台上，先清了清脖子。", "explanation": "这里应该用〈嗓子〉。“清嗓子”指清理喉咙，不说“清脖子”。"}, {"text": "他朝我伸出脖子，要跟我握手。", "explanation": "这里应该用〈手〉。“握手”要伸出手，不说伸出脖子。"}, {"text": "老师问完，他轻轻地点了点脖子。", "explanation": "这里应该用〈头〉。“点头”指头部的动作，不说“点脖子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把脖子被扭了，动不了。", "corrected_sentence": "我的脖子被扭了，动不了。", "error_description": "错误：“把”与“被”同用，句式冲突。“脖子”作主语时只用“被”，应说“我的脖子被扭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他打篮球时拉伤了脖子们。", "corrected_sentence": "他打篮球时拉伤了脖子。", "error_description": "错误：“脖子”是身体部位，不能加表示人群的后缀“们”。正确为“拉伤了脖子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
