INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "十进制数中从右数第五位。", "primary_collocate": null, "pronunciation": "wàn wèi", "ipa": "wan˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "十进制里，从右数第五位叫万位。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "63427的万位是6，千位是3。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数的万位上没有数，所以只有四位。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万位上的2表示两万。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先看了万位，再看千位。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个五位数，万位是5的比万位是3的大。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把9放在万位，这个数就变大了。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个位、十位、百位、千位之后，就是万位。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题让我们填出万位上的数字。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要比较两个五位数，先比万位。", "target_word": "万位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "萬位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "十进制记数法中从右数的第五个数位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0aec723e-4c3d-4b32-a6e4-74bef640e8d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "万位", "is_correct": true, "explanation": "正确答案。十进制数中从右数第五位叫万位。"}, {"text": "换位", "is_correct": false, "explanation": "huàn wèi 与 wàn wèi 只差声母（h 与 w），声调相同，意思是交换位置。"}, {"text": "站位", "is_correct": false, "explanation": "zhàn wèi 与 wàn wèi 只差声母（zh 与 w），声调相同，意思是站立的位置。"}, {"text": "万倍", "is_correct": false, "explanation": "wàn bèi 与 wàn wèi 只差第二音节声母（b 与 w），声调相同，意思是一万倍。"}], "explanations": {"万位": "正确答案。十进制数中从右数第五位叫万位。", "换位": "huàn wèi 与 wàn wèi 只差声母（h 与 w），声调相同，意思是交换位置。", "站位": "zhàn wèi 与 wàn wèi 只差声母（zh 与 w），声调相同，意思是站立的位置。", "万倍": "wàn bèi 与 wàn wèi 只差第二音节声母（b 与 w），声调相同，意思是一万倍。"}, "sentence_index": null, "correct_answer": "万位"}, "level_3": {"options": [{"text": "万位", "is_correct": true, "explanation": "正确。从右数第五位的名称就是万位。"}, {"text": "个位", "is_correct": false, "explanation": "语义：个位是从右数第一位，与“从右数第五位”矛盾。"}, {"text": "小数点", "is_correct": false, "explanation": "语义：小数点是标点，不是数位，与“从右数第五位叫”不相容。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不是数位名称，不能与“叫”和“十进制里”构成合理表达。"}], "explanations": {"万位": "正确。从右数第五位的名称就是万位。", "个位": "语义：个位是从右数第一位，与“从右数第五位”矛盾。", "小数点": "语义：小数点是标点，不是数位，与“从右数第五位叫”不相容。", "身高": "搭配：“身高”不是数位名称，不能与“叫”和“十进制里”构成合理表达。"}, "sentence_index": 0, "correct_answer": "万位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子的万位很大。", "explanation": "这里应该用〈面积〉。桌面的大小用“面积”，“万位”只指数的位置，不能用来形容桌子。"}, {"text": "这台电脑的万位很快。", "explanation": "“万位”只指数的位置，不能指机器的性能，“快”也不能修饰它，这里是误用，没有替代词。"}, {"text": "这首歌的万位很好听。", "explanation": "“万位”不能指歌曲的旋律或内容，这里是误用，没有替代词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96260, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "万位", "is_correct": true, "explanation": "正确答案。从右数第五位叫万位。"}, {"text": "王位", "is_correct": false, "explanation": "wáng wèi 与 wàn wèi 韵尾不同（ng 与 n）且声调不同，意思是君主的地位。"}, {"text": "玩味", "is_correct": false, "explanation": "wán wèi 与 wàn wèi 只差声调（2 与 4），意思是细细体会。"}, {"text": "万物", "is_correct": false, "explanation": "wàn wù 与 wàn wèi 只差第二音节韵母（u 与 ei），声调相同，意思是各种事物。"}], "explanations": {"万位": "正确答案。从右数第五位叫万位。", "王位": "wáng wèi 与 wàn wèi 韵尾不同（ng 与 n）且声调不同，意思是君主的地位。", "玩味": "wán wèi 与 wàn wèi 只差声调（2 与 4），意思是细细体会。", "万物": "wàn wù 与 wàn wèi 只差第二音节韵母（u 与 ei），声调相同，意思是各种事物。"}, "sentence_index": null, "correct_answer": "万位"}, "level_3": {"options": [{"text": "万位", "is_correct": true, "explanation": "正确。把9放在第五位，才符合“这个数就变大了”的数位含义。"}, {"text": "角落", "is_correct": false, "explanation": "语义：角落不是数位，把数字放在角落不能让数变大，与“这个数”的语境矛盾。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“放在”后不能接“微笑”作为位置，与“把9”的搭配也不成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是数位，把9放进书包不能让这个数变大，语境不相容。"}], "explanations": {"万位": "正确。把9放在第五位，才符合“这个数就变大了”的数位含义。", "角落": "语义：角落不是数位，把数字放在角落不能让数变大，与“这个数”的语境矛盾。", "微笑": "搭配：“放在”后不能接“微笑”作为位置，与“把9”的搭配也不成立。", "书包": "语义：书包不是数位，把9放进书包不能让这个数变大，语境不相容。"}, "sentence_index": 6, "correct_answer": "万位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我坐在这个万位上，很舒服。", "explanation": "这里应该用〈位置〉。“万位”只指数中的一个数位，不能指座位，说座位要用“位置”。"}, {"text": "这条路的万位很远。", "explanation": "这里应该用〈距离〉。路程的远近用“距离”，“万位”只指数的位置，不能用来形容路。"}, {"text": "他把万位放进了口袋里。", "explanation": "“万位”是数的位置，不是可以装进口袋的东西，这里是误用，没有替代词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先算了万位上数。", "corrected_sentence": "他先算了万位上的数。", "error_description": "错误：“万位上数”；正确：“万位上的数”。定语“万位上的”修饰“数”时，中间必须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在五位数里，万位在千位的右边。", "corrected_sentence": "在五位数里，万位在千位的左边。", "error_description": "错误：“万位在千位的右边”；正确：“万位在千位的左边”。万位是从右数第五位，比千位更靠左。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cc678ef-1029-4d43-a3f3-5e0e59b6ec34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厚", "is_correct": true, "explanation": "“厚”指厚度大，与“薄”（厚度小）相对。"}, {"text": "宽", "is_correct": false, "explanation": "“宽”与“薄”在此义下没有反义关系，“宽”的反义词是“窄”。"}, {"text": "高", "is_correct": false, "explanation": "“高”与“薄”的任何义项都没有反义关系，“高”的反义词是“低”。"}, {"text": "远", "is_correct": false, "explanation": "“远”与“薄”在此义下没有反义关系，“远”的反义词是“近”。"}], "correct_answer": "厚", "explanations": {"厚": "“厚”指厚度大，与“薄”（厚度小）相对。", "宽": "“宽”与“薄”在此义下没有反义关系，“宽”的反义词是“窄”。", "高": "“高”与“薄”的任何义项都没有反义关系，“高”的反义词是“低”。", "远": "“远”与“薄”在此义下没有反义关系，“远”的反义词是“近”。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "厚", "is_correct": true, "explanation": "“厚”指厚度大，与“薄”（厚度小）相对。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”与“薄”在此义下没有反义关系，“亮”的反义词是“暗”。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“薄”在此义下没有反义关系，“快”的反义词是“慢”。"}, {"text": "近", "is_correct": false, "explanation": "“近”与“薄”在此义下没有反义关系，“近”的反义词是“远”。"}], "correct_answer": "厚", "explanations": {"厚": "“厚”指厚度大，与“薄”（厚度小）相对。", "亮": "“亮”与“薄”在此义下没有反义关系，“亮”的反义词是“暗”。", "快": "“快”与“薄”在此义下没有反义关系，“快”的反义词是“慢”。", "近": "“近”与“薄”在此义下没有反义关系，“近”的反义词是“远”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "厚度小的。", "primary_collocate": null, "pronunciation": "báo", "ipa": "pau̯˧˥", "syllable_count": 1, "sentences": [{"text": "这本书很薄，一个晚上就能看完。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，这件外套太薄了。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块很薄的毛巾。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸太薄，写字时会透到后面。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙太薄，隔壁的声音听得很清楚。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面包切得很薄，放进盘子里。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布很薄，夏天穿正合适。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机做得越来越薄，拿着很轻。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰很薄，你们别走上去。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条被子太薄，晚上盖着还是冷。", "target_word": "薄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "薄薄的", "label": "重叠"}, {"form": "薄片", "label": "复合"}], "register": "中性", "sense_fingerprint": "厚度小，与“厚”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd92a59cf-6673-4b7a-9df1-a19597e37236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "薄", "is_correct": true, "explanation": "薄 báo（第二声），指东西的厚度小。"}, {"text": "保", "is_correct": false, "explanation": "bǎo（第三声）与 báo（第二声）声调不同，意思是保护。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 báo（第二声）声调不同，意思是包裹。"}, {"text": "报", "is_correct": false, "explanation": "bào（第四声）与 báo（第二声）声调不同，意思是报纸或报告。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo（第三声）与 báo（第二声）声调不同，意思是宝贝。"}, {"text": "抱", "is_correct": false, "explanation": "bào（第四声）与 báo（第二声）声调不同，意思是拥抱。"}], "explanations": {"薄": "薄 báo（第二声），指东西的厚度小。", "保": "bǎo（第三声）与 báo（第二声）声调不同，意思是保护。", "包": "bāo（第一声）与 báo（第二声）声调不同，意思是包裹。", "报": "bào（第四声）与 báo（第二声）声调不同，意思是报纸或报告。", "宝": "bǎo（第三声）与 báo（第二声）声调不同，意思是宝贝。", "抱": "bào（第四声）与 báo（第二声）声调不同，意思是拥抱。"}, "sentence_index": null, "correct_answer": "薄"}, "level_3": {"options": [{"text": "薄", "is_correct": true, "explanation": "薄表示厚度小，填入后“这本书很薄，一个晚上就能看完”通顺。"}, {"text": "长", "is_correct": false, "explanation": "语义：“长”指篇幅大，与“一个晚上就能看完”矛盾。"}, {"text": "难", "is_correct": false, "explanation": "语义：“难”指内容难懂，与“一个晚上就能看完”的语境不协调。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”指厚度大，厚书一般读得慢，与“一个晚上就能看完”矛盾。"}], "explanations": {"薄": "薄表示厚度小，填入后“这本书很薄，一个晚上就能看完”通顺。", "长": "语义：“长”指篇幅大，与“一个晚上就能看完”矛盾。", "难": "语义：“难”指内容难懂，与“一个晚上就能看完”的语境不协调。", "厚": "语义：“厚”指厚度大，厚书一般读得慢，与“一个晚上就能看完”矛盾。"}, "sentence_index": 0, "correct_answer": "薄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本字典很薄，有一千多页。", "explanation": "这里应该用〈厚〉。“薄”指厚度小，一千多页的字典应说“很厚”，不能说“很薄”。"}, {"text": "这根麻绳很薄，捆东西很结实。", "explanation": "这里应该用〈细〉。绳子这类细长的东西应说“细”，“薄”用于扁平物体的厚度小。"}, {"text": "这面墙很薄，隔音效果特别好。", "explanation": "这里应该用〈厚〉。隔音好的墙要厚，“薄”与“隔音效果特别好”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "薄", "is_correct": true, "explanation": "薄 báo（第二声），指东西的厚度小。"}, {"text": "饱", "is_correct": false, "explanation": "bǎo（第三声）与 báo（第二声）声调不同，意思是吃饱、饱满。"}, {"text": "暴", "is_correct": false, "explanation": "bào（第四声）与 báo（第二声）声调不同，意思是暴露或暴力。"}, {"text": "爆", "is_correct": false, "explanation": "bào（第四声）与 báo（第二声）声调不同，意思是爆炸或爆裂。"}], "explanations": {"薄": "薄 báo（第二声），指东西的厚度小。", "饱": "bǎo（第三声）与 báo（第二声）声调不同，意思是吃饱、饱满。", "暴": "bào（第四声）与 báo（第二声）声调不同，意思是暴露或暴力。", "爆": "bào（第四声）与 báo（第二声）声调不同，意思是爆炸或爆裂。"}, "sentence_index": null, "correct_answer": "薄"}, "level_3": {"options": [{"text": "薄", "is_correct": true, "explanation": "薄表示厚度小，填入后“这块布很薄，夏天穿正合适”通顺。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”指厚实，与“夏天穿正合适”矛盾。"}, {"text": "暖", "is_correct": false, "explanation": "语义：“暖”指保暖，与“夏天”的语境矛盾。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”指分量大，用在夏天穿的布料上不合适。"}], "explanations": {"薄": "薄表示厚度小，填入后“这块布很薄，夏天穿正合适”通顺。", "厚": "语义：“厚”指厚实，与“夏天穿正合适”矛盾。", "暖": "语义：“暖”指保暖，与“夏天”的语境矛盾。", "重": "语义：“重”指分量大，用在夏天穿的布料上不合适。"}, "sentence_index": 6, "correct_answer": "薄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根头发很薄，几乎看不见。", "explanation": "头发这类细长的东西应用“细”，“薄”用于扁平物体的厚度小，这里用错了词。"}, {"text": "这个池塘很薄，水只有一米。", "explanation": "水的深浅应用“浅”，不用“薄”，这里应该说“很浅”。"}, {"text": "这条路很薄，只能走一个人。", "explanation": "路的宽度应用“窄”，不用“薄”，这里应该说“很窄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服薄很，夏天穿正好。", "corrected_sentence": "这件衣服很薄，夏天穿正好。", "error_description": "形容词“薄”作谓语时，程度副词“很”应放在前面，应说“很薄”，不能说“薄很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条被子很薄薄的，晚上盖着冷。", "corrected_sentence": "这条被子薄薄的，晚上盖着冷。", "error_description": "“薄薄的”是重叠形式，本身已表示程度，前面不能再加程度副词“很”。应说“薄薄的”或“很薄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
