INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解散是原来在一起的人，各自走开。", "primary_collocate": null, "pronunciation": "jiě sàn", "ipa": "tɕje˨˩˦ san˥˩", "syllable_count": 2, "sentences": [{"text": "队伍走到学校门口就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说一声“解散”，同学们就各自回家了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到“解散”的口令，大家马上跑开了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "训练结束，教练一挥手，大家就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开完会，大家在门口说了再见就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游行的人群到广场后就解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站了半个小时后，同学们终于解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "升旗仪式一结束，学生们就解散回教室了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "集合了一个小时，大家才解散回家。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，队员们在球场上解散了。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "解散了", "label": "体标"}, {"form": "解散过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不及物：聚在一起的人各自走开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解散", "is_correct": true, "explanation": "正确：“解散”指人群各自走开，与“队伍走到学校门口”的语境合理。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：队伍不能“游泳”，句子说不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”是生理动作，与队伍到门口的意思无关。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主语是学生，队伍不能毕业。"}], "explanations": {"解散": "正确：“解散”指人群各自走开，与“队伍走到学校门口”的语境合理。", "游泳": "语义：队伍不能“游泳”，句子说不通。", "呼吸": "语义：“呼吸”是生理动作，与队伍到门口的意思无关。", "毕业": "搭配：“毕业”的主语是学生，队伍不能毕业。"}, "sentence_index": 0, "correct_answer": "解散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理决定解散这位员工的职务。", "explanation": "这里应该用〈解除〉。解散指原来在一起的人各自走开，不能带“职务”这种宾语；解除职务要用解除。"}, {"text": "教练一挥手，大家就解散了操场。", "explanation": "这里应该用〈离开〉。解散表示人群各自走开，不带处所宾语“操场”。"}, {"text": "会议结束后，大家又解散在一起了。", "explanation": "这里应该用〈集合〉。解散表示各自走开，与“在一起”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解散", "is_correct": true, "explanation": "正确：“解散”指人群各自走开，“站了半个小时后终于”之后正是散开的时候。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光的消失，不能用于同学。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”只说液体凝固，不能用于同学。"}, {"text": "殉职", "is_correct": false, "explanation": "语义：“殉职”指在工作中牺牲，同学们站了半个小时不可能“殉职”，句子说不通。"}], "explanations": {"解散": "正确：“解散”指人群各自走开，“站了半个小时后终于”之后正是散开的时候。", "熄灭": "语义：“熄灭”指火或光的消失，不能用于同学。", "结冰": "语义：“结冰”只说液体凝固，不能用于同学。", "殉职": "语义：“殉职”指在工作中牺牲，同学们站了半个小时不可能“殉职”，句子说不通。"}, "sentence_index": 6, "correct_answer": "解散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛结束后，队员们把比赛解散了。", "explanation": "这里应该用〈结束〉。解散表示人群各自走开，不能用来处理比赛。"}, {"text": "比赛结束后，观众们解散了球场。", "explanation": "这里应该用〈撤离〉。解散不带处所宾语“球场”。"}, {"text": "比赛结束后，队员们解散成一排。", "explanation": "这里应该用〈站成一排〉。解散表示各自走开，不能表示排成一排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出结束后，观众们很快就解散了现场。", "corrected_sentence": "演出结束后，观众们很快就解散了。", "error_description": "错误：多了宾语“现场”。正确：“解散了”。不及物的“解散”表示各自走开，不带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后，同学们都解散家回了。", "corrected_sentence": "下课后，同学们都解散回家了。", "error_description": "错误：“家回”。正确：“回家”。“回家”是动宾短语，接在“解散”之后，词序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
