INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使集体或组织散伙；让队伍散开。", "primary_collocate": null, "pronunciation": "jiě sàn", "ipa": "tɕje˨˩˦ san˥˩", "syllable_count": 2, "sentences": [{"text": "老板决定解散这家小公司。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府下令解散这个非法组织。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练说完话，就解散了队伍。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校决定解散这个没有人参加的社团。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们因为没钱，只好解散了乐队。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理想解散这个工作小组，重新找人。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王下令解散军队，让大家回家种地。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，教练宣布解散这支球队。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察解散了没有批准的集会。", "target_word": "解散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "任务结束后，军官下令解散这个临时组建的连队。", "target_word": "解散", "complexity_tier": "T3", "furigana": "rèn wù jié shù hòu, jūn guān xià lìng jiě sàn zhè ge lín shí zǔ jiàn de lián duì.", "sentence_source": "generated"}], "morphological_forms": [{"form": "解散了", "label": "体标"}, {"form": "解散过", "label": "体标"}], "register": "中性", "sense_fingerprint": "及物：使组织、团体散伙，或让队伍散开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解散", "is_correct": true, "explanation": "正确：“解散”是使公司散伙，与“老板决定”和“小公司”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”是擦拭动作，不能以公司为宾语，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能以公司为宾语，句子说不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，与公司无关。"}], "explanations": {"解散": "正确：“解散”是使公司散伙，与“老板决定”和“小公司”搭配。", "擦": "语义：“擦”是擦拭动作，不能以公司为宾语，句子说不通。", "唱": "语义：“唱”不能以公司为宾语，句子说不通。", "煮": "语义：“煮”是烹饪动作，与公司无关。"}, "sentence_index": 0, "correct_answer": "解散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校决定解散这场比赛。", "explanation": "这里应该用〈取消〉。解散用于组织、团体，比赛要用取消。"}, {"text": "公司决定解散这名员工。", "explanation": "这里应该用〈解雇〉。解散指使团体散伙，个人要用解雇，不能说“解散这名员工”。"}, {"text": "工厂决定解散这台机器。", "explanation": "这里应该用〈报废〉。解散指使团体散伙，机器不是团体，要用报废。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解散", "is_correct": true, "explanation": "正确：“解散”是使军队散开，与“国王下令”和“让大家回家”的语境一致。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”的宾语是消息或决定，不能说“宣布军队”。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”针对动物或幼儿，不能用于军队。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能以军队为宾语，句子说不通。"}], "explanations": {"解散": "正确：“解散”是使军队散开，与“国王下令”和“让大家回家”的语境一致。", "宣布": "搭配：“宣布”的宾语是消息或决定，不能说“宣布军队”。", "喂养": "语义：“喂养”针对动物或幼儿，不能用于军队。", "唱": "语义：“唱”不能以军队为宾语，句子说不通。"}, "sentence_index": 6, "correct_answer": "解散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国会决定解散这条法律。", "explanation": "这里应该用〈废除〉。解散用于组织、团体，法律要用废除。"}, {"text": "军官下令解散这个命令。", "explanation": "这里应该用〈撤销〉。解散针对团体，命令要用撤销。"}, {"text": "他们决定解散这个计划。", "explanation": "这里应该用〈放弃〉。解散用于组织、团体，计划要用放弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校正在解散了这个社团，因为没有人参加。", "corrected_sentence": "学校正在解散这个社团，因为没有人参加。", "error_description": "错误：“正在”与“了”不能同时用。正确：去掉“了”，“正在解散”表示动作进行中。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导很解散了这个委员会。", "corrected_sentence": "领导很快解散了这个委员会。", "error_description": "错误：“很”不能直接修饰动作动词“解散”。正确：用“很快”作状语，说“很快解散了这个委员会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96266, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
