INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比赛的活动。", "primary_collocate": null, "pronunciation": "sài shì", "ipa": "sai̯˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市每年都会举办很多体育赛事。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雨，今天的赛事取消了。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在电视上看足球赛事。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一场重要的国际赛事。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赛事一共分为三天进行。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上可以免费看赛事直播。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的赛事安排已经出来了。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为这次赛事练了半年。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国运动员都来参加这次赛事。", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的赛事几点开始？", "target_word": "赛事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体育赛事", "label": "复合"}, {"form": "赛事直播", "label": "复合"}], "register": "书面", "sense_fingerprint": "比赛这类活动，如举办、取消、直播的赛事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd92a59cf-6673-4b7a-9df1-a19597e37236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96266, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赛事", "is_correct": true, "explanation": "正确答案。赛事指比赛的活动。"}, {"text": "菜市", "is_correct": false, "explanation": "「菜市」与「赛事」的声母不同（c 与 s），声调相同，意思是菜市场。"}, {"text": "在世", "is_correct": false, "explanation": "「在世」与「赛事」的声母不同（z 与 s），声调相同，意思是活着。"}, {"text": "赛诗", "is_correct": false, "explanation": "「赛诗」与「赛事」只有第二个音节的声调不同（第一声与第四声），意思是比赛作诗。"}], "explanations": {"赛事": "正确答案。赛事指比赛的活动。", "菜市": "「菜市」与「赛事」的声母不同（c 与 s），声调相同，意思是菜市场。", "在世": "「在世」与「赛事」的声母不同（z 与 s），声调相同，意思是活着。", "赛诗": "「赛诗」与「赛事」只有第二个音节的声调不同（第一声与第四声），意思是比赛作诗。"}, "sentence_index": null, "correct_answer": "赛事"}, "level_3": {"options": [{"text": "演唱会", "is_correct": false, "explanation": "语义：「体育」指体育运动，演唱会不属于体育赛事，与前面的「体育」所指不同，说不通。"}, {"text": "赛事", "is_correct": true, "explanation": "正确答案。「举办很多体育赛事」中，赛事指比赛的活动。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：「举办」只能搭配活动，不能说「举办衣服」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以举办的活动，「体育天气」不成立。"}], "explanations": {"演唱会": "语义：「体育」指体育运动，演唱会不属于体育赛事，与前面的「体育」所指不同，说不通。", "赛事": "正确答案。「举办很多体育赛事」中，赛事指比赛的活动。", "衣服": "搭配：「举办」只能搭配活动，不能说「举办衣服」。", "天气": "语义：天气不是可以举办的活动，「体育天气」不成立。"}, "sentence_index": 0, "correct_answer": "赛事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们下午要打一场赛事。", "explanation": "这里应该用〈比赛〉。「打」搭配的是具体的比赛，赛事是比赛活动的统称，不能说「打赛事」。"}, {"text": "那位赛事昨天受伤了。", "explanation": "这里应该用〈选手〉。赛事指比赛的活动，不指人，不会受伤；受伤的应是选手。"}, {"text": "球员们在赛事上奔跑。", "explanation": "这里应该用〈赛场〉。赛事指比赛的活动，不是场地，不能说「在赛事上」奔跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：海洋与学校的安排无关，「学校的海洋安排」说不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「安排」不能搭配「味道」，不能说「学校的味道安排」。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：「相貌」指人的容貌，不能作为学校安排的对象。"}, {"text": "赛事", "is_correct": true, "explanation": "正确答案。「学校的赛事安排」指学校对比赛活动所做的安排。"}], "explanations": {"海洋": "语义：海洋与学校的安排无关，「学校的海洋安排」说不通。", "味道": "搭配：「安排」不能搭配「味道」，不能说「学校的味道安排」。", "相貌": "语义：「相貌」指人的容貌，不能作为学校安排的对象。", "赛事": "正确答案。「学校的赛事安排」指学校对比赛活动所做的安排。"}, "sentence_index": 6, "correct_answer": "赛事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气喝完了这场赛事。", "explanation": "这里应该用〈饮料〉。「喝」的对象是饮品，赛事是比赛活动，不能喝。"}, {"text": "他穿上了赛事，准备出发。", "explanation": "这里应该用〈球衣〉。「穿」的对象是衣服，赛事是活动，不能穿。"}, {"text": "他捧着赛事走下了领奖台。", "explanation": "这里应该用〈奖杯〉。「捧」的对象是具体的物品，赛事是活动，不能捧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些赛事们都很精彩。", "corrected_sentence": "这些赛事都很精彩。", "error_description": "「赛事」是抽象名词，不能加「们」表示复数。错误形式「这些赛事们」应改为「这些赛事」，「们」只附在指人的名词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参加了这只赛事。", "corrected_sentence": "他参加了这场赛事。", "error_description": "「赛事」的量词应用「场」，「只」用于动物或单个物品。错误形式「这只赛事」应改为「这场赛事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9263adb-01a0-4e76-88ed-ae3a83f089cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
