INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "较真是特别认真，一点也不马虎。", "primary_collocate": null, "pronunciation": "jiào zhēn", "ipa": "tɕjɑʊ˥˩ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "经理对每份文件都很较真。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥做实验时非常较真。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她较真起来，连标点也要检查。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生很较真，每个数字都看三遍。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李对时间很较真，从来不迟到。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做饭也这么较真，盐都要称一称。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很较真，所以大家都不敢马虎。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画画时很较真，一条线要画很久。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很较真，把钱数了三遍。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做翻译就要较真，一个词也不能错。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "较真儿", "label": "儿化"}, {"form": "较了真", "label": "体标"}], "register": "口语", "sense_fingerprint": "做事特别认真，一点也不马虎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较真", "is_correct": true, "explanation": "正确：“较真”表示做事特别认真，符合“每份文件都很”的语境。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”说价格，不能说经理“对文件很便宜”。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”说地方人多，不能用于经理对文件的态度。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄，不能说“对每份文件都很年轻”。"}], "explanations": {"较真": "正确：“较真”表示做事特别认真，符合“每份文件都很”的语境。", "便宜": "语义：“便宜”说价格，不能说经理“对文件很便宜”。", "拥挤": "语义：“拥挤”说地方人多，不能用于经理对文件的态度。", "年轻": "语义：“年轻”说年龄，不能说“对每份文件都很年轻”。"}, "sentence_index": 0, "correct_answer": "较真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位医生很较真地哭了起来。", "explanation": "较真是对事的认真态度，不表示情绪；这里应该用〈伤心〉。"}, {"text": "这台机器很较真，每次都出故障。", "explanation": "较真说的是人对事的认真态度，机器没有态度，不能说“机器很较真”。"}, {"text": "他很较真地摔了一跤。", "explanation": "“较真”形容人做事认真，不能用来修饰摔跤这种意外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较真", "is_correct": true, "explanation": "正确：“较真”指对小事也不放松，符合“老板很”的严格语境。"}, {"text": "迁就", "is_correct": false, "explanation": "语义：“迁就”指顺从、不坚持，与“大家都不敢马虎”的语境矛盾。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”指不加约束，与“大家都不敢马虎”的严格氛围相反。"}, {"text": "纵容", "is_correct": false, "explanation": "语义：“纵容”指放任不管，与“所以大家都不敢马虎”矛盾。"}], "explanations": {"较真": "正确：“较真”指对小事也不放松，符合“老板很”的严格语境。", "迁就": "语义：“迁就”指顺从、不坚持，与“大家都不敢马虎”的语境矛盾。", "放纵": "语义：“放纵”指不加约束，与“大家都不敢马虎”的严格氛围相反。", "纵容": "语义：“纵容”指放任不管，与“所以大家都不敢马虎”矛盾。"}, "sentence_index": 6, "correct_answer": "较真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗很较真地摇了摇尾巴。", "explanation": "“较真”形容人对事的认真态度，不能用来修饰摇尾巴这种动作；这里应该去掉〈较真〉。"}, {"text": "今天很较真地下了一场雨。", "explanation": "“较真”形容人对事认真，不能用来修饰天气。"}, {"text": "他很较真地长高了两厘米。", "explanation": "“较真”形容人对事的认真态度，不能用来形容身高的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位会计是个很较真人，账目一分钱都不放过。", "corrected_sentence": "这位会计是个很较真的人，账目一分钱都不放过。", "error_description": "定语错误：动词性短语“较真”修饰名词时要加“的”，应说“很较真的人”，不说“很较真人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟同事较真很，最后还是没说服对方。", "corrected_sentence": "他跟同事较真得很，最后还是没说服对方。", "error_description": "状态补语错误：“很”不能直接跟在动词“较真”后，要用“得”连接，应说“较真得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认真，对一点小事也不放松。", "primary_collocate": null, "pronunciation": "jiào zhēn", "ipa": "tɕjɑʊ˥˩ ʈʂən˥", "syllable_count": 2, "sentences": [{"text": "他做事很较真，一个小错也不放过。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对钱的事特别较真。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别跟他较真，他只是开玩笑。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对作业很较真，写错一个字就要重写。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总爱较真，连几块钱都要算清楚。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用这么较真，小事不要紧。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷下棋时特别较真，从不让人。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作很较真，每天都检查两遍。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友就是爱较真，什么都要问清楚。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一较真，谁说也不听。", "target_word": "较真", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "较真儿", "label": "儿化"}, {"form": "较了真", "label": "体标"}], "register": "口语", "sense_fingerprint": "对小事也认真计较，不肯放松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较真", "is_correct": true, "explanation": "正确：“较真”表示对小事也认真计较，符合“一个小错也不放过”。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”与后句“一个小错也不放过”意思相反，前后矛盾。"}, {"text": "偷懒", "is_correct": false, "explanation": "语义：“偷懒”表示不认真，与后句“一个小错也不放过”矛盾。"}, {"text": "较量", "is_correct": false, "explanation": "搭配：“较量”指比高低，不说“做事很较量”。"}], "explanations": {"较真": "正确：“较真”表示对小事也认真计较，符合“一个小错也不放过”。", "放松": "语义：“放松”与后句“一个小错也不放过”意思相反，前后矛盾。", "偷懒": "语义：“偷懒”表示不认真，与后句“一个小错也不放过”矛盾。", "较量": "搭配：“较量”指比高低，不说“做事很较量”。"}, "sentence_index": 0, "correct_answer": "较真"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱很较真，每次都把菜冻坏了。", "explanation": "“较真”形容人对事情认真、一点也不放松，冰箱没有这种态度，不能说“很较真”。"}, {"text": "我很较真地打了个喷嚏。", "explanation": "“较真”形容人对事情的认真态度，不能用来修饰打喷嚏这种不由自主的动作。"}, {"text": "这把椅子很较真，每次都要坐一坐。", "explanation": "“较真”形容人对事情认真，椅子没有这种态度，不能说“很较真”；形容椅子应说“结实”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较真", "is_correct": true, "explanation": "正确：“较真”指特别认真、不肯放松，符合“从不让人”。"}, {"text": "退让", "is_correct": false, "explanation": "语义：“退让”表示让步，与后句“从不让人”矛盾。"}, {"text": "谦让", "is_correct": false, "explanation": "语义：“谦让”表示把好处让给别人，与“从不让人”意思相反。"}, {"text": "客气", "is_correct": false, "explanation": "语义：下棋“特别客气”就会让人，与后句“从不让人”矛盾。"}], "explanations": {"较真": "正确：“较真”指特别认真、不肯放松，符合“从不让人”。", "退让": "语义：“退让”表示让步，与后句“从不让人”矛盾。", "谦让": "语义：“谦让”表示把好处让给别人，与“从不让人”意思相反。", "客气": "语义：下棋“特别客气”就会让人，与后句“从不让人”矛盾。"}, "sentence_index": 6, "correct_answer": "较真"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花很较真地开了三朵花。", "explanation": "“较真”形容人对事的认真态度，不能用来修饰开花这种自然变化；这里应该去掉〈较真〉。"}, {"text": "我很较真地高兴起来。", "explanation": "“较真”形容人对事情的认真态度，不用来修饰高兴这类情绪的变化。"}, {"text": "他很较真地做了一个梦。", "explanation": "“较真”形容人做事认真，做梦是无意识的，不能用“较真”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是个很较真人，不肯让步。", "corrected_sentence": "他是个很较真的人，不肯让步。", "error_description": "定语错误：动词性短语“较真”修饰名词时要加“的”，应说“很较真的人”，不说“很较真人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟我较真很，最后还是我让了步。", "corrected_sentence": "他跟我较真得很，最后还是我让了步。", "error_description": "状态补语错误：“很”不能直接跟在动词“较真”后，要用“得”连接，应说“较真得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
