INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96269, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过滤是让水从小孔里流过，把脏东西留下来。", "primary_collocate": null, "pronunciation": "guò lǜ", "ipa": "kwo˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "小孔很细，能过滤水里的脏东西。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把洗菜水倒进网里过滤一下。", "target_word": "过滤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从小孔流过，脏东西留在上面，这就是过滤。", "target_word": "过滤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用小网过滤鱼缸里的水。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脏水过滤以后，干净多了。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎么过滤泥水。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用细网过滤池塘里的水。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "泥水过滤后，杂质留在了网上。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈正在过滤刚煮好的汤。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水太脏了，先过滤再用吧。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "过滤了", "label": "体标"}, {"form": "过滤过", "label": "体标"}, {"form": "过滤网", "label": "复合"}, {"form": "過濾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让水从小孔流过，把脏东西留在外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过滤", "is_correct": true, "explanation": "过滤：水从小孔流过，脏东西留下，与“小孔很细”的句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，不能作用于水里的脏东西。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于物体表面，不能擦水里的脏东西。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象是固体，不能切水里的脏东西。"}], "explanations": {"过滤": "过滤：水从小孔流过，脏东西留下，与“小孔很细”的句意相符。", "唱": "语义：“唱”指发出歌声，不能作用于水里的脏东西。", "擦": "搭配：“擦”用于物体表面，不能擦水里的脏东西。", "切": "搭配：“切”的对象是固体，不能切水里的脏东西。"}, "sentence_index": 0, "correct_answer": "过滤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每周都过滤书桌。", "explanation": "这里应该用〈擦〉。过滤指让水从小孔里流过、留下杂质，书桌是固体，要用擦，不能说过滤书桌。"}, {"text": "用清水过滤小碗。", "explanation": "这里应该用〈清洗〉。过滤是让水从小孔里流过、把脏东西留下，小碗是器具，洗小碗要用清洗。"}, {"text": "用大火过滤饭。", "explanation": "这里应该用〈煮〉。过滤针对液体，饭是固体，做饭要用煮，不能说过滤饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过滤", "is_correct": true, "explanation": "过滤：细网让水通过，留下杂质，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象一般是物品或身体，不能说洗池塘里的水。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”用于土石，不能挖水。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热使水沸腾，与用细网、留下杂质的意思不符。"}], "explanations": {"过滤": "过滤：细网让水通过，留下杂质，符合句意。", "洗": "搭配：“洗”的对象一般是物品或身体，不能说洗池塘里的水。", "挖": "搭配：“挖”用于土石，不能挖水。", "煮": "语义：煮是加热使水沸腾，与用细网、留下杂质的意思不符。"}, "sentence_index": 6, "correct_answer": "过滤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把椅子过滤干净了。", "explanation": "这里用的是〈擦拭〉的意思。过滤只指水从小孔里流过、把脏东西留下来，椅子是固体，不能用过滤来形容擦干净。"}, {"text": "爸爸用布过滤了地板。", "explanation": "这里用的是〈擦拭〉的意思。过滤只指水从小孔里流过、把脏东西留下来，地板是固体平面，不能用过滤来形容擦地板。"}, {"text": "哥哥用扫帚过滤了操场。", "explanation": "这里用的是〈清扫〉的意思。过滤只指水从小孔里流过、把脏东西留下来，扫操场不能说过滤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先把水里的脏东西过滤。", "corrected_sentence": "先把水里的脏东西过滤掉。", "error_description": "“把”字句中动词后要有补语，不能只说“过滤”；应为“过滤掉”，表示把脏东西去除。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈过滤了一只泥水。", "corrected_sentence": "妈妈过滤了一桶泥水。", "error_description": "量词“只”不能计量“泥水”：应为“一桶泥水”，不能说“一只泥水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
