INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使液体或气体通过滤材，留下杂质。", "primary_collocate": null, "pronunciation": "guò lǜ", "ipa": "kwo˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈用纱布过滤豆浆里的渣。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器能过滤空气中的灰尘。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡要用滤纸过滤一下才干净。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水必须先过滤，然后才能喝。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把泡好的茶水过滤了一遍。", "target_word": "过滤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池的水每天都要过滤。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个净水器可以过滤自来水里的杂质。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做果汁时，先过滤掉里面的果渣。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "口罩可以过滤空气里的小颗粒。", "target_word": "过滤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶用干净的布过滤了米酒。", "target_word": "过滤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过滤了", "label": "体标"}, {"form": "过滤过", "label": "体标"}, {"form": "过滤器", "label": "复合"}, {"form": "過濾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让液体或气体穿过滤材，把杂质留下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf0233fc-559d-4f30-b637-88120fddf0aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过滤", "is_correct": true, "explanation": "过滤：让液体通过纱布，把渣留下，符合句意。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”用于纸、布、头发等固体，不能剪豆浆里的渣。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于物体表面，不能擦豆浆里面的渣。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热烹饪，与用纱布去除渣的动作不符。"}], "explanations": {"过滤": "过滤：让液体通过纱布，把渣留下，符合句意。", "剪": "搭配：“剪”用于纸、布、头发等固体，不能剪豆浆里的渣。", "擦": "搭配：“擦”用于物体表面，不能擦豆浆里面的渣。", "煮": "语义：煮是加热烹饪，与用纱布去除渣的动作不符。"}, "sentence_index": 0, "correct_answer": "过滤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在超市过滤了一台冰箱。", "explanation": "这里应该用〈购买〉。过滤是让液体或空气穿过滤材、留下杂质，冰箱是机器，买冰箱要用购买，不能说过滤冰箱。"}, {"text": "妈妈用清水过滤了蔬菜。", "explanation": "这里应该用〈清洗〉。过滤的对象是液体或气体，蔬菜是固体，洗蔬菜要用清洗。"}, {"text": "工人用刷子过滤了鞋上的泥。", "explanation": "这里应该用〈去除〉。过滤不是用刷子进行的动作，清掉鞋上的泥要用去除，不能说过滤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过滤", "is_correct": true, "explanation": "过滤：净水器让自来水穿过滤材，留下杂质，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象一般是物品或身体，不能说洗自来水里的杂质。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”的对象是土石，不能挖水里的杂质。"}, {"text": "削", "is_correct": false, "explanation": "语义：削是去掉物体表层，与水中杂质被留下的意思不符。"}], "explanations": {"过滤": "过滤：净水器让自来水穿过滤材，留下杂质，符合句意。", "洗": "搭配：“洗”的对象一般是物品或身体，不能说洗自来水里的杂质。", "挖": "搭配：“挖”的对象是土石，不能挖水里的杂质。", "削": "语义：削是去掉物体表层，与水中杂质被留下的意思不符。"}, "sentence_index": 6, "correct_answer": "过滤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用抹布过滤了灶台。", "explanation": "这里用的是〈擦拭〉的意思。过滤只指让液体或气体穿过滤材、留下杂质，灶台是固体表面，不能用过滤来形容擦灶台。"}, {"text": "他把一个苹果过滤了一遍。", "explanation": "这里应该用〈清洗〉。过滤只指液体或气体穿过滤材，苹果是固体，洗苹果要用清洗。"}, {"text": "老师用黑板擦过滤了黑板。", "explanation": "这里用的是〈擦拭〉的意思。过滤只指让液体或气体穿过滤材、留下杂质，黑板是固体平面，不能用过滤来形容擦黑板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "用滤纸把咖啡过滤很干净。", "corrected_sentence": "用滤纸把咖啡过滤得很干净。", "error_description": "“过滤”后带程度补语时须加“得”：应为“过滤得很干净”，不能说“过滤很干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶过滤了一只米酒。", "corrected_sentence": "奶奶过滤了一锅米酒。", "error_description": "量词“只”不能计量“米酒”：应为“一锅米酒”，不能说“一只米酒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95c531cf-8505-455d-a359-63392764b7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
