INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96271, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "达因是量力的大小的一个单位。", "primary_collocate": null, "pronunciation": "dá yīn", "ipa": "ta˧˥ in˥˥", "syllable_count": 2, "sentences": [{"text": "力的大小可以用达因来算。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小球受到了十达因的力。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一达因是很小的一个力。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了“五达因”。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里说，力的单位有牛顿和达因。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只小虫推桌子，只用了几达因的力。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子拉绳子，力一共是三十达因。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达因比牛顿小得多。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道一牛顿等于多少达因吗？", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验里，弹簧受到二十达因的力就停下了。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "量力的大小的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96271, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因 dá yīn 是正确答案，意思是力的单位。"}, {"text": "打印", "is_correct": false, "explanation": "打印 dǎyìn 与 dá yīn 两个音节的声调都不同，意思是打印。"}, {"text": "答应", "is_correct": false, "explanation": "答应 dāying 第一音节声调不同，第二音节是轻声 ying（韵母 ing），意思是同意或回答。"}, {"text": "大衣", "is_correct": false, "explanation": "大衣 dàyī 第一音节声调不同，第二音节去掉鼻音 n，意思是外套。"}], "explanations": {"达因": "达因 dá yīn 是正确答案，意思是力的单位。", "打印": "打印 dǎyìn 与 dá yīn 两个音节的声调都不同，意思是打印。", "答应": "答应 dāying 第一音节声调不同，第二音节是轻声 ying（韵母 ing），意思是同意或回答。", "大衣": "大衣 dàyī 第一音节声调不同，第二音节去掉鼻音 n，意思是外套。"}, "sentence_index": null, "correct_answer": "达因"}, "level_3": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因是量力大小的单位，与“力的大小”相符。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：厘米量的是长度，不用来量力的大小。"}, {"text": "摄氏度", "is_correct": false, "explanation": "语义：摄氏度量的是温度，不能用来量力。"}, {"text": "升", "is_correct": false, "explanation": "语义：升量的是体积，不能用来量力的大小。"}], "explanations": {"达因": "达因是量力大小的单位，与“力的大小”相符。", "厘米": "语义：厘米量的是长度，不用来量力的大小。", "摄氏度": "语义：摄氏度量的是温度，不能用来量力。", "升": "语义：升量的是体积，不能用来量力的大小。"}, "sentence_index": 0, "correct_answer": "达因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路有五达因长。", "explanation": "这里词义用错了。达因只量力的大小，不量长度，“这条路”的长短不能用达因来说。"}, {"text": "我买了三达因苹果。", "explanation": "这里应该用〈个〉。达因是力的单位，只用于计量力，计数苹果要用量词“个”。"}, {"text": "他用了一达因的时间写完作业。", "explanation": "这里词义用错了。达因指力的单位，不用来计量时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96271, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因 dá yīn 是正确答案，意思是力的单位。"}, {"text": "大鹰", "is_correct": false, "explanation": "大鹰 dàyīng 第一音节声调不同，第二音节 yīn 变为 yīng（韵母 in 变 ing），意思是大型猛禽。"}, {"text": "大印", "is_correct": false, "explanation": "大印 dàyìn 两个音节的声调都不同，意思是官方的大印章。"}, {"text": "大营", "is_correct": false, "explanation": "大营 dàyíng 第一音节声调不同，第二音节韵母变为 ing 并改声调，意思是大的军营。"}], "explanations": {"达因": "达因 dá yīn 是正确答案，意思是力的单位。", "大鹰": "大鹰 dàyīng 第一音节声调不同，第二音节 yīn 变为 yīng（韵母 in 变 ing），意思是大型猛禽。", "大印": "大印 dàyìn 两个音节的声调都不同，意思是官方的大印章。", "大营": "大营 dàyíng 第一音节声调不同，第二音节韵母变为 ing 并改声调，意思是大的军营。"}, "sentence_index": null, "correct_answer": "达因"}, "level_3": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因是力的单位，与“力一共是三十”相符。"}, {"text": "分贝", "is_correct": false, "explanation": "语义：分贝量的是声音的响度，不是力。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里量的是距离，不能用来表示力的大小。"}, {"text": "小时", "is_correct": false, "explanation": "语义：小时是时间单位，不能用来计量力。"}], "explanations": {"达因": "达因是力的单位，与“力一共是三十”相符。", "分贝": "语义：分贝量的是声音的响度，不是力。", "公里": "语义：公里量的是距离，不能用来表示力的大小。", "小时": "语义：小时是时间单位，不能用来计量力。"}, "sentence_index": 6, "correct_answer": "达因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶水有两达因。", "explanation": "这里词义用错了。达因只量力的大小，不量体积，这句把它用在了水的容量上。"}, {"text": "他每天要走五达因的路。", "explanation": "这里词义用错了。达因指力的单位，不用于路程，这句用它来量距离。"}, {"text": "奶奶买了十达因牛奶。", "explanation": "这里应该用〈瓶〉。达因只用来计量力，计量牛奶要用量词“瓶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根弹簧受到了七只达因的拉力。", "corrected_sentence": "这根弹簧受到了七达因的拉力。", "error_description": "量词错误：“只”用于动物或成对的器物，不能用来计量力。达因本身就是量词，应说“七达因”，不说“七只达因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "推车的人用了六个达因的力。", "corrected_sentence": "推车的人用了六达因的力。", "error_description": "量词叠用：达因本身就是量词，前面不能再加“个”。应说“六达因”，不说“六个达因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
