INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96272, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "abstract", "definition": "力的非国际单位，使一克质量物体产生一厘米每秒平方加速度的力。", "primary_collocate": null, "pronunciation": "dá yīn", "ipa": "ta˧˥ in˥˥", "syllable_count": 2, "sentences": [{"text": "这本旧书里还用达因做力的单位。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达因不是国际单位，现在用得不多。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一达因的力能让一克的东西动起来。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理课上，老师讲了什么是达因。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把四百达因换成牛顿，算了很久。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个力等于一百达因。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小实验中，手的力只有一千达因左右。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单位叫达因，是一个很老的单位。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看过达因这个词。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用达因做单位，数字会变得很大。", "target_word": "达因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "力的非国际单位，一克物体加速一厘米每秒平方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因 dá yīn 是正确答案，意思是力的非国际单位。"}, {"text": "打印", "is_correct": false, "explanation": "打印 dǎyìn 与 dá yīn 两个音节的声调都不同，意思是打印。"}, {"text": "答应", "is_correct": false, "explanation": "答应 dāying 第一音节声调不同，第二音节是轻声 ying（韵母 ing），意思是同意或回答。"}, {"text": "大衣", "is_correct": false, "explanation": "大衣 dàyī 第一音节声调不同，第二音节去掉鼻音 n，意思是外套。"}], "explanations": {"达因": "达因 dá yīn 是正确答案，意思是力的非国际单位。", "打印": "打印 dǎyìn 与 dá yīn 两个音节的声调都不同，意思是打印。", "答应": "答应 dāying 第一音节声调不同，第二音节是轻声 ying（韵母 ing），意思是同意或回答。", "大衣": "大衣 dàyī 第一音节声调不同，第二音节去掉鼻音 n，意思是外套。"}, "sentence_index": null, "correct_answer": "达因"}, "level_3": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因是力的单位，与“做力的单位”相符。"}, {"text": "厘米", "is_correct": false, "explanation": "语义：厘米是长度单位，不是力的单位。"}, {"text": "摄氏度", "is_correct": false, "explanation": "语义：摄氏度是温度单位，不能做力的单位。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是体积单位，不是力的单位。"}], "explanations": {"达因": "达因是力的单位，与“做力的单位”相符。", "厘米": "语义：厘米是长度单位，不是力的单位。", "摄氏度": "语义：摄氏度是温度单位，不能做力的单位。", "升": "语义：升是体积单位，不是力的单位。"}, "sentence_index": 0, "correct_answer": "达因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河有五达因宽。", "explanation": "这里词义用错了。达因指力的单位，不用来量宽度，这句用它来量河的宽窄。"}, {"text": "我们班有三达因学生。", "explanation": "这里应该用〈名〉。达因只用来计量力，计数学生要用量词“名”。"}, {"text": "他用了一达因的时间写作业。", "explanation": "这里词义用错了。达因不用来计量时间，这句用它来量时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96272, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因 dá yīn 是正确答案，意思是力的非国际单位。"}, {"text": "大鹰", "is_correct": false, "explanation": "大鹰 dàyīng 第一音节声调不同，第二音节 yīn 变为 yīng（韵母 in 变 ing），意思是大型猛禽。"}, {"text": "大印", "is_correct": false, "explanation": "大印 dàyìn 两个音节的声调都不同，意思是官方的大印章。"}, {"text": "大营", "is_correct": false, "explanation": "大营 dàyíng 第一音节声调不同，第二音节韵母变为 ing 并改声调，意思是大的军营。"}], "explanations": {"达因": "达因 dá yīn 是正确答案，意思是力的非国际单位。", "大鹰": "大鹰 dàyīng 第一音节声调不同，第二音节 yīn 变为 yīng（韵母 in 变 ing），意思是大型猛禽。", "大印": "大印 dàyìn 两个音节的声调都不同，意思是官方的大印章。", "大营": "大营 dàyíng 第一音节声调不同，第二音节韵母变为 ing 并改声调，意思是大的军营。"}, "sentence_index": null, "correct_answer": "达因"}, "level_3": {"options": [{"text": "达因", "is_correct": true, "explanation": "达因是力的单位，与“手的力只有一千”相符。"}, {"text": "分贝", "is_correct": false, "explanation": "语义：分贝量的是声音的响度，不是力。"}, {"text": "公里", "is_correct": false, "explanation": "语义：公里量的是距离，不能用来表示力的大小。"}, {"text": "小时", "is_correct": false, "explanation": "语义：小时是时间单位，不能用来计量力。"}], "explanations": {"达因": "达因是力的单位，与“手的力只有一千”相符。", "分贝": "语义：分贝量的是声音的响度，不是力。", "公里": "语义：公里量的是距离，不能用来表示力的大小。", "小时": "语义：小时是时间单位，不能用来计量力。"}, "sentence_index": 6, "correct_answer": "达因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这壶茶有两达因。", "explanation": "这里词义用错了。达因只量力，不量茶的体积，这句把它用在了液体上。"}, {"text": "他每天跑五达因的步。", "explanation": "这里词义用错了。达因指力的单位，不用于量步数或距离。"}, {"text": "妈妈买了十达因橘子。", "explanation": "这里应该用〈个〉。达因只用来计量力，计数橘子要用量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器测到了九只达因的力。", "corrected_sentence": "这台仪器测到了九达因的力。", "error_description": "量词错误：“只”不能用来计量力。达因本身就是量词，应说“九达因”，不说“九只达因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个力是四百个达因。", "corrected_sentence": "这个力是四百达因。", "error_description": "量词叠用：达因本身是量词，前面不能加“个”。应说“四百达因”，不说“四百个达因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
