INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96273, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "远远是离得很远。", "primary_collocate": null, "pronunciation": "yuǎn yuǎn", "ipa": "ɥɛn˨˩˦ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我远远地看见他走过来了。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她远远地站在门口。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们远远地跑开了。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们远远就听到了他的声音。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小狗远远地跟在后面。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的雪远远就能看见。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕狗，远远地躲着。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师远远地向我挥手。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他远远地朝我们喊了一声。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远远看去，那座房子像一只船。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示空间距离很远，常作状语，如远远地看见、远远地站着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远远", "is_correct": true, "explanation": "远远表示空间距离很远，可以修饰“看见”，句意通顺。"}, {"text": "狠狠", "is_correct": false, "explanation": "语义：狠狠表示用力或凶狠，与“看见”这种感知动作不合。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：拼命表示用尽力气，看见他走过来不需要用尽力气。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：大声修饰说话或声音，不能修饰“看见”。"}], "explanations": {"远远": "远远表示空间距离很远，可以修饰“看见”，句意通顺。", "狠狠": "语义：狠狠表示用力或凶狠，与“看见”这种感知动作不合。", "拼命": "语义：拼命表示用尽力气，看见他走过来不需要用尽力气。", "大声": "搭配：大声修饰说话或声音，不能修饰“看见”。"}, "sentence_index": 0, "correct_answer": "远远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题远远地解决了。", "explanation": "这里应该用〈彻底〉。远远表示空间或时间上的距离，不能用来说明问题被解决的程度。"}, {"text": "他的成绩远远地及格了。", "explanation": "这里应该用〈勉强〉。远远表示距离，不用于描述及格的程度。"}, {"text": "这次的困难远远地克服了。", "explanation": "这里应该用〈顺利〉。远远表示距离，不用来描述克服困难的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远远", "is_correct": true, "explanation": "远远表示空间距离很远，修饰“躲着”，与“怕狗”的语境吻合。"}, {"text": "大胆", "is_correct": false, "explanation": "语义：大胆表示不怕，与前句“他怕狗”的语境相反。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：热情形容态度，不能修饰“躲着”这种躲避动作。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴表示愉快的心情，与“怕狗”而躲避的语境不合。"}], "explanations": {"远远": "远远表示空间距离很远，修饰“躲着”，与“怕狗”的语境吻合。", "大胆": "语义：大胆表示不怕，与前句“他怕狗”的语境相反。", "热情": "搭配：热情形容态度，不能修饰“躲着”这种躲避动作。", "高兴": "语义：高兴表示愉快的心情，与“怕狗”而躲避的语境不合。"}, "sentence_index": 6, "correct_answer": "远远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他远远地记住了我的名字。", "explanation": "这里应该用〈牢牢〉。远远表示距离，记忆不是空间距离，应说“牢牢记住”。"}, {"text": "他远远地读完了这本书。", "explanation": "这里应该用〈认真〉。远远表示距离，不能用来描述读书的态度。"}, {"text": "这件事远远地说明了问题。", "explanation": "这里应该用〈清楚〉。远远表示距离，不能用来说明问题的清晰程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我远远的看见他在门口等我。", "corrected_sentence": "我远远地看见他在门口等我。", "error_description": "错误：“远远”修饰动词“看见”作状语，应用“地”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很远远地看见了老师。", "corrected_sentence": "我远远地看见了老师。", "error_description": "“远远”表示空间距离，不能与表示程度的“很”叠用。应去掉“很”，说“我远远地看见了老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
