INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96274, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "表示差距或程度很大，多用在比较或否定之前。", "primary_collocate": null, "pronunciation": "yuǎn yuǎn", "ipa": "ɥɛn˨˩˦ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "今年的客人远远超过去年。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩远远高于我。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的东西远远不够用。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的结果远远超过了我们的想象。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的水平远远不如他。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点钱远远不够买车。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的生活远远好于以前。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工资远远多于我的。", "target_word": "远远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的困难远远超出了我们的预料。", "target_word": "远远", "complexity_tier": "T3", "furigana": "zhè cì de kùnnan yuǎnyuǎn chāochū le wǒmen de yùliào", "sentence_source": "generated"}, {"text": "这个办法远远不能解决问题。", "target_word": "远远", "complexity_tier": "T3", "furigana": "zhè ge bànfǎ yuǎnyuǎn bùnéng jiějué wèntí", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用在比较或否定前，表示差距、程度很大，如远远超过、远远不够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远远", "is_correct": true, "explanation": "远远表示差距很大，与“超过去年”的比较搭配，句意通顺。"}, {"text": "只好", "is_correct": false, "explanation": "语义：只好表示无奈的选择，不能修饰“超过去年”这种比较结果。"}, {"text": "白白", "is_correct": false, "explanation": "语义：白白表示徒劳，与“超过去年”这一正面的比较结果相悖。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：从来多与否定或“一直”的语境连用，不能与一次性的“超过去年”搭配。"}], "explanations": {"远远": "远远表示差距很大，与“超过去年”的比较搭配，句意通顺。", "只好": "语义：只好表示无奈的选择，不能修饰“超过去年”这种比较结果。", "白白": "语义：白白表示徒劳，与“超过去年”这一正面的比较结果相悖。", "从来": "搭配：从来多与否定或“一直”的语境连用，不能与一次性的“超过去年”搭配。"}, "sentence_index": 0, "correct_answer": "远远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我远远认为这个办法是对的。", "explanation": "这里应该用〈始终〉。远远表示与某个标准相比差距很大，不用来修饰“认为”这类判断。"}, {"text": "这件衣服远远漂亮。", "explanation": "这里应该用〈非常〉。远远要用在比较或否定前，如“远远超过”“远远不够”，不能单独修饰形容词。"}, {"text": "他远远地喜欢这首歌。", "explanation": "这里应该用〈非常〉。远远用于比较或差距，不单纯修饰“喜欢”的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远远", "is_correct": true, "explanation": "远远表示差距很大，与比较结构“好于以前”搭配，句意通顺。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示不经常发生，不能修饰“好于以前”这种比较结果。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：曾经指过去，与“现在的生活”矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：赶紧表示急着做某事，不能修饰“好于以前”这种比较。"}], "explanations": {"远远": "远远表示差距很大，与比较结构“好于以前”搭配，句意通顺。", "偶尔": "语义：偶尔表示不经常发生，不能修饰“好于以前”这种比较结果。", "曾经": "语义：曾经指过去，与“现在的生活”矛盾。", "赶紧": "搭配：赶紧表示急着做某事，不能修饰“好于以前”这种比较。"}, "sentence_index": 6, "correct_answer": "远远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事远远地发生在昨天。", "explanation": "这里应该用〈刚刚〉。远远表示距离或差距大，不用来说明发生的时间很近。"}, {"text": "这个菜远远好吃。", "explanation": "这里应该用〈特别〉。远远要用在比较或否定前，不能单独修饰“好吃”。"}, {"text": "他远远地同意了我的看法。", "explanation": "这里应该用〈欣然〉。远远表示差距大，不用来修饰“同意”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的价格远远的低于我们的预算。", "corrected_sentence": "这次的价格远远低于我们的预算。", "error_description": "错误：“远远”作状语直接修饰“低于”，不加“的”。“远远的”不能修饰动词，应说“远远低于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器的效率远远很高于旧的那台。", "corrected_sentence": "这台机器的效率远远高于旧的那台。", "error_description": "“远远”和“很”都表示程度，不能叠用。应去掉“很”，说“远远高于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
