INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96275, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "部位是身体或东西的某一块地方。", "primary_collocate": null, "pronunciation": "bù wèi", "ipa": "pu˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他的腿受伤了，医生检查了这个部位。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部位的皮肤很薄。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按摩时要注意脖子这个部位。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要碰这个部位，会很疼。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把药涂在受伤的部位。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刀的这个部位最锋利。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天要保护好身体容易受凉的部位。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对着镜子看脸上长痘的部位。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肉是猪身上最嫩的部位。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳晒了一天，肩膀的这个部位红了。", "target_word": "部位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "身体或物体上的某一块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96275, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部位", "is_correct": true, "explanation": "正确。部位指身体或东西的某一块地方。"}, {"text": "铺位", "is_correct": false, "explanation": "pù wèi（第四声）与 bù wèi 声母不同（p 与 b），意思是铺位，如火车卧铺中的床位，不指身体的地方。"}, {"text": "补位", "is_correct": false, "explanation": "bǔ wèi（第三声）与 bù wèi 声调不同（第三声与第四声），意思是补位，指补上空缺的位置。"}, {"text": "部委", "is_correct": false, "explanation": "bù wěi（第三声）与 bù wèi 第二个音节声调不同，意思是政府部门与委员会，如中央部委。"}], "explanations": {"部位": "正确。部位指身体或东西的某一块地方。", "铺位": "pù wèi（第四声）与 bù wèi 声母不同（p 与 b），意思是铺位，如火车卧铺中的床位，不指身体的地方。", "补位": "bǔ wèi（第三声）与 bù wèi 声调不同（第三声与第四声），意思是补位，指补上空缺的位置。", "部委": "bù wěi（第三声）与 bù wèi 第二个音节声调不同，意思是政府部门与委员会，如中央部委。"}, "sentence_index": null, "correct_answer": "部位"}, "level_3": {"options": [{"text": "感情", "is_correct": false, "explanation": "语义：感情是抽象的情绪，医生检查不了。"}, {"text": "部位", "is_correct": true, "explanation": "正确。“部位”指腿部受伤的具体地方，与“检查”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是医生检查的对象。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：医生“检查”的对象一般是病人的身体或病情，不说检查“字迹”。"}], "explanations": {"感情": "语义：感情是抽象的情绪，医生检查不了。", "部位": "正确。“部位”指腿部受伤的具体地方，与“检查”搭配。", "天气": "语义：天气是自然现象，不是医生检查的对象。", "字迹": "搭配：医生“检查”的对象一般是病人的身体或病情，不说检查“字迹”。"}, "sentence_index": 0, "correct_answer": "部位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子的部位很好，阳光充足。", "explanation": "这里应该用〈位置〉。“部位”指身体或器物的局部，说房间所在的地点要用〈位置〉。"}, {"text": "他在车站找到了一个能坐的部位。", "explanation": "这里应该用〈地方〉。“部位”指具体的局部，不指可以坐下的场所，要说“地方”。"}, {"text": "这首歌的副歌部位最好听。", "explanation": "这里应该用〈部分〉。“部位”指身体或物件的具体局部，说歌曲的一段要用〈部分〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96275, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "部位", "is_correct": true, "explanation": "正确。部位指身体或东西的某一块地方。"}, {"text": "部类", "is_correct": false, "explanation": "lèi（第四声）与 wèi 声母不同（l 与 w），部类指按门类划分的类别，不指某一块地方。"}, {"text": "部内", "is_correct": false, "explanation": "bù nèi 与 bù wèi 第二个音节声母不同（n 与 w），部内指部门内部，不指身体或物件的地方。"}, {"text": "不为", "is_correct": false, "explanation": "bù wéi（第二声）与 bù wèi 第二个音节声调不同，意思是不去做、不作为，如“不为所动”。"}], "explanations": {"部位": "正确。部位指身体或东西的某一块地方。", "部类": "lèi（第四声）与 wèi 声母不同（l 与 w），部类指按门类划分的类别，不指某一块地方。", "部内": "bù nèi 与 bù wèi 第二个音节声母不同（n 与 w），部内指部门内部，不指身体或物件的地方。", "不为": "bù wéi（第二声）与 bù wèi 第二个音节声调不同，意思是不去做、不作为，如“不为所动”。"}, "sentence_index": null, "correct_answer": "部位"}, "level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情是情绪，不会因天冷而受凉。"}, {"text": "部位", "is_correct": true, "explanation": "正确。“部位”指身体上容易受凉的具体地方，与“身体”和“保护”呼应。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不会受凉，不能用“受凉”来形容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有温度，不会受凉。"}], "explanations": {"心情": "语义：心情是情绪，不会因天冷而受凉。", "部位": "正确。“部位”指身体上容易受凉的具体地方，与“身体”和“保护”呼应。", "工资": "语义：工资是收入，不会受凉，不能用“受凉”来形容。", "颜色": "语义：颜色没有温度，不会受凉。"}, "sentence_index": 6, "correct_answer": "部位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳晒了一天，我的后背这张部位红了。", "explanation": "量词错误：“张”用于纸张、桌面等平面的东西，“部位”应用量词“个”。"}, {"text": "他的肩膀那根部位晒得很红。", "explanation": "量词错误：“根”用于细长的东西，“部位”应用量词“个”。"}, {"text": "这副部位被太阳晒红了。", "explanation": "量词错误：“副”用于成套或成对的物品，“部位”应用量词“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士用纱布盖住了伤口的这只部位。", "corrected_sentence": "护士用纱布盖住了伤口的这个部位。", "error_description": "错误：量词“只”。“部位”应搭配量词“个”，“只”用于动物或成对物品中的一个。应改为“这个部位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的膝盖有一条部位总是很疼。", "corrected_sentence": "他的膝盖有一个部位总是很疼。", "error_description": "错误：量词“条”。“部位”应搭配量词“个”，“条”用于细长的东西。应改为“一个部位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
