INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "钱包是装钱的小包。", "primary_collocate": null, "pronunciation": "qián bāo", "ipa": "t͡ɕʰjɛn˧˥ pɑʊ˥", "syllable_count": 2, "sentences": [{"text": "我的钱包放在书包里。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在地铁上丢了钱包。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个钱包是妈妈送我的。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱包里只有五十块钱。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个红色的新钱包。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到钱包了，你看见了吗？", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷偷走了他的钱包。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里拿出钱包付钱。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱包太旧了，我想换一个。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把钱包放好，别弄丢了。", "target_word": "钱包", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "錢包", "label": "繁体"}], "register": "中性", "sense_fingerprint": "随身携带、用来装钱的小包", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96277, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间不是实物，放不进书包。"}, {"text": "钱包", "is_correct": true, "explanation": "正确。“钱包”是随身携带、可以放进书包的小包，与“放在书包里”呼应。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是抽象的感受，不能装进书包。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“放在……里”搭配小件物品，桌子体积太大，不能放进书包。"}], "explanations": {"时间": "语义：时间不是实物，放不进书包。", "钱包": "正确。“钱包”是随身携带、可以放进书包的小包，与“放在书包里”呼应。", "心情": "语义：心情是抽象的感受，不能装进书包。", "桌子": "搭配：“放在……里”搭配小件物品，桌子体积太大，不能放进书包。"}, "sentence_index": 0, "correct_answer": "钱包"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "收银台的钱包里装着一整天的收入。", "explanation": "这里应该用〈钱箱〉。钱包是随身携带的小包，装不下商店一整天的收入，这里要用〈钱箱〉。"}, {"text": "他每天把硬币投进钱包里攒起来。", "explanation": "这里应该用〈存钱罐〉。钱包是随身携带的小包，攒硬币要用〈存钱罐〉，不能投进钱包。"}, {"text": "他把工资装进钱包寄回了老家。", "explanation": "这里应该用〈信封〉。寄钱回家要用〈信封〉，钱包是随身携带的小包，不用来装钱寄出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被偷走。"}, {"text": "钱包", "is_correct": true, "explanation": "正确。“钱包”是可以被偷的随身小包，与“小偷偷走了他的……”呼应。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体尺寸，不是可以被偷走的东西。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“偷走”一般搭配可随身携带的小件物品，不搭配“房子”。"}], "explanations": {"天气": "语义：天气是自然现象，不能被偷走。", "钱包": "正确。“钱包”是可以被偷的随身小包，与“小偷偷走了他的……”呼应。", "身高": "语义：身高是人的身体尺寸，不是可以被偷走的东西。", "房子": "搭配：“偷走”一般搭配可随身携带的小件物品，不搭配“房子”。"}, "sentence_index": 6, "correct_answer": "钱包"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本钱包很旧，该换了。", "explanation": "量词错误：“本”用于书本，“钱包”应用量词“个”。"}, {"text": "我买了一张新钱包。", "explanation": "量词错误：“张”用于纸张、桌面等平面的东西，“钱包”应用“个”。"}, {"text": "他从口袋里拿出一条钱包付钱。", "explanation": "量词错误：“条”用于细长的东西，“钱包”应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去超市前买了一本新钱包。", "corrected_sentence": "他去超市前买了一个新钱包。", "error_description": "错误：量词“本”。“本”用于书本，“钱包”应搭配量词“个”。应改为“一个新钱包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下车时忘了拿那根钱包。", "corrected_sentence": "我下车时忘了拿那个钱包。", "error_description": "错误：量词“根”。“钱包”应搭配量词“个”，“根”用于细长的东西。应改为“那个钱包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
