INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "关系网是你认识的很多人连成的一张网。", "primary_collocate": null, "pronunciation": "guān xì wǎng", "ipa": "kwan˥ ɕi˥˩ waŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他在这个城市有一张很大的关系网。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚来这里，还没有自己的关系网。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作的时候，关系网能帮上大忙。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的关系网很广，什么人都认识。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多参加活动，可以慢慢扩大你的关系网。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠关系网找到了这份工作。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板的关系网遍布全国各地。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的朋友，也是你关系网里的人。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的关系网里有没有学医的人？", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的关系网太小，帮不上这个忙。", "target_word": "关系网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张关系网", "label": "量词"}, {"form": "关系网络", "label": "复合"}], "register": "口语", "sense_fingerprint": "你认识的很多人连成的人脉网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系网", "is_correct": true, "explanation": "“一张很大的关系网”指很多人连成的人脉网，符合“他在这个城市有”的语境。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片是小小的个人信息卡，“很大的名片”与“在这个城市有”的人脉语境不合。"}, {"text": "车票", "is_correct": false, "explanation": "体貌：车票是小纸片，不能用“很大”形容，句子读起来不通。"}, {"text": "请柬", "is_correct": false, "explanation": "语义：请柬是邀请用的卡片，不能指一个人在城市里拥有的人际网络。"}], "explanations": {"关系网": "“一张很大的关系网”指很多人连成的人脉网，符合“他在这个城市有”的语境。", "名片": "语义：名片是小小的个人信息卡，“很大的名片”与“在这个城市有”的人脉语境不合。", "车票": "体貌：车票是小纸片，不能用“很大”形容，句子读起来不通。", "请柬": "语义：请柬是邀请用的卡片，不能指一个人在城市里拥有的人际网络。"}, "sentence_index": 0, "correct_answer": "关系网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他的关系网一直很好。", "explanation": "这里应该用〈关系〉。关系网指许多人连成的人脉网，说两个人之间的好坏要用“关系”。"}, {"text": "这个关系网很快，我们用它下载了一部电影。", "explanation": "这里应该用〈网络〉。关系网指人际关系，不能用来形容网速快慢。"}, {"text": "他的关系网是个能办事的大人物，一句话就把事情办得很顺。", "explanation": "这里应该用〈靠山〉。关系网指许多人连成的网，不能指一个能帮你办事的有力人物，那种人叫“靠山”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系网", "is_correct": true, "explanation": "“遍布全国各地”可以用来说人际网络分布很广，只有“关系网”合适。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不会“遍布全国各地”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的数值，不能“遍布”各地。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色是面部的状态，说它“遍布全国各地”不通。"}], "explanations": {"关系网": "“遍布全国各地”可以用来说人际网络分布很广，只有“关系网”合适。", "脾气": "语义：脾气是性格特点，不会“遍布全国各地”。", "体重": "体貌：体重是身体的数值，不能“遍布”各地。", "脸色": "体貌：脸色是面部的状态，说它“遍布全国各地”不通。"}, "sentence_index": 6, "correct_answer": "关系网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔夫把关系网撒进河里，捞上来好多鱼。", "explanation": "这里应该用〈渔网〉。关系网指人与人之间连成的网，不能指撒进河里捕鱼的渔网。"}, {"text": "窗角结了一张关系网，蜘蛛正在上面爬。", "explanation": "这里应该用〈蛛网〉。关系网只指人际关系连成的网，不能指蜘蛛结在窗角的蛛网。"}, {"text": "这家店的关系网可以在线买东西。", "explanation": "这里应该用〈网店〉。关系网指人际关系连成的网，不能指可以网上买东西的网店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在北京工作多年，攒下了一条很大的关系网。", "corrected_sentence": "他在北京工作多年，攒下了一张很大的关系网。", "error_description": "错误形式：一条关系网；正确形式：一张关系网。“条”用于细长的东西，关系网的量词应该用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常参加各种活动，慢慢放大了自己的关系网。", "corrected_sentence": "他常参加各种活动，慢慢扩大了自己的关系网。", "error_description": "错误形式：放大关系网；正确形式：扩大关系网。“放大”多用于图片、声音，让关系网变大要说“扩大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
