INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预防和治疗（疾病、虫害等）。", "primary_collocate": null, "pronunciation": "fáng zhì", "ipa": "faŋ˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "医生说，春天要注意防治感冒。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要防治这种传染病。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里请来医生，防治孩子们的病。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防治疾病要先从洗手做起。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年夏天，学校都要防治蚊子带来的病。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院在防治心脏病方面很有名。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，防治感冒要多穿衣服。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为防治流感发了很多药。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的习惯能帮我们防治很多病。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一直在防治这种病，现在好多了。", "target_word": "防治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防治了", "label": "体标"}, {"form": "防治着", "label": "体标"}, {"form": "防治过", "label": "体标"}], "register": "书面", "sense_fingerprint": "预防疾病并在发病后治好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c091c7-baba-435e-971b-0e8f96dc6d24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96281, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防治", "is_correct": true, "explanation": "防治 fáng zhì 是正确答案，意思是预防并治疗。"}, {"text": "房址", "is_correct": false, "explanation": "房址 fángzhǐ 与 fáng zhì 只差第二音节的声调，意思是房屋的地基。"}, {"text": "纺织", "is_correct": false, "explanation": "纺织 fǎngzhī 两个音节的声调都不同，意思是把纤维织成布。"}, {"text": "放置", "is_correct": false, "explanation": "放置 fàngzhì 第一音节声调不同（fàng 第四声），意思是摆放。"}, {"text": "房主", "is_correct": false, "explanation": "房主 fángzhǔ 第二音节韵母 i 变为 u，声调也不同，意思是房子的主人。"}], "explanations": {"防治": "防治 fáng zhì 是正确答案，意思是预防并治疗。", "房址": "房址 fángzhǐ 与 fáng zhì 只差第二音节的声调，意思是房屋的地基。", "纺织": "纺织 fǎngzhī 两个音节的声调都不同，意思是把纤维织成布。", "放置": "放置 fàngzhì 第一音节声调不同（fàng 第四声），意思是摆放。", "房主": "房主 fángzhǔ 第二音节韵母 i 变为 u，声调也不同，意思是房子的主人。"}, "sentence_index": null, "correct_answer": "防治"}, "level_3": {"options": [{"text": "防治", "is_correct": true, "explanation": "防治是动词，与“注意”及“感冒”的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏是喜爱事物，不能用来处理感冒。"}, {"text": "培养", "is_correct": false, "explanation": "语义：培养多用于人才或习惯，不用于感冒。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：打扮的对象是人或外貌，不能带“感冒”作宾语。"}], "explanations": {"防治": "防治是动词，与“注意”及“感冒”的语境相符。", "欣赏": "语义：欣赏是喜爱事物，不能用来处理感冒。", "培养": "语义：培养多用于人才或习惯，不用于感冒。", "打扮": "搭配：打扮的对象是人或外貌，不能带“感冒”作宾语。"}, "sentence_index": 0, "correct_answer": "防治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈正在防治家里的椅子。", "explanation": "这里词义用错了。防治的对象是疾病，不能用于家具。"}, {"text": "他每天都要防治自己的工作。", "explanation": "防治的对象是疾病、虫害、污染等，不能用于“工作”。"}, {"text": "爸爸吃完饭就去防治电视。", "explanation": "防治的对象不包括电器，这句把它用在了电视上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防治", "is_correct": true, "explanation": "防治是动词，与“感冒要多穿衣服”的语境相符。"}, {"text": "见面", "is_correct": false, "explanation": "配价：见面是不及物动词，不能带“感冒”作宾语。"}, {"text": "逛", "is_correct": false, "explanation": "配价：逛是不及物动词，不能带“感冒”作宾语。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是窃取的意思，不能用来处理感冒。"}], "explanations": {"防治": "防治是动词，与“感冒要多穿衣服”的语境相符。", "见面": "配价：见面是不及物动词，不能带“感冒”作宾语。", "逛": "配价：逛是不及物动词，不能带“感冒”作宾语。", "偷": "语义：偷是窃取的意思，不能用来处理感冒。"}, "sentence_index": 6, "correct_answer": "防治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们在边境防治敌人。", "explanation": "这里应该用〈防御〉。防治只用于疾病、虫害、污染，不用于敌人。"}, {"text": "这位老师防治了全班的学生。", "explanation": "防治的对象是疾病、虫害等，不能用于人，这句把它用在了学生身上。"}, {"text": "他每天都防治这份合同。", "explanation": "防治的对象不包括合同这类文件，这句词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里的医生把流感防治了好，没有人生病。", "corrected_sentence": "村里的医生把流感防治好了，没有人生病。", "error_description": "补语与了的位置错误：结果补语“好”要紧跟动词，了放在句末。应说“防治好了”，不说“防治了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
