INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防治", "is_correct": true, "explanation": "防治是动词，与“工厂要先……污染，再生产”的语境相符。"}, {"text": "见面", "is_correct": false, "explanation": "配价：见面是不及物动词，不能带“污染”作宾语。"}, {"text": "逛", "is_correct": false, "explanation": "语义：逛是随意走走、游览（如逛商店），宾语是地方，不能用来处理污染。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是窃取的意思，不能用来处理污染。"}], "explanations": {"防治": "防治是动词，与“工厂要先……污染，再生产”的语境相符。", "见面": "配价：见面是不及物动词，不能带“污染”作宾语。", "逛": "语义：逛是随意走走、游览（如逛商店），宾语是地方，不能用来处理污染。", "偷": "语义：偷是窃取的意思，不能用来处理污染。"}, "sentence_index": 6, "correct_answer": "防治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察在街上防治游客。", "explanation": "防治针对的是疾病、虫害、污染，不能用于人，这句把它用在了游客身上。"}, {"text": "这位老板防治了全部员工。", "explanation": "防治的对象不是人，这句把它用在了员工身上，词义用错了。"}, {"text": "我们班防治了一场考试。", "explanation": "防治不用于考试这类活动，这句词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把果园的虫害防治了好，虫子少了很多。", "corrected_sentence": "农民把果园的虫害防治好了，虫子少了很多。", "error_description": "补语与了的位置错误：结果补语“好”要紧跟动词，了放在句末。应说“防治好了”，不说“防治了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把两种污染防治了好。", "corrected_sentence": "工厂把两种污染防治好了。", "error_description": "补语与了的位置错误：结果补语“好”要紧跟动词，了放在句末。应说“防治好了”，不说“防治了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6cc8cc4-19b1-46e4-bd66-ca28932598cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
