INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96283, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西挡住太阳，地上就会有一块黑黑的地方。", "primary_collocate": null, "pronunciation": "yīn yǐng", "ipa": "in⁵⁵ iŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "大树下面有一大片阴影。", "target_word": "阴影", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天我们坐在阴影里乘凉。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳升得越来越高，树的阴影就变短了。", "target_word": "阴影", "complexity_tier": "T3", "furigana": "tàiyáng shēng de yuè lái yuè gāo, shù de yīnyǐng jiù biàn duǎn le.", "sentence_source": "generated"}, {"text": "孩子在楼房的阴影里玩游戏。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午，教室的窗外有一块阴影。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他躲进阴影里，不想晒太阳。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "云走过来，地上出现了一片阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阴影越来越长，天快黑了。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把自行车放在阴影里。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上有很多树，走在阴影里很舒服。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "陰影", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西挡住阳光后，地上出现的黑暗区域（具体的影子）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96283, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阴影", "is_correct": true, "explanation": "正确：“阴影”指东西挡住阳光后地上的暗区，与“大树下面”“一大片”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能铺成“一大片”的地面区域，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“一大片”多用于可以铺展的东西，“冰箱”是单件家电，不能说“一大片冰箱”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学习任务，不是能铺在树下的东西，句子不通。"}], "explanations": {"阴影": "正确：“阴影”指东西挡住阳光后地上的暗区，与“大树下面”“一大片”相符。", "太阳": "语义：太阳是天体，不能铺成“一大片”的地面区域，句子不通。", "冰箱": "搭配：“一大片”多用于可以铺展的东西，“冰箱”是单件家电，不能说“一大片冰箱”。", "作业": "语义：“作业”是学习任务，不是能铺在树下的东西，句子不通。"}, "sentence_index": 0, "correct_answer": "阴影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天的阴影照在身上，很暖和。", "explanation": "这里应该用〈阳光〉。阴影是挡住光线后形成的暗区，不能照在身上让人暖和；让人暖和的是阳光。"}, {"text": "地上有一只阴影，很清楚。", "explanation": "量词错误：阴影指地上的暗区，量词用“片”或“块”，不说“只”。"}, {"text": "他在镜子里看到自己的阴影。", "explanation": "这里应该用〈倒影〉。阴影是东西挡住光线后形成的暗区，镜中映出的人像是光的反射，要说“倒影”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96283, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阴影", "is_correct": true, "explanation": "正确：“阴影”指云遮住阳光后地上出现的暗区，与“云走过来”“地上出现”相符。"}, {"text": "风", "is_correct": false, "explanation": "语义：风看不见，也不能“一片”地出现在地上，句子不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是挂在窗上的织物，不会因为云走过来而在地上出现一片。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“一片”不能修饰一把钥匙，钥匙是可数的小件物品。"}], "explanations": {"阴影": "正确：“阴影”指云遮住阳光后地上出现的暗区，与“云走过来”“地上出现”相符。", "风": "语义：风看不见，也不能“一片”地出现在地上，句子不通。", "窗帘": "语义：窗帘是挂在窗上的织物，不会因为云走过来而在地上出现一片。", "钥匙": "搭配：“一片”不能修饰一把钥匙，钥匙是可数的小件物品。"}, "sentence_index": 6, "correct_answer": "阴影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的阴影很亮，照得人睁不开眼。", "explanation": "这里应该用〈灯光〉。阴影是挡住光线后的暗区，本身不会发亮；“很亮，照得人睁不开眼”说的是灯光。"}, {"text": "地上有一把阴影，很长。", "explanation": "量词错误：“把”用于有柄的器具，阴影是地上的暗区，应用“片”或“块”。"}, {"text": "地上有一颗阴影，圆圆的。", "explanation": "量词错误：“颗”用于小而圆的颗粒状东西，阴影是地上的暗区，应用“片”或“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96283, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地上有一大颗阴影。", "corrected_sentence": "地上有一大片阴影。", "error_description": "错误形式：“一大颗阴影”；正确形式：“一大片阴影”。“颗”用于小而圆的东西，阴影是地上的一块暗区，量词应用“片”或“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96283, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地上出现了一大颗阴影。", "corrected_sentence": "地上出现了一大块阴影。", "error_description": "错误形式：“一大颗阴影”；正确形式：“一大块阴影”。“颗”用于小而圆的东西，阴影是地上的暗区，量词应用“块”或“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
