INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96284, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻使人心情沉重、长久难以释怀的不良影响，如留在心里的创伤或负担。", "primary_collocate": null, "pronunciation": "yīn yǐng", "ipa": "in⁵⁵ iŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "那次事故在他心里留下了阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子走出了父母离婚的阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试失败的阴影一直跟着她。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事给我们的生活带来了阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，他心里一直压着童年的阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她慢慢从失败的阴影中走了出来。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的那次事故，让他对水有了阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的一句批评，在她心里投下了长长的阴影。", "target_word": "阴影", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友的话让我心里的阴影少了很多。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑了，眼里再也没有往日的阴影。", "target_word": "阴影", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "陰影", "label": "繁体"}], "register": "中性", "sense_fingerprint": "留在心里的沉重不良影响（心理层面的比喻用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阴影", "is_correct": true, "explanation": "正确：“阴影”指留在心里的沉重不良影响，与“那次事故”“留下了”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能留在人的心里，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“留下”后可以接“印象”“影响”，不能接“价格”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能留在人的心里，句子不通。"}], "explanations": {"阴影": "正确：“阴影”指留在心里的沉重不良影响，与“那次事故”“留下了”相符。", "桌子": "语义：桌子是家具，不能留在人的心里，句子不通。", "价格": "搭配：“留下”后可以接“印象”“影响”，不能接“价格”。", "汽车": "语义：汽车是交通工具，不能留在人的心里，句子不通。"}, "sentence_index": 0, "correct_answer": "阴影"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她小时候的阴影很美好，常常想起来。", "explanation": "这里应该用〈记忆〉。阴影指遮光的暗区或使人沮丧的不良影响，不能形容美好的过去；美好的过去要说“记忆”。"}, {"text": "这次聚会让我们心里充满了阴影，大家却都很开心。", "explanation": "语义矛盾：“阴影”指使人沮丧的不良影响，与“大家却都很开心”相抵触；表示开心的心情不用“阴影”。"}, {"text": "那次事故在他心里留下了一根阴影。", "explanation": "量词错误：心里的阴影用“道”，不说“根”；“根”用于细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阴影", "is_correct": true, "explanation": "正确：“阴影”指留在心里的沉重不良影响，“对水有了”表示心理上对水产生了害怕的感受。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁用的工具，不能成为人对水的心理感受，句子不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不能成为人对水的心理感受，句子不通。"}, {"text": "办法", "is_correct": false, "explanation": "搭配：“对……有了”一般接感受或印象，不能接“办法”。"}], "explanations": {"阴影": "正确：“阴影”指留在心里的沉重不良影响，“对水有了”表示心理上对水产生了害怕的感受。", "钥匙": "语义：钥匙是开锁用的工具，不能成为人对水的心理感受，句子不通。", "厨房": "语义：厨房是做饭的地方，不能成为人对水的心理感受，句子不通。", "办法": "搭配：“对……有了”一般接感受或印象，不能接“办法”。"}, "sentence_index": 6, "correct_answer": "阴影"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的阴影很清脆，像银铃一样。", "explanation": "这里应该用〈笑声〉。阴影指遮光的暗区或使人沮丧的影响，不能形容声音清脆；清脆形容笑声，要用“笑声”。"}, {"text": "那件事在她心里留下了一张阴影。", "explanation": "量词错误：“张”用于平面的东西，如纸、桌子；留在心里的阴影用“道”。"}, {"text": "她眼里还有一把阴影，很久没有散去。", "explanation": "量词错误：“把”用于有柄的器具，不能用来数阴影；心里的阴影用“道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次事故给他留下了一颗阴影。", "corrected_sentence": "那次事故给他留下了一道阴影。", "error_description": "错误形式：“一颗阴影”；正确形式：“一道阴影”。“颗”用于小而圆的东西，留在心里的阴影应用“道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那段日子给她留下了一颗阴影。", "corrected_sentence": "那段日子给她留下了一道阴影。", "error_description": "错误形式：“一颗阴影”；正确形式：“一道阴影”。“颗”用于小而圆的东西，留在心里的阴影应用“道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
