INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸡妈妈生的蛋，可以煮着吃。", "primary_collocate": null, "pronunciation": "jī dàn", "ipa": "tɕi˥ tan˥˩", "syllable_count": 2, "sentences": [{"text": "小朋友喜欢吃煮鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上我吃了两个鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡妈妈生了很多鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在农场里找到了五个鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个鸡蛋是热的，刚煮好。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鸡蛋放在桌子上，转身走了。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃炒鸡蛋还是煮饺子？", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟用小手拿着鸡蛋，走得很慢。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我煮了一个鸡蛋当早饭。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃鸡蛋以前，要先把壳剥掉。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "炒鸡蛋", "label": "复合"}, {"form": "雞蛋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鸡生的、可以煮着吃的蛋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸡蛋", "is_correct": true, "explanation": "正确：鸡蛋 jīdàn，指鸡生的、可以煮着吃的蛋。"}, {"text": "积淀", "is_correct": false, "explanation": "积淀 jīdiàn 与 鸡蛋 jīdàn 的第二个音节只差介音 i，意思是长期积累形成的沉积。"}, {"text": "鸡胆", "is_correct": false, "explanation": "dǎn（第三声）与 dàn（第四声）声调不同，意思是鸡的胆囊。"}, {"text": "金蛋", "is_correct": false, "explanation": "jīn 与 jī 的韵母不同（多一个鼻音韵尾 n），意思是金色的蛋。"}], "explanations": {"鸡蛋": "正确：鸡蛋 jīdàn，指鸡生的、可以煮着吃的蛋。", "积淀": "积淀 jīdiàn 与 鸡蛋 jīdàn 的第二个音节只差介音 i，意思是长期积累形成的沉积。", "鸡胆": "dǎn（第三声）与 dàn（第四声）声调不同，意思是鸡的胆囊。", "金蛋": "jīn 与 jī 的韵母不同（多一个鼻音韵尾 n），意思是金色的蛋。"}, "sentence_index": null, "correct_answer": "鸡蛋"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，也不能煮着吃。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：蛋糕一般烤或蒸出来，不说“煮着吃”。"}, {"text": "鸡蛋", "is_correct": true, "explanation": "正确：“煮鸡蛋”是常见的说法，符合“小朋友喜欢吃”的语境。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不能煮，也不能吃。"}], "explanations": {"石头": "语义：石头不能吃，也不能煮着吃。", "蛋糕": "搭配：蛋糕一般烤或蒸出来，不说“煮着吃”。", "鸡蛋": "正确：“煮鸡蛋”是常见的说法，符合“小朋友喜欢吃”的语境。", "足球": "语义：足球不能煮，也不能吃。"}, "sentence_index": 0, "correct_answer": "鸡蛋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在农场里找到了五块鸡蛋。", "explanation": "量词错误：这里应该用〈个〉。“块”用于块状的东西，鸡蛋不用“块”。"}, {"text": "我们在农场里找到了五根鸡蛋。", "explanation": "量词错误：这里应该用〈个〉。“根”用于细长的东西，鸡蛋不用“根”。"}, {"text": "我们在农场里找到了五张鸡蛋。", "explanation": "量词错误：这里应该用〈个〉。“张”用于平面的东西，鸡蛋不用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": false, "explanation": "搭配：牛奶不用“炒”。"}, {"text": "鸡蛋", "is_correct": true, "explanation": "正确：“炒鸡蛋”是常见的吃法，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能炒，也不能吃。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典不能炒。"}], "explanations": {"牛奶": "搭配：牛奶不用“炒”。", "鸡蛋": "正确：“炒鸡蛋”是常见的吃法，符合句意。", "手机": "语义：手机不能炒，也不能吃。", "字典": "语义：字典不能炒。"}, "sentence_index": 6, "correct_answer": "鸡蛋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃这条鸡蛋以前，要先把壳剥掉。", "explanation": "量词错误：这里应该用〈个〉（“这个鸡蛋”）。“条”用于细长的东西，鸡蛋不用“条”。"}, {"text": "吃这辆鸡蛋以前，要先把壳剥掉。", "explanation": "量词错误：这里应该用〈个〉（“这个鸡蛋”）。“辆”用于车，不用于鸡蛋。"}, {"text": "吃这把鸡蛋以前，要先把壳剥掉。", "explanation": "量词错误：这里应该用〈个〉（“这个鸡蛋”）。“把”用于有柄的东西，鸡蛋不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸下班后煮了三块鸡蛋。", "corrected_sentence": "爸爸下班后煮了三个鸡蛋。", "error_description": "量词错误：“鸡蛋”应用量词“个”，“块”用于块状的东西，应说“三个鸡蛋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐没拿了一个鸡蛋。", "corrected_sentence": "姐姐拿了一个鸡蛋。", "error_description": "否定错误：“没”否定已发生的动作时不与动词后的“了”同用，“没拿了”不成句，应去掉“没”，说“姐姐拿了一个鸡蛋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
