INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96286, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "母鸡所产的蛋，椭圆形，有硬壳，可供食用。", "primary_collocate": null, "pronunciation": "jī dàn", "ipa": "tɕi˥ tan˥˩", "syllable_count": 2, "sentences": [{"text": "早饭我吃了一个鸡蛋和一杯牛奶。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在冰箱里放了六个鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋掉在地上，一下子就碎了。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你去超市买一斤鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕要用面粉、牛奶和鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个鸡蛋的壳很硬，我敲了两下才敲开。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上煮两个鸡蛋。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不小心把鸡蛋打破了，只好再买一盒。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的鸡蛋和棕色的鸡蛋，我都喜欢吃。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里煮着三个鸡蛋，你别走开。", "target_word": "鸡蛋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "煮鸡蛋", "label": "复合"}, {"form": "雞蛋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "母鸡所产、有硬壳、可食用的蛋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96286, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸡蛋", "is_correct": true, "explanation": "正确：鸡蛋 jīdàn，指母鸡所产的蛋。"}, {"text": "机电", "is_correct": false, "explanation": "机电 jīdiàn 与 鸡蛋 jīdàn 的第二个音节只差介音 i，意思是机械与电气。"}, {"text": "鸡胆", "is_correct": false, "explanation": "dǎn（第三声）与 dàn（第四声）声调不同，意思是鸡的胆囊。"}, {"text": "金蛋", "is_correct": false, "explanation": "jīn 与 jī 的韵母不同（多一个鼻音韵尾 n），意思是金色的蛋。"}], "explanations": {"鸡蛋": "正确：鸡蛋 jīdàn，指母鸡所产的蛋。", "机电": "机电 jīdiàn 与 鸡蛋 jīdàn 的第二个音节只差介音 i，意思是机械与电气。", "鸡胆": "dǎn（第三声）与 dàn（第四声）声调不同，意思是鸡的胆囊。", "金蛋": "jīn 与 jī 的韵母不同（多一个鼻音韵尾 n），意思是金色的蛋。"}, "sentence_index": null, "correct_answer": "鸡蛋"}, "level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机不能吃，与句中的“吃了”冲突。"}, {"text": "鸡蛋", "is_correct": true, "explanation": "正确：“一个鸡蛋”是早饭常见的食物，与“吃了”“牛奶”相配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，早饭不会吃石头。"}, {"text": "皮鞋", "is_correct": false, "explanation": "语义：皮鞋不能吃，早饭不会吃皮鞋。"}], "explanations": {"手机": "语义：手机不能吃，与句中的“吃了”冲突。", "鸡蛋": "正确：“一个鸡蛋”是早饭常见的食物，与“吃了”“牛奶”相配。", "石头": "语义：石头不能吃，早饭不会吃石头。", "皮鞋": "语义：皮鞋不能吃，早饭不会吃皮鞋。"}, "sentence_index": 0, "correct_answer": "鸡蛋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你去超市买一根鸡蛋。", "explanation": "量词错误：“根”用于细长的东西，鸡蛋不用“根”，可用〈个〉或〈斤〉计量。"}, {"text": "请你去超市买一片鸡蛋。", "explanation": "量词错误：“片”用于薄而平的东西，鸡蛋不用“片”，可用〈个〉或〈斤〉计量。"}, {"text": "请你去超市买一头鸡蛋。", "explanation": "量词错误：“头”用于大牲畜，不用于鸡蛋，可用〈个〉或〈斤〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": false, "explanation": "语义：足球不能煮，也不能吃。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：蛋糕一般烤或蒸出来，不说“煮”。"}, {"text": "鸡蛋", "is_correct": true, "explanation": "正确：“煮两个鸡蛋”是常见的说法，与“每天早上”相符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能煮。"}], "explanations": {"足球": "语义：足球不能煮，也不能吃。", "蛋糕": "搭配：蛋糕一般烤或蒸出来，不说“煮”。", "鸡蛋": "正确：“煮两个鸡蛋”是常见的说法，与“每天早上”相符。", "玩具": "语义：玩具不能煮。"}, "sentence_index": 6, "correct_answer": "鸡蛋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "锅里煮着三条鸡蛋，你别走开。", "explanation": "量词错误：这里应该用〈个〉。“条”用于细长的东西，鸡蛋不用“条”。"}, {"text": "锅里煮着三辆鸡蛋，你别走开。", "explanation": "量词错误：这里应该用〈个〉。“辆”用于车，不用于鸡蛋。"}, {"text": "锅里煮着三把鸡蛋，你别走开。", "explanation": "量词错误：这里应该用〈个〉。“把”用于有柄的东西，鸡蛋不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天早上给我煮一块鸡蛋。", "corrected_sentence": "妈妈每天早上给我煮一个鸡蛋。", "error_description": "量词错误：“鸡蛋”应用量词“个”，“块”用于块状的东西，应说“一个鸡蛋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈没煮了两个鸡蛋。", "corrected_sentence": "妈妈煮了两个鸡蛋。", "error_description": "否定错误：“没”否定已发生的动作时不与动词后的“了”同用，“没煮了”不成句，应去掉“没”，说“妈妈煮了两个鸡蛋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
