INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96287, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能带人上楼下楼的大箱子，按一下按钮它就动。", "primary_collocate": null, "pronunciation": "diàn tī", "ipa": "tjɛn⁵¹ tʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "我家住在十楼，每天坐电梯。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯里有很多人。", "target_word": "电梯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请按一下电梯的按钮。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯坏了，我们只好走楼梯。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在电梯门口等朋友。", "target_word": "电梯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩第一次坐电梯，有点儿怕。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯慢慢往下走，门开了。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电梯太小，不能坐十个人。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我等了很久，电梯还没来。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人上楼不方便，所以喜欢用电梯。", "target_word": "电梯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "電梯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带人上下楼、按按钮就动的大箱子（日常口语说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电梯", "is_correct": true, "explanation": "正确：“坐电梯”指乘坐电梯上下楼，与“住在十楼”相符。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“坐”一般不接“楼梯”，上楼梯要说“走”或“爬”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被人坐，句子不通。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能被人坐，句子不通。"}], "explanations": {"电梯": "正确：“坐电梯”指乘坐电梯上下楼，与“住在十楼”相符。", "楼梯": "搭配：“坐”一般不接“楼梯”，上楼梯要说“走”或“爬”。", "空气": "语义：空气不能被人坐，句子不通。", "玻璃": "语义：玻璃不能被人坐，句子不通。"}, "sentence_index": 0, "correct_answer": "电梯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们楼里刚装了一只电梯，很方便。", "explanation": "量词错误：电梯用“部”或“台”，不说“只”；“只”用于动物或成对物品中的一个。"}, {"text": "这栋楼一共有一把电梯。", "explanation": "量词错误：“把”用于有柄的器具，电梯应用“部”或“台”。"}, {"text": "商场里新买了一根电梯。", "explanation": "量词错误：“根”用于细长的东西，电梯应用“部”或“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电梯", "is_correct": true, "explanation": "正确：“电梯”能自己慢慢往下走，门开了说明已经到达。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“往下走”的主语多是能移动的人或物，“楼梯”是固定设施，不说“慢慢往下走”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不会自己往下走，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会自己往下走，与“门开了”也不相关。"}], "explanations": {"电梯": "正确：“电梯”能自己慢慢往下走，门开了说明已经到达。", "楼梯": "搭配：“往下走”的主语多是能移动的人或物，“楼梯”是固定设施，不说“慢慢往下走”。", "窗户": "语义：窗户是墙上的开口，不会自己往下走，句子不通。", "手机": "语义：手机不会自己往下走，与“门开了”也不相关。"}, "sentence_index": 6, "correct_answer": "电梯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人上楼不方便，所以家里装了一张电梯。", "explanation": "量词错误：“张”用于平面的东西，电梯用“部”或“台”，不说“张”。"}, {"text": "老人上楼不方便，所以社区装了一颗电梯。", "explanation": "量词错误：“颗”用于小而圆的东西，电梯应用“部”或“台”。"}, {"text": "老人上楼不方便，所以他请人买了一块电梯。", "explanation": "量词错误：“块”用于块状的东西，电梯应用“部”或“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区新装了一辆电梯，很方便。", "corrected_sentence": "我们小区新装了一部电梯，很方便。", "error_description": "错误形式：“一辆电梯”；正确形式：“一部电梯”。“辆”用于车辆，电梯用“部”或“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把电梯很旧，经常停。", "corrected_sentence": "这台电梯很旧，经常停。", "error_description": "错误形式：“这把电梯”；正确形式：“这台电梯”。“把”用于有柄的器具，电梯用“台”或“部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
