INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装在高层建筑中，用电力运送人员或货物上下楼层的升降设备。", "primary_collocate": null, "pronunciation": "diàn tī", "ipa": "tjɛn⁵¹ tʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "这栋大楼有六部电梯。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯可以运送人员和货物。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发生火灾时，不要乘坐电梯。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人每个月检查一次电梯。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货物要用电梯运到五楼。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高层建筑都应该安装电梯。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电梯停在了十八层。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电梯最多可以坐十三人。", "target_word": "电梯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场里的电梯运行得很安静。", "target_word": "电梯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老小区加装电梯，居民很满意。", "target_word": "电梯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "電梯", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高层建筑中用电力运送人员或货物的升降设备（设备、管理角度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电梯", "is_correct": true, "explanation": "正确：“六部电梯”指大楼里的六台升降设备，与句中“大楼”相符。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“部”不用于树，树应说“棵”。"}, {"text": "老鼠", "is_correct": false, "explanation": "搭配：“部”不用于动物，老鼠应说“只”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：大楼里不会有河流，句子不通。"}], "explanations": {"电梯": "正确：“六部电梯”指大楼里的六台升降设备，与句中“大楼”相符。", "树": "搭配：“部”不用于树，树应说“棵”。", "老鼠": "搭配：“部”不用于动物，老鼠应说“只”。", "河流": "语义：大楼里不会有河流，句子不通。"}, "sentence_index": 0, "correct_answer": "电梯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这栋大楼有六只电梯。", "explanation": "量词错误：“只”用于动物或成对物品中的一个，电梯应用“部”或“台”。"}, {"text": "这栋大楼里有一间电梯。", "explanation": "量词错误：“间”用于房屋，电梯应用“部”或“台”。"}, {"text": "这栋大楼有一条电梯。", "explanation": "量词错误：“条”用于细长的东西，电梯应用“部”或“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电梯", "is_correct": true, "explanation": "正确：“电梯”可以停在某一层，与“十八层”相符。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“停”多接可移动的交通工具，“楼梯”是固定设施，不说“停在”。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不能停在楼层上，与“十八层”冲突。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是家电，不能自己停在某一层，句子不通。"}], "explanations": {"电梯": "正确：“电梯”可以停在某一层，与“十八层”相符。", "楼梯": "搭配：“停”多接可移动的交通工具，“楼梯”是固定设施，不说“停在”。", "河水": "语义：河水不能停在楼层上，与“十八层”冲突。", "空调": "语义：空调是家电，不能自己停在某一层，句子不通。"}, "sentence_index": 6, "correct_answer": "电梯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老小区里新添了一页电梯，居民很满意。", "explanation": "量词错误：“页”用于纸张，电梯应用“部”或“台”。"}, {"text": "老小区里新添了一颗电梯，居民很满意。", "explanation": "量词错误：“颗”用于小而圆的东西，电梯应用“部”或“台”。"}, {"text": "老小区里新添了一本电梯，居民很满意。", "explanation": "量词错误：“本”用于书册，电梯应用“部”或“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋写字楼装了两间电梯，运行很平稳。", "corrected_sentence": "这栋写字楼装了两台电梯，运行很平稳。", "error_description": "错误形式：“两间电梯”；正确形式：“两台电梯”。“间”用于房屋，电梯用“部”或“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每块电梯都要定期做安全检测。", "corrected_sentence": "每台电梯都要定期做安全检测。", "error_description": "错误形式：“每块电梯”；正确形式：“每台电梯”。“块”用于块状物，电梯用“部”或“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
