INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "早上空气里白白的一片，看远处会看不清。", "primary_collocate": null, "pronunciation": "wù", "ipa": "u˥˩", "syllable_count": 1, "sentences": [{"text": "今天早上有雾，我看不清远处的山。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上起雾了，路上的车开得很慢。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾很大，我们只好在家里等。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的雾，像一片白白的云。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾散了以后，太阳出来了。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清晨的湖边常常有雾。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮的时候，雾还没有散。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外一片雾，什么都看不见。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天早上的雾真大，走路要小心。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在雾里走了很久，终于找到了家。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "大雾", "label": "复合"}, {"form": "霧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "早晨空气中白茫茫、让人看不清远处的一片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雾", "is_correct": true, "explanation": "正确：雾 wù，指早上空气里白茫茫、看不清远处的一片。"}, {"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞。"}, {"text": "路", "is_correct": false, "explanation": "l 与 w 声母不同，意思是道路。"}, {"text": "树", "is_correct": false, "explanation": "sh 与 w 声母不同，意思是树木。"}], "explanations": {"雾": "正确：雾 wù，指早上空气里白茫茫、看不清远处的一片。", "舞": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞。", "路": "l 与 w 声母不同，意思是道路。", "树": "sh 与 w 声母不同，意思是树木。"}, "sentence_index": null, "correct_answer": "雾"}, "level_3": {"options": [{"text": "晚霞", "is_correct": false, "explanation": "搭配：晚霞出现在傍晚，不能和“早上”搭配。"}, {"text": "雾", "is_correct": true, "explanation": "正确：“有雾”说明早上视线受阻，与“看不清远处的山”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会挡住视线。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会让人看不清远处。"}], "explanations": {"晚霞": "搭配：晚霞出现在傍晚，不能和“早上”搭配。", "雾": "正确：“有雾”说明早上视线受阻，与“看不清远处的山”相符。", "石头": "语义：石头不会挡住视线。", "手机": "语义：手机不会让人看不清远处。"}, "sentence_index": 0, "correct_answer": "雾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在屋里抽雾。", "explanation": "这里应该用〈烟〉。人可以抽烟，雾不能抽。"}, {"text": "山里有一条雾，像一片白白的云。", "explanation": "量词错误：“条”用于细长的东西，雾不用“条”。说一片雾可以用〈片〉或〈团〉，如“一片雾”。"}, {"text": "他把雾点着了，屋里很暖和。", "explanation": "词义错误：“点着”的对象应是〈柴火〉这类可燃物；“雾”是白色水汽，不能被点燃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96289, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雾", "is_correct": true, "explanation": "正确：雾 wù，指早上空气里白茫茫、看不清远处的一片。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是数字“五”。"}, {"text": "户", "is_correct": false, "explanation": "h 与 w 声母不同，意思是门，住户。"}, {"text": "度", "is_correct": false, "explanation": "d 与 w 声母不同，意思是程度，度量。"}], "explanations": {"雾": "正确：雾 wù，指早上空气里白茫茫、看不清远处的一片。", "五": "wǔ（第三声）与 wù（第四声）声调不同，意思是数字“五”。", "户": "h 与 w 声母不同，意思是门，住户。", "度": "d 与 w 声母不同，意思是程度，度量。"}, "sentence_index": null, "correct_answer": "雾"}, "level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮不会“散”。"}, {"text": "雾", "is_correct": true, "explanation": "正确：“雾”会在天亮后慢慢散去，与句意相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不会“散”。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：雨停了说“停”，不说“散”。"}], "explanations": {"月亮": "语义：月亮不会“散”。", "雾": "正确：“雾”会在天亮后慢慢散去，与句意相符。", "面包": "语义：面包不会“散”。", "雨": "搭配：雨停了说“停”，不说“散”。"}, "sentence_index": 6, "correct_answer": "雾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "做蛋糕要用面粉和雾。", "explanation": "词义错误：“做蛋糕”要用〈鸡蛋〉这类食材；“雾”是早上空气里的水汽，不能当作食材。"}, {"text": "我在一座雾里走了很久，终于找到了家。", "explanation": "量词错误：“座”用于山、桥等大型物体，雾不用“座”。“在雾里走”不需要量词。"}, {"text": "我在一棵雾里走了很久，终于找到了家。", "explanation": "量词错误：“棵”用于植物，雾不用“棵”。“在雾里走”不需要量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今早山上起了一条雾。", "corrected_sentence": "今早山上起了一场雾。", "error_description": "量词错误：雾应用量词“场”计量，“条”用于细长的东西，应说“一场雾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公路上起了雾大，车只能慢慢开。", "corrected_sentence": "公路上起了大雾，车只能慢慢开。", "error_description": "语序错误：作修饰语的“大”应放在“雾”前，说“大雾”，不能说“雾大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
