INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接近地面的空气中由小水滴聚集而成的白色水汽，使能见度降低。", "primary_collocate": null, "pronunciation": "wù", "ipa": "u˥˩", "syllable_count": 1, "sentences": [{"text": "空气很湿的时候，地面附近容易起雾。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾是由很小的水滴聚在一起形成的。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾让能见度变得很低。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为有大雾，飞机不能起飞。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里温度下降，水汽变成了雾。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有雾的时候开车要开慢一点。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速路上雾很浓，能见度只有几十米。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的雾来得快，去得也快。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雾持续了一整个上午。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说明天早上有雾。", "target_word": "雾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "浓雾", "label": "复合"}, {"form": "霧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "近地面小水滴聚成、降低能见度的白色水汽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雾", "is_correct": true, "explanation": "正确：雾 wù，指近地面小水滴聚成的白色水汽。"}, {"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞。"}, {"text": "路", "is_correct": false, "explanation": "l 与 w 声母不同，意思是道路。"}, {"text": "树", "is_correct": false, "explanation": "sh 与 w 声母不同，意思是树木。"}], "explanations": {"雾": "正确：雾 wù，指近地面小水滴聚成的白色水汽。", "舞": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞。", "路": "l 与 w 声母不同，意思是道路。", "树": "sh 与 w 声母不同，意思是树木。"}, "sentence_index": null, "correct_answer": "雾"}, "level_3": {"options": [{"text": "露", "is_correct": false, "explanation": "搭配：露要说“结”，不说“起”。"}, {"text": "雾", "is_correct": true, "explanation": "正确：空气湿时，地面附近容易形成水汽，说“起雾”，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会在地面附近“起”来。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会在空气中“起”来。"}], "explanations": {"露": "搭配：露要说“结”，不说“起”。", "雾": "正确：空气湿时，地面附近容易形成水汽，说“起雾”，符合句意。", "石头": "语义：石头不会在地面附近“起”来。", "手机": "语义：手机不会在空气中“起”来。"}, "sentence_index": 0, "correct_answer": "雾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在屋里抽雾。", "explanation": "这里应该用〈烟〉。人可以抽烟，雾不能抽。"}, {"text": "因为有一条大雾，飞机不能起飞。", "explanation": "量词错误：这里应该用〈场〉。“条”用于细长的东西，雾要用“场”计量。"}, {"text": "因为有一碗大雾，飞机不能起飞。", "explanation": "量词错误：这里应该用〈场〉。“碗”用于盛东西的器皿，雾不用“碗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96290, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雾", "is_correct": true, "explanation": "正确：雾 wù，指近地面小水滴聚成的白色水汽。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是数字“五”。"}, {"text": "户", "is_correct": false, "explanation": "h 与 w 声母不同，意思是门，住户。"}, {"text": "度", "is_correct": false, "explanation": "d 与 w 声母不同，意思是程度，度量。"}], "explanations": {"雾": "正确：雾 wù，指近地面小水滴聚成的白色水汽。", "五": "wǔ（第三声）与 wù（第四声）声调不同，意思是数字“五”。", "户": "h 与 w 声母不同，意思是门，住户。", "度": "d 与 w 声母不同，意思是程度，度量。"}, "sentence_index": null, "correct_answer": "雾"}, "level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "搭配：雨不说“浓”，“浓”多用于雾、烟等。"}, {"text": "雾", "is_correct": true, "explanation": "正确：“雾很浓”说明能见度低，与“只有几十米”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会“浓”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会“浓”。"}], "explanations": {"雨": "搭配：雨不说“浓”，“浓”多用于雾、烟等。", "雾": "正确：“雾很浓”说明能见度低，与“只有几十米”相符。", "汽车": "语义：汽车不会“浓”。", "书": "语义：书不会“浓”。"}, "sentence_index": 6, "correct_answer": "雾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气预报说明天早上有一块雾。", "explanation": "这里应该用〈场〉。“块”用于块状的东西，雾不用“块”。"}, {"text": "天气预报说明天早上有一座雾。", "explanation": "这里应该用〈场〉。“座”用于山、桥等大型物体，雾不用“座”。"}, {"text": "天气预报说明天早上有一把雾。", "explanation": "这里应该用〈场〉。“把”用于有柄的东西，雾不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天亮前山谷里起了一个浓雾。", "corrected_sentence": "天亮前山谷里起了一场浓雾。", "error_description": "量词错误：雾应用量词“场”计量，“个”不用于雾，应说“一场浓雾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "高速路上有一场雾浓，能见度很低。", "corrected_sentence": "高速路上有一场浓雾，能见度很低。", "error_description": "语序错误：修饰“雾”的“浓”应放在“雾”前，说“浓雾”，不能说“雾浓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
