INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96291, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情还没开始，先把要用的东西弄好。", "primary_collocate": null, "pronunciation": "yù bèi", "ipa": "y˥˩ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈预备了很多好吃的菜。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人快到了，我们预备点水果吧。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他预备好了明天要用的书。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师预备了一些小礼物给学生。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前请预备好你的护照。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经预备好雨伞，下雨也不怕。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行要用的东西，你预备好了吗？", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在厨房里预备晚饭。", "target_word": "预备", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议马上开始，请大家预备好笔记本。", "target_word": "预备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预备了两个杯子给客人用。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "预备了", "label": "体标（了）"}, {"form": "预备好", "label": "结果补语"}, {"form": "预备预备", "label": "重叠"}, {"form": "預備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "预备：事前把要用的东西准备好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预备", "is_correct": true, "explanation": "“预备”是事先把要用的东西准备好，可以说“预备了很多好吃的菜”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能跟“好吃的菜”搭配，句子不通。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：参观是去看地方或展览，不能用于“好吃的菜”。"}, {"text": "复习", "is_correct": false, "explanation": "语义：复习是温习已学的内容，与菜无关。"}], "explanations": {"预备": "“预备”是事先把要用的东西准备好，可以说“预备了很多好吃的菜”。", "唱": "搭配：“唱”不能跟“好吃的菜”搭配，句子不通。", "参观": "搭配：参观是去看地方或展览，不能用于“好吃的菜”。", "复习": "语义：复习是温习已学的内容，与菜无关。"}, "sentence_index": 0, "correct_answer": "预备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我预备了很多朋友，一起去看电影。", "explanation": "这里应该用〈邀请〉。预备用于准备物品或安排，不能用来指请人来。"}, {"text": "我预备你的帮助，非常感谢。", "explanation": "这里应该用〈感激〉。预备指事先准备东西或安排，不能用来表示对别人帮助的谢意。"}, {"text": "我预备到了那个声音。", "explanation": "这里应该用〈听到〉。预备不能表示用耳朵接收声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预备", "is_correct": true, "explanation": "“预备”是事先把要用的东西准备好，可以说“你预备好了吗”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能用于“旅行要用的东西”。"}, {"text": "写", "is_correct": false, "explanation": "语义：写的对象是文字或文件，与“东西”不合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“东西”作宾语，这样问不通。"}], "explanations": {"预备": "“预备”是事先把要用的东西准备好，可以说“你预备好了吗”。", "唱": "搭配：“唱”的对象是歌曲，不能用于“旅行要用的东西”。", "写": "语义：写的对象是文字或文件，与“东西”不合。", "睡": "配价：“睡”是不及物动词，不能带“东西”作宾语，这样问不通。"}, "sentence_index": 6, "correct_answer": "预备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大声预备了一声。", "explanation": "这里应该用〈喊〉。预备指事先准备物品，不能用来指发出声音。"}, {"text": "他向我预备了一次。", "explanation": "这里应该用〈道歉〉。预备不能用来表示向别人认错或致歉。"}, {"text": "他咳嗽了几声，预备了几声。", "explanation": "这里应该用〈发出〉。预备指事先准备东西，不能用来表示发出声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你预备到钥匙。", "corrected_sentence": "请你预备好钥匙。", "error_description": "结果补语“到”不能接在“预备”后。“预备”的结果补语应为“好”，说“预备好钥匙”，表示事先把要用的东西准备好。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸正在预备了晚饭。", "corrected_sentence": "爸爸正在预备晚饭。", "error_description": "“正在”表示动作正在进行，不能和表示完成的“了”一起用；应删去“了”，说“爸爸正在预备晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
