INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96292, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先做好准备；筹划安排。", "primary_collocate": null, "pronunciation": "yù bèi", "ipa": "y˥˩ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们预备下个月去旅行。", "target_word": "预备", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他预备明年考研究生。", "target_word": "预备", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校预备在六月开运动会。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你预备什么时候搬家？", "target_word": "预备", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她预备下周请朋友来家里吃饭。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司预备明年开一家新店。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我预备先工作两年再出国读书。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们预备在秋天结婚。", "target_word": "预备", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师预备下星期给我们考试。", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你预备怎么回答这个问题？", "target_word": "预备", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "预备了", "label": "体标（了）"}, {"form": "预备着", "label": "体标（着）"}, {"form": "预备预备", "label": "重叠"}, {"form": "預備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "预备：事先筹划安排，打算做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bc3fefe-ca22-418d-b568-6a52acd06a5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预备", "is_correct": true, "explanation": "“预备”是事先筹划安排，可以说“预备下个月去旅行”。"}, {"text": "复习", "is_correct": false, "explanation": "语义：复习是温习已学的内容，不能用来安排下个月的旅行。"}, {"text": "参观", "is_correct": false, "explanation": "语义：参观是去看展览或地方，不能用来安排“去旅行”。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”用于已经开始的任务，不能用于尚未开始的旅行计划。"}], "explanations": {"预备": "“预备”是事先筹划安排，可以说“预备下个月去旅行”。", "复习": "语义：复习是温习已学的内容，不能用来安排下个月的旅行。", "参观": "语义：参观是去看展览或地方，不能用来安排“去旅行”。", "完成": "搭配：“完成”用于已经开始的任务，不能用于尚未开始的旅行计划。"}, "sentence_index": 0, "correct_answer": "预备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还在预备窗外飘来的香味。", "explanation": "这里应该用〈闻到〉。预备是筹划安排，不能用来表示用鼻子接收气味。"}, {"text": "我们在预备那阵哭声。", "explanation": "这里应该用〈听到〉。预备是筹划安排，不能用来表示用耳朵接收声音。"}, {"text": "他预备童年的往事，沉默了很久。", "explanation": "这里应该用〈回忆〉。预备指事先的筹划，不能用来指想起过去的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预备", "is_correct": true, "explanation": "“预备”是事先筹划，可以说“预备先工作两年再出国读书”。"}, {"text": "退休", "is_correct": false, "explanation": "语义：退休是离开工作岗位，与“先工作两年”的计划相矛盾。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与工作和出国读书没有计划关系，句子意思不通。"}, {"text": "失业", "is_correct": false, "explanation": "搭配：“失业”是状态，不能和“先……再……”的计划结构搭配。"}], "explanations": {"预备": "“预备”是事先筹划，可以说“预备先工作两年再出国读书”。", "退休": "语义：退休是离开工作岗位，与“先工作两年”的计划相矛盾。", "唱歌": "语义：唱歌与工作和出国读书没有计划关系，句子意思不通。", "失业": "搭配：“失业”是状态，不能和“先……再……”的计划结构搭配。"}, "sentence_index": 6, "correct_answer": "预备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他预备着一阵心痛。", "explanation": "这里应该用〈感到〉。预备是事先筹划，不能用来指身体或内心产生某种感受。"}, {"text": "我预备不出他的样子。", "explanation": "这里应该用〈想象〉。预备是事先安排，不能表示在脑中构想。"}, {"text": "他预备了口气，很失望。", "explanation": "这里应该用〈叹气〉。预备是事先准备，不能用来指呼出气息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们预备了明天搬家。", "corrected_sentence": "他们预备明天搬家。", "error_description": "“了”表示动作已经完成，与将来时间“明天”矛盾；应删去“了”，说“他们预备明天搬家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8074a392-827d-47c3-932d-cbf2f41ea506') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
