INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96293, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "三流", "is_correct": true, "explanation": "反义：“三流”指等级最低、水平最差，与“一流”意思相反，构成反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外貌好看，与“一流”不构成反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”与“吵闹”相对，与“一流”的“最高等级”的意思没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“一流”的意思没有相对关系。"}], "correct_answer": "三流", "explanations": {"三流": "反义：“三流”指等级最低、水平最差，与“一流”意思相反，构成反义关系。", "美丽": "“美丽”形容外貌好看，与“一流”不构成反义关系。", "安静": "“安静”与“吵闹”相对，与“一流”的“最高等级”的意思没有反义关系。", "陌生": "“陌生”指不熟悉，与“一流”的意思没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
