INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96293, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "最好的，比别人都好。", "primary_collocate": null, "pronunciation": "yī liú", "ipa": "i˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这家饭店的菜是一流的。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语说得一流。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老师的水平一流，学生都喜欢他。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一流的大学，很多人想去。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的酒店服务一流。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一流的歌手，唱歌特别好听。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的医院在全国是一流的。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢足球踢得一流，是我们队的主力。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一流的东西，价钱也不便宜。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑质量一流，用了五年还很好。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一流的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "最好的，比别人都好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96293, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确答案：一流（yī liú），指水平、质量属于最高等级。"}, {"text": "遗留", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是留下来、残存，与“一流”的意思无关。"}, {"text": "一楼", "is_correct": false, "explanation": "lóu 与 liú 韵母不同（-ou 与 -iu），意思是楼房的第一层。"}, {"text": "医疗", "is_correct": false, "explanation": "liáo 与 liú 韵母不同（-iao 与 -iu），意思是治病、诊疗。"}, {"text": "一里", "is_correct": false, "explanation": "lǐ（第三声）与 liú 韵母和声调都不同，意思是一里，是距离单位。"}], "explanations": {"一流": "正确答案：一流（yī liú），指水平、质量属于最高等级。", "遗留": "yí（第二声）与 yī（第一声）声调不同，意思是留下来、残存，与“一流”的意思无关。", "一楼": "lóu 与 liú 韵母不同（-ou 与 -iu），意思是楼房的第一层。", "医疗": "liáo 与 liú 韵母不同（-iao 与 -iu），意思是治病、诊疗。", "一里": "lǐ（第三声）与 liú 韵母和声调都不同，意思是一里，是距离单位。"}, "sentence_index": null, "correct_answer": "一流"}, "level_3": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确：“一流”表示水平最高，符合“菜是……的”的语境。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大”说体积或规模，不能用来评价菜的水平。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，用来形容菜，意思不通。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容人的态度，用来说菜意思不通。"}], "explanations": {"一流": "正确：“一流”表示水平最高，符合“菜是……的”的语境。", "巨大": "搭配：“巨大”说体积或规模，不能用来评价菜的水平。", "沉默": "语义：“沉默”指不说话，用来形容菜，意思不通。", "冷淡": "语义：“冷淡”形容人的态度，用来说菜意思不通。"}, "sentence_index": 0, "correct_answer": "一流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我一流的朋友，我们从小就在一起。", "explanation": "这里误用“一流”形容友情。“一流”只评价水平或质量的等级，不能用来说朋友之间的亲疏，这里应改用〈要好〉。"}, {"text": "这次参加活动的人数是一流的。", "explanation": "这里应该用〈很多〉。“一流”只说水平或质量，人数这类数量不能用“一流”来形容。"}, {"text": "这个孩子的年纪一流，才五岁。", "explanation": "这里应该用〈小〉。“一流”只评价水平或质量的等级，年纪没有等级之分，不能用“一流”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96293, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确答案：一流（yī liú），指水平、质量属于最高等级。"}, {"text": "一连", "is_correct": false, "explanation": "lián（第二声）与 liú 声调相同，韵母不同（-ian 与 -iu），意思是连续不断。"}, {"text": "一轮", "is_correct": false, "explanation": "lún（第二声）与 liú 声调相同，韵母不同（-un 与 -iu），意思是一个循环或一圈。"}, {"text": "一溜", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是一行、一排。"}, {"text": "一例", "is_correct": false, "explanation": "lì（第四声）与 liú 韵母和声调都不同，意思是一个例子。"}], "explanations": {"一流": "正确答案：一流（yī liú），指水平、质量属于最高等级。", "一连": "lián（第二声）与 liú 声调相同，韵母不同（-ian 与 -iu），意思是连续不断。", "一轮": "lún（第二声）与 liú 声调相同，韵母不同（-un 与 -iu），意思是一个循环或一圈。", "一溜": "liù（第四声）与 liú（第二声）声调不同，意思是一行、一排。", "一例": "lì（第四声）与 liú 韵母和声调都不同，意思是一个例子。"}, "sentence_index": null, "correct_answer": "一流"}, "level_3": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确：“一流”指水平最高，与“在全国”的评价相符。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指某个地方，与“在全国”的范围相矛盾。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”形容空间或宽度，不能用来评价医院的水平。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质地，不用来评价医院的水平。"}], "explanations": {"一流": "正确：“一流”指水平最高，与“在全国”的评价相符。", "本地": "语义：“本地”指某个地方，与“在全国”的范围相矛盾。", "狭窄": "语义：“狭窄”形容空间或宽度，不能用来评价医院的水平。", "粗糙": "搭配：“粗糙”形容表面质地，不用来评价医院的水平。"}, "sentence_index": 6, "correct_answer": "一流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的价格是一流的，只要一百块钱。", "explanation": "这里应该用〈便宜〉。“一流”说水平或质量，价格的高低不能用“一流”来表示。"}, {"text": "这朵花的颜色是一流的，特别鲜艳。", "explanation": "这里应该用〈好看〉。“一流”评价的是水平或质量的等级，颜色只能说好看或不好看，不能用“一流”来评等级。"}, {"text": "这个箱子的重量是一流的，我一个人根本搬不动。", "explanation": "这里应该用〈沉〉。“一流”评价水平或质量的等级，重量只分多少，不分等级，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85')