INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她唱歌唱一流，大家都很喜欢。", "corrected_sentence": "她唱歌唱得一流，大家都很喜欢。", "error_description": "“一流”作补语描述“唱”的水平时，动词和它之间要用“得”：应说“唱得一流”，说“唱一流”是漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96293, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他打篮球打一流，大家都很佩服他。", "corrected_sentence": "他打篮球打得一流，大家都很佩服他。", "error_description": "“一流”作补语描述“打”的水平时，动词和它之间要用“得”：应说“打得一流”，说“打一流”是漏掉了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "三流", "is_correct": true, "explanation": "反义：“三流”指等级最低、水平最差，与“一流”意思相反，构成反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑反应快，与“一流”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”与“冷清”相对，与“一流”的意思没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "“干燥”指缺少水分，与“一流”的意思没有相对关系。"}], "correct_answer": "三流", "explanations": {"三流": "反义：“三流”指等级最低、水平最差，与“一流”意思相反，构成反义关系。", "聪明": "“聪明”形容头脑反应快，与“一流”没有反义关系。", "热闹": "“热闹”与“冷清”相对，与“一流”的意思没有反义关系。", "干燥": "“干燥”指缺少水分，与“一流”的意思没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "三流", "is_correct": true, "explanation": "反义：“三流”指等级最低、水平最差，与“一流”意思相反，构成反义关系。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外貌好看，与“一流”不构成反义关系。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”形容做事专心踏实，与“一流”没有反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "“大方”形容举止不拘谨或不吝啬，与“一流”没有相对关系。"}], "correct_answer": "三流", "explanations": {"三流": "反义：“三流”指等级最低、水平最差，与“一流”意思相反，构成反义关系。", "美丽": "“美丽”形容外貌好看，与“一流”不构成反义关系。", "认真": "“认真”形容做事专心踏实，与“一流”没有反义关系。", "大方": "“大方”形容举止不拘谨或不吝啬，与“一流”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "第一等的；水平、质量属于最高等级的。", "primary_collocate": null, "pronunciation": "yī liú", "ipa": "i˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他是世界一流的科学家。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司有一流的设备。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一流的演员要认真练习。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队的水平是一流的。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去一流的大学读书。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的质量是一流的。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的唱功一流，全国有名。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有一流的医生。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用一流的技术做汽车。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请了一流的老师教孩子。", "target_word": "一流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一流的", "label": "的字结构"}], "register": "中性", "sense_fingerprint": "水平、质量属于最高等级的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '629f9a25-8e87-4655-a9f6-d3ea5f28d1a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。"}, {"text": "一里", "is_correct": false, "explanation": "lǐ（第三声）与 liú 韵母和声调都不同，意思是一里，是距离单位。"}, {"text": "一楼", "is_correct": false, "explanation": "lóu 与 liú 韵母不同（-ou 与 -iu），意思是楼房的第一层。"}, {"text": "医疗", "is_correct": false, "explanation": "liáo 与 liú 韵母不同（-iao 与 -iu），意思是治病、诊疗。"}, {"text": "一溜", "is_correct": false, "explanation": "liù（第四声）与 liú（第二声）声调不同，意思是一行、一排。"}], "explanations": {"一流": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。", "一里": "lǐ（第三声）与 liú 韵母和声调都不同，意思是一里，是距离单位。", "一楼": "lóu 与 liú 韵母不同（-ou 与 -iu），意思是楼房的第一层。", "医疗": "liáo 与 liú 韵母不同（-iao 与 -iu），意思是治病、诊疗。", "一溜": "liù（第四声）与 liú（第二声）声调不同，意思是一行、一排。"}, "sentence_index": null, "correct_answer": "一流"}, "level_3": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确：“一流”表示水平最高，符合“是世界……的科学家”的语境。"}, {"text": "本地", "is_correct": false, "explanation": "语义：“本地”指某个地方，与“世界”的范围相矛盾。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，不能用来形容科学家的水平。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”是味道，不能用来形容人或科学家。"}], "explanations": {"一流": "正确：“一流”表示水平最高，符合“是世界……的科学家”的语境。", "本地": "语义：“本地”指某个地方，与“世界”的范围相矛盾。", "雪白": "语义：“雪白”形容颜色，不能用来形容科学家的水平。", "辣": "搭配：“辣”是味道，不能用来形容人或科学家。"}, "sentence_index": 0, "correct_answer": "一流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我一流的同学，我们常一起吃饭。", "explanation": "这里误用“一流”形容同学关系。“一流”只评价水平或质量，不能说同学之间的亲疏，这里应改用〈要好〉。"}, {"text": "这场比赛的观众数量是一流的。", "explanation": "这里应该用〈很多〉。“一流”不用来形容观众人数等数量。"}, {"text": "这件毛衣的价格是一流的，只要五十块。", "explanation": "这里应该用〈便宜〉。价格的高低不能用“一流”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。"}, {"text": "遗留", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是留下来、残存。"}, {"text": "一连", "is_correct": false, "explanation": "lián（第二声）与 liú 声调相同，韵母不同（-ian 与 -iu），意思是连续不断。"}, {"text": "一轮", "is_correct": false, "explanation": "lún（第二声）与 liú 声调相同，韵母不同（-un 与 -iu），意思是一个循环或一圈。"}, {"text": "一例", "is_correct": false, "explanation": "lì（第四声）与 liú 韵母和声调都不同，意思是一个例子。"}], "explanations": {"一流": "正确答案：一流（yī liú），指第一等，水平、质量属于最高等级。", "遗留": "yí（第二声）与 yī（第一声）声调不同，意思是留下来、残存。", "一连": "lián（第二声）与 liú 声调相同，韵母不同（-ian 与 -iu），意思是连续不断。", "一轮": "lún（第二声）与 liú 声调相同，韵母不同（-un 与 -iu），意思是一个循环或一圈。", "一例": "lì（第四声）与 liú 韵母和声调都不同，意思是一个例子。"}, "sentence_index": null, "correct_answer": "一流"}, "level_3": {"options": [{"text": "一流", "is_correct": true, "explanation": "正确：“一流”表示水平最高，符合“她的唱功……，全国有名”的语境。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容身材或规模，不能用来形容唱功。"}, {"text": "矮小", "is_correct": false, "explanation": "搭配：“矮小”形容身材，与“唱功”搭配不通。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，用来说唱功意思不通。"}], "explanations": {"一流": "正确：“一流”表示水平最高，符合“她的唱功……，全国有名”的语境。", "高大": "搭配：“高大”形容身材或规模，不能用来形容唱功。", "矮小": "搭配：“矮小”形容身材，与“唱功”搭配不通。", "透明": "语义：“透明”形容物体能透光，用来说唱功意思不通。"}, "sentence_index": 6, "correct_answer": "一流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的颜色是一流的，特别鲜艳。", "explanation": "这里应该用〈漂亮〉。“一流”评价的是水平或质量的等级，颜色只能用漂亮这类词描述，不能用“一流”来评等级。"}, {"text": "他才十二岁，年纪是一流的。", "explanation": "这里应该用〈小〉。年纪有大小，没有“一流”之分。"}, {"text": "这袋米的重量是一流的，我一个人拿不动。", "explanation": "这里应该用〈沉〉。“一流”评价水平或质量的等级，重量只分多少，不分等级，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是国内一流地画家，作品很受欢迎。", "corrected_sentence": "她是国内一流的画家，作品很受欢迎。", "error_description": "“一流”修饰名词时要用“的”，不用“地”：应说“一流的画家”。“地”是修饰动词的状语标记，用在名词前面不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她钢琴弹一流，常常参加比赛。", "corrected_sentence": "她钢琴弹得一流，常常参加比赛。", "error_description": "“一流”作补语描述“弹”的水平，动词和它之间要用“得”：应说“弹得一流”，说“弹一流”是漏掉了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f19303e6-ca92-4bad-aec4-f61c3a420f85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
