INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "看一下，时间很短。", "primary_collocate": null, "pronunciation": "yì yǎn", "ipa": "i˥˩ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他回头看了我一眼。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再看一眼这张照片。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看了一眼手表，说该走了。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，她又看了一眼窗外。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师看了一眼我的作业，笑了。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只看了一眼，就关上了门。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有看我一眼，直接走了。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快看一眼，那是谁？", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子偷偷看了爸爸一眼。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了一眼天空，说要下雨了。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "短暂地看一下，常说看一眼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96295, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。yǎn（第三声），意思是看一下，时间很短。"}, {"text": "一言", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是一句话。"}, {"text": "一碗", "is_correct": false, "explanation": "wǎn 与 yǎn 声母不同（w／y），意思是一碗。"}, {"text": "一盏", "is_correct": false, "explanation": "zhǎn 与 yǎn 声母不同（zh／y），意思是一盏（灯）。"}], "explanations": {"一眼": "正确答案。yǎn（第三声），意思是看一下，时间很短。", "一言": "yán（第二声）与 yǎn（第三声）声调不同，意思是一句话。", "一碗": "wǎn 与 yǎn 声母不同（w／y），意思是一碗。", "一盏": "zhǎn 与 yǎn 声母不同（zh／y），意思是一盏（灯）。"}, "sentence_index": null, "correct_answer": "一眼"}, "level_3": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。“看了我一眼”表示看一次，与“回头”的瞬间动作相符。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“一辈子”指整个人生，与“回头”的瞬间动作矛盾。"}, {"text": "一天", "is_correct": false, "explanation": "语义：“一天”指整整一天，不能用来形容回头看一下。"}, {"text": "一顿", "is_correct": false, "explanation": "搭配：“一顿”用于吃饭或挨骂，不能与“看”搭配。"}], "explanations": {"一眼": "正确答案。“看了我一眼”表示看一次，与“回头”的瞬间动作相符。", "一辈子": "语义：“一辈子”指整个人生，与“回头”的瞬间动作矛盾。", "一天": "语义：“一天”指整整一天，不能用来形容回头看一下。", "一顿": "搭配：“一顿”用于吃饭或挨骂，不能与“看”搭配。"}, "sentence_index": 0, "correct_answer": "一眼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在门口站了一眼。", "explanation": "这里应该用〈一会儿〉。一眼只表示看的瞬间，不能表示站立的时长。"}, {"text": "他写了一眼作业就睡了。", "explanation": "这里应该用〈一会儿〉。一眼只表示看的瞬间，不能表示写作业的时长。"}, {"text": "帮我把门关一眼。", "explanation": "这里应该用〈一下〉。一眼只能用于看这类视觉动作，不能用于“关门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96295, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。yǎn（第三声），意思是看一下，时间很短。"}, {"text": "一晚", "is_correct": false, "explanation": "wǎn 与 yǎn 声母不同（w／y），意思是一整夜。"}, {"text": "一闪", "is_correct": false, "explanation": "shǎn 与 yǎn 声母不同（sh／y），意思是闪一下。"}, {"text": "一版", "is_correct": false, "explanation": "bǎn 与 yǎn 声母不同（b／y），意思是报纸等的一个版面。"}], "explanations": {"一眼": "正确答案。yǎn（第三声），意思是看一下，时间很短。", "一晚": "wǎn 与 yǎn 声母不同（w／y），意思是一整夜。", "一闪": "shǎn 与 yǎn 声母不同（sh／y），意思是闪一下。", "一版": "bǎn 与 yǎn 声母不同（b／y），意思是报纸等的一个版面。"}, "sentence_index": null, "correct_answer": "一眼"}, "level_3": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。“没有看我一眼”表示没有看一下，与“直接走了”相符。"}, {"text": "一声", "is_correct": false, "explanation": "搭配：“一声”用于叫喊或说话，不能用于“看”。"}, {"text": "一年", "is_correct": false, "explanation": "语义：“一年”指很长的时间，与“直接走了”的快速动作矛盾。"}, {"text": "一场", "is_correct": false, "explanation": "搭配：“一场”用于比赛、雨等事件，不能修饰“看”。"}], "explanations": {"一眼": "正确答案。“没有看我一眼”表示没有看一下，与“直接走了”相符。", "一声": "搭配：“一声”用于叫喊或说话，不能用于“看”。", "一年": "语义：“一年”指很长的时间，与“直接走了”的快速动作矛盾。", "一场": "搭配：“一场”用于比赛、雨等事件，不能修饰“看”。"}, "sentence_index": 6, "correct_answer": "一眼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一眼谈了三个小时的合作。", "explanation": "这里把“一眼”理解成“一下子、很快”，但“一眼”只指看一下的瞬间，不能修饰“谈了三个小时的合作”这种长时段。"}, {"text": "妈妈一眼把菜炒好了。", "explanation": "这里把“一眼”理解成“一下子、很快”，但“一眼”只指看的瞬间，炒菜是需要过程的烹饪动作，不能用它修饰。"}, {"text": "爸爸一眼把孩子送到学校了。", "explanation": "这里把“一眼”理解成“一下子、很快”，但“一眼”只指看的瞬间，“把孩子送到学校”是位移过程，不能用它修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚进门，她就看着我一眼。", "corrected_sentence": "我刚进门，她就看了我一眼。", "error_description": "错误形式：“看着我一眼”；正确形式：“看了我一眼”。“看着”表示持续的动作，不能与表示次数的“一眼”搭配，此处应用完成体“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从书架上取下这本书，又看了一眼的封面。", "corrected_sentence": "她从书架上取下这本书，又看了一眼封面。", "error_description": "错误形式：“看了一眼的封面”；正确形式：“看了一眼封面”。“一眼”作数量补语，后面不能直接加“的”接名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
