INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "看一次的工夫；极短的一瞥。", "primary_collocate": null, "pronunciation": "yì yǎn", "ipa": "i˥˩ jɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我一眼就认出了他。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一眼就看到了那本书。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服我一眼就喜欢上了。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一眼就看出我很累。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一眼看去，房间里没有人。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一眼就发现了错误。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在人群中一眼找到了妈妈。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一眼就看出这封信是妈妈写的。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一眼就爱上了这个小镇。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的答案，他一眼就看懂了。", "target_word": "一眼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "极短的一瞥，常说一眼就看出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。yǎn（第三声），意思是极短的一瞥。"}, {"text": "一言", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是一句话。"}, {"text": "一碗", "is_correct": false, "explanation": "wǎn 与 yǎn 声母不同（w／y），意思是一碗。"}, {"text": "一盏", "is_correct": false, "explanation": "zhǎn 与 yǎn 声母不同（zh／y），意思是一盏（灯）。"}], "explanations": {"一眼": "正确答案。yǎn（第三声），意思是极短的一瞥。", "一言": "yán（第二声）与 yǎn（第三声）声调不同，意思是一句话。", "一碗": "wǎn 与 yǎn 声母不同（w／y），意思是一碗。", "一盏": "zhǎn 与 yǎn 声母不同（zh／y），意思是一盏（灯）。"}, "sentence_index": null, "correct_answer": "一眼"}, "level_3": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。“我一眼就认出了他”表示瞬间认出，符合“就”的即刻义。"}, {"text": "一辈子", "is_correct": false, "explanation": "语义：“一辈子”指整个人生，与“就认出”的即刻动作矛盾。"}, {"text": "一生", "is_correct": false, "explanation": "语义：“一生”指整个生命，时间过长，与“就认出”的即刻义冲突。"}, {"text": "一顿", "is_correct": false, "explanation": "搭配：“一顿”用于吃饭或挨骂，不能与“认出”搭配。"}], "explanations": {"一眼": "正确答案。“我一眼就认出了他”表示瞬间认出，符合“就”的即刻义。", "一辈子": "语义：“一辈子”指整个人生，与“就认出”的即刻动作矛盾。", "一生": "语义：“一生”指整个生命，时间过长，与“就认出”的即刻义冲突。", "一顿": "搭配：“一顿”用于吃饭或挨骂，不能与“认出”搭配。"}, "sentence_index": 0, "correct_answer": "一眼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想了一眼才看出答案。", "explanation": "这里应该用〈一会儿〉。一眼只表示看的瞬间，不能表示思考的一段时间。"}, {"text": "他听了一眼录音就关掉了。", "explanation": "这里应该用〈一会儿〉或〈一段〉。一眼只表示看的瞬间，不能用于听录音。"}, {"text": "他一眼就学完了三年的课程。", "explanation": "这里把“一眼就”理解成“很快就”，但“一眼”指看一下的瞬间，不能用来修饰“学完三年的课程”这种长时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96296, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。yǎn（第三声），意思是极短的一瞥。"}, {"text": "一晚", "is_correct": false, "explanation": "wǎn 与 yǎn 声母不同（w／y），意思是一整夜。"}, {"text": "一闪", "is_correct": false, "explanation": "shǎn 与 yǎn 声母不同（sh／y），意思是闪一下。"}, {"text": "一版", "is_correct": false, "explanation": "bǎn 与 yǎn 声母不同（b／y），意思是报纸等的一个版面。"}], "explanations": {"一眼": "正确答案。yǎn（第三声），意思是极短的一瞥。", "一晚": "wǎn 与 yǎn 声母不同（w／y），意思是一整夜。", "一闪": "shǎn 与 yǎn 声母不同（sh／y），意思是闪一下。", "一版": "bǎn 与 yǎn 声母不同（b／y），意思是报纸等的一个版面。"}, "sentence_index": null, "correct_answer": "一眼"}, "level_3": {"options": [{"text": "一眼", "is_correct": true, "explanation": "正确答案。“在人群中一眼找到”表示瞬间看见，符合词义。"}, {"text": "一片", "is_correct": false, "explanation": "搭配：“一片”指大片的面积，如树叶、草地，不能修饰“找”。"}, {"text": "一圈", "is_correct": false, "explanation": "语义：“一圈”指绕行一周，与“在人群中找”的瞬间动作不合。"}, {"text": "一场", "is_correct": false, "explanation": "搭配：“一场”用于比赛、雨等事件，不能修饰“找”。"}], "explanations": {"一眼": "正确答案。“在人群中一眼找到”表示瞬间看见，符合词义。", "一片": "搭配：“一片”指大片的面积，如树叶、草地，不能修饰“找”。", "一圈": "语义：“一圈”指绕行一周，与“在人群中找”的瞬间动作不合。", "一场": "搭配：“一场”用于比赛、雨等事件，不能修饰“找”。"}, "sentence_index": 6, "correct_answer": "一眼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一眼就吃完了那碗面条。", "explanation": "这里把“一眼就”理解成“很快就”，但“一眼”指看的瞬间，不能用来修饰“吃完那碗面条”这种进食过程。"}, {"text": "他一眼就洗好了那件衣服。", "explanation": "这里把“一眼就”理解成“很快就”，但“一眼”指看的瞬间，“洗好”需要一段洗涤过程，不能用它修饰。"}, {"text": "我一眼就写完了这封信。", "explanation": "这里把“一眼就”理解成“很快就”，但“一眼”指看的瞬间，“写完”需要一段书写过程，不能用它修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一眼就看了出我的心事。", "corrected_sentence": "他一眼就看出了我的心事。", "error_description": "错误形式：“看了出”；正确形式：“看出了”。“看出”是动词加结果补语，“了”要放在整个“看出”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道题很难，他却一眼的就看懂了解法。", "corrected_sentence": "这道题很难，他却一眼就看懂了解法。", "error_description": "错误形式：“一眼的就看懂”；正确形式：“一眼就看懂”。“一眼”作状语时后面直接接“就”，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下台", "is_correct": true, "explanation": "正确答案。“下台”指离开舞台，与“上台”相对，属于反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”是日常动作，与“上台”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”是学习活动，与“上台”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是休息动作，与“上台”没有反义关系。"}], "correct_answer": "下台", "explanations": {"下台": "正确答案。“下台”指离开舞台，与“上台”相对，属于反义关系。", "吃饭": "“吃饭”是日常动作，与“上台”没有反义关系。", "读书": "“读书”是学习活动，与“上台”没有反义关系。", "睡觉": "“睡觉”是休息动作，与“上台”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下台", "is_correct": true, "explanation": "正确答案。“下台”指离开舞台，与“上台”相对，属于反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”是书写动作，与“上台”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是运动动作，与“上台”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是步行活动，与“上台”没有反义关系。"}], "correct_answer": "下台", "explanations": {"下台": "正确答案。“下台”指离开舞台，与“上台”相对，属于反义关系。", "写字": "“写字”是书写动作，与“上台”没有反义关系。", "跑步": "“跑步”是运动动作，与“上台”没有反义关系。", "散步": "“散步”是步行活动，与“上台”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走到高高的台子上去给大家看。", "primary_collocate": null, "pronunciation": "shàng tái", "ipa": "ʂɑŋ˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "小明上台唱了一首歌。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请下一位同学上台。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有点儿紧张，不敢上台。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一个一个上台表演。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上台前喝了一口水。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我上台讲故事。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候上台？", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次上台跳舞。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等她上台。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着白衬衫上台。", "target_word": "上台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了台", "label": "完成体"}, {"form": "上过台", "label": "经历体"}], "register": "中性", "sense_fingerprint": "走上台子，在众人面前表演或讲话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上台", "is_correct": true, "explanation": "正确答案。tái（第二声），意思是走上舞台或讲台。"}, {"text": "上来", "is_correct": false, "explanation": "lái 与 tái 声母不同（l／t），意思是向上来。"}, {"text": "上排", "is_correct": false, "explanation": "pái 与 tái 声母不同（p／t），意思是上一排。"}, {"text": "上天", "is_correct": false, "explanation": "tiān 与 tái 韵母不同（ian／ai），意思是升到天上。"}], "explanations": {"上台": "正确答案。tái（第二声），意思是走上舞台或讲台。", "上来": "lái 与 tái 声母不同（l／t），意思是向上来。", "上排": "pái 与 tái 声母不同（p／t），意思是上一排。", "上天": "tiān 与 tái 韵母不同（ian／ai），意思是升到天上。"}, "sentence_index": null, "correct_answer": "上台"}, "level_3": {"options": [{"text": "上台", "is_correct": true, "explanation": "正确答案。“小明上台唱了一首歌”表示走上台子表演。"}, {"text": "下台", "is_correct": false, "explanation": "语义：“下台”指离开舞台，与句中“唱歌”的表演语境相反。"}, {"text": "上任", "is_correct": false, "explanation": "语义：“上任”指就任职务，与“唱歌”无关。"}, {"text": "上火", "is_correct": false, "explanation": "语义：“上火”指体内燥热或急躁，与登台唱歌无关。"}], "explanations": {"上台": "正确答案。“小明上台唱了一首歌”表示走上台子表演。", "下台": "语义：“下台”指离开舞台，与句中“唱歌”的表演语境相反。", "上任": "语义：“上任”指就任职务，与“唱歌”无关。", "上火": "语义：“上火”指体内燥热或急躁，与登台唱歌无关。"}, "sentence_index": 0, "correct_answer": "上台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他上台踢了一场球。", "explanation": "这里应该用〈上场〉。上台指走上舞台或讲台，踢球要在球场上，应用“上场”。"}, {"text": "周末我们一起上台爬了一座山。", "explanation": "这里应该用〈上山〉。上台指走上舞台或讲台，爬山要说“上山”。"}, {"text": "他下班后上台去超市买菜。", "explanation": "这里应该用〈上街〉。上台指走上台子，去超市买东西应用“上街”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上台", "is_correct": true, "explanation": "正确答案。“你什么时候上台”询问登台的时间，符合语境。"}, {"text": "上衣", "is_correct": false, "explanation": "词性：“上衣”是名词，指衣服，不能放在“什么时候”后面作谓语。"}, {"text": "上面", "is_correct": false, "explanation": "词性：“上面”是方位词，不能作谓语表示动作。"}, {"text": "上午", "is_correct": false, "explanation": "词性：“上午”是时间名词，与“什么时候”重复，不能作谓语。"}], "explanations": {"上台": "正确答案。“你什么时候上台”询问登台的时间，符合语境。", "上衣": "词性：“上衣”是名词，指衣服，不能放在“什么时候”后面作谓语。", "上面": "词性：“上面”是方位词，不能作谓语表示动作。", "上午": "词性：“上午”是时间名词，与“什么时候”重复，不能作谓语。"}, "sentence_index": 6, "correct_answer": "上台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一放学就上台写作业。", "explanation": "这里应该用〈坐到书桌前〉。上台指走上舞台或讲台，写作业不需要上台。"}, {"text": "老师每天上台去办公室批改作业。", "explanation": "这里把“上台”当成一般的“去、到”，但“上台”只指走上舞台或讲台，去办公室批改作业不能用“上台”。"}, {"text": "我每天晚上上台去厨房做饭。", "explanation": "这里把“上台”当成一般的“去、到”，但“上台”只指走上舞台或讲台，厨房不是舞台或讲台，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上台过跳舞，不太紧张。", "corrected_sentence": "我上过台跳舞，不太紧张。", "error_description": "错误形式：“上台过”；正确形式：“上过台”。经历体“过”要紧接在“上”之后，即“上过台”，不能放在“台”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他第一次上台了一首歌，有点儿紧张。", "corrected_sentence": "他第一次上台唱了一首歌，有点儿紧张。", "error_description": "错误形式：“上台了一首歌”；正确形式：“上台唱了一首歌”。“上台”是不及物动词，不能直接带宾语，要用“唱”等动词引出歌。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96299, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上期", "is_correct": true, "explanation": "上期与下期是同一系列前后相邻的两期，二者构成反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户与下期没有反义关系，它不属于时间序列中的词。"}, {"text": "河流", "is_correct": false, "explanation": "河流与下期没有反义关系，二者不在同一语义范围内。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子与下期没有反义关系，它是具体的家具名词。"}], "correct_answer": "上期", "explanations": {"上期": "上期与下期是同一系列前后相邻的两期，二者构成反义关系。", "窗户": "窗户与下期没有反义关系，它不属于时间序列中的词。", "河流": "河流与下期没有反义关系，二者不在同一语义范围内。", "桌子": "桌子与下期没有反义关系，它是具体的家具名词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96299, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上期", "is_correct": true, "explanation": "上期与下期是同一系列前后相邻的两期，二者构成反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头与下期没有反义关系，它是具体的自然物名词。"}, {"text": "树木", "is_correct": false, "explanation": "树木与下期没有反义关系，二者不在同一语义范围内。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子与下期没有反义关系，它是具体的家具名词。"}], "correct_answer": "上期", "explanations": {"上期": "上期与下期是同一系列前后相邻的两期，二者构成反义关系。", "石头": "石头与下期没有反义关系，它是具体的自然物名词。", "树木": "树木与下期没有反义关系，二者不在同一语义范围内。", "椅子": "椅子与下期没有反义关系，它是具体的家具名词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这一次过去以后的下一次。", "primary_collocate": null, "pronunciation": "xià qī", "ipa": "ɕja˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这期的活动结束了，下期再见。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天先讲到这里，下期我们接着讲。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期的比赛，我一定参加。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次我没中奖，下期再试试。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期节目会请一位新老师来。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的会开完了，下期在三月。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期的主题是什么？", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期活动我们一起参加吧。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这期杂志我看完了，等下期出来再买。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家下期早一点来。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "本次之后的下一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：听到的是“下期”（xià qī），指这一次之后的下一次。"}, {"text": "假期", "is_correct": false, "explanation": "xià 与 jià（第四声）声母不同（x/j），假期意思是放假的时间。"}, {"text": "下棋", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，下棋意思是玩棋类游戏。"}, {"text": "限期", "is_correct": false, "explanation": "xià 与 xiàn 相差一个韵尾 n，限期意思是规定的期限。"}], "explanations": {"下期": "正确：听到的是“下期”（xià qī），指这一次之后的下一次。", "假期": "xià 与 jià（第四声）声母不同（x/j），假期意思是放假的时间。", "下棋": "qī（第一声）与 qí（第二声）声调不同，下棋意思是玩棋类游戏。", "限期": "xià 与 xiàn 相差一个韵尾 n，限期意思是规定的期限。"}, "sentence_index": null, "correct_answer": "下期"}, "level_3": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：下期指这一次之后的下一次，与“再见”的将来语境相符。"}, {"text": "上期", "is_correct": false, "explanation": "语义：上期指已经过去的一期，与后面“再见”所指的将来冲突。"}, {"text": "前期", "is_correct": false, "explanation": "搭配：前期指早先的阶段，不能用于道别。"}, {"text": "过期", "is_correct": false, "explanation": "语义：过期指已经过去的时期，与“再见”所指的将来冲突，道别时不用。"}], "explanations": {"下期": "正确：下期指这一次之后的下一次，与“再见”的将来语境相符。", "上期": "语义：上期指已经过去的一期，与后面“再见”所指的将来冲突。", "前期": "搭配：前期指早先的阶段，不能用于道别。", "过期": "语义：过期指已经过去的时期，与“再见”所指的将来冲突，道别时不用。"}, "sentence_index": 0, "correct_answer": "下期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下期要上大学了。", "explanation": "这里应该用〈下学期〉。下期指按期进行之事的下一次，不能指学习阶段的下一段。"}, {"text": "我下期要当老师。", "explanation": "这里应该用〈将来〉。下期指同类事项的下一期，不能指人生的将来。"}, {"text": "车快到了，下期是北京站。", "explanation": "这里应该用〈下一站〉。下期不能指车站，只指按期进行之事的下一期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96299, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：听到的是“下期”（xià qī），指这一次之后的下一次。"}, {"text": "下机", "is_correct": false, "explanation": "qī 与 jī 声母不同（q/j），声调相同，下机意思是下飞机。"}, {"text": "下气", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，下气意思是低声下气，即放低姿态。"}, {"text": "先期", "is_correct": false, "explanation": "xià 与 xiān 相差韵尾 n，先期意思是提前的时期。"}], "explanations": {"下期": "正确：听到的是“下期”（xià qī），指这一次之后的下一次。", "下机": "qī 与 jī 声母不同（q/j），声调相同，下机意思是下飞机。", "下气": "qī（第一声）与 qì（第四声）声调不同，下气意思是低声下气，即放低姿态。", "先期": "xià 与 xiān 相差韵尾 n，先期意思是提前的时期。"}, "sentence_index": null, "correct_answer": "下期"}, "level_3": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：下期指下一次，作“主题”的修饰语，与活动或节目的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有“主题”，不能用来问它的主题是什么。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：“主题”通常搭配活动、节目或刊物，不说作息的主题。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不属于可以确定主题的事物。"}], "explanations": {"下期": "正确：下期指下一次，作“主题”的修饰语，与活动或节目的语境相符。", "天气": "语义：天气没有“主题”，不能用来问它的主题是什么。", "作息": "搭配：“主题”通常搭配活动、节目或刊物，不说作息的主题。", "体重": "语义：体重是身体的数值，不属于可以确定主题的事物。"}, "sentence_index": 6, "correct_answer": "下期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下期的孩子都很聪明。", "explanation": "这里应该用〈下一代〉。下期指按期进行之事的下一次，不能指人的世代。"}, {"text": "今天下期我们去公园。", "explanation": "这里应该用〈下午〉。下期不指一天之内的时段，不能与“今天”组合表示时间。"}, {"text": "下期的台阶很高。", "explanation": "这里应该用〈下一级〉。下期指按期进行之事的下一次，不能指台阶的一级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一个期的活动很精彩，下期更精彩。", "corrected_sentence": "这一期的活动很精彩，下期更精彩。", "error_description": "错误：“这一个期”。正确：“这一期”。“期”作量词不与“个”搭配，应说“这一期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
