INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下一个期次；下一期（刊物、课程、活动等）。", "primary_collocate": null, "pronunciation": "xià qī", "ipa": "ɕja˥˩ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "下期杂志的封面是一只猫。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期汉语课从下周一开始。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经订了下期的报纸。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期的班有三十个学生。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志每月出一本，下期十号上市。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期的故事比这期更好看。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑说下期会写旅行的文章。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期的学费你交了吗？", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想报名下期的游泳班。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下期的课本已经发给学生了。", "target_word": "下期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "刊物、课程、活动的下一期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65bb2d9-4405-4ce1-ac3a-a625d1021933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：听到的是“下期”（xià qī），指刊物、课程或活动的下一期。"}, {"text": "假期", "is_correct": false, "explanation": "xià 与 jià（第四声）声母不同（x/j），假期意思是放假的时间。"}, {"text": "下棋", "is_correct": false, "explanation": "qī（第一声）与 qí（第二声）声调不同，下棋意思是玩棋类游戏。"}, {"text": "限期", "is_correct": false, "explanation": "xià 与 xiàn 相差一个韵尾 n，限期意思是规定的期限。"}], "explanations": {"下期": "正确：听到的是“下期”（xià qī），指刊物、课程或活动的下一期。", "假期": "xià 与 jià（第四声）声母不同（x/j），假期意思是放假的时间。", "下棋": "qī（第一声）与 qí（第二声）声调不同，下棋意思是玩棋类游戏。", "限期": "xià 与 xiàn 相差一个韵尾 n，限期意思是规定的期限。"}, "sentence_index": null, "correct_answer": "下期"}, "level_3": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：下期指刊物的下一期，作“杂志”的修饰语，与“封面”语境相符。"}, {"text": "饭量", "is_correct": false, "explanation": "语义：饭量指吃东西的多少，与杂志无关，“饭量杂志”不能成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与杂志无关，“体重杂志”不能成立。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：作息不能修饰刊物，“作息杂志”搭配不当。"}], "explanations": {"下期": "正确：下期指刊物的下一期，作“杂志”的修饰语，与“封面”语境相符。", "饭量": "语义：饭量指吃东西的多少，与杂志无关，“饭量杂志”不能成立。", "体重": "语义：体重与杂志无关，“体重杂志”不能成立。", "作息": "搭配：作息不能修饰刊物，“作息杂志”搭配不当。"}, "sentence_index": 0, "correct_answer": "下期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下期去北京出差。", "explanation": "这里应该用〈下次〉。下期指刊物、课程、活动等的下一期，一次性的出差不能用“下期”。"}, {"text": "我下期想去外国留学。", "explanation": "这里应该用〈以后〉。下期指同类事项的下一期，不能指人生的将来。"}, {"text": "我下期早上起床很早。", "explanation": "这里应该用〈明天〉。下期指刊物、课程、活动等的下一期，不指一天之后的日子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96300, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：听到的是“下期”（xià qī），指刊物、课程或活动的下一期。"}, {"text": "下机", "is_correct": false, "explanation": "qī 与 jī 声母不同（q/j），声调相同，下机意思是下飞机。"}, {"text": "下气", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，下气意思是低声下气，即放低姿态。"}, {"text": "先期", "is_correct": false, "explanation": "xià 与 xiān 相差韵尾 n，先期意思是提前的时期。"}], "explanations": {"下期": "正确：听到的是“下期”（xià qī），指刊物、课程或活动的下一期。", "下机": "qī 与 jī 声母不同（q/j），声调相同，下机意思是下飞机。", "下气": "qī（第一声）与 qì（第四声）声调不同，下气意思是低声下气，即放低姿态。", "先期": "xià 与 xiān 相差韵尾 n，先期意思是提前的时期。"}, "sentence_index": null, "correct_answer": "下期"}, "level_3": {"options": [{"text": "下期", "is_correct": true, "explanation": "正确：下期指刊物的下一期，作主语，符合“编辑说……会写文章”的语境。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高不能与“写旅行的文章”搭配，无法作为写作的主语。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不会写文章，与“编辑说……会写”冲突。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不会说话也不会写文章，不能作“编辑说”的对象。"}], "explanations": {"下期": "正确：下期指刊物的下一期，作主语，符合“编辑说……会写文章”的语境。", "身高": "搭配：身高不能与“写旅行的文章”搭配，无法作为写作的主语。", "味道": "语义：味道不会写文章，与“编辑说……会写”冲突。", "闹钟": "语义：闹钟不会说话也不会写文章，不能作“编辑说”的对象。"}, "sentence_index": 6, "correct_answer": "下期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下期想去中国。", "explanation": "这里应该用〈明年〉。下期只指按期进行之事的下一期，不能用来说个人的出国计划。"}, {"text": "今天下期我们在家吃饭。", "explanation": "这里应该用〈晚上〉。下期不指一天之内的时段，不能与“今天”组合表示时间。"}, {"text": "我下期要吃一碗面。", "explanation": "这里应该用〈下一顿〉。下期只指刊物、课程、活动等的下一期，不能指一顿饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e13211ad-1855-4052-83ac-3b9c2842535c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
