INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96301, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自己家那边的球场，比赛时有很多自己人给你加油。", "primary_collocate": null, "pronunciation": "zhǔ chǎng", "ipa": "ʈʂu²¹⁴ ʈʂʰaŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "今天我们队在主场比赛。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主场有很多球迷给我们加油。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在主场踢球，我们不太紧张。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的主场在北京。", "target_word": "主场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这场比赛是在我们的主场。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们都来主场看球了。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主场的球迷唱着歌欢迎球员。", "target_word": "主场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到主场，球员们很高兴。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在主场输球，大家都很难过。", "target_word": "主场", "complexity_tier": "T3", "furigana": "zài zhǔ chǎng shū qiú, dà jiā dōu hěn nán guò.", "sentence_source": "generated"}, {"text": "周末我们去主场给球队加油。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "主场优势", "label": "复合词"}, {"form": "主場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己家那边的球场，有很多自己人加油（球迷、气氛角度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96301, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。主场：自己家那边的球场，比赛时有很多自己人给你加油。"}, {"text": "猪场", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，猪场指养猪的地方，与球场无关。"}, {"text": "主唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。"}, {"text": "主产", "is_correct": false, "explanation": "chǎn 与 chǎng 韵母不同（an 与 ang），主产指某地主要生产的东西。"}], "explanations": {"主场": "正确答案。主场：自己家那边的球场，比赛时有很多自己人给你加油。", "猪场": "zhū（第一声）与 zhǔ（第三声）声调不同，猪场指养猪的地方，与球场无关。", "主唱": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。", "主产": "chǎn 与 chǎng 韵母不同（an 与 ang），主产指某地主要生产的东西。"}, "sentence_index": null, "correct_answer": "主场"}, "level_3": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。句子说的是比赛地点，“主场”指自己队的比赛场地。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：球迷是观众，不是比赛场地，“在球迷比赛”说不通。"}, {"text": "主力", "is_correct": false, "explanation": "搭配：“主力”指主要队员，不能作为“在……比赛”的地点。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判是执法的人，不是比赛场地，句子说的是在哪里比赛。"}], "explanations": {"主场": "正确答案。句子说的是比赛地点，“主场”指自己队的比赛场地。", "球迷": "语义：球迷是观众，不是比赛场地，“在球迷比赛”说不通。", "主力": "搭配：“主力”指主要队员，不能作为“在……比赛”的地点。", "裁判": "语义：裁判是执法的人，不是比赛场地，句子说的是在哪里比赛。"}, "sentence_index": 0, "correct_answer": "主场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家楼下新建了一个主场，每天晚上都有人在那里踢球。", "explanation": "这里应该用〈球场〉。主场专指某队的主办比赛场地，供大家随便踢球的场地要用球场。"}, {"text": "周末我们一家人在主场包饺子，很热闹。", "explanation": "这里应该用〈厨房〉。主场只指体育比赛中某队的主场，做饭的地方要用厨房。"}, {"text": "我们一家人每天都在主场吃晚饭。", "explanation": "这里应该用〈家〉。主场只指体育比赛中某队的主办场地，不能用来指自己住的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96301, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。主场：自己家那边的球场，比赛时有很多自己人给你加油。"}, {"text": "主掌", "is_correct": false, "explanation": "zh 与 ch 声母不同（zhǎng 与 chǎng），主掌指掌管、主持。"}, {"text": "驻场", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，驻场指在某个场所长期演出或工作。"}, {"text": "主唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。"}], "explanations": {"主场": "正确答案。主场：自己家那边的球场，比赛时有很多自己人给你加油。", "主掌": "zh 与 ch 声母不同（zhǎng 与 chǎng），主掌指掌管、主持。", "驻场": "zhù（第四声）与 zhǔ（第三声）声调不同，驻场指在某个场所长期演出或工作。", "主唱": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。"}, "sentence_index": null, "correct_answer": "主场"}, "level_3": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。“主场的球迷”指支持主队、在自己场地看球的球迷。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，“厨房的球迷”说不通，与唱歌欢迎球员的句意不符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是看书的地方，不会有球迷唱歌欢迎球员。"}, {"text": "主语", "is_correct": false, "explanation": "搭配：“主语”是语法成分，不能用来修饰“球迷”表示场地。"}], "explanations": {"主场": "正确答案。“主场的球迷”指支持主队、在自己场地看球的球迷。", "厨房": "语义：厨房是做饭的地方，“厨房的球迷”说不通，与唱歌欢迎球员的句意不符。", "图书馆": "语义：图书馆是看书的地方，不会有球迷唱歌欢迎球员。", "主语": "搭配：“主语”是语法成分，不能用来修饰“球迷”表示场地。"}, "sentence_index": 6, "correct_answer": "主场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们去主场跑步，那里很安静。", "explanation": "这里应该用〈体育场〉。主场只指比赛中某队的比赛场地，平时跑步锻炼的地方要用体育场。"}, {"text": "妈妈每天下班后都去主场买菜，很方便。", "explanation": "这里应该用〈菜市场〉。主场只指体育比赛中某队的主场，买菜的地方要用菜市场。"}, {"text": "学校的主场很大，学生们每天在这里上课。", "explanation": "这里应该用〈教室〉。主场只指比赛时某队的主办场地，上课的地方要用教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天从主场比赛。", "corrected_sentence": "我们明天在主场比赛。", "error_description": "错误形式：“我们明天从主场比赛”；正确形式：“我们明天在主场比赛”。表示比赛地点要用“在”，“从”表示起点，“从主场比赛”说不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把主场建得很漂亮。", "corrected_sentence": "这座主场建得很漂亮。", "error_description": "“主场”是场馆，应用量词“座”；“把”用于有柄的器具，不能用来计量场馆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
