INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "体育比赛中，某队所在地的比赛场地；与客场相对。", "primary_collocate": null, "pronunciation": "zhǔ chǎng", "ipa": "ʈʂu²¹⁴ ʈʂʰaŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这个周末，北京队回主场比赛。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队在主场赢了对手。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主场和客场的比赛都很重要。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上海队今年的主场是新球场。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们已经在主场连赢五场了。", "target_word": "主场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本场比赛在红队的主场进行。", "target_word": "主场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主场作战，球队的成绩更好。", "target_word": "主场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下一场我们不在主场，要去客场。", "target_word": "主场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在主场，球队今年没有输过。", "target_word": "主场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主场比赛的门票已经卖完了。", "target_word": "主场", "complexity_tier": "T3", "furigana": "zhǔ chǎng bǐ sài de mén piào yǐ jīng mài wán le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "主场优势", "label": "复合词"}, {"form": "主場", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体育比赛中某队所在地的比赛场地，与客场相对（赛制角度）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。主场：某队所在地的比赛场地，与客场相对。"}, {"text": "主唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。"}, {"text": "主产", "is_correct": false, "explanation": "chǎn 与 chǎng 韵母不同（an 与 ang），主产指某地主要生产的东西。"}, {"text": "主掌", "is_correct": false, "explanation": "zh 与 ch 声母不同（zhǎng 与 chǎng），主掌指掌管、主持。"}], "explanations": {"主场": "正确答案。主场：某队所在地的比赛场地，与客场相对。", "主唱": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。", "主产": "chǎn 与 chǎng 韵母不同（an 与 ang），主产指某地主要生产的东西。", "主掌": "zh 与 ch 声母不同（zhǎng 与 chǎng），主掌指掌管、主持。"}, "sentence_index": null, "correct_answer": "主场"}, "level_3": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。“回主场比赛”指回到自己队的比赛场地。"}, {"text": "主角", "is_correct": false, "explanation": "语义：主角指戏剧或故事中的主要人物，不是比赛场地，“回主角比赛”说不通。"}, {"text": "教练", "is_correct": false, "explanation": "语义：教练是人员，不能作为可以“回”去比赛的地点。"}, {"text": "主力", "is_correct": false, "explanation": "搭配：“回”要搭配可以回去的场地，“主力”指主要队员，不能这样搭配。"}], "explanations": {"主场": "正确答案。“回主场比赛”指回到自己队的比赛场地。", "主角": "语义：主角指戏剧或故事中的主要人物，不是比赛场地，“回主角比赛”说不通。", "教练": "语义：教练是人员，不能作为可以“回”去比赛的地点。", "主力": "搭配：“回”要搭配可以回去的场地，“主力”指主要队员，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "主场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城北的那个主场是市民经常去的地方，大家在这里跑步。", "explanation": "这里应该用〈球场〉。主场专指某队的主办比赛场地，供市民锻炼的场地要用球场。"}, {"text": "妈妈每天在主场做饭，很辛苦。", "explanation": "这里应该用〈厨房〉。主场只指体育比赛中某队的主场，做饭的地方要用厨房。"}, {"text": "下课后，学生们都去主场吃饭。", "explanation": "这里应该用〈食堂〉。主场只指体育比赛中某队的主办场地，吃饭的地方要用食堂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96302, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。主场：某队所在地的比赛场地，与客场相对。"}, {"text": "猪场", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）声调不同，猪场指养猪的场地。"}, {"text": "驻场", "is_correct": false, "explanation": "zhù（第四声）与 zhǔ（第三声）声调不同，驻场指在某个场所长期演出或工作。"}, {"text": "主唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。"}], "explanations": {"主场": "正确答案。主场：某队所在地的比赛场地，与客场相对。", "猪场": "zhū（第一声）与 zhǔ（第三声）声调不同，猪场指养猪的场地。", "驻场": "zhù（第四声）与 zhǔ（第三声）声调不同，驻场指在某个场所长期演出或工作。", "主唱": "chàng（第四声）与 chǎng（第三声）声调不同，主唱指乐队里的主要歌手。"}, "sentence_index": null, "correct_answer": "主场"}, "level_3": {"options": [{"text": "主场", "is_correct": true, "explanation": "正确答案。“主场作战”是固定说法，指在自己场地比赛。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，“厨房作战”与比赛的句意不符。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：球迷是观众，不能“作战”，句子说的是比赛场地。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“主场作战”是固定说法，“教室作战”不能这样搭配。"}], "explanations": {"主场": "正确答案。“主场作战”是固定说法，指在自己场地比赛。", "厨房": "语义：厨房是做饭的地方，“厨房作战”与比赛的句意不符。", "球迷": "语义：球迷是观众，不能“作战”，句子说的是比赛场地。", "教室": "搭配：“主场作战”是固定说法，“教室作战”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "主场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末大家都去主场看书，那里很安静。", "explanation": "这里应该用〈阅览室〉。主场只指体育比赛中某队的主场，看书的地方要用阅览室。"}, {"text": "我每天早上在主场跑步，跑完就去上班。", "explanation": "这里应该用〈跑道〉。主场指比赛时某队的主场，平时跑步的路线要用跑道。"}, {"text": "周末我们去主场看电影，人不多。", "explanation": "这里应该用〈电影院〉。主场只指比赛中某队的主场，看电影的地方要用电影院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆主场的规模很大，能容纳三万人。", "corrected_sentence": "这座主场的规模很大，能容纳三万人。", "error_description": "“主场”是场馆，应用量词“座”；“辆”用于车辆，不能用来计量场馆。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从主场赢得了比赛。", "corrected_sentence": "我们在主场赢得了比赛。", "error_description": "错误形式：“我们从主场赢得了比赛”；正确形式：“我们在主场赢得了比赛”。表示比赛地点要用“在”，“从”表示起点，“从主场赢得了比赛”说不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩回", "is_correct": true, "explanation": "正确答案。缩回：把伸出去的手或脚收回来，与“伸出”意思相反。"}, {"text": "躲进", "is_correct": false, "explanation": "躲进：藏到某处里面，与“伸出”不构成反义关系。"}, {"text": "抱起", "is_correct": false, "explanation": "抱起：用手臂托起东西，与“伸出”不是反义词。"}, {"text": "晃动", "is_correct": false, "explanation": "晃动：来回摆动，与“伸出”不是反义词。"}], "correct_answer": "缩回", "explanations": {"缩回": "正确答案。缩回：把伸出去的手或脚收回来，与“伸出”意思相反。", "躲进": "躲进：藏到某处里面，与“伸出”不构成反义关系。", "抱起": "抱起：用手臂托起东西，与“伸出”不是反义词。", "晃动": "晃动：来回摆动，与“伸出”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩回", "is_correct": true, "explanation": "正确答案。缩回：把伸出去的手或脚收回来，与“伸出”意思相反。"}, {"text": "捏紧", "is_correct": false, "explanation": "捏紧：用手指用力夹住，与“伸出”不构成反义关系。"}, {"text": "藏起", "is_correct": false, "explanation": "藏起：收起来不让人看见，与“伸出”不是反义词。"}, {"text": "合拢", "is_correct": false, "explanation": "合拢：两边靠到一起，与“伸出”不是反义词。"}], "correct_answer": "缩回", "explanations": {"缩回": "正确答案。缩回：把伸出去的手或脚收回来，与“伸出”意思相反。", "捏紧": "捏紧：用手指用力夹住，与“伸出”不构成反义关系。", "藏起": "藏起：收起来不让人看见，与“伸出”不是反义词。", "合拢": "合拢：两边靠到一起，与“伸出”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把手或脚向外面长长地放出去。", "primary_collocate": null, "pronunciation": "shēn chū", "ipa": "ʂən˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "他向我伸出手。", "target_word": "伸出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩伸出小手，想拿桌上的糖。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请伸出你的手，让医生量一下血压。", "target_word": "伸出", "complexity_tier": "T3", "furigana": "qǐng shēn chū nǐ de shǒu, ràng yī shēng liáng yí xià xuè yā.", "sentence_source": "generated"}, {"text": "他从毯子下伸出一只脚。", "target_word": "伸出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说：“同学们，请伸出左手。”", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她伸出手，轻轻拉住了妹妹。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机伸出手，向后面的车打手势。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在雨中伸出手，接了几滴雨水。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人伸出颤抖的手，想摸摸孩子的脸。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我伸出脚，把球踢给了他。", "target_word": "伸出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伸出了", "label": "体标"}, {"form": "伸出过", "label": "体标"}, {"form": "伸出来", "label": "复合"}, {"form": "伸出去", "label": "复合"}], "register": "中性", "sense_fingerprint": "人把手或脚向外伸长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伸出", "is_correct": true, "explanation": "正确答案。伸出：把手或脚向外放出去。"}, {"text": "生出", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（eng 与 en），生出指长出、产生，与伸手无关。"}, {"text": "身处", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，身处指处在某种环境或境地。"}, {"text": "渗出", "is_correct": false, "explanation": "shèn（第四声）与 shēn（第一声）声调不同，渗出指液体从缝隙里慢慢流出。"}], "explanations": {"伸出": "正确答案。伸出：把手或脚向外放出去。", "生出": "shēng 与 shēn 韵母不同（eng 与 en），生出指长出、产生，与伸手无关。", "身处": "chù（第四声）与 chū（第一声）声调不同，身处指处在某种环境或境地。", "渗出": "shèn（第四声）与 shēn（第一声）声调不同，渗出指液体从缝隙里慢慢流出。"}, "sentence_index": null, "correct_answer": "伸出"}, "level_3": {"options": [{"text": "伸出", "is_correct": true, "explanation": "正确答案。“伸出手”指把手向对方伸过去。"}, {"text": "撕破", "is_correct": false, "explanation": "语义：撕破是把东西弄破，与“向我伸手”的动作不符。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：烧掉是把东西烧毁，句子说的是向我伸手，意思说不通。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要“送什么”和“送给谁”两部分，“手”不能作为被送的东西。"}], "explanations": {"伸出": "正确答案。“伸出手”指把手向对方伸过去。", "撕破": "语义：撕破是把东西弄破，与“向我伸手”的动作不符。", "烧掉": "语义：烧掉是把东西烧毁，句子说的是向我伸手，意思说不通。", "送给": "配价：“送给”需要“送什么”和“送给谁”两部分，“手”不能作为被送的东西。"}, "sentence_index": 0, "correct_answer": "伸出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他伸出一个好办法，大家都同意了。", "explanation": "这里应该用〈想出〉。伸出指把手或脚向外放，办法是想出来的，要用想出。"}, {"text": "老师伸出一个问题，请大家回答。", "explanation": "这里应该用〈提出〉。伸出指把手或脚向外放，“提出问题”是另一个说法，不能用伸出。"}, {"text": "他从口袋里伸出一张纸条。", "explanation": "这里应该用〈拿出〉。伸出是把手或脚向外放，从口袋里取出东西要用拿出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伸出", "is_correct": true, "explanation": "正确答案。“伸出手”配合后文打手势，指司机把手伸出车外。"}, {"text": "缝上", "is_correct": false, "explanation": "语义：缝上是把东西缝到别处，司机不会缝手，与打手势的动作不符。"}, {"text": "割断", "is_correct": false, "explanation": "语义：割断是切断，句子说的是打手势，不是割断手。"}, {"text": "摘下", "is_correct": false, "explanation": "搭配：“摘下”多用于帽子、手套等物件，不能用来搭配“手”本身。"}], "explanations": {"伸出": "正确答案。“伸出手”配合后文打手势，指司机把手伸出车外。", "缝上": "语义：缝上是把东西缝到别处，司机不会缝手，与打手势的动作不符。", "割断": "语义：割断是切断，句子说的是打手势，不是割断手。", "摘下": "搭配：“摘下”多用于帽子、手套等物件，不能用来搭配“手”本身。"}, "sentence_index": 6, "correct_answer": "伸出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从箱子里伸出一件旧衣服。", "explanation": "这里应该用〈抽出〉。伸出是把手或脚向外放，从箱子里拉出衣服要用抽出。"}, {"text": "他把胸脯伸出来，显得很自信。", "explanation": "这里应该用〈挺〉。伸出指把手或脚向外放，胸脯是向前挺起的，要用挺。"}, {"text": "他把那张旧桌子伸出来，放到了门口。", "explanation": "这里应该用〈搬〉。伸出指把手或脚向外放，移动桌子这类物件要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从窗口伸出手过，接了几滴雨水。", "corrected_sentence": "他从窗口伸出过手，接了几滴雨水。", "error_description": "错误形式：“伸出手过”；正确形式：“伸出过手”。“过”是体标，应紧跟动词“伸出”，说“伸出过手”，不能放在宾语“手”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把我伸出了手，我握住了它。", "corrected_sentence": "他向我伸出了手，我握住了它。", "error_description": "错误形式：“把我伸出了手”；正确形式：“向我伸出了手”。“伸出”的对象是“手”，表示朝某人伸出要用介词“向”；“把”引出被处置的对象，“我”不能被“伸出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩回", "is_correct": true, "explanation": "正确答案。缩回：把伸出去的部分收回来，与“伸出”意思相反。"}, {"text": "躲藏", "is_correct": false, "explanation": "躲藏：藏起来，与“伸出”不构成反义关系。"}, {"text": "托起", "is_correct": false, "explanation": "托起：用手向上托，与“伸出”不是反义词。"}, {"text": "摇晃", "is_correct": false, "explanation": "摇晃：来回晃动，与“伸出”不是反义词。"}], "correct_answer": "缩回", "explanations": {"缩回": "正确答案。缩回：把伸出去的部分收回来，与“伸出”意思相反。", "躲藏": "躲藏：藏起来，与“伸出”不构成反义关系。", "托起": "托起：用手向上托，与“伸出”不是反义词。", "摇晃": "摇晃：来回晃动，与“伸出”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缩回", "is_correct": true, "explanation": "正确答案。缩回：把伸出去的部分收回来，与“伸出”意思相反。"}, {"text": "掉落", "is_correct": false, "explanation": "掉落：从高处落下，与“伸出”不是反义词。"}, {"text": "贴上", "is_correct": false, "explanation": "贴上：粘在别的东西上，与“伸出”不是反义词。"}, {"text": "拆除", "is_correct": false, "explanation": "拆除：把建筑或设施拆掉，与“伸出”不是反义词。"}], "correct_answer": "缩回", "explanations": {"缩回": "正确答案。缩回：把伸出去的部分收回来，与“伸出”意思相反。", "掉落": "掉落：从高处落下，与“伸出”不是反义词。", "贴上": "贴上：粘在别的东西上，与“伸出”不是反义词。", "拆除": "拆除：把建筑或设施拆掉，与“伸出”不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向外展开或延伸出（身体部位、物体等）。", "primary_collocate": null, "pronunciation": "shēn chū", "ipa": "ʂən˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "一根树枝伸出了墙外。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外伸出一根长长的竹竿。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乌龟慢慢伸出头来。", "target_word": "伸出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫从门后伸出小脑袋。", "target_word": "伸出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河边的柳树伸出长长的枝条。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子的二楼伸出一个小阳台。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜗牛伸出两只小触角。", "target_word": "伸出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山崖上伸出一块大石头。", "target_word": "伸出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从车窗伸出头，大声喊我的名字。", "target_word": "伸出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上伸出一个铁钩，上面挂着灯。", "target_word": "伸出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "伸出了", "label": "体标"}, {"form": "伸出过", "label": "体标"}, {"form": "伸出来", "label": "复合"}, {"form": "伸出去", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或身体部位向外延伸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d2c36d4-50c2-46de-9f3e-8dd3d76bc06f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伸出", "is_correct": true, "explanation": "正确答案。伸出：身体部位或物体向外延伸。"}, {"text": "生出", "is_correct": false, "explanation": "shēng 与 shēn 韵母不同（eng 与 en），生出指长出、产生，与向外延伸不同。"}, {"text": "身处", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，身处指处在某种环境或境地。"}, {"text": "渗出", "is_correct": false, "explanation": "shèn（第四声）与 shēn（第一声）声调不同，渗出指液体从缝隙里慢慢流出。"}], "explanations": {"伸出": "正确答案。伸出：身体部位或物体向外延伸。", "生出": "shēng 与 shēn 韵母不同（eng 与 en），生出指长出、产生，与向外延伸不同。", "身处": "chù（第四声）与 chū（第一声）声调不同，身处指处在某种环境或境地。", "渗出": "shèn（第四声）与 shēn（第一声）声调不同，渗出指液体从缝隙里慢慢流出。"}, "sentence_index": null, "correct_answer": "伸出"}, "level_3": {"options": [{"text": "伸出", "is_correct": true, "explanation": "正确答案。“伸出墙外”指树枝从墙内向外延伸。"}, {"text": "躲藏", "is_correct": false, "explanation": "语义：躲藏是藏起来，树枝不能躲在墙外，与句意不符。"}, {"text": "拆下", "is_correct": false, "explanation": "语义：拆下是把东西从原处取下，与树枝从墙内伸到墙外的意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要搬运的对象和去向，“一根树枝搬运了墙外”不成立。"}], "explanations": {"伸出": "正确答案。“伸出墙外”指树枝从墙内向外延伸。", "躲藏": "语义：躲藏是藏起来，树枝不能躲在墙外，与句意不符。", "拆下": "语义：拆下是把东西从原处取下，与树枝从墙内伸到墙外的意思不符。", "搬运": "配价：“搬运”需要搬运的对象和去向，“一根树枝搬运了墙外”不成立。"}, "sentence_index": 0, "correct_answer": "伸出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门缝里伸出一阵笑声。", "explanation": "这里应该用〈传出〉。伸出用于身体部位或物体向外延伸，笑声是传出来的，不能说伸出。"}, {"text": "他心里突然伸出一个主意。", "explanation": "这里应该用〈冒出〉。伸出指具体的物体向外延伸，主意是头脑里产生的，要用冒出。"}, {"text": "院子里伸出一棵大树。", "explanation": "这里应该用〈长出〉。伸出指从物体上向外延伸的部分，整棵树是从地里生长出来的，要用长出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伸出", "is_correct": true, "explanation": "正确答案。“蜗牛伸出两只小触角”指触角从身体向外伸长。"}, {"text": "咬住", "is_correct": false, "explanation": "语义：咬住是用牙齿夹住，蜗牛不会咬住自己的触角，与句意不符。"}, {"text": "剪断", "is_correct": false, "explanation": "语义：剪断是切断，句子说的是触角伸出，不是被剪断。"}, {"text": "挂上", "is_correct": false, "explanation": "搭配：“挂上”需要挂东西的地方，“触角”不能挂上去。"}], "explanations": {"伸出": "正确答案。“蜗牛伸出两只小触角”指触角从身体向外伸长。", "咬住": "语义：咬住是用牙齿夹住，蜗牛不会咬住自己的触角，与句意不符。", "剪断": "语义：剪断是切断，句子说的是触角伸出，不是被剪断。", "挂上": "搭配：“挂上”需要挂东西的地方，“触角”不能挂上去。"}, "sentence_index": 6, "correct_answer": "伸出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牙膏从管子里伸出来。", "explanation": "这里应该用〈挤出〉。伸出用于身体部位或细长物体向外延伸，牙膏是被挤出来的，不能说伸出。"}, {"text": "他额头上伸出了许多汗珠。", "explanation": "这里应该用〈渗出〉。伸出指身体部位或细长物体向外延伸，汗珠是从皮肤里渗出来的，要用渗出。"}, {"text": "路边伸出一根电线杆。", "explanation": "这里应该用〈竖着〉。电线杆是竖立在地上的，不是向外延伸，要用竖着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳台上被伸出一个小架子，可以放花盆。", "corrected_sentence": "阳台上伸出一个小架子，可以放花盆。", "error_description": "“被”字多加了。“伸出”表示物体自己向外延伸，不是被动动作，不能用“被”，应说“阳台上伸出一个小架子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座码头向水面被伸出很远。", "corrected_sentence": "这座码头向水面伸出很远。", "error_description": "“被”字多加了。“伸出”表示物体自己向外延伸，码头不是被动的承受者，不能用“被”，应说“向水面伸出很远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df412bd-0ffc-428f-bcfd-b3515c8a86fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做不好事情的时候，说出来的不是真的理由。", "primary_collocate": null, "pronunciation": "jiè kǒu", "ipa": "tɕjɛ⁵¹ kʰoʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "考试没考好，他说是笔坏了，这是借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作做不好，别总拿忙当借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每次输球，都有一堆借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队输了比赛，教练不接受任何借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业没写完，他的借口是狗吃了本子。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败了就认错，不要再找借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说路上堵车，其实是睡过头的借口。", "target_word": "借口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错了事还找借口，老师很生气。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "项目没完成，他编了一个借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想进步的人，从不给失败找借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "事情没做好时说出的不真实的理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "借口", "is_correct": true, "explanation": "“借口”指推托的说辞，此处指“笔坏了”这一说法，符合句意。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是题目的正确解法，与“笔坏了”这类推托说辞不符。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“这是成绩”不能指代推托的说辞，成绩是考试结果本身。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气与考试没考好无关，“这是天气”不能作为推托的说法。"}], "explanations": {"借口": "“借口”指推托的说辞，此处指“笔坏了”这一说法，符合句意。", "答案": "语义：“答案”是题目的正确解法，与“笔坏了”这类推托说辞不符。", "成绩": "搭配：“这是成绩”不能指代推托的说辞，成绩是考试结果本身。", "天气": "语义：天气与考试没考好无关，“这是天气”不能作为推托的说法。"}, "sentence_index": 0, "correct_answer": "借口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给出了一个真实的借口，教练听后很满意。", "explanation": "这里应该用〈理由〉。“借口”指不真实的推托理由，不能用“真实的”修饰；说明真实情况要用〈理由〉。"}, {"text": "教练在下半场换了新借口，球队很快扳平了比分。", "explanation": "这里应该用〈战术〉。“借口”指推托的说辞，不能用来扭转比赛；调整比赛打法要用〈战术〉。"}, {"text": "他的简历里写满了借口，招聘的人很满意。", "explanation": "这里应该用〈经历〉。“借口”不能写进简历；简历里列出工作经验和过往工作要用〈经历〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "借口", "is_correct": true, "explanation": "“借口”指推托的理由，此处指“路上堵车”这一假托，符合句意。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是叫醒用的器具，不能作为“睡过头”的推托说法。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，与“睡过头”的推托无关，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“睡过头的座位”不成搭配，“座位”不能用“睡过头”来修饰。"}], "explanations": {"借口": "“借口”指推托的理由，此处指“路上堵车”这一假托，符合句意。", "闹钟": "语义：闹钟是叫醒用的器具，不能作为“睡过头”的推托说法。", "早餐": "语义：早餐是食物，与“睡过头”的推托无关，句意不通。", "座位": "搭配：“睡过头的座位”不成搭配，“座位”不能用“睡过头”来修饰。"}, "sentence_index": 6, "correct_answer": "借口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题有很多解决借口。", "explanation": "这里应该用〈办法〉。“借口”是推托的说辞，不能用来解决问题；“解决”要搭配〈办法〉。"}, {"text": "他制定了学习借口。", "explanation": "这里应该用〈计划〉。“制定”搭配计划、方案，不能用于借口。"}, {"text": "工人把借口一块块码好，准备砌墙。", "explanation": "这里应该用〈砖〉。“借口”是推托的说辞，不能用来砌墙；砌墙的材料要用〈砖〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总为失败找出一张新借口。", "corrected_sentence": "他总为失败找出一个新借口。", "error_description": "错误：“一张新借口”；正确：“一个新借口”。“借口”的量词是“个”，“张”不用于借口。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96305, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是找一只借口，大家都不再相信他了。", "corrected_sentence": "他总是找一个借口，大家都不再相信他了。", "error_description": "错误：“一只借口”；正确：“一个借口”。“借口”的量词是“个”，“只”不用于借口。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
