INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96306, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为推托或掩饰而找的理由。", "primary_collocate": null, "pronunciation": "jiè kǒu", "ipa": "tɕjɛ⁵¹ kʰoʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "他总是找借口不做作业。", "target_word": "借口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "迟到不是借口，下次请早点出门。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说头疼，其实只是个借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以家里有事为借口，提前离开了会场。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别给自己的懒惰找借口。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不接受这样的借口。", "target_word": "借口", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王用肚子疼做借口，没有去上班。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的借口太多了，没人再相信他。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿加班当借口，躲开了这次聚会。", "target_word": "借口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨只是借口，他就是不想出门。", "target_word": "借口", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "为推托或掩饰而找的理由（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca76034f-6a3f-449d-886e-105190999ca9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "借口", "is_correct": true, "explanation": "“借口”指为推托而找的理由，与“找借口不做作业”的句意相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包与做作业无关，不能作为推托不做作业的理由。"}, {"text": "橡皮", "is_correct": false, "explanation": "语义：橡皮是学习用品，“找橡皮”不构成推托不做作业的说法。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“找作业”与“不做作业”意思相悖，“作业”不能作为推托的对象。"}], "explanations": {"借口": "“借口”指为推托而找的理由，与“找借口不做作业”的句意相符。", "书包": "语义：书包与做作业无关，不能作为推托不做作业的理由。", "橡皮": "语义：橡皮是学习用品，“找橡皮”不构成推托不做作业的说法。", "作业": "搭配：“找作业”与“不做作业”意思相悖，“作业”不能作为推托的对象。"}, "sentence_index": 0, "correct_answer": "借口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说出了真实的借口，大家都理解了。", "explanation": "这里应该用〈理由〉。“借口”指为推托而找的不真实理由，不能用“真实的”修饰；说明实际情况要用〈理由〉。"}, {"text": "这篇论文的借口很有说服力，导师很欣赏。", "explanation": "这里应该用〈论点〉。“借口”指推托的说辞，不能指论文的观点；论文的观点要用〈论点〉。"}, {"text": "这台电脑的借口出现了故障，需要修理。", "explanation": "这里应该用〈零件〉。“借口”不是实物，不能指电脑的组成部分；电脑的部件要用〈零件〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "借口", "is_correct": true, "explanation": "“借口”指为推托而找的理由，“用肚子疼做借口”即拿肚子疼当推托不上班的理由，符合句意。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“用肚子疼做早饭”句意不通，早饭是食物，不能是推托的理由。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：“用肚子疼做衣服”句意不通，与不去上班无关。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“用肚子疼做椅子”句意不通，椅子是家具，不是理由。"}], "explanations": {"借口": "“借口”指为推托而找的理由，“用肚子疼做借口”即拿肚子疼当推托不上班的理由，符合句意。", "早饭": "语义：“用肚子疼做早饭”句意不通，早饭是食物，不能是推托的理由。", "衣服": "语义：“用肚子疼做衣服”句意不通，与不去上班无关。", "椅子": "语义：“用肚子疼做椅子”句意不通，椅子是家具，不是理由。"}, "sentence_index": 6, "correct_answer": "借口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的借口帮我解决了难题，我很感激。", "explanation": "这里应该用〈办法〉。“借口”指推托的理由，不能用来解决问题，解决难题要用〈办法〉。"}, {"text": "他制定了一个借口，准备明天执行。", "explanation": "这里应该用〈计划〉。“制定”搭配计划、方案，不能用于借口；借口是临时找的说法。"}, {"text": "仓库里的借口堆得像小山，工人正在搬运。", "explanation": "这里应该用〈货物〉。“借口”是推托的说辞，不是可以堆放搬运的物品；仓库里堆放搬运的东西要用〈货物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每次考试前，妹妹都想出一只新借口。", "corrected_sentence": "每次考试前，妹妹都想出一个新借口。", "error_description": "错误：“一只新借口”；正确：“一个新借口”。“借口”的量词是“个”，“只”不用于借口。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找了过很多借口，但老师都不信。", "corrected_sentence": "他找过很多借口，但老师都不信。", "error_description": "错误：“找了过”；正确：“找过”。“了”与“过”不能同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78ef4368-fbf7-44e9-aef1-75531e1a73d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
