INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96307, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做了好事，大家都夸你，你心里很高兴。", "primary_collocate": null, "pronunciation": "guāng róng", "ipa": "kwɑŋ˥ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师夸我了，我觉得很光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱包还给了失主，大家都夸他，他觉得很光荣。", "target_word": "光荣", "complexity_tier": "T3", "furigana": "tā bǎ qiánbāo huán gěi le shīzhǔ, dàjiā dōu kuā tā, tā juéde hěn guāngróng", "sentence_source": "generated"}, {"text": "小明得到了小红花，觉得特别光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈夸我做得好，我感到很光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都向他鼓掌，他觉得非常光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮老人拿东西，我觉得很光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当众表扬了她，她觉得光荣极了。", "target_word": "光荣", "complexity_tier": "T3", "furigana": "lǎoshī dāngzhòng biǎoyáng le tā, tā juéde guāngróng jí le", "sentence_source": "generated"}, {"text": "我拿着奖状回家，觉得很光荣。", "target_word": "光荣", "complexity_tier": "T3", "furigana": "wǒ názhe jiǎngzhuàng huí jiā, juéde hěn guāngróng", "sentence_source": "generated"}, {"text": "能帮上忙，哥哥觉得很光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到大家的夸奖，他觉得光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光荣榜", "label": "复合"}, {"form": "光榮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做了好事受到夸奖，心里感到高兴和自豪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光荣", "is_correct": true, "explanation": "光荣表示受夸奖后的自豪，与“老师夸我了”的语境吻合。"}, {"text": "难过", "is_correct": false, "explanation": "语义：难过表示伤心，与被老师夸奖的喜悦相反。"}, {"text": "委屈", "is_correct": false, "explanation": "语义：委屈表示受了冤枉，与被夸奖的语境不合。"}, {"text": "狼狈", "is_correct": false, "explanation": "搭配：狼狈形容窘迫的样子，不能用来描述受夸奖后的感受。"}], "explanations": {"光荣": "光荣表示受夸奖后的自豪，与“老师夸我了”的语境吻合。", "难过": "语义：难过表示伤心，与被老师夸奖的喜悦相反。", "委屈": "语义：委屈表示受了冤枉，与被夸奖的语境不合。", "狼狈": "搭配：狼狈形容窘迫的样子，不能用来描述受夸奖后的感受。"}, "sentence_index": 0, "correct_answer": "光荣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我丢了钱包，觉得很光荣。", "explanation": "这里应该用〈难过〉。光荣指做了好事受夸奖后的高兴，丢东西不能用“光荣”。"}, {"text": "外面下雨了，我觉得很光荣。", "explanation": "这里应该用〈凉快〉。光荣指做了好事受夸奖后的高兴，与天气无关。"}, {"text": "孩子们玩得很光荣。", "explanation": "这里应该用〈开心〉。光荣指因做好事受赞扬而自豪，不用于一般的玩耍快乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光荣", "is_correct": true, "explanation": "光荣表示受表扬后的自豪，与“老师当众表扬了她”的语境吻合。"}, {"text": "生气", "is_correct": false, "explanation": "语义：生气表示愤怒，与被当众表扬后的心情相反。"}, {"text": "沮丧", "is_correct": false, "explanation": "语义：沮丧表示失望，与被表扬的语境不合。"}, {"text": "冰冷", "is_correct": false, "explanation": "搭配：冰冷描述温度或态度，不能用来形容受表扬后的心理感受。"}], "explanations": {"光荣": "光荣表示受表扬后的自豪，与“老师当众表扬了她”的语境吻合。", "生气": "语义：生气表示愤怒，与被当众表扬后的心情相反。", "沮丧": "语义：沮丧表示失望，与被表扬的语境不合。", "冰冷": "搭配：冰冷描述温度或态度，不能用来形容受表扬后的心理感受。"}, "sentence_index": 6, "correct_answer": "光荣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑步很光荣。", "explanation": "这里应该用〈轻松〉。光荣指做好事受夸奖后的高兴，不用来形容跑步这类动作。"}, {"text": "他听到消息很光荣。", "explanation": "这里应该用〈高兴〉。光荣指因做好事受赞扬而自豪，不用于一般的消息。"}, {"text": "这杯水很光荣。", "explanation": "这里应该用〈干净〉。光荣指因做好事受夸奖而自豪，不用来形容物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈夸她，她觉得的很光荣。", "corrected_sentence": "妈妈夸她，她觉得很光荣。", "error_description": "“的”不能加在动词“觉得”后面。这里应说“觉得很光荣”，“很”修饰形容词“光荣”，中间不需要“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到表扬，我觉得很非常光荣。", "corrected_sentence": "听到表扬，我觉得非常光荣。", "error_description": "“很”和“非常”都是程度副词，不能叠用。应去掉“很”，说“非常光荣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "耻辱", "is_correct": true, "explanation": "耻辱与光荣是反义词：光荣指受尊重，耻辱指受羞辱。"}, {"text": "愉快", "is_correct": false, "explanation": "愉快表示心情好，与“光荣”并不构成反义关系。"}, {"text": "勇敢", "is_correct": false, "explanation": "勇敢是品质词，与“光荣”不是反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软描写质地，与“光荣”的意义无关，不是反义词。"}], "correct_answer": "耻辱", "explanations": {"耻辱": "耻辱与光荣是反义词：光荣指受尊重，耻辱指受羞辱。", "愉快": "愉快表示心情好，与“光荣”并不构成反义关系。", "勇敢": "勇敢是品质词，与“光荣”不是反义关系。", "柔软": "柔软描写质地，与“光荣”的意义无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "耻辱", "is_correct": true, "explanation": "耻辱与光荣是反义词：光荣指受尊重，耻辱指受羞辱。"}, {"text": "悲伤", "is_correct": false, "explanation": "悲伤表示难过的心情，与“光荣”并不构成反义关系。"}, {"text": "清澈", "is_correct": false, "explanation": "清澈描写水或眼神的透明，与“光荣”的意义无关。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝形容反应慢，与“光荣”不是反义关系。"}], "correct_answer": "耻辱", "explanations": {"耻辱": "耻辱与光荣是反义词：光荣指受尊重，耻辱指受羞辱。", "悲伤": "悲伤表示难过的心情，与“光荣”并不构成反义关系。", "清澈": "清澈描写水或眼神的透明，与“光荣”的意义无关。", "迟钝": "迟钝形容反应慢，与“光荣”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "因做出贡献或取得成就而受到尊重、赞扬，值得骄傲的。", "primary_collocate": null, "pronunciation": "guāng róng", "ipa": "kwɑŋ˥ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "当医生是一件光荣的事。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他立了功，全家都觉得光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次光荣的任务。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她获得了光荣的称号。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老工人光荣地退休了。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们为这个光荣的集体而骄傲。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿到了奖，这是很光荣的事情。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的光荣历史值得我们学习。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老兵们讲起了光荣的过去。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能代表学校参加比赛，他觉得很光荣。", "target_word": "光荣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "光荣榜", "label": "复合"}, {"form": "光榮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "因贡献或成就而受到尊重和赞扬，值得骄傲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf6d6c22-a9d8-46c5-94a5-24ad05fbccee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光荣", "is_correct": true, "explanation": "光荣表示因贡献而受尊重，可以修饰“事”，句意通顺。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：狭窄形容空间，不能用来形容“一件事”。"}, {"text": "滑溜", "is_correct": false, "explanation": "搭配：滑溜形容表面光滑、容易打滑，不能用来形容“一件事”。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：冰凉描述温度的感受，与“当医生是一件……的事”这一评价不合。"}], "explanations": {"光荣": "光荣表示因贡献而受尊重，可以修饰“事”，句意通顺。", "狭窄": "搭配：狭窄形容空间，不能用来形容“一件事”。", "滑溜": "搭配：滑溜形容表面光滑、容易打滑，不能用来形容“一件事”。", "冰凉": "语义：冰凉描述温度的感受，与“当医生是一件……的事”这一评价不合。"}, "sentence_index": 0, "correct_answer": "光荣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气很光荣。", "explanation": "这里应该用〈晴朗〉。光荣指因贡献或成就而受尊重，不用来形容天气。"}, {"text": "他撒了谎，大家都觉得他很光荣。", "explanation": "这里应该用〈丢脸〉。光荣指因成就而受尊重，撒谎不能用“光荣”。"}, {"text": "这次的失败让他觉得很光荣。", "explanation": "这里应该用〈惭愧〉。光荣指值得骄傲的受尊重状态，失败后不能用“光荣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光荣", "is_correct": true, "explanation": "光荣表示因成就而受尊重，可以修饰“事情”，与“拿到了奖”的语境吻合。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：滚烫描述温度，不能用来形容“事情”的价值。"}, {"text": "稀薄", "is_correct": false, "explanation": "搭配：稀薄形容气体或浓度，不能修饰“事情”。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：嘈杂形容声音吵闹，不能用来评价“事情”。"}], "explanations": {"光荣": "光荣表示因成就而受尊重，可以修饰“事情”，与“拿到了奖”的语境吻合。", "滚烫": "语义：滚烫描述温度，不能用来形容“事情”的价值。", "稀薄": "搭配：稀薄形容气体或浓度，不能修饰“事情”。", "嘈杂": "搭配：嘈杂形容声音吵闹，不能用来评价“事情”。"}, "sentence_index": 6, "correct_answer": "光荣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿得很光荣。", "explanation": "这里应该用〈体面〉。光荣指因贡献或成就而受尊重，不用来形容穿着。"}, {"text": "这把椅子很光荣。", "explanation": "这里应该用〈结实〉。光荣指因贡献或成就而受尊重，不用来形容物品。"}, {"text": "这碗汤很光荣。", "explanation": "这里应该用〈鲜美〉。光荣指因贡献或成就而受尊重，不用来形容食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他光荣的完成了任务。", "corrected_sentence": "他光荣地完成了任务。", "error_description": "“光荣”修饰动作“完成”时应用“地”，误用“的”是错误的。正确说法是“光荣地完成了任务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一件非常很光荣的事。", "corrected_sentence": "这是一件非常光荣的事。", "error_description": "“非常”和“很”都是程度副词，不能叠用。应去掉“很”，说“非常光荣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e63072b-0c7b-4bce-92df-bd88ea7c0498') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
