INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96310, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在同一时间点上的；语言学中指不涉及历史演变、只就某一时期状态进行考察的。", "primary_collocate": null, "pronunciation": "gòng shí", "ipa": "kʊŋ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "这篇文章只看一个时期的语言，是共时研究。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共时的方法只看一个时期的语言。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，共时描写不看语言的历史。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先做共时分析，不谈词是怎么变来的。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书从共时的角度，说明现在的汉语语法。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文写的是现代汉语的共时系统。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做共时调查时，只看现在的说法。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共时研究不用管词是怎么变来的。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对两种方言做了共时的比较，没有写历史。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位学者专门做汉语的共时描写。", "target_word": "共时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共时性", "label": "复合"}, {"form": "共时研究", "label": "复合"}, {"form": "共時", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "语言学中只考察某一时期状态、不涉及历史演变的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96310, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "共时", "is_correct": true, "explanation": "共时（gòng shí）是本词，指同一时间点上的；语言学中只考察某一时期状态、不涉及历史演变。"}, {"text": "工时", "is_correct": false, "explanation": "工时（gōng shí）第一音节为阴平，与共时的去声不同，意思是工作时间。"}, {"text": "公式", "is_correct": false, "explanation": "公式（gōng shì）两个音节的声调都与共时不同，意思是数学或化学中的式子。"}, {"text": "公示", "is_correct": false, "explanation": "公示（gōng shì）两个音节的声调都与共时不同，意思是向社会公开告知。"}, {"text": "共事", "is_correct": false, "explanation": "共事（gòng shì）第二音节声调不同（去声），意思是一起工作。"}], "explanations": {"共时": "共时（gòng shí）是本词，指同一时间点上的；语言学中只考察某一时期状态、不涉及历史演变。", "工时": "工时（gōng shí）第一音节为阴平，与共时的去声不同，意思是工作时间。", "公式": "公式（gōng shì）两个音节的声调都与共时不同，意思是数学或化学中的式子。", "公示": "公示（gōng shì）两个音节的声调都与共时不同，意思是向社会公开告知。", "共事": "共事（gòng shì）第二音节声调不同（去声），意思是一起工作。"}, "sentence_index": null, "correct_answer": "共时"}, "level_3": {"options": [{"text": "共时", "is_correct": true, "explanation": "共时：与“只看一个时期的语言”相合，指只考察某一时期的状态。"}, {"text": "历时", "is_correct": false, "explanation": "语义：历时指考察语言的历史演变，与“只看一个时期的语言”相反，这里说历时研究会自相矛盾。"}, {"text": "纵向", "is_correct": false, "explanation": "语义：纵向指沿时间方向的考察，与“只看一个时期的语言”相矛盾。"}, {"text": "复杂", "is_correct": false, "explanation": "搭配：复杂用来形容情况或问题，不用来说研究的类型。"}], "explanations": {"共时": "共时：与“只看一个时期的语言”相合，指只考察某一时期的状态。", "历时": "语义：历时指考察语言的历史演变，与“只看一个时期的语言”相反，这里说历时研究会自相矛盾。", "纵向": "语义：纵向指沿时间方向的考察，与“只看一个时期的语言”相矛盾。", "复杂": "搭配：复杂用来形容情况或问题，不用来说研究的类型。"}, "sentence_index": 0, "correct_answer": "共时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他研究共时的历史，讲的都是古代的变化。", "explanation": "语义：共时指不涉及历史演变的考察，不能修饰“历史”。这里应该用〈历时〉，表示考察一段时间内的演变。"}, {"text": "这篇论文用共时的方法，追溯了两种语言的同源关系。", "explanation": "语义：共时的方法只考察某一时期的状态，不追溯来源；追溯同源关系要用〈历时〉。"}, {"text": "这篇文章比较了三个朝代的词义变化，属于共时研究。", "explanation": "语义：比较三个朝代的变化属于历时研究，共时只考察某一时期的状态，应该用〈历时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96310, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "共时", "is_correct": true, "explanation": "共时（gòng shí）是本词，指同一时间点上的；语言学中只考察某一时期状态。"}, {"text": "工事", "is_correct": false, "explanation": "工事（gōng shì）两个音节的声调都与共时不同，意思是修建的工程或防御工事。"}, {"text": "攻势", "is_correct": false, "explanation": "攻势（gōng shì）两个音节的声调都与共时不同，意思是进攻的态势。"}, {"text": "公使", "is_correct": false, "explanation": "公使（gōng shǐ）第一音节为阴平、第二音节为上声，与共时的声调不同，意思是外交使节。"}], "explanations": {"共时": "共时（gòng shí）是本词，指同一时间点上的；语言学中只考察某一时期状态。", "工事": "工事（gōng shì）两个音节的声调都与共时不同，意思是修建的工程或防御工事。", "攻势": "攻势（gōng shì）两个音节的声调都与共时不同，意思是进攻的态势。", "公使": "公使（gōng shǐ）第一音节为阴平、第二音节为上声，与共时的声调不同，意思是外交使节。"}, "sentence_index": null, "correct_answer": "共时"}, "level_3": {"options": [{"text": "共时", "is_correct": true, "explanation": "共时：与“只看现在的说法”相合，指只考察当前某一时期的状态。"}, {"text": "长期", "is_correct": false, "explanation": "语义：长期强调时间跨度长，与“只看现在的说法”相矛盾。"}, {"text": "古老", "is_correct": false, "explanation": "搭配：古老形容事物年代久远，不说“古老调查”。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：漫长指时间很长，与“只看现在”的考察范围相矛盾。"}], "explanations": {"共时": "共时：与“只看现在的说法”相合，指只考察当前某一时期的状态。", "长期": "语义：长期强调时间跨度长，与“只看现在的说法”相矛盾。", "古老": "搭配：古老形容事物年代久远，不说“古老调查”。", "漫长": "语义：漫长指时间很长，与“只看现在”的考察范围相矛盾。"}, "sentence_index": 6, "correct_answer": "共时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告是共时的，却记录了三年里词的变化。", "explanation": "语义：共时不考虑时间上的变化，记录三年里词的变化属于历时考察，应该用〈历时〉。"}, {"text": "这本词典注重共时的词源考证。", "explanation": "语义：词源考证要追溯历史来源，属于历时研究，这里应该用〈历时〉。"}, {"text": "这个词的共时变得很快，一年就换了一个意思。", "explanation": "语义：共时只考察某一时期的状态，不考察变化的快慢；说词义的变化要用〈历时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "语言学课上，老师先讲很共时语法，再讲历时语法。", "corrected_sentence": "语言学课上，老师先讲共时语法，再讲历时语法。", "error_description": "程度错误：“共时”是非等级性的术语，不能受“很”修饰，应说“共时语法”，不说“很共时语法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个理论是共时得，值得多研究。", "corrected_sentence": "这个理论是共时的，值得多研究。", "error_description": "结构助词错误：“是共时”后应用“的”，不用“得”，应说“是共时的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
