INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由主体分出来的部分；整体中分化出的支派或支流。", "primary_collocate": null, "pronunciation": "fēn zhī", "ipa": "fən˥ ʈ͡ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "这家公司在很多城市都有分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河在山下分成两个分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言学是一门大学科的重要分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个银行的分支遍布全国。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学有很多分支，比如代数和几何。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路有一个通往海边的分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家族后来分成了几个分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司的北京分支工作。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大河有很多小分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的故事有三条分支。", "target_word": "分支", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "由主体分出的支派、支流或下属部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98662808-ed68-4962-b8c7-ba656fb782da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96312, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分支", "is_correct": true, "explanation": "分支：此处指公司设在各地的分公司或分号。"}, {"text": "树枝", "is_correct": false, "explanation": "语义：树枝是植物的部分，公司不会有树枝，与“公司”的语境冲突。"}, {"text": "河流", "is_correct": false, "explanation": "语义：公司不会“有”河流，河流是自然地理事物，与句意不符。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：花瓣是花的部分，与公司无关，放进句子里语义不通。"}], "explanations": {"分支": "分支：此处指公司设在各地的分公司或分号。", "树枝": "语义：树枝是植物的部分，公司不会有树枝，与“公司”的语境冲突。", "河流": "语义：公司不会“有”河流，河流是自然地理事物，与句意不符。", "花瓣": "语义：花瓣是花的部分，与公司无关，放进句子里语义不通。"}, "sentence_index": 0, "correct_answer": "分支"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的分支每天早上都背着书包去上学。", "explanation": "这里应该用〈学生〉。分支指机构或支派，不会背着书包去上学；会这样做的是学生。"}, {"text": "他的手掌上长出了三个分支，每个分支上都长着一根手指。", "explanation": "这里应该用〈手指〉。分支指由主体分出的部分，不指手掌上长出的指头。"}, {"text": "这家公司的分支是一个人，每天自己在办公室里工作。", "explanation": "这里应该用〈员工〉。分支指机构，不能指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分支", "is_correct": true, "explanation": "分支：由家族分出的各支派，与“分成了几个”的语境相合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：家族是人群，不能分成房间，房间不是家族的分支。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“分成”几个，与“家族”的语境冲突。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，家族是人群，不能分成几个饭菜。"}], "explanations": {"分支": "分支：由家族分出的各支派，与“分成了几个”的语境相合。", "房间": "语义：家族是人群，不能分成房间，房间不是家族的分支。", "天气": "语义：天气不能被“分成”几个，与“家族”的语境冲突。", "饭菜": "语义：饭菜是食物，家族是人群，不能分成几个饭菜。"}, "sentence_index": 6, "correct_answer": "分支"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的分支每天早上七点起床，自己做早饭。", "explanation": "这里应该用〈员工〉。分支指机构或支派，不会起床做饭；会这样做的是人。"}, {"text": "这家银行的分支从地面笔直向上长，粗得要三个人才能合抱。", "explanation": "这里应该用〈树干〉。分支指从主体分出的部分，不能指从地面笔直长起、要多人合抱的树干。"}, {"text": "我们在院子里养了一排分支，它们每天一起跑来跑去，吵个不停。", "explanation": "这里应该用〈孩子〉。分支是枝条或支派，不会跑来跑去、吵个不停；会这样的是孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司在北京设立了一根分支。", "corrected_sentence": "这家公司在北京设立了一个分支。", "error_description": "量词错误：“分支”指机构时应用“个”或“家”，“根”用于细长的枝条。应把“一根分支”改为“一个分支”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在国外开了两根分支。", "corrected_sentence": "他在国外开了两家分支。", "error_description": "量词错误：“分支”指机构时应用“家”或“个”，“根”用于细长的东西。应把“两根”改为“两家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dae554e3-f06a-4694-91ea-5a27875966e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
