INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "除了本来的名字以外，别人也这样叫你的另一个名字。", "primary_collocate": null, "pronunciation": "bié hào", "ipa": "pjɛ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他真名叫王明，但大家都用别号“小胖”叫他。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "同学们给我起了一个别号，平时都这么叫我。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "你在网上的别号是谁给你起的？", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "大家平时都叫他的别号，很少有人叫他的本名。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "这个别号在他的朋友中叫了很多年。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "她不喜欢别人用别号叫她。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "除了本名，我在班里还有一个别号叫大头。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "他个子很高，大家给他起了别号“长腿”。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "老师知道我的别号，也笑着用它叫我。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "我的别号是朋友们一起想出来的，大家都这么叫我。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "別號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别人给某人起的、本名以外的称呼，类似外号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别号", "is_correct": true, "explanation": "别号：本名以外另取的称呼，与“用……“小胖”叫他”相合。"}, {"text": "真名", "is_correct": false, "explanation": "语义：真名是王明，与前文“真名叫王明”矛盾，且真名不用作昵称。"}, {"text": "学号", "is_correct": false, "explanation": "搭配：学号是编号，不用来称呼人。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重是数值，不能用来称呼人。"}], "explanations": {"别号": "别号：本名以外另取的称呼，与“用……“小胖”叫他”相合。", "真名": "语义：真名是王明，与前文“真名叫王明”矛盾，且真名不用作昵称。", "学号": "搭配：学号是编号，不用来称呼人。", "体重": "搭配：体重是数值，不能用来称呼人。"}, "sentence_index": 0, "correct_answer": "别号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的别号，我每天都这么叫他。", "explanation": "语义：别号是对人的称呼，不能直接用来指人本身；这里应该说“他是我的朋友”，表示〈朋友〉。"}, {"text": "我有一只别号，只有好朋友知道。", "explanation": "量词：别号用“个”，“只”一般用于动物或成对的东西，这里应该用〈个〉。"}, {"text": "我的别号是五月三日，那天我们家要吃蛋糕。", "explanation": "语义：别号是对人的称呼，不是日期；这里应该用〈生日〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别号", "is_correct": true, "explanation": "别号：本名以外另取的称呼，与“除了本名，我在班里还有一个……叫大头”相合。"}, {"text": "本名", "is_correct": false, "explanation": "语义：句中已说“除了本名”，再说“还有一个本名叫大头”自相矛盾。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：生日是日期，不能作人的称呼。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：座位指位置，不用来称呼人。"}], "explanations": {"别号": "别号：本名以外另取的称呼，与“除了本名，我在班里还有一个……叫大头”相合。", "本名": "语义：句中已说“除了本名”，再说“还有一个本名叫大头”自相矛盾。", "生日": "搭配：生日是日期，不能作人的称呼。", "座位": "搭配：座位指位置，不用来称呼人。"}, "sentence_index": 6, "correct_answer": "别号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的别号和本名一模一样，所以大家分不清。", "explanation": "语义：别号是本名以外另取的称呼，不能与本人的名字完全相同；这里把它混同为〈原名〉。"}, {"text": "这篇文章的别号很长，要读很久。", "explanation": "搭配：别号指人的称呼，不用于文章；文章或书的另一个名称应说〈别名〉。"}, {"text": "他被任命为公司的别号，负责管理财务。", "explanation": "语义：别号是别人对人的称呼，不是职务；这里误当作〈职位〉的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在朋友圈里有两只别号，大家都这么叫他。", "corrected_sentence": "他在朋友圈里有两个别号，大家都这么叫他。", "error_description": "量词错误：别号要用量词“个”，不说“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都用别号他，很少有人知道他的本名。", "corrected_sentence": "大家都用别号叫他，很少有人知道他的本名。", "error_description": "动词缺失：“用别号”后需要动词“叫”，“用别号他”不成句，应说“大家都用别号叫他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
