INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96314, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "除本名和字之外，另取的称号。", "primary_collocate": null, "pronunciation": "bié hào", "ipa": "pjɛ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "苏轼的别号是东坡居士。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的文人除了名和字，常常还有别号。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李白的别号叫青莲居士。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家的别号很有诗意。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给自己取了一个别号，叫“山人”。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着这位诗人的名、字和别号。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "齐白石的别号很多，其中一个叫“借山翁”。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人的别号常常表示自己的爱好。", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他名叫陈云，字子安，别号竹林先生。", "target_word": "别号", "complexity_tier": "T3", "furigana": "bié hào", "sentence_source": "generated"}, {"text": "老师问我们：“欧阳修的别号是什么？”", "target_word": "别号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "别號", "label": "繁体"}], "register": "书面", "sense_fingerprint": "古代文人在名和字之外自己另取的雅号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a66d-b287-4d90-aad3-fbae94057ed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别号", "is_correct": true, "explanation": "别号：除本名和字之外另取的称号，东坡居士是苏轼的别号。"}, {"text": "家乡", "is_correct": false, "explanation": "语义：家乡指出生的地方，“东坡居士”是称号，不是地方。"}, {"text": "名", "is_correct": false, "explanation": "语义：名是本名，东坡居士是另取的称号，不能说是名。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：生日是日期，不能作称号。"}], "explanations": {"别号": "别号：除本名和字之外另取的称号，东坡居士是苏轼的别号。", "家乡": "语义：家乡指出生的地方，“东坡居士”是称号，不是地方。", "名": "语义：名是本名，东坡居士是另取的称号，不能说是名。", "生日": "搭配：生日是日期，不能作称号。"}, "sentence_index": 0, "correct_answer": "别号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的别号叫“小黄山”。", "explanation": "搭配：别号指人另取的称号，不用于山；地方的另一个名字应说〈别称〉。"}, {"text": "这位画家有一只别号，很少有人知道。", "explanation": "量词：别号用“个”，“只”不用于称号，这里应该用〈个〉。"}, {"text": "古代文人的别号是他们的祖籍，表示出生的地方。", "explanation": "语义：别号是另取的称号，不表示出生或祖籍的地方；这里混淆了〈籍贯〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '597bceb7-a6e9-42bb-8280-603ac3903286') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
